// Auswahl
// ---------------------------------------------------------------------------

/**
 * Drei Vorschlaege ziehen, gewichtet und **ohne Doppel** (GDD 09 Abschnitt 2).
 *
 * Ohne Doppel, weil drei gleiche Karten keine Wahl sind. Gezogen wird nach Gewicht, und der
 * gezogene Eintrag faellt fuer dieses Angebot heraus - so bleiben seltene Perks selten,
 * ohne dass ein Angebot je aus einer einzigen Karte besteht.
 *
 * Rein: Der Generator kommt von aussen, damit dasselbe Angebot bei gleichem Zustand
 * reproduzierbar ist (Implementierungsplan Abschnitt 3).
 */
export function offerPerks(rng: Rng, count = PERK_CHOICES): PerkDef[] {
  const pool = [...PERKS]
  const chosen: PerkDef[] = []

  for (let i = 0; i < count && pool.length > 0; i++) {
    let total = 0
    for (const perk of pool) total += perk.weight

    let roll = rng.next() * total
    let index = pool.length - 1
    for (let k = 0; k < pool.length; k++) {
      roll -= (pool[k] as PerkDef).weight
      if (roll <= 0) {
        index = k
        break
      }
    }

    chosen.push(pool[index] as PerkDef)
    pool.splice(index, 1)
  }

  return chosen
}

/**
 * Das offene Angebot - erzeugt es, falls noch keines steht.
 *
 * Es liegt im Spielstand und nicht in den Laufzeitdaten: Sonst wuerde ein Neuladen ein
 * neues Angebot wuerfeln, und wer seine drei Karten nicht mag, drueckt F5. Eine Auswahl,
 * die man beliebig oft wiederholen kann, ist keine.
 */
export function currentOffer(state: GameState): PerkDef[] {
  if (pendingLevelUps(state) === 0) {
    if (state.run.perkOffer.length > 0) state.run.perkOffer = []
    return []
  }

  const stored = state.run.perkOffer.filter(isKnownPerk)
  if (stored.length > 0) {
    state.run.perkOffer = stored
    return stored.map(perkById)
  }

  const offer = offerPerks(state.runtime.rng)
  state.run.perkOffer = offer.map((perk) => perk.id)
  return offer
}

/**
 * Einen Perk annehmen. Gibt `false` zurueck, wenn gerade kein Aufstieg offen ist oder der
 * Perk nicht im aktuellen Angebot steht - beides waere sonst ein Weg, sich Perks zu holen,
 * ohne dafuer aufzusteigen.
 */
export function choosePerk(state: GameState, perkId: string): boolean {
  if (pendingLevelUps(state) === 0) return false
  if (!isKnownPerk(perkId)) return false
  if (!state.run.perkOffer.includes(perkId)) return false

  state.run.perks.push(perkId)
  state.run.level = claimedLevel(state) + 1
  // Das naechste Angebot wird beim naechsten Aufruf frisch gezogen.
  state.run.perkOffer = []
  emit('perk.chosen', { perkId, level: state.run.level })
  return true
}

/**
 * Einen Perk **ohne** Aufstieg gutschreiben.
 *
 * Die Haendler-Drohne verkauft "seltene Verbesserungen" (GDD 11 Abschnitt 7) - das ist
 * genau ein Perk, nur bezahlt statt gewaehlt. Er geht deshalb in dieselbe Liste und wirkt
 * ueber dieselbe Kette in `sim/stats.ts`; ein zweiter Ort fuer dauerhafte Run-Boni waere
 * ein zweites Regelwerk fuer dieselbe Sache.
 *
 * `choosePerk` bleibt davon unberuehrt und verlangt weiterhin einen offenen Aufstieg: Das
 * ist der Weg fuer den Levelaufstieg, und er darf keine Abkuerzung bekommen. Diese Funktion
 * ist die andere Tuer, und sie kostet Gold.
 */
export function grantPerk(state: GameState, perkId: string): boolean {
  if (!isKnownPerk(perkId)) return false

  state.run.perks.push(perkId)
  emit('perk.chosen', { perkId, level: claimedLevel(state) })
  return true
}

/**
 * Neue Stufen melden. Aus dem Takt aufrufen.
 *
 * Der Aufstieg selbst ist abgeleitet und passiert deshalb "von allein" - trotzdem braucht
 * es einen Augenblick, an dem er *gemeldet* wird: fuer die Anzeige jetzt und fuer den Klang
 * spaeter (GDD 13 Abschnitt 11). Gemeldet wird jede Stufe einzeln, auch wenn eine Bosswelle
 * drei auf einmal bringt - sonst verschluckt eine Meldung zwei Aufstiege.
 */
export function stepProgression(state: GameState): void {
  const level = currentLevel(state)
  const announced = state.runtime.announcedLevel

  // Erster Takt nach dem Laden: stumm nachziehen, nicht nachtraeglich alles melden.
  if (announced < 0) {
    state.runtime.announcedLevel = level
    return
  }

  if (level <= announced) return
  for (let reached = announced + 1; reached <= level; reached++) {
    emit('level.up', { level: reached })
  }
  state.runtime.announcedLevel = level
}

// ---------------------------------------------------------------------------
// Wirkung
// ---------------------------------------------------------------------------

/**
 * Summe aller Perk-Boni auf einen Kampfwert.
 *
 * Additiv, nicht multiplikativ - dieselbe Regel wie bei Buffs (GDD 03 Abschnitt 9). Zehn
 * Perks zu je acht Prozent ergeben +80 %, nicht +116 %. Multiplikativ waere jeder Deckel
 * wirkungslos und die Kurve nicht mehr zu ueberblicken.
 */
export function perkStatBonus(state: GameState, key: StatKey): number {
  let total = 0
  for (const id of state.run.perks) {
    if (!isKnownPerk(id)) continue
    const effect = perkById(id).effect
    if (effect.kind === 'stat' && effect.stat === key) total += effect.amount
  }
  return total
}

/** Summe aller Perk-Boni auf eine Groesse des Runs. */
export function perkGlobalBonus(state: GameState, key: PerkGlobal): number {
  let total = 0
  for (const id of state.run.perks) {
    if (!isKnownPerk(id)) continue
    const effect = perkById(id).effect
    if (effect.kind === 'global' && effect.global === key) total += effect.amount
  }
  return total
}

/** Wie oft ein bestimmter Perk bereits gewaehlt wurde - fuer die Anzeige. */
export function perkCount(state: GameState, perkId: string): number {
  let count = 0
  for (const id of state.run.perks) if (id === perkId) count += 1
  return count
}

/**
 * Wie viele Perks bereits auf **dieselbe** Groesse wirken - unabhaengig von ihrer Stufe.
 *
 * Der Unterschied zu `perkCount` ist der Unterschied zwischen Karte und Wirkung:
 * "Damage +8%" und "Damage +80%" sind zwei Eintraege, aber eine Richtung. Die Karte im
 * Aufstiegsfenster zaehlt sich selbst ("owned x2" heisst: genau diese zweimal); die
 * ausfuehrliche Auskunft daneben rechnet die ganze Richtung zusammen und braucht deshalb
 * diese Zahl. Mit `perkCount` stuende dort "dein erster dieser Art" neben einem bereits
 * angesammelten "+6%" - zwei Saetze, die sich widersprechen.
 */
export function perkFamilyCount(state: GameState, effect: PerkEffect): number {
  let count = 0
  for (const id of state.run.perks) {
    if (!isKnownPerk(id)) continue
    const other = perkById(id).effect
    if (other.kind !== effect.kind) continue
    if (other.kind === 'stat' && effect.kind === 'stat' && other.stat !== effect.stat) continue
    if (other.kind === 'global' && effect.kind === 'global' && other.global !== effect.global) {
      continue
    }
    count += 1
  }
  return count
}

/**
 * Alle Spielertexte laufen ueber `t()` (GDD 16 Abschnitt 1). Der Test sichert die
 * Platzhalter-Ersetzung ab - sie ist die Stelle, an der eine spaetere deutsche Fassung
 * bricht, wenn sie unsauber ist.
 */

import { assert, assertEqual, check, suite } from '../../core/assert.ts'
import { hasString, STRINGS, t } from '../../data/strings.ts'

export function stringsSuite(): void {
  suite('data/strings')

  check('Text ohne Platzhalter kommt unveraendert', () => {
    assertEqual(t('game.title'), 'WAVEBREAKER')
  })

  check('Platzhalter werden ersetzt', () => {
    assertEqual(t('hud.wave', { wave: 12 }), 'Wave 12')
    assertEqual(t('hud.speed', { factor: 4 }), 'Speed x4')
  })

  check('fehlende Werte bleiben sichtbar stehen, statt zu verschwinden', () => {
    assertEqual(t('hud.wave', {}), 'Wave {wave}')
  })

  check('jeder Text ist englisch und nicht leer', () => {
    for (const [key, value] of Object.entries(STRINGS)) {
      assert(value.trim().length > 0, `leerer Text: ${key}`)
      assert(
        !/[äöüßÄÖÜ]/.test(value),
        `Spielsprache ist Englisch, "${key}" enthaelt deutsche Zeichen`,
      )
    }
  })

  check('hasString erkennt unbekannte Schluessel', () => {
    assertEqual(hasString('game.title'), true)
    assertEqual(hasString('gibt.es.nicht'), false)
  })
}

