/**
 * Der laufende Anschlag: Text, der sich Buchstabe fuer Buchstabe selbst schreibt.
 *
 * Er stand zuerst allein beim Ausgang einer Welle (`ui/outcome.ts`) und ist von dort
 * hierher gewandert, weil er dieselbe Aufgabe ueberall loest, wo Text **ankommt**: Eine
 * Meldung, die im selben Bild fertig dasteht, ist vorbei, bevor der Blick sie gefunden
 * hat. Der Anschlag gibt ihr eine **Dauer** und zieht das Auge an die Stelle, an der
 * gerade etwas Neues steht.
 *
 * Drei Entscheidungen praegen die Datei:
 *
 * **Derselbe Text schreibt sich nicht zweimal.** Die Aufrufer sind Panels, die nach jeder
 * Handlung neu durchlaufen - das Lager baut sich bei jedem Klick auf, das HUD prueft in
 * jedem Bild. Ohne diese Sperre setzte jeder Durchlauf den Anschlag neu an, und die
 * Ueberschrift zitterte. Deshalb merkt sich ein Anschlag, was er zuletzt geschrieben hat,
 * und die Aufrufer duerfen ihn stumpf in ihrer Schleife aufrufen.
 *
 * **Ob getippt wird, beantwortet das Stilblatt.** `--motion` traegt beides an einer Stelle:
 * den Schalter im Spiel (`data-motion` am Wurzelknoten) und die Einstellung des
 * Betriebssystems (`prefers-reduced-motion`). Dieselbe Quelle benutzt schon die Wanderung
 * beim Bereichswechsel (`ui/flip.ts`). Ein eigener Durchgriff auf die Einstellungen kaeme
 * an der Betriebssystem-Einstellung vorbei - der Anschlag liefe dann bei jemandem weiter,
 * der Bewegung abbestellt hat.
 *
 * **Ein Anschlag, mehrere Zeilen.** Ein Fenster hat eine Ueberschrift **und** einen Satz
 * darunter. Zwei getrennte Anschlaege liefen gleichzeitig los und stolperten uebereinander;
 * hier laeuft der Cursor von der einen Zeile in die naechste, so wie ihn jemand schriebe.
 */

import { createRng } from '../core/rng.ts'

/** Grundtakt zwischen zwei Buchstaben, in Millisekunden. */
const TYPE_MS = 68
/** Vorlauf, bevor der erste Buchstabe faellt - der Cursor steht schon, das Wort noch nicht. */
const START_MS = 130
/** Atemzug zwischen zwei Zeilen. Etwa ein Wort lang, damit der Zeilenwechsel zu sehen ist. */
const BREAK_MS = TYPE_MS * 4
/** Wie lange der Cursor stehen bleibt, nachdem der letzte Buchstabe gefallen ist. */
const CARET_HOLD_MS = 700

/**
 * Fester Startwert statt echtem Zufall.
 *
 * Der Rhythmus soll unregelmaessig **wirken**, nicht unnachstellbar sein - und die
 * Querschnittsregel aus Abschnitt 9 des Plans laesst `Math.random()` nur fuer den Startwert
 * eines Runs zu. Der Strom laeuft ueber alle Anschlaege hinweg weiter: Zwei Ueberschriften
 * hintereinander tippen deshalb verschieden, obwohl der Startwert derselbe ist.
 */
const rng = createRng(0x7ea19c)

/** Eine Zeile des Anschlags: wohin geschrieben wird und was. */
export type TypeLine = { node: HTMLElement; text: string }

/**
 * Was mit dem Cursor am Ende geschieht.
 *
 *   `drop`  - er bleibt einen Augenblick stehen und geht dann. Fuer alles, was liegenbleibt:
 *             eine Ueberschrift, ein Hinweis, ein Fenster. Ein Balken, der dort ewig
 *             blinkte, saehe aus wie ein Eingabefeld.
 *   `keep`  - er blinkt weiter. Fuer Schriftzuege, die von selbst wieder gehen - daran
 *             erkennt man, dass die Meldung noch "lebt".
 *   `none`  - gar keiner.
 */
export type CaretMode = 'drop' | 'keep' | 'none'

export type TypewriterOptions = {
  /** Grundtakt zwischen zwei Buchstaben. */
  speed?: number
  /** Vorlauf vor dem ersten Buchstaben. */
  delay?: number
  caret?: CaretMode
  /** Laeuft, sobald der letzte Buchstabe steht - auch wenn gar nicht getippt wurde. */
  onDone?: () => void
}

export type Typewriter = {
  /** Schreibt die Zeilen an. Derselbe Text wie zuletzt tut nichts. */
  write(...lines: TypeLine[]): void
  /**
   * Anschlag abbrechen und vergessen, was zuletzt geschrieben wurde - der naechste Auftritt
   * schreibt dann wieder von vorn, auch mit demselben Text.
   *
   * Der Text selbst bleibt stehen. Aufgerufen wird das beim Schliessen, und dort laeuft
   * meist noch ein Abgang: Eine Meldung, die waehrend ihres Abgangs leer wird, verschwindet
   * zweimal.
   */
  reset(): void
}

export function createTypewriter(options: TypewriterOptions = {}): Typewriter {
  const speed = options.speed ?? TYPE_MS
  const lead = options.delay ?? START_MS
  const mode = options.caret ?? 'drop'
  const caret = mode === 'none' ? null : createCaret()

  /** Laufende Zeitschaltung. 0 heisst: keine. */
  let timer = 0
  let lines: readonly TypeLine[] = []
  /** Welche Zeile gerade geschrieben wird. */
  let index = 0
  /** Wie viele Zeichen dieser Zeile schon stehen. */
  let written = 0
  /**
   * Der Textknoten der laufenden Zeile.
   *
   * Geschrieben wird in ihn und nicht in `textContent` des Elements: Der Cursor haengt als
   * zweites Kind daneben, und `textContent` wuerde ihn bei jedem Buchstaben mit wegwerfen.
   */
  let sink: Text | null = null
  /** Woran erkannt wird, dass derselbe Text noch einmal angefordert wird. */
  let signature: string | null = null

  function stopTimer(): void {
    if (timer !== 0) window.clearTimeout(timer)
    timer = 0
  }

  /**
   * Abstand bis zum naechsten Buchstaben.
   *
   * Ein starrer Takt liest sich als Laufschrift, nicht als Anschlag. Deshalb dieselbe grobe
   * Verteilung wie bei einer tippenden Hand: meist knapp am Grundtakt, in einem von zehn
   * Faellen ein Zoegern, in einem von zehn ein Ausbruch nach vorn.
   */
  function nextDelay(): number {
    const roll = rng.next()
    if (roll < 0.1) return speed * 2
    if (roll > 0.9) return speed * 0.5
    return rng.range(speed * 0.6, speed * 1.4)
  }

  /** Steht die Oberflaeche still? Siehe den Kopf der Datei - `--motion` ist die eine Quelle. */
  function still(node: HTMLElement): boolean {
    return getComputedStyle(node).getPropertyValue('--motion').trim() === '0'
  }

  function openLine(): void {
    const line = lines[index]
    if (line === undefined) return
    written = 0
    sink = document.createTextNode('')
    if (caret) line.node.replaceChildren(sink, caret)
    else line.node.replaceChildren(sink)
  }

  function step(): void {
    const line = lines[index]
    if (line === undefined) {
      finish()
      return
    }

    if (written < line.text.length) {
      written += 1
      if (sink) sink.data = line.text.slice(0, written)
      timer = window.setTimeout(step, nextDelay())
      return
    }

    index += 1
    if (index >= lines.length) {
      finish()
      return
    }

    openLine()
    timer = window.setTimeout(step, BREAK_MS)
  }

  function finish(): void {
    timer = 0
    // Der Cursor bleibt noch einen Augenblick - er faellt sonst im selben Bild mit dem
    // letzten Buchstaben zusammen, und der Anschlag endete mit einem Zucken.
    if (mode === 'drop' && caret) {
      timer = window.setTimeout(() => {
        caret.remove()
        timer = 0
      }, CARET_HOLD_MS)
    }
    options.onDone?.()
  }

  return {
    write(...next) {
      const mark = next.map((line) => line.text).join('�')
      if (mark === signature) return
      signature = mark

      stopTimer()
      lines = next
      index = 0
      written = 0
      sink = null
      caret?.remove()

      const first = next[0]
      if (first === undefined) return

      /*
       * Bewegung aus: Der Text steht sofort ganz da. Ein Anschlag, der auf 1 ms gekuerzt
       * wird, waere kein ruhigeres Bild, sondern ein Zucken - deshalb faellt er hier ganz
       * weg statt schneller zu laufen.
       */
      if (still(first.node)) {
        for (const line of next) line.node.textContent = line.text
        const last = next[next.length - 1]
        if (mode === 'keep' && caret && last) last.node.appendChild(caret)
