input.content:
/**
 * Alle laufenden Zahlen der Oberflaeche (GDD 13 Abschnitt 4).
 *
 * Verteilt auf mehrere Stellen, aber bewusst in **einer** Datei: Sie alle lesen denselben
 * Zustand und muessen im selben Bild dasselbe zeigen.
 *
 *   Goldschild    oben links ueber dem Feld - Gold und liegendes Gold
 *   Wellenkarte   oben rechts - Welle, Wellenwerte, Fortschritt, Wellensteuerung
 *   Boss-Leiste   oben mittig, nur solange ein Boss lebt (GDD 07 Abschnitt 7)
 *   Rumpfleiste   unten, direkt ueber der Bedienleiste - Stations-HP samt Kampfwerten
 *   Tempo         unten links im Feld
 *   Wellenkarte der Basis  oben rechts, wo kein Kampf zu sehen ist
 *
 * **Alles schwebt ueber dem Feld, nichts steht mehr in der unteren Leiste.** Vorher trugen
 * zwei grosse Karten in der Leiste dieselben Zahlen; zusammen mit dem Upgrade-Panel nahm
 * die Leiste damit 44 Prozent der Bildhoehe ein, und vom Spielfeld blieb ein Streifen. Die
 * Zahlen sind jetzt duenne Schilder ueber dem Feld - sie verdecken ein paar Prozent statt
 * die Haelfte, und die Leiste traegt nur noch das, was man anfasst.
 *
 * **Eine** Lebensleiste fuer die gesamte Station, keine HP je Modul (GDD 03 Abschnitt 5).
 * Das ist keine Vereinfachung der Anzeige, sondern die Spielregel: Module koennen nicht
 * zerstoert werden, und der Schaden geht immer auf dieselbe Leiste.
 *
 * Geschrieben wird nur, wenn sich etwas geaendert hat - die Signatur unten vergleicht alles
 * Sichtbare auf einmal. Ohne sie schriebe jedes Bild dieselben Zeichenketten neu.
 */

import { on } from '../core/events.ts'
import { formatNumber } from '../core/format.ts'
import type { SpeedFactor } from '../core/loop.ts'
import { SPEED_FACTORS, WAVE_PAUSE_SECONDS } from '../data/balance.ts'
import { t } from '../data/strings.ts'
import { goToNextWave, goToPreviousWave, toggleAutoWaves } from '../app/actions.ts'
import type { GameState } from '../app/state.ts'
import { enemyById } from '../data/enemies.ts'
import { activeBoss } from '../sim/enemies.ts'
import { goldOnField } from '../sim/economy.ts'
import { CORE_UID } from '../sim/station.ts'
import { effectiveTowerStats, globalMultiplier } from '../sim/stats.ts'
import { canSkipTo, isBossWave } from '../sim/waves.ts'
import { icon, type IconName } from './icons.ts'
import type { SettingsControls } from './settings.ts'

export type HudTargets = {
  /** Schwebende Anzeigen ueber dem Spielfeld. Die einzige Ebene, die das HUD benutzt. */
  overlay: HTMLElement
}

export type Hud = {
  /**
   * Pro Bild aufrufen - schreibt nur, wenn sich etwas geaendert hat. `frameSeconds` ist
   * echte Zeit, keine Simulationszeit: Bei Tempo x4 laufen die Zahlen gleich schnell hoch.
   */
  update(frameSeconds: number): void
  detach(): void
}

export function mountHud(state: GameState, targets: HudTargets, controls: SettingsControls): Hud {
  const { overlay } = targets

  // --- Goldschild, oben links ---
  // Ein eigenes Schild statt nackter Zahlen: Gold ist die Waehrung, in der jede Entscheidung
  // dieses Spiels bezahlt wird, und war vorher als einzige Anzeige ohne Rahmen kaum als
  // Anzeige zu erkennen.
  const resources = div('plate', 'resource-bar')
  const gold = figure('coin', 22, 'res')
  const onField = figure('coin', 14, 'res', 'dim')
  onField.node.title = t('hud.onField', { amount: '' })
  resources.append(gold.node, onField.node)

  // --- Boss, oben mittig ---
  // Name, aktuelle und maximale HP (GDD 13 Abschnitt 4). Die Marke sagt, *dass* es ein
  // Boss ist, der Name sagt, *welcher* - beides braucht es, sobald es mehrere gibt (E15).
  const bossBar = div('boss-bar')
  bossBar.hidden = true
  const bossTag = document.createElement('span')
  bossTag.className = 'tag'
  bossTag.textContent = t('hud.boss')
  const bossName = document.createElement('span')
  bossName.className = 'name'
  const bossOuter = div('boss-hp')
  const bossFill = document.createElement('i')
  const bossText = document.createElement('span')
  bossOuter.append(bossFill, bossText)
  bossBar.append(bossTag, bossName, bossOuter)

  // --- Tempo, unten links im Feld ---
  const speedBar = div('speed-control')
  const slower = stepButton('-', t('settings.speed'), () => stepSpeed(-1))
  const speedValue = document.createElement('span')
  speedValue.className = 'speed-value'
  const faster = stepButton('+', t('settings.speed'), () => stepSpeed(1))
  speedBar.append(slower, speedValue, faster)

  // --- Wellenwechsel, gross ueber dem Feld ---
  const banner = div('wave-banner')

  /*
   * --- Wellenkarte, oben rechts ---
   *
   * Alles zur Welle in einem Schild: wie weit sie ist, wie hart sie zuschlaegt, und die
   * drei Knoepfe, mit denen man sie steuert. Vorher lag dieselbe Auskunft als breite Karte
   * unten in der Leiste, weit weg von allem anderen, was oben stand.
   */
  const waveCard = div('plate', 'wave-card')
  const waveHead = div('head')
  const waveLabel = document.createElement('span')
  waveLabel.className = 'wave-label'
  const scales = div('scales', 'enemy')
  const waveDamage = figure('damage', 16, 'fig')
  const waveHp = figure('hull', 16, 'fig')
  waveDamage.node.title = t('status.waveDamage')
  waveHp.node.title = t('status.waveHp')
  scales.append(waveDamage.node, waveHp.node)
  waveHead.append(waveLabel, scales)

  const progress = bar('progress')

  const waveControls = div('wave-controls')
  const previous = iconButton('prev', t('hud.prevWave'), () => goToPreviousWave(state))
  const auto = stepButton(t('hud.auto'), t('hud.autoOn'), () => toggleAutoWaves(state))
  auto.classList.add('auto-button')
  const next = iconButton('next', t('hud.nextWave'), () => goToNextWave(state))
  waveControls.append(previous, auto, next)

  waveCard.append(waveHead, progress.node, waveControls)

  /*
   * --- Rumpfleiste, unten ueber der Bedienleiste ---
   *
   * Die eine Lebensleiste der Station, geklemmt zwischen Feld und Leiste, und links und
   * rechts davon die zwei Zahlen, an denen man ablesen soll, ob ein Upgrade etwas gebracht
   * hat: Schaden des Hauptturms und Goldfaktor.
   *
   * Sie sitzt dort, weil das die Kante zwischen "Spiel" und "Bedienung" ist: Man sieht sie
   * beim Blick nach unten auf die Upgrades, ohne dass sie ins Feld ragt.
   */
  const hullBar = div('hull-bar')
  const damage = figure('bullet', 16, 'fig')
  const goldFactor = figure('coin', 16, 'fig', 'gold')
  const hp = bar('hp')
  hullBar.append(damage.node, hp.node, goldFactor.node)

  // --- Wellenkarte der Basis, oben rechts ---
  // Sie traegt auch die Stations-HP: Der Kampf laeuft in der Basis weiter (GDD 02), und
  // wer dort baut, soll nicht erst beim Zurueckwechseln merken, dass die Station faellt.
  const metaCard = div('panel', 'meta-card')
  const metaWave = metaRow(metaCard, t('hud.waveShort'))
  const metaGold = metaRow(metaCard, t('hud.gold'))
  const metaHp = bar('hp')
  metaHp.node.title = t('status.stationHp')
  metaCard.appendChild(metaHp.node)

  overlay.append(resources, waveCard, bossBar, speedBar, banner, hullBar, metaCard)

  function stepSpeed(direction: number): void {
    const index = SPEED_FACTORS.indexOf(controls.speed())
    const target = SPEED_FACTORS[Math.min(SPEED_FACTORS.length - 1, Math.max(0, index + direction))]
    if (target !== undefined) controls.setSpeed(target as SpeedFactor)
  }

  // Eingesammeltes Gold quittiert die Anzeige mit einem kurzen Puls. Die Klasse raeumt
  // das Ende der Bewegung selbst weg - schnelles Nachsammeln stoesst sie neu an.
  const stopPulse = on('gold.collected', () => restart(gold.node, 'pulse'))
  gold.node.addEventListener('animationend', () => gold.node.classList.remove('pulse'))

  // Die Lebensleiste zuckt mit dem Kern - derselbe Treffer, ueberall wo er ablesbar ist.
  const stopHitPulse = on('station.damaged', () => {
    restart(hp.node, 'hit')
    restart(metaHp.node, 'hit')
  })
  for (const node of [hp.node, metaHp.node]) {
    node.addEventListener('animationend', () => node.classList.remove('hit'))
  }

  /*
   * Der Schriftzug ueber dem Feld benennt jede Zaesur einmal und geht von selbst wieder -
   * kein Hinweisfenster (GDD 13 Abschnitt 12).
   *
   * `announced` haelt die zuletzt angesagte Welle fest. Ein verlorener Anlauf startet
   * dieselbe Welle sofort neu, und ohne diese Sperre uebermalte die Ansage "Wave 12" im
   * selben Augenblick die Meldung "Wave 12 lost" - ausgerechnet die wichtigere von beiden.
   */
  let announced = -1

  const stopBanner = on('wave.started', ({ wave }) => {
    if (wave === announced) return
    announced = wave
    banner.textContent = t('hud.wave', { wave })
    banner.classList.toggle('boss', isBossWave(wave))
    banner.classList.remove('lost')
    restart(banner, 'show')
  })

  const stopLost = on('wave.lost', ({ wave, attempt }) => {
    announced = wave
    banner.textContent = t('hud.waveLost', { wave, attempt })
    banner.classList.remove('boss')
    banner.classList.add('lost')
    restart(banner, 'show')
  })

  banner.addEventListener('animationend', () => banner.classList.remove('show'))

  // Zahlen, die auf ihren neuen Stand zulaufen. Gold springt sonst bei jedem Stapel um
  // Hunderte - man sieht dann, dass sich etwas geaendert hat, aber nicht wie viel.
  const goldCount = counter(gold.value)
  const metaGoldCount = counter(metaGold)
  const damageCount = counter(damage.value)

  let last = ''

  return {
    update(frameSeconds: number) {
      // Vor der Signaturpruefung: Die Zahlen laufen weiter, auch wenn sich sonst nichts regt.
      goldCount.step(frameSeconds)
      metaGoldCount.step(frameSeconds)
      damageCount.step(frameSeconds)

      const combat = state.runtime.combat
      const boss = activeBoss(state)
      const field = goldOnField(state)
      const plan = combat.plan
      /*
       * Der Boss steht **ausserhalb** des Wellenplans: `spawnBoss` setzt ihn zu Beginn
       * seiner Welle, `plan.spawns` kennt ihn nicht (GDD 07 Abschnitt 7). Ohne ihn im
       * Nenner meldete die Leiste "12 / 12", waehrend er noch quer ueber dem Feld stand.
       *
       * Gezaehlt wird `bossId`, nicht die Wellennummer: Ist die Obergrenze gleichzeitiger
       * Gegner erreicht, erscheint er nicht - dann darf er auch nicht mitzaehlen.
       */
      const total = (plan ? plan.spawns.length : 0) + (combat.bossId !== null ? 1 : 0)

      const signature = [
        state.run.wave,
        Math.round(combat.stationHp),
        Math.round(state.run.gold),
        Math.round(field),
        combat.phase,
        // Nur in der Pause laeuft die Uhr sichtbar - waehrend der Welle zaehlt derselbe
        // Wert die verstrichene Zeit, und die Anzeige schriebe sich in jedem Bild neu.
        combat.phase === 'pause' ? Math.round(combat.timer * 10) : 0,
        combat.killsThisWave,
        state.run.autoWaves,
        state.run.waveRecord,
        JSON.stringify(state.run.upgrades),
        controls.speed(),
        boss ? Math.round(boss.hp) : 'none',
      ].join('|')
      if (signature === last) return
      last = signature

      goldCount.to(state.run.gold)
      metaGoldCount.to(state.run.gold)
      onField.value.textContent = formatNumber(Math.floor(field))
      metaWave.textContent = formatNumber(state.run.wave)

      speedValue.textContent = t('hud.speedShort', { factor: controls.speed() })
      slower.disabled = controls.speed() === SPEED_FACTORS[0]
      faster.disabled = controls.speed() === SPEED_FACTORS[SPEED_FACTORS.length - 1]

      // Kampfwerte: der Schaden des Hauptturms und der Goldfaktor - dieselben zwei Zahlen,
      // an denen der Spieler ablesen soll, ob sich ein Upgrade gelohnt hat.
      const core = effectiveTowerStats(state, CORE_UID)
      damageCount.to(core ? core.damage : 0)
      damage.node.title = t('status.damage')
      goldFactor.value.textContent = t('hud.factor', {
        value: globalMultiplier(state.run.upgrades, 'goldBonus').toFixed(2),
      })
      goldFactor.node.title = t('status.goldFactor')

      const hpFraction = combat.maxStationHp > 0 ? combat.stationHp / combat.maxStationHp : 0
      const hpText = `${formatNumber(Math.ceil(combat.stationHp))} / ${formatNumber(combat.maxStationHp)}`
      // Zwei Orte, ein Wert: die Rumpfleiste im Kampf und die Wellenkarte der Basis.
      for (const leiste of [hp, metaHp]) {
        leiste.set(hpFraction, hpText)
        leiste.fill.classList.toggle('low', hpFraction <= 0.3)
      }
      hp.node.title = t('status.stationHp')

      waveLabel.textContent =
        combat.phase === 'pause'
          ? t('hud.wavePause', { wave: state.run.wave + 1 })
          : t('hud.wave', { wave: state.run.wave })
      waveDamage.value.textContent = plan ? plan.damageScale.toFixed(2) : formatNumber(1)
      waveHp.value.textContent = plan ? plan.hpScale.toFixed(2) : formatNumber(1)

      // In der Welle zeigt die Leiste, wie viel geschafft ist; in der Pause, wie lange sie
      // noch dauert. Sie laeuft dabei leer statt voll zu bleiben - aus toter Zeit wird
      // eine sichtbare Frist, und der Wechsel ist auch ohne Blick auf den Text erkennbar.
      const pausing = combat.phase === 'pause'
      progress.node.classList.toggle('pause', pausing)

      if (pausing) {
        const left = Math.max(0, combat.timer)
        // Ohne Auto-Modus wartet das Spiel auf den Spieler - dann laeuft keine Uhr mehr.
        const waiting = !state.run.autoWaves || left <= 0
        progress.set(
          waiting ? 0 : left / WAVE_PAUSE_SECONDS,
          waiting ? t('status.waveReady') : t('status.nextWave', { seconds: left.toFixed(1) }),
        )
      } else {
        const done = Math.min(combat.killsThisWave, total)
        progress.set(total > 0 ? done / total : 0, t('status.progress', { done, total }))
      }

      previous.disabled = !canSkipTo(state, state.run.wave - 1)
      next.disabled = state.run.wave + 1 > state.run.waveRecord + 1
      auto.classList.toggle('active', state.run.autoWaves)
      auto.title = state.run.autoWaves ? t('hud.autoOn') : t('hud.autoOff')

      bossBar.hidden = boss === null
      if (boss) {
        const def = enemyById(boss.defId)
        const fraction = boss.maxHp > 0 ? boss.hp / boss.maxHp : 0

        // Die Leiste traegt seine Farbe, nicht eine eigene - dieselbe Regel wie beim
        // Lebensbalken am Gegner: Die Anzeige gehoert sichtbar zu dem Ding auf dem Feld.
        bossBar.style.setProperty('--boss', def.color)
        bossName.textContent = def.name
        bossFill.style.width = `${clamp(fraction) * 100}%`
        bossText.textContent = `${formatNumber(Math.ceil(boss.hp))} / ${formatNumber(Math.ceil(boss.maxHp))}`
      }
    },
    detach() {
      stopPulse()
      stopHitPulse()
      stopBanner()
      stopLost()
      for (const node of [resources, waveCard, bossBar, speedBar, banner, hullBar, metaCard]) {
        node.remove()
      }
    },
  }
}

// ---------------------------------------------------------------------------
// Bausteine
// ---------------------------------------------------------------------------

/**
 * Knoten mit Klassen. Als Liste statt als eine Zeichenkette - der Selbsttest sucht in
 * `ui/` nach Spielertexten im Code, und "card wave-card" liest sich fuer ihn wie ein Satz.
 */
function div(...classes: string[]): HTMLDivElement {
  const node = document.createElement('div')
  node.classList.add(...classes)
  return node
}

/** Symbol plus Zahl - die Grundform jeder Anzeige. */
function figure(
  name: IconName,
  size: number,
  ...classes: string[]
): { node: HTMLElement; value: HTMLElement } {
  const node = document.createElement('span')
  node.classList.add(...classes)
  node.innerHTML = icon(name, size)

  const value = document.createElement('b')
  node.appendChild(value)
  return { node, value }
}

/** Leiste mit Fuellung und mittiger Beschriftung. */
function bar(className: string): {
  node: HTMLElement
  fill: HTMLElement
  set(fraction: number, text: string): void
} {
  const node = div('bar', className)
  const fill = document.createElement('i')
  const text = document.createElement('span')
  node.append(fill, text)

  return {
    node,
    fill,
    set(fraction, label) {
      fill.style.width = `${clamp(fraction) * 100}%`
      text.textContent = label
    },
  }
}

/**
 * Zahl, die auf ihren neuen Stand zulaeuft statt zu springen.
 *
 * Der Schritt haengt an der vergangenen Zeit, nicht an der Bildrate - bei 30 und bei 120
 * Bildern dauert derselbe Anstieg gleich lang. Nahe am Ziel wird aufgesetzt, sonst zappelt
 * die letzte Stelle ewig weiter.
 */
function counter(node: HTMLElement): { to(value: number): void; step(dt: number): void } {
  let shown = 0
  let target = 0
  let running = true

  return {
    to(value) {
      if (value === target) return
      target = value
      running = true
    },
    step(dt) {
      if (!running) return
      const diff = target - shown
      if (Math.abs(diff) < 0.5) {
        shown = target
        running = false
      } else {
        shown += diff * (1 - Math.exp(-dt * 14))
      }
      node.textContent = formatNumber(Math.floor(shown))
    },
  }
}

function metaRow(root: HTMLElement, label: string): HTMLElement {
  const row = div('meta-row')
  const name = document.createElement('span')
  name.textContent = label
  const value = document.createElement('b')
  row.append(name, value)
  root.appendChild(row)
  return value
}

/**
 * Eine Quittungsbewegung neu anstossen.
 *
 * Der Zwischenschritt ueber `offsetWidth` erzwingt einen Umbruch - ohne ihn setzt der
 * Browser dieselbe Klasse fort, und der zweite Treffer bliebe unsichtbar.
 */
function restart(node: HTMLElement, className: string): void {
  node.classList.remove(className)
  void node.offsetWidth
  node.classList.add(className)
}

function stepButton(text: string, title: string, onClick: () => void): HTMLButtonElement {
  const element = document.createElement('button')
  element.type = 'button'
  element.textContent = text
  element.title = title
  element.addEventListener('click', onClick)
  return element
}

/**
 * Schaltflaeche, deren Inhalt ein Symbol ist.
 *
 * Vorher waren die beiden Wellenpfeile fertige Bilddateien mit eigenem Rahmen - sie fielen
 * dadurch aus der Formensprache heraus und liessen sich nicht mitfaerben. Jetzt tragen sie
 * denselben Rahmen wie jeder andere Knopf, und das Zeichen darin nimmt die Farbe seines
 * Zustands an.
 */
function iconButton(name: IconName, title: string, onClick: () => void): HTMLButtonElement {
  const element = document.createElement('button')
  element.type = 'button'
  element.className = 'icon-button'
  element.innerHTML = icon(name, 18)
  element.title = title
  element.setAttribute('aria-label', title)
  element.addEventListener('click', onClick)
  return element
}

function clamp(value: number): number {
  return Math.max(0, Math.min(1, value))
}

/**
 * Rahmen der Oberflaeche: Bereiche, Navileiste, Panels (GDD 13 Abschnitt 3 und 4).
 *
 * Der Aufbau folgt den Entwurfsbildern:
 *
 *   Kampf                              Basis
 *   +--------------------------+       +--------------------------+
 *   |  Gold        Wellenkarte |       |       |        |  Welle   |
 *   |        Spielfeld         |       | Lager |  Feld  |  Detail  |
 *   |         Rumpfleiste      |       |       |        |  Kaufen  |
 *   +--------------------------+       +--------------------------+
 *   | Navi | Upgrade-Kacheln   |       | Navi                     |
 *   +--------------------------+       +--------------------------+
 *
 * Drei Regeln halten das zusammen:
 *   - **Der Bereich steht am `#app`**, nicht in jedem Knoten. Was sichtbar ist, entscheidet
 *     das Stilblatt ueber `[data-view]`. Deshalb muss hier nichts ein- und ausgeblendet
 *     werden, und die HUD-Anzeigen koennen stumpf weiterrechnen.
 *   - **Panels bauen sich nur auf Anforderung neu.** `refresh()` nach einer Handlung,
 *     `update()` pro Bild - sonst spraenge bei jedem eingesammelten Goldstapel die
 *     Bildlaufposition zurueck.
 *   - **Ein Bereichswechsel ist eine Bewegung, kein Schnitt** (siehe `goTo`).
 */

import { t } from '../data/strings.ts'
import { setView } from '../app/actions.ts'
import type { GameState, View } from '../app/state.ts'
import { renderInventory, renderModuleDetail, renderShop } from './base.ts'
import { icon, type IconName } from './icons.ts'
import { mountSettings, type SettingsControls } from './settings.ts'
import { mountUpgradeMenu, type UpgradeMenu } from './upgrades.ts'

export type ShellTargets = {
  /** Traegt `data-view` - daran haengt die gesamte Sichtbarkeit. */
  app: HTMLElement
  /** Schwebende Anzeigen ueber dem Spielfeld. */
  overlay: HTMLElement
  /** Untere Leiste: Navileiste und Upgrade-Panel. */
  dock: HTMLElement
}

export type Shell = {
  /** Panels neu aufbauen. Nach jeder Handlung aufrufen, nicht pro Bild. */
  refresh(): void
  /** Pro Bild aufrufen - aktualisiert nur, was sich staendig aendert. */
  update(): void
  detach(): void
}

const NAV: readonly {
  id: View
  icon: IconName
  label: 'view.combat' | 'view.base' | 'view.upgrades' | 'view.settings'
}[] = [
  { id: 'combat', icon: 'combat', label: 'view.combat' },
  { id: 'base', icon: 'base', label: 'view.base' },
  { id: 'upgrades', icon: 'upgrade', label: 'view.upgrades' },
  { id: 'settings', icon: 'gear', label: 'view.settings' },
]

/**
 * Wie lange die alten Panels abtreten, bevor die neuen auffahren.
 *
 * Kurz genug, dass der Klick sofort wirkt - der Knopf selbst quittiert im selben Bild, und
 * das Bild tritt schon zurueck. Lang genug, dass man das Abtreten als Bewegung sieht und
 * nicht als Verschwinden.
 */
const LEAVE_MS = 160

export function mountShell(
  state: GameState,
  targets: ShellTargets,
  controls: SettingsControls,
): Shell {
  const { app, overlay, dock } = targets

  // --- Ueber dem Spielfeld ---
  const title = element('h1', 'view-title')
  const inventory = element('section', 'panel', 'inventory-panel')
  const rail = element('div', 'rail')
  const detail = element('section', 'panel', 'detail-panel')
  const shop = element('section', 'panel', 'shop-panel')
  const settings = element('section', 'panel', 'settings-panel')

  // Die Wellen- und Goldkarte der Basis gehoert dem HUD - sie traegt laufende Zahlen und
  // haengt deshalb direkt in der Overlay-Ebene, nicht in dieser Spalte.
  rail.append(detail, shop)
  overlay.append(title, inventory, rail, settings)

  // --- Untere Leiste ---
  // Sie traegt nur noch, was man anfasst. Alle Zahlen stehen ueber dem Feld (siehe
  // `ui/hud.ts`) - vorher lagen sie hier und machten die Leiste doppelt so hoch.
  const dockRow = element('div', 'dock-row')
  const nav = element('nav', 'nav')
  const upgrades = element('section', 'panel', 'upgrade-panel')

  dockRow.append(nav, upgrades)
  dock.append(dockRow)

  const buttons = new Map<View, HTMLButtonElement>()
  for (const entry of NAV) {
    const button = document.createElement('button')
    button.type = 'button'
    button.className = `nav-button nav-${entry.id}`
    button.title = t(entry.label)
    button.setAttribute('aria-label', t(entry.label))
    button.innerHTML = icon(entry.icon, 30)
    button.addEventListener('click', () => goTo(entry.id))
    buttons.set(entry.id, button)
    nav.appendChild(button)
  }

  const settingsPanel = mountSettings(settings, controls)
  let menu: UpgradeMenu | null = null

  /**
   * Bereichswechsel als Bewegung.
   *
   * Drei Dinge laufen ineinander, statt dass ein Bild durch ein anderes ersetzt wird:
   *
   *   1. Der Knopf quittiert sofort - noch im selben Bild, sonst fuehlt sich der Klick
   *      taub an, egal wie schoen der Rest wird.
   *   2. Was jetzt zu sehen ist, **tritt ab**: `data-leaving` laesst jedes sichtbare Panel
   *      in die Richtung davonziehen, in der es sitzt, dabei weich werden und verblassen.
   *      Ohne diesen Schritt verschwaende das alte Bild schlagartig - genau das liest sich
   *      als Sprung.
   *   3. Gleichzeitig tritt das Spielfeld einen Wimpernschlag zurueck (`nudgeCamera`) und
   *      kommt von selbst wieder heran. Dadurch bewegt sich auch die Ebene, die bei einem
   *      Bereichswechsel eigentlich stehen bleibt, und das Ganze wirkt wie **eine**
   *      Maschine, die umschaltet, statt wie zwei Bilder.
   *
   * Erst danach wechselt der Bereich, und die neuen Panels fahren gestaffelt auf.
   * Ein zweiter Klick waehrend des Abtretens wird verworfen - sonst ueberholten sich zwei
   * Wechsel, und das Ergebnis waere genau das Ruckeln, das die Bewegung vermeiden soll.
   */
  let switching = false

  function goTo(view: View): void {
    if (switching) return
    if (state.runtime.view === view) return

    switching = true
    app.dataset['leaving'] = view
    controls.nudgeCamera()

    window.setTimeout(() => {
      delete app.dataset['leaving']
      setView(state, view)
      refresh()
      switching = false
    }, LEAVE_MS)
  }

  function refresh(): void {
    const view = state.runtime.view
    app.dataset['view'] = view
    title.textContent = t(view === 'base' ? 'view.base' : 'view.settings')

    for (const [id, button] of buttons) button.classList.toggle('active', view === id)

    // Nur der sichtbare Bereich wird aufgebaut - alles zugleich waere Arbeit fuer nichts.
    if (view === 'base') {
      renderInventory(state, inventory, refresh)
      renderModuleDetail(state, detail)
      renderShop(shop)
    } else if (view === 'combat' || view === 'upgrades') {
      if (!menu) menu = mountUpgradeMenu(state, upgrades, refresh)
      menu.setMode(view === 'upgrades' ? 'full' : 'compact')
      menu.update()
    } else if (view === 'settings') {
      settingsPanel.update()
    }
  }

  refresh()

  return {
    refresh,
    update() {
      const view = state.runtime.view
      if (view === 'combat' || view === 'upgrades') menu?.update()
    },
    detach() {
      for (const node of [title, inventory, rail, settings, dockRow]) node.remove()
    },
  }
}

/**
 * Knoten mit Klassen. Bewusst als Liste statt als eine Zeichenkette: Der Selbsttest
 * durchsucht `ui/` nach Spielertexten im Code, und "panel upgrade-panel" liest sich fuer
 * ihn wie ein Satz. Einzelne Woerter sind eindeutig technisch.
 */
function element(tag: string, ...classes: string[]): HTMLElement {
  const node = document.createElement(tag)
  node.classList.add(...classes)
  return node
}

input.new_string:
  buffLines: () => showBuffLines,
  setBuffLines(on) {
    showBuffLines = on
  },
  resetCamera: () => resetAuto(camera),
  // Knapp unter 1: Das Bild tritt einen Wimpernschlag zurueck und kommt von selbst
  // wieder. Mehr waere ein Zoom, weniger waere nicht zu sehen.
  nudgeCamera: () => pulseZoom(camera, 0.97),
}

const shell = mountShell(state, targets, controls)
const hud = mountHud(state, { overlay: targets.overlay }, controls)

input.old_string:
  buffLines: () => showBuffLines,
  setBuffLines(on) {
    showBuffLines = on
  },
  resetCamera: () => resetAuto(camera),
}

const shell = mountShell(state, targets, controls)
const hud = mountHud(state, { overlay: targets.overlay, statusRow: shell.statusRow }, controls)

input.content:
/*
 * Gestalt der Oberflaeche (GDD 13).
 *
 * Aufbau in zwei Zonen, wie in den Entwurfsbildern:
 *
 *   #field   Spielfeld. Das Canvas fuellt es ganz, Panels schweben darueber.
 *   #dock    Untere Leiste. Nur noch Navileiste und Upgrade-Kacheln - alles, was eine Zahl
 *            zeigt statt sich anfassen zu lassen, liegt als Schild ueber dem Feld.
 *
 * Was sichtbar ist, entscheidet **allein** `#app[data-view]`. Kein Skript blendet Panels
 * ein oder aus - es setzt nur den Bereich, der Rest steht hier. Damit gibt es genau eine
 * Stelle, an der man nachliest, was ein Bereich zeigt.
 *
 * Der Look ist Neon auf fast schwarzem Marineblau: dunkle Flaechen, helle Kanten, und um
 * jede helle Kante ein Schein. Das Leuchten steckt deshalb nicht in einzelnen Regeln,
 * sondern in drei Werten (`--glow-*`), die ueberall dasselbe bedeuten.
 */

:root {
  /*
   * Palette aus dem Referenzbild - dieselben Werte stehen als PALETTE in
   * src/render/theme.ts. Canvas und DOM liegen uebereinander; wer hier etwas aendert,
   * aendert es dort mit, sonst laufen Spielfeld und Oberflaeche farblich auseinander.
   */
  --ink: #070a18;
  --ink-deep: #03050d;
  --panel: #10204e;
  --panel-deep: #0a1436;
  --edge: #7fd8ff;
  --cyan: #46c8ff;
  --teal: #2ee0c0;
  --lime: #7fe83f;
  --magenta: #ff2d78;
  --gold: #ffcc33;
  --violet: #b45cff;
  --section: #29a3f5;

  /* Rollen. Im Spiel wird auf diese Namen verwiesen, nicht auf die Farben darueber. */
  --bg: var(--ink);
  --line: rgba(127, 216, 255, 0.62);
  --line-soft: rgba(127, 216, 255, 0.26);
  --text: #ffffff;
  --text-dim: #8fa8d4;
  --accent: var(--cyan);
  --ok: var(--teal);
  --fail: var(--magenta);
  --warn: var(--gold);

  /*
   * Die drei Leuchtstufen. Jede besteht aus demselben Dreiklang: eine harte Linie direkt
   * an der Kante, ein weicher Schein nach aussen, ein Schein nach innen. Erst der innere
   * macht aus einem Rahmen eine Roehre - ohne ihn sieht Neon aus wie ein blauer Strich.
   */
  --glow-soft: 0 0 0 1px rgba(70, 200, 255, 0.08), 0 0 12px rgba(70, 200, 255, 0.16),
    inset 0 0 14px rgba(70, 200, 255, 0.07);
  --glow: 0 0 0 1px rgba(70, 200, 255, 0.12), 0 0 20px rgba(70, 200, 255, 0.26),
    inset 0 0 22px rgba(70, 200, 255, 0.1);
  --glow-strong: 0 0 0 1px rgba(70, 200, 255, 0.2), 0 0 30px rgba(70, 200, 255, 0.42),
    inset 0 0 26px rgba(70, 200, 255, 0.16);

  /*
   * Tiefe. Panels liegen ueber dem Feld, Karten liegen im Panel. Ohne den Unterschied
   * wirkt die Oberflaeche flach aufgemalt statt gebaut.
   */
  --shadow-panel: 0 14px 34px rgba(3, 5, 13, 0.66);
  --shadow-card: 0 3px 10px rgba(3, 5, 13, 0.55);
  --shadow-lift: 0 10px 22px rgba(3, 5, 13, 0.7);

  /* Panelflaeche: oben etwas heller, damit die Flaeche eine Richtung hat. */
  --fill-panel: linear-gradient(170deg, rgba(24, 48, 108, 0.9), rgba(9, 17, 44, 0.94));
  --fill-card: linear-gradient(170deg, rgba(17, 34, 80, 0.9), rgba(7, 13, 36, 0.94));

  --font: 'Segoe UI', system-ui, sans-serif;
  --mono: ui-monospace, 'Cascadia Mono', 'Consolas', monospace;
  /* Zahlenschrift aus dem Anlagensatz. Nur ab 14 px verwenden - darunter zerfaellt sie. */
  --font-pixel: 'monogram', var(--mono);

  /*
   * Bewegung (GDD 13 Abschnitt 10).
   *
   * Zwei Kurven und vier Dauern, mehr braucht es nicht. `--ease-out` landet weich und
   * schiesst nie ueber - sie traegt jede Bewegung, die etwas transportiert. `--ease-spring`
   * schiesst leicht ueber und ist deshalb nur fuer Quittungen da: ein Knopf, der antwortet.
   *
   * Die Dauern sind gestaffelt, damit nicht alles gleich schnell laeuft. Genau daraus
   * entsteht Tiefe: Der Hintergrund braucht laenger als die Karte darauf, die Karte laenger
   * als ihr Zeichen.
   */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --dur-tap: 140ms;
  --dur-icon: 260ms;
  --dur-card: 380ms;
  --dur-view: 520ms;
  /* Abstand zwischen zwei benachbarten Elementen derselben Staffel. */
  --stagger: 42ms;
}

@font-face {
  font-family: 'monogram';
  src: url('/fonts/monogram.ttf') format('truetype');
  font-display: swap;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
}

button {
  font-family: inherit;
}

/* --- Zonen --------------------------------------------------------------- */

#app {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
}

#field {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
}

#stage {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

#overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

#overlay > * {
  pointer-events: auto;
}

/*
 * Die untere Leiste.
 *
 * Sie ist bewusst flach: Sie traegt nur noch Navileiste und Upgrade-Kacheln. Vorher standen
 * hier zusaetzlich zwei Statuskarten, und das Upgrade-Panel durfte 32 vh hoch werden -
 * zusammen verdeckte die Leiste fast die Haelfte des Spielfelds. Der Spieler soll die
 * Station sehen, nicht die Bedienung.
 *
 * Die helle Kante trennt Feld und Bedienung und leuchtet nach oben ins Feld hinein.
 */
#dock {
  position: relative;
  flex: 0 0 auto;
  padding: 8px 10px 10px;
  border-top: 1px solid var(--cyan);
  background: linear-gradient(180deg, rgba(16, 32, 78, 0.55), var(--ink-deep));
  box-shadow: 0 -10px 26px rgba(70, 200, 255, 0.1);
}

/* --- Sichtbarkeit je Bereich --------------------------------------------- */

.resource-bar,
.speed-control,
.hull-bar,
.wave-card,
.upgrade-panel,
.wave-banner,
.meta-card,
.inventory-panel,
.rail,
.settings-panel,
.view-title {
  display: none;
}

#app[data-view='combat'] .resource-bar,
#app[data-view='upgrades'] .resource-bar,
#app[data-view='combat'] .speed-control,
#app[data-view='upgrades'] .speed-control,
#app[data-view='combat'] .hull-bar,
#app[data-view='upgrades'] .hull-bar {
  display: flex;
}

#app[data-view='combat'] .wave-card,
#app[data-view='upgrades'] .wave-card {
  display: flex;
}

/* Der Wellenname gehoert dorthin, wo das Feld zu sehen ist - nicht ueber die Baustelle. */
#app[data-view='combat'] .wave-banner,
#app[data-view='upgrades'] .wave-banner {
  display: block;
}

#app[data-view='combat'] .upgrade-panel,
#app[data-view='upgrades'] .upgrade-panel {
  display: flex;
}

#app[data-view='base'] .meta-card,
#app[data-view='base'] .inventory-panel,
#app[data-view='base'] .rail {
  display: flex;
}

#app[data-view='settings'] .settings-panel {
  display: block;
}

#app[data-view='base'] .view-title,
#app[data-view='settings'] .view-title {
  display: block;
}

/* Die Boss-Leiste haengt an ihrem eigenen Schalter - sie gehoert nur in den Kampf. */
#app:not([data-view='combat']) .boss-bar {
  display: none;
}

/* --- Bewegung: auftreten und abtreten ------------------------------------ */

/*
 * Ein Bereichswechsel ist eine Bewegung, kein Schnitt (GDD 13 Abschnitt 10).
 *
 * Jedes Panel faehrt aus der Richtung auf, in der es sitzt, und zieht in dieselbe Richtung
 * wieder ab. Dabei laufen immer **mehrere** Groessen zugleich: Ort, Groesse, Weichzeichnung
 * und Deckkraft. Nur zu blenden liest sich als Bildwechsel; erst die Verschiebung um wenige
 * Pixel und die Skalierung von 0,985 auf 1 machen daraus eine Bewegung im Raum.
 *
 * Die Weichzeichnung ist der Teil, den man am wenigsten bewusst sieht und am meisten spuert:
 * Sie ersetzt die Bewegungsunschaerfe, die es auf einem Bildschirm nicht gibt.
 */

@keyframes enter-up {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.985);
    filter: blur(6px);
  }
}

@keyframes enter-left {
  from {
    opacity: 0;
    transform: translateX(-18px) scale(0.985);
    filter: blur(6px);
  }
}

@keyframes enter-right {
  from {
    opacity: 0;
    transform: translateX(18px) scale(0.985);
    filter: blur(6px);
  }
}

@keyframes enter-down {
  from {
    opacity: 0;
    transform: translateY(-14px) scale(0.985);
    filter: blur(6px);
  }
}

/* Mittig gesetzte Elemente behalten ihre Verschiebung, sonst springen sie aus der Mitte. */
@keyframes enter-center {
  from {
    opacity: 0;
    transform: translate(-50%, calc(-50% + 14px)) scale(0.97);
    filter: blur(8px);
  }
}

@keyframes enter-title {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(-10px);
    filter: blur(5px);
  }
}

@keyframes leave-up {
  to {
    opacity: 0;
    transform: translateY(10px) scale(0.99);
    filter: blur(5px);
  }
}

@keyframes leave-left {
  to {
    opacity: 0;
    transform: translateX(-14px) scale(0.99);
    filter: blur(5px);
  }
}

@keyframes leave-right {
  to {
    opacity: 0;
    transform: translateX(14px) scale(0.99);
    filter: blur(5px);
  }
}

@keyframes leave-down {
  to {
    opacity: 0;
    transform: translateY(-10px) scale(0.99);
    filter: blur(5px);
  }
}

@keyframes leave-center {
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.96);
    filter: blur(7px);
  }
}

@keyframes leave-title {
  to {
    opacity: 0;
    transform: translateX(-50%) translateY(-8px);
    filter: blur(5px);
  }
}

/* Karten und Listeneintraege innerhalb eines Panels - gestaffelt, siehe unten. */
@keyframes card-rise {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
    filter: blur(4px);
  }
}

@keyframes pop {
  0% {
    transform: scale(0.8);
  }
  60% {
    transform: scale(1.14);
  }
}

/* Auftritt: aus der Richtung, in der das Panel sitzt. */
.upgrade-panel,
.hull-bar {
  animation: enter-up var(--dur-view) var(--ease-out);
}

.nav {
  animation: enter-up var(--dur-view) var(--ease-out) 60ms backwards;
}

.inventory-panel {
  animation: enter-left var(--dur-view) var(--ease-out);
}

.rail,
.meta-card,
.wave-card {
  animation: enter-right var(--dur-view) var(--ease-out);
}

.resource-bar {
  animation: enter-down var(--dur-view) var(--ease-out);
}

.speed-control {
  animation: enter-up var(--dur-card) var(--ease-out) 80ms backwards;
}

.settings-panel {
  animation: enter-center var(--dur-view) var(--ease-out);
}

.view-title {
  animation: enter-title var(--dur-view) var(--ease-out);
}

/*
 * Abtritt. `data-leaving` steht am `#app`, solange der alte Bereich noch zu sehen ist
 * (siehe `goTo` in `ui/shell.ts`). Die Dauer ist kuerzer als der Auftritt: Wegtreten darf
 * schnell gehen, Ankommen soll man sehen.
 *
 * `forwards` haelt den Endzustand, damit das Panel nicht im letzten Bild noch einmal
 * aufblitzt, bevor der Bereich wirklich wechselt.
 */
#app[data-leaving] .upgrade-panel,
#app[data-leaving] .hull-bar,
#app[data-leaving] .nav {
  animation: leave-up 150ms var(--ease-out) forwards;
}

#app[data-leaving] .inventory-panel {
  animation: leave-left 150ms var(--ease-out) forwards;
}

#app[data-leaving] .rail,
#app[data-leaving] .meta-card,
#app[data-leaving] .wave-card {
  animation: leave-right 150ms var(--ease-out) forwards;
}

#app[data-leaving] .resource-bar,
#app[data-leaving] .speed-control {
  animation: leave-down 150ms var(--ease-out) forwards;
}

#app[data-leaving] .settings-panel {
  animation: leave-center 150ms var(--ease-out) forwards;
}

#app[data-leaving] .view-title {
  animation: leave-title 150ms var(--ease-out) forwards;
}

/*
 * Staffelung.
 *
 * Alle Kacheln zugleich auffahren zu lassen sieht aus wie ein Block, der eingeblendet wird.
 * Ein Versatz von rund 40 ms je Nachbar macht daraus eine Welle, die durch das Raster
 * laeuft - man liest die Reihenfolge, ohne sie zu bemerken. Ueber die achte Kachel hinaus
 * wird nicht weiter gestaffelt: Sonst warteten die letzten Eintraege einer langen Liste
 * spuerbar lange.
 */
.upgrade-grid > *,
ul.inventory > *,
.cat-tabs > * {
  animation: card-rise var(--dur-card) var(--ease-out) backwards;
}

.upgrade-grid > *:nth-child(1),
ul.inventory > *:nth-child(1),
.cat-tabs > *:nth-child(1) {
  animation-delay: 0ms;
}
.upgrade-grid > *:nth-child(2),
ul.inventory > *:nth-child(2),
.cat-tabs > *:nth-child(2) {
  animation-delay: var(--stagger);
}
.upgrade-grid > *:nth-child(3),
ul.inventory > *:nth-child(3),
.cat-tabs > *:nth-child(3) {
  animation-delay: calc(2 * var(--stagger));
}
.upgrade-grid > *:nth-child(4),
ul.inventory > *:nth-child(4),
.cat-tabs > *:nth-child(4) {
  animation-delay: calc(3 * var(--stagger));
}
.upgrade-grid > *:nth-child(5),
ul.inventory > *:nth-child(5) {
  animation-delay: calc(4 * var(--stagger));
}
.upgrade-grid > *:nth-child(6),
ul.inventory > *:nth-child(6) {
  animation-delay: calc(5 * var(--stagger));
}
.upgrade-grid > *:nth-child(7),
ul.inventory > *:nth-child(7) {
  animation-delay: calc(6 * var(--stagger));
}
.upgrade-grid > *:nth-child(n + 8),
ul.inventory > *:nth-child(n + 8) {
  animation-delay: calc(7 * var(--stagger));
}

/* Der gewaehlte Reiter quittiert den Wechsel mit einem kurzen Stupser. */
.nav-button.active .pix {
  animation: pop var(--dur-icon) var(--ease-spring);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    animation-delay: 0ms !important;
    transition-duration: 1ms !important;
  }
}

/* --- Gemeinsame Bausteine ------------------------------------------------ */

/*
 * Panel und Schild sind dasselbe in zwei Groessen: Ein Panel traegt Inhalt, ein Schild
 * traegt eine Zahl. Beide sind dunkle Flaechen mit leuchtender Kante.
 */
.panel,
.plate {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--fill-panel);
  box-shadow: var(--glow), var(--shadow-panel);
  backdrop-filter: blur(7px);
}

.panel {
  padding: 12px 14px;
  overflow-y: auto;
}

.plate {
  padding: 7px 12px;
}

.panel header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}

.panel h2 {
  margin: 0;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--edge);
  text-shadow: 0 0 10px rgba(127, 216, 255, 0.5);
}

.panel h3 {
  margin: 12px 0 4px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.panel p {
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.5;
}

.panel .slots {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--text-dim);
}

.muted {
  color: var(--text-dim);
}

.warn {
  color: var(--warn);
}

/*
 * Symbol aus dem Anlagensatz. Die Datei liefert nur die Form - die Farbe kommt aus
 * `currentColor`, damit dasselbe Zeichen je nach Bedeutung anders leuchtet.
 */
.pix {
  display: inline-block;
  flex: none;
  width: var(--pix-size, 16px);
  height: var(--pix-size, 16px);
  background-color: currentColor;
  -webkit-mask: var(--icon) center / contain no-repeat;
  mask: var(--icon) center / contain no-repeat;
}

/* Raritaetsrahmen mit Symbol darin. Pixelgenau skaliert, sonst franst der Rahmen aus. */
.tile {
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 32px;
  height: 32px;
  background: var(--frame) center / contain no-repeat;
  image-rendering: pixelated;
}

/*
 * Kleine Schaltflaeche - Tempo, Auto-Modus, Einstellungen.
 *
 * Der Rahmen leuchtet erst beim Beruehren richtig auf: Ein Knopf, der immer schon leuchtet,
 * sagt nichts mehr, wenn man ihn erreicht.
 */
.chip,
.wave-controls button,
.speed-control button {
  min-height: 30px;
  padding: 4px 11px;
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  background: rgba(10, 20, 54, 0.65);
  color: var(--text-dim);
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: color var(--dur-tap) var(--ease-out),
    border-color var(--dur-tap) var(--ease-out), box-shadow var(--dur-tap) var(--ease-out),
    transform var(--dur-tap) var(--ease-out);
}

.chip:hover:not(:disabled),
.wave-controls button:hover:not(:disabled),
.speed-control button:hover:not(:disabled) {
  color: var(--text);
  border-color: var(--line);
  box-shadow: var(--glow-soft);
}

.chip:active:not(:disabled),
.wave-controls button:active:not(:disabled),
.speed-control button:active:not(:disabled) {
  transform: scale(0.94);
}

.chip.active,
.wave-controls button.active {
  border-color: var(--lime);
  color: var(--lime);
  box-shadow: 0 0 14px rgba(127, 232, 63, 0.35), inset 0 0 12px rgba(127, 232, 63, 0.12);
  text-shadow: 0 0 8px rgba(127, 232, 63, 0.6);
}

.chip:disabled,
.wave-controls button:disabled,
.speed-control button:disabled {
  opacity: 0.28;
  cursor: default;
}

/* Schaltflaeche, deren ganzer Inhalt ein Symbol ist. */
.icon-button {
  display: grid;
  place-items: center;
  width: 34px;
  padding: 0;
}

/*
 * Leiste mit Fuellung und mittiger Beschriftung.
 *
 * Die Fuellung traegt eine laufende Schraffur aus dem Anlagensatz - dadurch sieht man auch
 * bei stehender Leiste, dass Energie darin ist, und nicht nur einen farbigen Balken.
 */
.bar {
  position: relative;
  height: 17px;
  border: 1px solid var(--line-soft);
  border-radius: 6px;
  background: rgba(3, 5, 13, 0.85);
  overflow: hidden;
}

.bar i {
  position: absolute;
  inset: 0 auto 0 0;
  display: block;
  background: var(--ok);
  box-shadow: 0 0 12px currentColor;
  transition: width 160ms var(--ease-out);
}

/* Die Schraffur laeuft langsam durch die Fuellung - Energie in Bewegung. */
.bar i::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url('/ui/bar-hatch.png') left center / auto 100% repeat-x;
  opacity: 0.35;
  mix-blend-mode: overlay;
  animation: hatch-flow 1.6s linear infinite;
}

@keyframes hatch-flow {
  to {
    background-position-x: 42px;
  }
}

.bar i.low {
  background: var(--fail);
}

.bar span {
  position: relative;
  display: block;
  width: 100%;
  font-family: var(--font-pixel);
  font-size: 15px;
  line-height: 15px;
  text-align: center;
  color: var(--text);
  text-shadow: 0 0 4px rgba(0, 0, 0, 0.9);
}

.bar.progress i {
  background: var(--cyan);
}

/*
 * In der Pause laeuft dieselbe Leiste leer statt voll - und wechselt die Farbe, damit der
 * Unterschied zwischen "so viel ist geschafft" und "so lange noch" auf einen Blick
 * erkennbar ist, ohne den Text zu lesen.
 */
.bar.progress.pause i {
  background: var(--lime);
}

/*
 * Die Lebensleiste zuckt beim Treffer - derselbe Augenblick, in dem auch das Leuchten des
 * Kerns aufschlaegt. Ein Ruck von zwei Pixeln reicht: Die Leiste soll erschrecken, nicht
 * wandern.
 */
@keyframes hp-hit {
  0% {
    transform: translateX(0);
    border-color: var(--magenta);
  }
  30% {
    transform: translateX(-2px);
    border-color: var(--magenta);
    box-shadow: 0 0 16px rgba(255, 45, 120, 0.6);
  }
  65% {
    transform: translateX(2px);
  }
  100% {
    transform: translateX(0);
  }
}

.bar.hp.hit {
  animation: hp-hit 220ms var(--ease-out);
}

/* Sektionsbalken ueber einer Liste - der breite blaue Streifen aus der Vorlage. */
.section-bar {
  padding: 5px 12px;
  background: linear-gradient(90deg, var(--section), rgba(41, 163, 245, 0.15));
  border-left: 3px solid var(--edge);
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.35);
}

/* --- Ueber dem Spielfeld ------------------------------------------------- */

.view-title {
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  font-size: 24px;
  font-weight: 800;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--edge);
  text-shadow: 0 0 24px rgba(127, 216, 255, 0.6), 0 0 6px rgba(127, 216, 255, 0.9);
}

/*
 * Das Goldschild, oben links.
 *
 * Gold ist die Waehrung, in der jede Entscheidung dieses Spiels bezahlt wird. Vorher stand
 * es als nackte Zahl ohne Rahmen da und war als Anzeige kaum zu erkennen; jetzt sitzt es
 * auf einem eigenen Schild und traegt das Muenzzeichen aus dem Anlagensatz.
 */
.resource-bar {
  position: absolute;
  top: 10px;
  left: 10px;
  flex-direction: column;
  gap: 2px;
  padding: 8px 14px 8px 10px;
}

.resource-bar .res {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--gold);
  font-family: var(--font-pixel);
  font-size: 30px;
  line-height: 1;
  text-shadow: 0 0 14px rgba(255, 204, 51, 0.55);
}

.resource-bar .res .pix {
  filter: drop-shadow(0 0 6px rgba(255, 204, 51, 0.7));
}

.resource-bar .res.dim {
  font-size: 18px;
  opacity: 0.65;
}

/*
 * Quittung fuer eingesammeltes Gold. Kurz und klein: Die Zahl laeuft ohnehin sichtbar hoch,
 * der Puls sagt nur, dass der Zuwachs gerade **jetzt** vom Feld kam.
 */
@keyframes gold-pulse {
  0% {
    transform: scale(1);
  }
  35% {
    transform: scale(1.13);
    text-shadow: 0 0 26px rgba(255, 204, 51, 0.85);
  }
  100% {
    transform: scale(1);
  }
}

.resource-bar .res.pulse {
  animation: gold-pulse var(--dur-icon) var(--ease-out);
  transform-origin: left center;
}

/*
 * Die Wellenkarte, oben rechts.
 *
 * Alles zur laufenden Welle in einem schmalen Schild: Nummer, wie hart sie zuschlaegt, wie
 * weit sie ist, und die drei Knoepfe, mit denen man sie steuert. Vorher lag dieselbe
 * Auskunft als breite Karte unten in der Leiste - weit weg von allem anderen, was oben
 * stand, und doppelt so gross wie noetig.
 */
.wave-card {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 208px;
  flex-direction: column;
  gap: 6px;
  padding: 8px 10px;
}

.wave-card .head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.wave-label {
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--edge);
  text-shadow: 0 0 12px rgba(127, 216, 255, 0.5);
  white-space: nowrap;
}

.scales {
  display: flex;
  gap: 9px;
}

/* Werte des Gegners - in der Gegnerfarbe, damit sie nicht wie eigene Werte wirken. */
.scales.enemy .fig {
  color: var(--magenta);
}

.scales .fig b {
  font-size: 14px;
}

.wave-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* Der Auto-Knopf ist der einzige mit Text und nimmt deshalb den freien Platz. */
.wave-controls .auto-button {
  flex: 1 1 auto;
}

.fig {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--cyan);
}

.fig.gold {
  color: var(--gold);
}

.fig b {
  font-family: var(--font-pixel);
  font-size: 18px;
  font-weight: 400;
  color: var(--text);
}

/*
 * Die Rumpfleiste, unten ueber der Bedienleiste.
 *
 * Sie klemmt genau auf der Kante zwischen Spiel und Bedienung: Wer nach unten auf die
 * Upgrades schaut, sieht sie mit, ohne dass sie ins Feld ragt. Links der Schaden des
 * Hauptturms, rechts der Goldfaktor - die zwei Zahlen, an denen man ablesen soll, ob ein
 * Kauf etwas gebracht hat.
 */
.hull-bar {
  position: absolute;
  left: 10px;
  right: 10px;
  bottom: 8px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.hull-bar .bar {
  flex: 1 1 auto;
  height: 19px;
}

.hull-bar .fig {
  flex: none;
  padding: 3px 9px;
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  background: rgba(6, 12, 34, 0.7);
  backdrop-filter: blur(6px);
}

.hull-bar .fig b {
  font-size: 16px;
}

.speed-control {
  position: absolute;
  left: 10px;
  bottom: 38px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.speed-control button {
  min-width: 32px;
  border-color: rgba(127, 232, 63, 0.45);
  color: var(--lime);
  font-size: 15px;
}

.speed-control .speed-value {
  min-width: 42px;
  font-family: var(--font-pixel);
  font-size: 19px;
  text-align: center;
  color: var(--text);
  text-shadow: 0 0 10px rgba(70, 200, 255, 0.5);
}

/*
 * Name der neuen Welle. Er steht kurz oben ueber dem Feld und geht von selbst wieder -
 * eine Zaesur, kein Hinweisfenster. Bewusst ohne Flaeche und ohne Rahmen: Ein Kasten mitten
 * im Bild verdeckt die Station, ein Schriftzug legt sich nur darueber.
 */
.wave-banner {
  position: absolute;
  top: 84px;
  left: 50%;
  transform: translateX(-50%);
  opacity: 0;
  font-size: 28px;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  white-space: nowrap;
  color: var(--edge);
  text-shadow: 0 0 28px rgba(127, 216, 255, 0.7), 0 0 8px rgba(127, 216, 255, 0.9);
}

.wave-banner.boss {
  color: var(--magenta);
  text-shadow: 0 0 28px rgba(255, 45, 120, 0.7), 0 0 8px rgba(255, 45, 120, 0.9);
}

/*
 * Der verlorene Anlauf. Dieselbe Stelle, dieselbe Dauer, aber in Magenta und mit einem
 * kurzen Ruck - er kostet nichts ausser Zeit (GDD 02), also ist er eine Zaesur und keine
 * Niederlage. Deshalb kein eigener Kasten und kein Abwarten.
 */
.wave-banner.lost {
  color: var(--magenta);
  text-shadow: 0 0 30px rgba(255, 45, 120, 0.75);
}

.wave-banner.lost.show {
  animation: wave-banner 1500ms var(--ease-out), banner-shake 320ms var(--ease-out);
}

@keyframes banner-shake {
  0%,
  100% {
    margin-left: 0;
  }
  20% {
    margin-left: -7px;
  }
  55% {
    margin-left: 5px;
  }
  80% {
    margin-left: -3px;
  }
}

@keyframes wave-banner {
  0% {
    opacity: 0;
    transform: translateX(-50%) translateY(14px) scale(0.94);
    filter: blur(8px);
  }
  16% {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
    filter: blur(0);
  }
  70% {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
    filter: blur(0);
  }
  100% {
    opacity: 0;
    transform: translateX(-50%) translateY(-12px) scale(1.03);
    filter: blur(5px);
  }
}

.wave-banner.show {
  animation: wave-banner 1500ms var(--ease-out);
}

/*
 * Anzeigen ohne Bedienung duerfen den Zeiger nicht abfangen - darunter wird Gold
 * eingesammelt. Der Bezug auf `#overlay` ist noetig, weil `#overlay > *` die Ebene sonst
 * pauschal wieder anschaltet.
 */
#overlay .resource-bar,
#overlay .wave-banner,
#overlay .boss-bar,
#overlay .hull-bar {
  pointer-events: none;
}

/* Der Boss faehrt auf, statt zu erscheinen: sein Auftritt bekommt einen Anlauf. */
@keyframes boss-enter {
  0% {
    opacity: 0;
    transform: translateX(-50%) translateY(-16px) scale(0.92);
    filter: blur(7px);
  }
  60% {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1.04);
    filter: blur(0);
  }
  100% {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
  }
}

/*
 * Die Boss-Leiste faerbt sich nach ihrem Boss: `--boss` setzt das HUD aus den Gegnerdaten.
 * Solange keiner lebt, gilt Magenta - die Farbe der Bedrohung.
 */
.boss-bar {
  --boss: var(--magenta);
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  animation: boss-enter 460ms var(--ease-out);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 14px;
  border: 1px solid var(--boss);
  border-radius: 10px;
  background: rgba(9, 12, 34, 0.82);
  backdrop-filter: blur(7px);
  box-shadow: 0 0 24px rgba(255, 45, 120, 0.35), inset 0 0 18px rgba(255, 45, 120, 0.12);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--boss);
}

/* Die Marke sagt, dass es ein Boss ist - der Name, welcher. */
.boss-bar .tag {
  padding: 1px 7px;
  border: 1px solid var(--boss);
  border-radius: 5px;
  font-size: 10px;
  opacity: 0.8;
}

.boss-bar .name {
  font-size: 14px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text);
}

.boss-bar[hidden] {
  display: none;
}

.boss-hp {
  position: relative;
  width: 220px;
  height: 14px;
  border: 1px solid var(--boss);
  border-radius: 5px;
  overflow: hidden;
}

.boss-hp i {
  position: absolute;
  inset: 0 auto 0 0;
  display: block;
  background: var(--boss);
  box-shadow: 0 0 12px var(--boss);
  transition: width 160ms var(--ease-out);
}

.boss-hp span {
  position: relative;
  display: block;
  font-family: var(--font-pixel);
  font-size: 14px;
  line-height: 14px;
  text-align: center;
  color: var(--text);
}

/* --- Untere Leiste: Navigation und Upgrades ------------------------------ */

.dock-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: stretch;
}

.nav {
  display: flex;
  gap: 6px;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--fill-panel);
  box-shadow: var(--glow-soft);
}

/*
 * Die Navischaltflaechen.
 *
 * Bewusst gross: Zwischen Basis und Kampf wird staendig gewechselt, das ist der haeufigste
 * Griff im ganzen Spiel. Der Rahmen kommt als Bild aus dem Anlagensatz - eine gezeichnete
 * Achteckfassung mit Eckwinkeln, die ein CSS-Rahmen nicht hinbekommt.
 */
.nav-button {
  display: grid;
  place-items: center;
  width: 62px;
  height: 62px;
  padding: 0;
  border: 0;
  background: url('/ui/frame-slot.png') center / 100% 100% no-repeat;
  color: var(--text-dim);
  cursor: pointer;
  transition: color var(--dur-tap) var(--ease-out), filter var(--dur-tap) var(--ease-out),
    transform var(--dur-tap) var(--ease-out);
}

.nav-button:hover {
  color: var(--text);
  filter: brightness(1.2);
}

.nav-button:active {
  transform: scale(0.93);
}

.nav-button.active {
  color: var(--edge);
  filter: brightness(1.45) drop-shadow(0 0 10px rgba(70, 200, 255, 0.55));
}

.nav-button.active .pix {
  filter: drop-shadow(0 0 8px rgba(127, 216, 255, 0.8));
}

/*
 * Das Upgrade-Panel.
 *
 * Feste Hoehe statt eines Anteils der Bildhoehe: Vorher durfte es 32 vh hoch werden und
 * verdeckte auf einem hohen Fenster ein Drittel des Spielfelds. Vier Kategorien mit je drei
 * Pfaden passen in zwei Reihen - mehr Hoehe braucht es nicht, und was nicht passt, rollt.
 */
.upgrade-panel {
  flex-direction: column;
  gap: 0;
  max-height: 164px;
  padding: 0;
  overflow: hidden;
}

.cat-tabs {
  display: flex;
  gap: 5px;
  padding: 6px 8px;
  border-bottom: 1px solid var(--line-soft);
}

.cat-tab {
  padding: 3px 10px;
  border: 1px solid var(--line-soft);
  border-radius: 7px;
  background: rgba(10, 20, 54, 0.6);
  color: var(--text-dim);
  font: inherit;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color var(--dur-tap) var(--ease-out),
    border-color var(--dur-tap) var(--ease-out), box-shadow var(--dur-tap) var(--ease-out);
}

.cat-tab:hover {
  color: var(--text);
  border-color: var(--line);
}

.cat-tab.active {
  border-color: var(--accent);
  color: var(--accent);
  box-shadow: 0 0 14px rgba(70, 200, 255, 0.3), inset 0 0 10px rgba(70, 200, 255, 0.12);
  text-shadow: 0 0 8px currentColor;
}

/* In der vollen Ansicht steht jede Kategorie untereinander - die Reiter entfallen. */
.upgrade-panel.wide {
  max-height: 42vh;
}

.upgrade-panel.wide .cat-tabs {
  display: none;
}

.cat-body {
  overflow-y: auto;
}

.upgrade-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  padding: 8px;
}

.upgrade-card {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 9px;
  padding: 7px 9px;
  border: 1px solid var(--line-soft);
  border-radius: 9px;
  background: var(--fill-card);
  box-shadow: var(--shadow-card);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform var(--dur-tap) var(--ease-out),
    box-shadow var(--dur-tap) var(--ease-out), border-color var(--dur-tap) var(--ease-out);
}

.upgrade-card.affordable {
  border-color: var(--line);
  box-shadow: var(--glow-soft), var(--shadow-card);
}

/* Bezahlbar und unter dem Zeiger: die Kachel hebt sich aus dem Panel heraus. */
.upgrade-card:hover.affordable {
  transform: translateY(-2px);
  border-color: var(--accent);
  box-shadow: var(--glow), var(--shadow-lift);
}

.upgrade-card:active.affordable {
  transform: translateY(0) scale(0.98);
  box-shadow: var(--shadow-card);
}

.upgrade-card:disabled {
  opacity: 0.42;
  box-shadow: none;
  cursor: default;
}

/*
 * Quittung fuer einen Kauf. Die Klasse setzt `ui/upgrades.ts`, weg nimmt sie das Ende der
 * Bewegung selbst - so braucht die Quittung keine Uhr.
 */
@keyframes bought {
  0% {
    border-color: var(--lime);
    box-shadow: 0 0 0 rgba(127, 232, 63, 0.6);
    transform: scale(1);
  }
  30% {
    border-color: var(--lime);
    box-shadow: 0 0 26px rgba(127, 232, 63, 0.7), inset 0 0 18px rgba(127, 232, 63, 0.25);
    transform: scale(1.04);
  }
  100% {
    box-shadow: var(--shadow-card);
    transform: scale(1);
  }
}

.upgrade-card.bought {
  animation: bought 440ms var(--ease-out);
}

.upgrade-card .label {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--accent);
}

.upgrade-card .label span {
  color: var(--text);
}

.upgrade-card .value-box {
  display: grid;
  min-width: 72px;
  border: 1px solid var(--line-soft);
  border-radius: 6px;
  overflow: hidden;
  text-align: center;
}

.upgrade-card .value {
  padding: 1px 6px;
  font-family: var(--font-pixel);
  font-size: 17px;
  color: var(--text);
}

.upgrade-card .cost {
  padding: 1px 6px;
  border-top: 1px solid var(--line-soft);
  background: rgba(3, 5, 13, 0.5);
  font-family: var(--font-pixel);
  font-size: 15px;
  color: var(--cyan);
}

/*
 * Jede Kategorie faerbt Reiter und Kachelsymbole in der Farbe, in der ihr Turm auf dem
 * Feld leuchtet. Den Wert setzt `ui/upgrades.ts` als `--accent` am Reiter und am Abschnitt;
 * hier steht nur, was gilt, solange keiner gesetzt ist.
 */
.cat-tab,
.cat-section {
  --accent: var(--cyan);
}

/* --- Basis --------------------------------------------------------------- */

.inventory-panel {
  position: absolute;
  top: 54px;
  left: 10px;
  bottom: 10px;
  width: 228px;
  flex-direction: column;
}

.rail {
  position: absolute;
  top: 138px;
  right: 10px;
  bottom: 10px;
  width: 250px;
  flex-direction: column;
  gap: 10px;
}

.rail .detail-panel {
  flex: 1 1 auto;
  min-height: 0;
}

/* Der Kaufbereich sitzt unten rechts - genau dort, wo ihn der Entwurf zeigt. */
.rail .shop-panel {
  flex: 0 0 auto;
}

.meta-card {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 250px;
  flex-direction: column;
  gap: 5px;
  padding: 10px 12px;
}

.meta-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.meta-row span {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.meta-row b {
  font-family: var(--font-pixel);
  font-size: 23px;
  font-weight: 400;
  color: var(--text);
  text-shadow: 0 0 12px rgba(70, 200, 255, 0.35);
}

/* Die Lebensleiste schliesst die Karte ab - etwas Luft trennt sie von den Zahlen. */
.meta-card .bar {
  margin-top: 4px;
}

.wide-button {
  width: 100%;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--fill-card);
  box-shadow: var(--glow-soft);
  color: var(--text);
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
  transition: box-shadow var(--dur-tap) var(--ease-out),
    transform var(--dur-tap) var(--ease-out);
}

.wide-button:hover:not(:disabled) {
  box-shadow: var(--glow);
  transform: translateY(-1px);
}

.wide-button:active:not(:disabled) {
  transform: scale(0.98);
}

.wide-button:disabled {
  opacity: 0.38;
  box-shadow: none;
  cursor: default;
}

ul.inventory {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

ul.inventory .card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 2px 10px;
  padding: 7px 9px;
  border: 1px solid var(--line-soft);
  border-radius: 10px;
  background: var(--fill-card);
  box-shadow: var(--shadow-card);
  cursor: pointer;
  transition: transform var(--dur-tap) var(--ease-out),
    box-shadow var(--dur-tap) var(--ease-out), border-color var(--dur-tap) var(--ease-out);
}

ul.inventory .card:hover {
  transform: translateY(-2px);
  border-color: var(--line);
  box-shadow: var(--glow-soft), var(--shadow-lift);
}

ul.inventory .card:active {
  transform: translateY(0) scale(0.99);
  box-shadow: var(--shadow-card);
}

ul.inventory .card.active {
  border-color: var(--accent);
  box-shadow: var(--glow), var(--shadow-card);
}

ul.inventory .tile {
  grid-row: 1 / 3;
}

ul.inventory .name {
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
}

ul.inventory .rarity {
  font-size: 11px;
  font-weight: 700;
  color: var(--rarity, var(--text-dim));
  text-shadow: 0 0 10px currentColor;
}

ul.inventory .shape {
  grid-column: 2 / -1;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
}

.detail-panel header {
  align-items: center;
  gap: 10px;
}

.detail-panel h2 {
  flex: 1 1 auto;
}

.detail-panel .rarity {
  font-size: 11px;
  font-weight: 700;
  color: var(--rarity, var(--text-dim));
}

table.stats {
  width: 100%;
  margin-top: 10px;
  border-collapse: collapse;
  font-size: 12px;
}

table.stats th {
  padding: 2px 0;
  font-weight: 400;
  text-align: left;
  color: var(--text-dim);
}

table.stats td {
  padding: 2px 0 2px 6px;
  font-family: var(--mono);
  text-align: right;
  white-space: nowrap;
}

table.stats .arrow {
  padding: 0 4px;
  color: var(--text-dim);
}

table.stats .final {
  color: var(--ok);
}

table.stats em {
  font-size: 10px;
  font-style: normal;
  color: var(--warn);
}

ul.sources {
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
  color: var(--text-dim);
}

ul.sources li {
  padding: 1px 0;
}

/* --- Einstellungen ------------------------------------------------------- */

.settings-panel {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(420px, calc(100% - 24px));
}

.setting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 8px 0;
  border-bottom: 1px solid var(--line-soft);
}

.setting .label {
  font-size: 13px;
  color: var(--text);
}

.setting .chips {
  display: flex;
  gap: 6px;
}

/* --- Hinweise, Entwickleranzeige, Selbsttest ----------------------------- */

.tooltip {
  position: fixed;
  z-index: 20;
  max-width: 260px;
  padding: 6px 9px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(10, 20, 54, 0.94);
  box-shadow: var(--glow-soft);
  color: var(--text);
  font-size: 12px;
  line-height: 1.45;
  pointer-events: none;
}

.tooltip[hidden] {
  display: none;
}

/* Nur mit ?debug sichtbar - im normalen Bild hat sie nichts verloren. */
.devbar {
  position: absolute;
  bottom: 64px;
  left: 12px;
  padding: 8px 12px;
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  background: rgba(10, 20, 54, 0.9);
  color: var(--text-dim);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.7;
  letter-spacing: 0.02em;
}

.devbar b {
  color: var(--accent);
  font-weight: 600;
}

.devbar .hint {
  color: rgba(143, 168, 212, 0.6);
}

.report {
  position: fixed;
  inset: 0;
  z-index: 40;
  overflow: auto;
  padding: 32px clamp(16px, 5vw, 64px) 64px;
  background: var(--bg);
  font-family: var(--mono);
  font-size: 13px;
  line-height: 1.6;
}

.report h1 {
  margin: 0 0 4px;
  font-size: 20px;
  letter-spacing: 0.12em;
  color: var(--text);
}

.report .summary {
  margin-bottom: 24px;
  font-size: 15px;
}

.report .summary.ok {
  color: var(--ok);
}

.report .summary.fail {
  color: var(--fail);
}

.report h2 {
  margin: 24px 0 6px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.report ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.report li {
  padding: 2px 0 2px 22px;
  text-indent: -22px;
}

.report li.ok::before {
  content: '+  ';
  color: var(--ok);
}

.report li.fail {
  color: var(--fail);
}

.report li.fail::before {
  content: 'x  ';
}

.report pre {
  margin: 2px 0 8px 22px;
  color: var(--fail);
  text-indent: 0;
  white-space: pre-wrap;
  opacity: 0.85;
}

/* --- Breite Fenster ------------------------------------------------------ */

/*
 * Ab hier ist Platz fuer vier Kacheln nebeneinander - so steht es im Entwurf der unteren
 * Leiste. Darunter bleibt es bei zwei: Eine Kachel unter 150 Pixeln Breite kann ihren
 * Namen und ihren Preis nicht mehr nebeneinander zeigen.
 */
@media (min-width: 900px) {
  .upgrade-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

/* --- Schmale Fenster ----------------------------------------------------- */

@media (max-width: 900px) {
  .inventory-panel {
    width: 190px;
  }

  .rail,
  .meta-card {
    width: 210px;
  }

  .wave-card {
    width: 190px;
  }
}

/*
 * Sehr schmal wird aus dem Nebeneinander ein Untereinander - und die Navileiste rutscht
 * ganz nach unten, wie die Reiterleiste eines Telefonspiels. Bliebe sie in der Zeile,
 * schrumpfte das Upgrade-Panel auf eine Spalte Restbreite, und genau die Kacheln sind das,
 * was der Spieler waehrend einer Welle braucht.
 */
