48	  'boss.killed': { wave: number }
49	}
50	
51	export type EventName = keyof EventMap
52	export type EventHandler<K extends EventName> = (payload: EventMap[K]) => void
53	export type Unsubscribe = () => void
54	
55	type HandlerSet = Set<(payload: unknown) => void>
56	
57	const handlers = new Map<EventName, HandlerSet>()
58	
59	/**
60	 * Ein Fehler in einem Zuhoerer darf niemals das Bild anhalten. Er wird gemeldet und
61	 * der naechste Zuhoerer laeuft weiter. Tests koennen die Meldung umlenken.
62	 */
63	let reportError: (name: EventName, error: unknown) => void = (name, error) => {
64	  console.error(`[events] Zuhoerer fuer "${name}" ist gescheitert:`, error)
65	}
66	
67	export function on<K extends EventName>(name: K, handler: EventHandler<K>): Unsubscribe {
68	  let set = handlers.get(name)
69	  if (!set) {
70	    set = new Set()
71	    handlers.set(name, set)
72	  }
73	  const erased = handler as (payload: unknown) => void
74	  set.add(erased)
75	  return () => {
76	    set.delete(erased)
77	  }
78	}
79	
80	export function emit<K extends EventName>(name: K, payload: EventMap[K]): void {
81	  const set = handlers.get(name)
82	  if (!set || set.size === 0) return
83	  // Kopie: ein Zuhoerer darf sich waehrend der Zustellung abmelden.
84	  for (const handler of [...set]) {
85	    try {
86	      handler(payload)
87	    } catch (error) {
88	      reportError(name, error)
89	    }
90	  }
91	}
92	
93	export function listenerCount(name: EventName): number {
94	  return handlers.get(name)?.size ?? 0
95	}
96	
97	/** Alle Zuhoerer entfernen. Wird zwischen Selbsttests gebraucht. */
98	export function resetEvents(): void {
99	  handlers.clear()
100	}
101	
102	/** Fehlerbehandlung umlenken - im Selbsttest, damit erwartete Fehler nicht die Konsole fluten. */
103	export function setEventErrorReporter(reporter: (name: EventName, error: unknown) => void): void {
104	  reportError = reporter
105	}
