/**
 * Laufende Faehigkeiten anwenden (GDD 09 Teil B).
 *
 * Der Bonus kommt als fertige Zahl aus `runtime.combat` - `sim/abilities.ts` legt ihn dort
 * je Takt ab. Diese Datei fragt die Faehigkeiten also nicht, sie liest nur ab; sonst
 * entstuende ein Kreis zwischen Werten, Kampf und Faehigkeiten.
 *
 * Sie stehen **nach** den Perks und vor den Buffs: Eine Faehigkeit ist die kurzfristigste
 * aller Quellen, und was zuletzt dazukommt, soll auf allem anderen aufsetzen.
 */
export function applyAbilities(base: CombatStats, state: GameState): CombatStats {
  const bonus = state.runtime.combat.abilityBonus
  const result = { ...base }
  for (const key of STAT_KEYS) {
    const amount = bonus[key]
    if (amount !== undefined && amount !== 0) result[key] = base[key] * (1 + amount)
  }
  return result
}

/** Buffs anwenden: Endwert = Wert x (1 + gedeckelte Summe). */
export function applyBuffs(base: CombatStats, buffs: BuffResult | undefined): CombatStats {

const base = baseStats(module.defId, module.kind, module.rarity)
const upgraded = state
  ? applyAbilities(applyPerks(applyUpgrades(base, module, state.run.upgrades), state), state)
  : base
return { base, upgraded, final: applyBuffs(upgraded, buffs) }

