// ---------------------------------------------------------------------------
// Level und Perks (GDD 09 Teil A)
// ---------------------------------------------------------------------------

/**
 * Einen der drei angebotenen Perks annehmen.
 *
 * Die Pruefung - steht ueberhaupt ein Aufstieg offen, gehoert der Perk zum Angebot - liegt
 * in `sim/progression.ts`. Hier steht nur, was danach passiert: Mehr Stations-HP sollen
 * sofort wirken, nicht erst ab der naechsten Welle, genau wie bei einem Upgrade.
 */
export function takePerk(state: GameState, perkId: string): boolean {
  if (!choosePerk(state, perkId)) return false
  applyStationHpChange(state)
  markDirty(state)
  return true
}

// ---------------------------------------------------------------------------
// Faehigkeiten (GDD 09 Teil B)
// ---------------------------------------------------------------------------

/** Eine Faehigkeit mit Gold freischalten. */
export function buyAbility(state: GameState, id: string): boolean {
  return unlockAbility(state, id)
}

/** Eine freigeschaltete Faehigkeit auf einen Slot legen oder von ihm nehmen. */
export function toggleAbilitySlot(state: GameState, id: string): boolean {
  return toggleEquipped(state, id)
}

/**
 * Eine Faehigkeit zuenden.
 *
 * **Nur in der Kampfansicht** (GDD 09 Abschnitt 7): Die Basis bleibt Verwaltungsbereich,
 * auch wenn der Kampf dort weiterlaeuft. Die Regel steht hier und nicht in `sim/`, weil
 * sie von der Ansicht abhaengt - und Ansichten kennt die Simulation nicht.
 */
export function fireAbility(state: GameState, id: string): boolean {
  if (state.runtime.view !== 'combat') return false
  return activateAbility(state, id)
}

/**
 * Die Huelle an einen neuen Hoechstwert anpassen.
 *
 * Wird der Hoechstwert groesser, waechst die aktuelle Huelle um denselben Betrag mit -
 * sonst kaufte man sich mehr Leben und stuende trotzdem gleich knapp da. Wird er kleiner,
 * bleibt die aktuelle Huelle stehen und `healStationFull` zieht sie bei der naechsten
 * Welle nach.
 */
function applyStationHpChange(state: GameState): void {
  const combat = state.runtime.combat
  const previousMax = combat.maxStationHp
  combat.maxStationHp = maxStationHp(state)
  if (combat.maxStationHp > previousMax) combat.stationHp += combat.maxStationHp - previousMax
}

// ---------------------------------------------------------------------------
// Wellensteuerung (GDD 07 Abschnitt 10)
// ---------------------------------------------------------------------------

input.content:
/**
 * Fenster, die den Spieler um eine Entscheidung bitten (GDD 13 Abschnitt 6).
 *
 * Bisher genau eines: die Perk-Auswahl beim Levelaufstieg. Turmkauf (E12), Ereignisse
 * (E16) und die Rueckkehr-Zusammenfassung (E17) kommen hier dazu.
 *
 * Zwei Entscheidungen praegen dieses Fenster:
 *
 * **Es haelt das Spiel nicht an.** Die Welle laeuft weiter, Gegner laufen weiter, Gold
 * faellt weiter. Das Spiel ist ein Idle-Spiel; ein Fenster, das alles einfriert, waere ein
 * Fremdkoerper - und wer gerade nicht waehlen will, soll weiterspielen koennen. Offene
 * Aufstiege stapeln sich von selbst (GDD 09 Abschnitt 2).
 *
 * **Es ist in jedem Bereich sichtbar.** Ein Aufstieg ist Fortschritt des Spielers, kein
 * Vorgang der Kampfansicht. Wer beim Bauen aufsteigt, soll seine Karten dort bekommen und
 * nicht erst beim Zurueckwechseln.
 */

import { t } from '../data/strings.ts'
import type { PerkDef } from '../data/perks.ts'
import { takePerk } from '../app/actions.ts'
import type { GameState } from '../app/state.ts'
import { currentOffer, pendingLevelUps, perkCount } from '../sim/progression.ts'
import { RARITY_COLOR } from '../render/theme.ts'

export type Dialogs = {
  /** Pro Bild aufrufen - baut nur neu, wenn sich das Angebot geaendert hat. */
  update(): void
  detach(): void
}

export function mountDialogs(
  state: GameState,
  overlay: HTMLElement,
  onChange: () => void,
): Dialogs {
  const backdrop = document.createElement('div')
  backdrop.className = 'levelup-backdrop'
  backdrop.hidden = true

  const panel = document.createElement('section')
  panel.className = 'panel levelup-panel'

  const title = document.createElement('h2')
  const hint = document.createElement('p')
  hint.className = 'muted'
  const cards = document.createElement('div')
  cards.className = 'perk-grid'
  const more = document.createElement('p')
  more.className = 'levelup-more'

  panel.append(title, hint, cards, more)
  backdrop.appendChild(panel)
  overlay.appendChild(backdrop)

  /**
   * Woran erkannt wird, dass sich etwas geaendert hat.
   *
   * Die Karten duerfen nicht in jedem Bild neu entstehen - sonst setzt der Browser die
   * Auftrittsbewegung staendig neu an, und ein Klick traefe eine Schaltflaeche, die es im
   * naechsten Augenblick nicht mehr gibt.
   */
  let last = ''

  function update(): void {
    const pending = pendingLevelUps(state)
    const offer = pending > 0 ? currentOffer(state) : []
    const signature = `${pending}|${offer.map((perk) => perk.id).join(',')}`
    if (signature === last) return
    last = signature

    backdrop.hidden = pending === 0
    if (pending === 0) {
      cards.replaceChildren()
      return
    }

    // Die erreichte Stufe ist die, fuer die gerade gewaehlt wird - also die naechste nach
    // der zuletzt abgeholten, nicht die hoechste erreichte. Sonst stuende bei drei offenen
    // Aufstiegen dreimal dieselbe Zahl.
    title.textContent = t('levelup.title', { level: state.run.level + 1 })
    hint.textContent = t('levelup.hint')
    more.textContent = pending > 1 ? t('levelup.more', { count: pending - 1 }) : ''

    cards.replaceChildren()
    for (const perk of offer) cards.appendChild(card(state, perk, onChange))
  }

  update()

  return {
    update,
    detach() {
      backdrop.remove()
    },
  }
}

/**
 * Eine Perk-Karte.
 *
 * Der Rahmen traegt die Farbe der Seltenheit - dieselbe Sprache wie bei Tuermen im Lager
 * und auf der Bauflaeche (GDD 13 Abschnitt 7). Ein legendaerer Perk ist damit schon zu
 * erkennen, bevor man seinen Text gelesen hat.
 */
function card(state: GameState, perk: PerkDef, onChange: () => void): HTMLElement {
  const button = document.createElement('button')
  button.type = 'button'
  button.className = 'perk-card'
  button.style.setProperty('--rarity', RARITY_COLOR[perk.rarity])

  const name = document.createElement('span')
  name.className = 'perk-name'
  name.textContent = perk.label

  const rarity = document.createElement('span')
  rarity.className = 'perk-rarity'
  rarity.textContent = t(rarityKey(perk.rarity))

  button.append(name, rarity)

  // Wie oft man diesen Perk schon hat. Bei einem Angebot, das sich wiederholen darf, ist
  // das die Auskunft, die den Unterschied zwischen "neu" und "noch mehr davon" macht.
  const owned = perkCount(state, perk.id)
  if (owned > 0) {
    const taken = document.createElement('span')
    taken.className = 'perk-taken'
    taken.textContent = t('levelup.taken', { count: owned })
    button.appendChild(taken)
  }

  button.addEventListener('click', () => {
    if (!takePerk(state, perk.id)) return
    onChange()
  })

  return button
}

function rarityKey(
  rarity: PerkDef['rarity'],
): 'rarity.common' | 'rarity.rare' | 'rarity.epic' | 'rarity.legendary' | 'rarity.mythic' {
  return `rarity.${rarity}` as const
}

