/**
 * Beweis aus E10.
 *
 * Der Plan verlangt: "Perk-Effekte erscheinen in `effectiveTowerStats`, nicht als Sonderfall
 * im Kampfcode." Genau das prueft die Haelfte dieser Datei - ein Perk wird gewaehlt, und
 * danach muss der Wert **auf demselben Weg** herauskommen, den auch Upgrades und Buffs
 * nehmen. Waere er anderswo eingerechnet, ginge er bei jeder spaeteren Quelle (Prestige)
 * verloren, und niemand faende den Grund.
 *
 * Die andere Haelfte sichert die Entscheidung ab, dass Erfahrung **nie verbraucht** wird:
 * Die Stufe ist abgeleitet, `run.level` zaehlt nur die abgeholten Perks. Diese Trennung ist
 * die Stelle, an der die beiden Zahlen auseinanderlaufen koennten - also wird sie geprueft.
 */

import { assert, assertClose, assertEqual, check, suite } from '../../core/assert.ts'
import { MAX_LEVEL, PERK_CHOICES, XP_BASE } from '../../data/balance.ts'
import { PERKS, perkById } from '../../data/perks.ts'
import { takePerk } from '../../app/actions.ts'
import { createInitialState, type GameState } from '../../app/state.ts'
import { invalidateStationView, resetStationViewCache, stationView } from '../../app/view.ts'
import { syncStation } from '../../sim/battle.ts'
import { createCombatState } from '../../sim/combat.ts'
import {
  cumulativeXp,
  currentLevel,
  currentOffer,
  levelFromXp,
  levelProgress,
  offerPerks,
  pendingLevelUps,
  perkCount,
  perkStatBonus,
  xpForLevel,
} from '../../sim/progression.ts'
import { createRng } from '../../core/rng.ts'
import { effectiveTowerStats, globalMultiplier, maxStationHp } from '../../sim/stats.ts'
import { CORE_UID } from '../../sim/station.ts'

function rig(): GameState {
  resetStationViewCache()
  const state = createInitialState(4711)
  state.runtime.combat = createCombatState()
  invalidateStationView(state)
  const view = stationView(state)
  syncStation(state, view.modules, view.buffs)
  return state
}

/** Erfahrung so weit hochsetzen, dass genau `count` Aufstiege offen sind. */
function raiseTo(state: GameState, level: number): void {
  state.run.xp = cumulativeXp(level)
}

export function progressionSuite(): void {
  suite('sim/progression')

  check('die Kurve trifft den Richtwert fuer Stufe 1 (GDD 09 Abschnitt 2)', () => {
    assertEqual(xpForLevel(1), XP_BASE)
  })

  check('jede Stufe kostet mehr als die vorige', () => {
    for (let level = 1; level < 60; level++) {
      assert(
        xpForLevel(level + 1) > xpForLevel(level),
        `Stufe ${level + 1} muss teurer sein als ${level}`,
      )
    }
  })

  check('die Richtwerte fuer Stufe 10 und 50 liegen unter zehn Prozent daneben', () => {
    // GDD 09 Abschnitt 2 nennt 5.000 und 100.000 ausdruecklich als Richtwerte. Ein reines
    // Potenzgesetz kann beide nicht exakt treffen - der gewaehlte Exponent verteilt den
    // Fehler, statt einen Wert exakt zu nehmen und den anderen um ein Fuenftel zu verfehlen.
    assert(Math.abs(xpForLevel(10) - 5000) / 5000 < 0.1, `Stufe 10: ${xpForLevel(10)}`)
    assert(Math.abs(xpForLevel(50) - 100000) / 100000 < 0.1, `Stufe 50: ${xpForLevel(50)}`)
  })

  check('die Summe der Schwellen ist die Schwelle der Summe', () => {
    let sum = 0
    for (let level = 1; level <= 40; level++) {
      assertEqual(cumulativeXp(level), sum, `bis Stufe ${level}`)
      sum += xpForLevel(level)
    }
  })

  check('Stufe 1 kostet nichts - dort beginnt jeder Run', () => {
    assertEqual(cumulativeXp(1), 0)
    assertEqual(levelFromXp(0), 1)
  })

  check('die Stufe folgt der Erfahrung, genau an der Schwelle', () => {
    for (const level of [2, 3, 7, 12, 25]) {
      const need = cumulativeXp(level)
      assertEqual(levelFromXp(need - 1), level - 1, `knapp unter Stufe ${level}`)
      assertEqual(levelFromXp(need), level, `genau auf Stufe ${level}`)
    }
  })

  check('kaputte Erfahrung bringt die Suche nicht zum Stehen', () => {
    // Eine Sicherheitsgrenze, keine Spielregel: Ohne sie liefe die Schleife bei einem
    // manipulierten Spielstand praktisch endlos.
    assertEqual(levelFromXp(Number.MAX_VALUE), MAX_LEVEL)
    assertEqual(levelFromXp(Number.NaN), 1)
    assertEqual(levelFromXp(-5), 1)
  })

  check('Erfahrung wird nie verbraucht - die Stufe ist abgeleitet', () => {
    const state = rig()
    raiseTo(state, 4)
    const before = state.run.xp

    assertEqual(currentLevel(state), 4)
    assertEqual(pendingLevelUps(state), 3, 'drei Aufstiege warten auf ihre Auswahl')

    const offer = currentOffer(state)
    assert(takePerk(state, (offer[0] as { id: string }).id), 'die erste Wahl muss greifen')

    assertEqual(state.run.xp, before, 'die Wahl kostet keine Erfahrung')
    assertEqual(currentLevel(state), 4, 'die erreichte Stufe bleibt')
    assertEqual(pendingLevelUps(state), 2, 'ein Aufstieg ist abgeholt')
  })

  check('mehrere Aufstiege stapeln sich (GDD 09 Abschnitt 2)', () => {
    const state = rig()
    raiseTo(state, 6)
    assertEqual(pendingLevelUps(state), 5)

    for (let i = 0; i < 5; i++) {
      const offer = currentOffer(state)
      assertEqual(offer.length, PERK_CHOICES, `Angebot ${i + 1}`)
      takePerk(state, (offer[0] as { id: string }).id)
    }
    assertEqual(pendingLevelUps(state), 0)
    assertEqual(state.run.perks.length, 5)
  })

  check('ohne offenen Aufstieg gibt es kein Angebot und keine Wahl', () => {
    const state = rig()
    assertEqual(pendingLevelUps(state), 0)
    assertDeepEqualLength(currentOffer(state), 0)
    assertEqual(takePerk(state, PERKS[0]!.id), false, 'ohne Aufstieg keine Wahl')
    assertEqual(state.run.perks.length, 0)
  })

  check('nur was im Angebot steht, kann gewaehlt werden', () => {
    const state = rig()
    raiseTo(state, 2)
    const offer = currentOffer(state).map((perk) => perk.id)
    const outside = PERKS.find((perk) => !offer.includes(perk.id))

    assert(outside !== undefined, 'es muss einen Perk ausserhalb des Angebots geben')
    assertEqual(takePerk(state, outside.id), false, 'ausserhalb des Angebots wird abgelehnt')
    assertEqual(pendingLevelUps(state), 1, 'der Aufstieg bleibt offen')
  })

  check('das Angebot bleibt stehen, bis gewaehlt wurde', () => {
    const state = rig()
    raiseTo(state, 2)
    const first = currentOffer(state).map((perk) => perk.id)
    const second = currentOffer(state).map((perk) => perk.id)
    assertEqual(first.join(','), second.join(','), 'zweimal fragen wuerfelt nicht neu')
    assertEqual(state.run.perkOffer.join(','), first.join(','), 'es steht im Spielstand')
  })

  check('ein Angebot enthaelt keine Doppel', () => {
    const rng = createRng(9)
    for (let round = 0; round < 200; round++) {
      const offer = offerPerks(rng)
      assertEqual(offer.length, PERK_CHOICES)
      assertEqual(new Set(offer.map((perk) => perk.id)).size, PERK_CHOICES, `Runde ${round}`)
    }
  })

  check('seltene Perks erscheinen seltener als gewoehnliche', () => {
    const rng = createRng(1234)
    let common = 0
    let legendary = 0
    for (let round = 0; round < 4000; round++) {
      for (const perk of offerPerks(rng, 1)) {
        if (perk.rarity === 'common') common += 1
        if (perk.rarity === 'legendary') legendary += 1
      }
    }
    assert(common > legendary * 5, `gewoehnlich ${common} gegen legendaer ${legendary}`)
    assert(legendary > 0, 'legendaer darf nicht unmoeglich sein')
  })

  // -------------------------------------------------------------------------
  // Wirkung - die eigentliche Abnahmebedingung der Etappe
  // -------------------------------------------------------------------------

  check('ein Perk erscheint in effectiveTowerStats, nicht als Sonderfall', () => {
    const state = rig()
    const before = effectiveTowerStats(state, CORE_UID)
    assert(before !== null, 'der Kern muss Werte haben')

    // Direkt gesetzt statt gewaehlt: Der Test prueft die **Wirkung**, nicht den Weg dorthin.
    state.run.perks.push('perk.damage.1')

    const after = effectiveTowerStats(state, CORE_UID)
    assert(after !== null, 'der Kern muss weiterhin Werte haben')
    assertClose(
      after.damage,
      before.damage * (1 + perkById('perk.damage.1').effect.amount),
      1e-9,
      'der Schaden muss durch dieselbe Kette laufen',
    )
  })

  check('Perks wirken auf alle Module, nicht auf eine Turmart', () => {
    const state = rig()
    state.run.perks.push('perk.rate.1')
    assertClose(perkStatBonus(state, 'attackSpeed'), 0.07, 1e-9)
    assertEqual(perkStatBonus(state, 'damage'), 0, 'ein Tempo-Perk ruehrt den Schaden nicht an')
  })

  check('gleiche Perks summieren sich additiv, nicht multiplikativ', () => {
    const state = rig()
    for (let i = 0; i < 10; i++) state.run.perks.push('perk.damage.1')
    // Zehnmal acht Prozent sind +80 %, nicht +116 % (1,08^10). Additiv, wie bei Buffs.
    assertClose(perkStatBonus(state, 'damage'), 0.8, 1e-9)
    assertEqual(perkCount(state, 'perk.damage.1'), 10)
  })

  check('ein Huellen-Perk vergroessert die Lebensleiste', () => {
    const state = rig()
    const before = maxStationHp(state)
    state.run.perks.push('perk.hull.1')
    assertClose(maxStationHp(state), Math.round(before * 1.1), 0.51)
  })

  check('globale Perks und globale Upgrades laufen zusammen', () => {
    const state = rig()
    assertEqual(globalMultiplier(state, 'goldBonus'), 1, 'ohne beides gibt es keine Wirkung')

    state.run.perks.push('perk.gold.1')
    assertClose(globalMultiplier(state, 'goldBonus'), 1.1, 1e-9)

    state.run.upgrades['global.goldBonus'] = 1
    // Additiv aus beiden Quellen - Perk 10 % plus Upgrade 6 % ergibt 16 %.
    assertClose(globalMultiplier(state, 'goldBonus'), 1.16, 1e-9)
  })

  check('Erfahrungsbonus gibt es nur als Perk und trotzdem ueber dieselbe Abfrage', () => {
    const state = rig()
    assertEqual(globalMultiplier(state, 'xpBonus'), 1)
    state.run.perks.push('perk.xp.1')
    assertClose(globalMultiplier(state, 'xpBonus'), 1.12, 1e-9)
  })

  check('unbekannte Perks im Spielstand werden uebergangen', () => {
    const state = rig()
    state.run.perks.push('perk.gibtsnicht')
    state.run.perks.push('perk.damage.1')
    // Kein Absturz, und der gueltige Eintrag wirkt weiter.
    assertClose(perkStatBonus(state, 'damage'), 0.08, 1e-9)
  })

  check('der Fortschritt in der Stufe stimmt mit der Kurve ueberein', () => {
    const state = rig()
    state.run.xp = cumulativeXp(5) + xpForLevel(5) / 2

    const progress = levelProgress(state)
    assertEqual(progress.level, 5)
    assertEqual(progress.need, xpForLevel(5))
    assertClose(progress.fraction, 0.5, 1e-6)
  })
}

/** Kleine Hilfe, damit die Absicht in der Zeile steht und nicht im Ausdruck. */
function assertDeepEqualLength(list: readonly unknown[], expected: number): void {
  assertEqual(list.length, expected)
}

/**
 * Beweis aus E11.
 *
 * Der Plan nennt genau eine Abnahmebedingung: "Abklingzeit in Simulationssekunden, nicht in
 * Echtzeit - bei x4 vergeht sie viermal so schnell." Das ist die erste Pruefung hier, und
 * sie ist wichtiger, als sie aussieht: Ein Cooldown an der Wanduhr waere bei x4 eine
 * Abwertung des Tempos, und beim Offline-Fortschritt (E17) waere er gar nicht mehr
 * nachvollziehbar.
 *
 * Daneben steht die zweite Entscheidung dieser Etappe: Die Wirkung einer Faehigkeit wird
 * **geschrieben, nicht erfragt** - `sim/abilities.ts` legt sie als Zahl in den
 * Kampfzustand, Kampf und Werte lesen sie dort ab. Deshalb wird geprueft, dass genau diese
 * Zahlen stimmen und dass sie wieder verschwinden, wenn die Wirkung ausgelaufen ist.
 */

import { assert, assertClose, assertEqual, check, suite } from '../../core/assert.ts'
import { abilityById } from '../../data/abilities.ts'
import { MAX_ABILITY_SLOTS } from '../../data/balance.ts'
import { buyAbility, fireAbility, toggleAbilitySlot } from '../../app/actions.ts'
import { createInitialState, type GameState } from '../../app/state.ts'
import { invalidateStationView, resetStationViewCache, stationView } from '../../app/view.ts'
import {
  activateAbility,
  canActivate,
  cooldownLeft,
  equippedAbilities,
  isEquipped,
  isUnlocked,
  resetAbilities,
  stepAbilities,
  unlockAbility,
} from '../../sim/abilities.ts'
import { syncStation } from '../../sim/battle.ts'
import { createCombatState, damageStation } from '../../sim/combat.ts'
import { spawnEnemy } from '../../sim/enemies.ts'
import { effectiveTowerStats, maxStationHp } from '../../sim/stats.ts'
import { CORE_UID } from '../../sim/station.ts'

function rig(gold = 100000): GameState {
  resetStationViewCache()
  const state = createInitialState(2024)
  state.runtime.combat = createCombatState()
  state.runtime.combat.phase = 'running'
  state.runtime.combat.maxStationHp = maxStationHp(state)
  state.runtime.combat.stationHp = state.runtime.combat.maxStationHp
  state.run.gold = gold
  invalidateStationView(state)
  const view = stationView(state)
  syncStation(state, view.modules, view.buffs)
  return state
}

/** Freischalten und sicherstellen, dass die Faehigkeit auch auf einem Slot liegt. */
function ready(state: GameState, id: string): void {
  unlockAbility(state, id)
  if (!isEquipped(state, id)) toggleAbilitySlot(state, id)
}

export function abilitiesSuite(): void {
  suite('sim/abilities')

  // -------------------------------------------------------------------------
  // Besitz und Belegung
  // -------------------------------------------------------------------------

  check('Freischalten kostet Gold und passiert genau einmal', () => {
    const state = rig(500)
    const def = abilityById('overload')

    assertEqual(unlockAbility(state, 'overload'), true)
    assertEqual(state.run.gold, 500 - def.unlockCost)
    assertEqual(isUnlocked(state, 'overload'), true)

    assertEqual(unlockAbility(state, 'overload'), false, 'ein zweites Mal geht nicht')
    assertEqual(state.run.gold, 500 - def.unlockCost, 'und kostet auch nichts')
  })

  check('ohne genug Gold aendert sich nichts', () => {
    const state = rig(10)
    assertEqual(unlockAbility(state, 'shield'), false)
    assertEqual(state.run.gold, 10)
    assertEqual(isUnlocked(state, 'shield'), false)
  })

  check('die erste freigeschaltete Faehigkeit landet gleich auf einem Slot', () => {
    const state = rig()
    unlockAbility(state, 'orbital')
    assertEqual(isEquipped(state, 'orbital'), true, 'sonst haette man etwas gekauft, das nichts tut')
  })

  check('mehr Slots als erlaubt gibt es nicht (GDD 09 Abschnitt 8)', () => {
    const state = rig()
    state.run.abilitySlots = 99
    for (const id of ['overload', 'shield', 'orbital', 'timewarp', 'repair']) {
      unlockAbility(state, id)
    }
    assert(
      equippedAbilities(state).length <= MAX_ABILITY_SLOTS,
      `hoechstens ${MAX_ABILITY_SLOTS}, war ${equippedAbilities(state).length}`,
    )
  })

  check('bei vollen Slots weicht der aelteste Eintrag', () => {
    const state = rig()
    state.run.abilitySlots = 1
    unlockAbility(state, 'overload')
    unlockAbility(state, 'shield')

    // Beide sind freigeschaltet, aber nur einer passt auf den einen Slot.
    assertEqual(state.run.equipped.length, 1)
    toggleAbilitySlot(state, 'shield')
    assertEqual(isEquipped(state, 'shield'), true, 'der Klick tut etwas, statt abzuweisen')
    assertEqual(isEquipped(state, 'overload'), false, 'der aeltere Eintrag weicht')
  })

  check('nur Freigeschaltetes kann belegt werden', () => {
    const state = rig()
    assertEqual(toggleAbilitySlot(state, 'repair'), false)
    assertEqual(isEquipped(state, 'repair'), false)
  })

  // -------------------------------------------------------------------------
  // Abklingzeit - die Abnahmebedingung der Etappe
  // -------------------------------------------------------------------------

  check('die Abklingzeit laeuft in Simulationssekunden, nicht an der Uhr', () => {
    const state = rig()
    ready(state, 'overload')
    const def = abilityById('overload')

    assertEqual(activateAbility(state, 'overload'), true)
    assertClose(cooldownLeft(state, 'overload'), def.cooldown, 1e-9)

    // Zehn Simulationssekunden - unabhaengig davon, wie viele echte Sekunden das waren.
    // Genau darin liegt der Unterschied zu einer Wanduhr: Bei Tempo x4 kommen dieselben
    // zehn Simulationssekunden in zweieinhalb echten zusammen.
    for (let i = 0; i < 600; i++) stepAbilities(state, 1 / 60)
    assertClose(cooldownLeft(state, 'overload'), def.cooldown - 10, 1e-6)
  })

  check('gleiche Simulationszeit in verschieden grossen Schritten ergibt dasselbe', () => {
    const fine = rig()
    const coarse = rig()
    ready(fine, 'orbital')
    ready(coarse, 'orbital')
    activateAbility(fine, 'orbital')
    activateAbility(coarse, 'orbital')

    for (let i = 0; i < 240; i++) stepAbilities(fine, 1 / 60)
    for (let i = 0; i < 60; i++) stepAbilities(coarse, 1 / 15)

    assertClose(cooldownLeft(fine, 'orbital'), cooldownLeft(coarse, 'orbital'), 1e-6)
  })

  check('waehrend der Abklingzeit geht kein zweiter Einsatz', () => {
    const state = rig()
    ready(state, 'orbital')

    assertEqual(activateAbility(state, 'orbital'), true)
    assertEqual(canActivate(state, 'orbital'), false)
    assertEqual(activateAbility(state, 'orbital'), false)

    // Bis kurz vor Schluss bleibt sie gesperrt, danach steht sie bereit.
    stepAbilities(state, abilityById('orbital').cooldown - 0.01)
    assertEqual(canActivate(state, 'orbital'), false)
    stepAbilities(state, 0.02)
    assertEqual(canActivate(state, 'orbital'), true)
  })

  check('nicht belegte Faehigkeiten lassen sich nicht zuenden', () => {
    const state = rig()
    unlockAbility(state, 'overload')
    toggleAbilitySlot(state, 'overload')
    assertEqual(isEquipped(state, 'overload'), false)
    assertEqual(activateAbility(state, 'overload'), false, 'Besitz allein genuegt nicht')
  })

  check('zuenden geht nur in der Kampfansicht (GDD 09 Abschnitt 7)', () => {
    const state = rig()
    ready(state, 'orbital')

    state.runtime.view = 'base'
    assertEqual(fireAbility(state, 'orbital'), false, 'die Basis bleibt Verwaltungsbereich')

    state.runtime.view = 'combat'
    assertEqual(fireAbility(state, 'orbital'), true)
  })

  // -------------------------------------------------------------------------
  // Wirkung
  // -------------------------------------------------------------------------

  check('eine Verstaerkung erscheint in effectiveTowerStats und verschwindet wieder', () => {
    const state = rig()
    ready(state, 'overload')

    const before = effectiveTowerStats(state, CORE_UID)
    assert(before !== null, 'der Kern muss Werte haben')

    activateAbility(state, 'overload')
    const during = effectiveTowerStats(state, CORE_UID)
    assert(during !== null, 'der Kern muss weiterhin Werte haben')
    assertClose(during.attackSpeed, before.attackSpeed * 1.5, 1e-9, 'waehrend der Wirkung')

    // Bis nach dem Ende der Wirkdauer laufen lassen.
    stepAbilities(state, abilityById('overload').duration + 0.1)
    const after = effectiveTowerStats(state, CORE_UID)
    assert(after !== null, 'der Kern muss danach Werte haben')
    assertClose(after.attackSpeed, before.attackSpeed, 1e-9, 'nach der Wirkung')
  })

  check('ein Schild faengt einen Anteil des Schadens ab', () => {
    const state = rig()
    ready(state, 'shield')
    const combat = state.runtime.combat

    const full = combat.stationHp
    damageStation(state, 100, { x: 0, y: 0 })
    const withoutShield = full - combat.stationHp
    assertClose(withoutShield, 100, 1e-9)

    combat.stationHp = full
    activateAbility(state, 'shield')
    damageStation(state, 100, { x: 0, y: 0 })
    const withShield = full - combat.stationHp
    assertClose(withShield, 100 * (1 - 0.6), 1e-9, 'sechzig Prozent bleiben draussen')
  })

  check('eine Verlangsamung bremst, haelt aber nie an', () => {
    const state = rig()
    ready(state, 'timewarp')

    assertEqual(state.runtime.combat.enemySpeedFactor, 1)
    activateAbility(state, 'timewarp')
    const factor = state.runtime.combat.enemySpeedFactor
    assert(factor > 0 && factor < 1, `Faktor muss zwischen 0 und 1 liegen, war ${factor}`)

    stepAbilities(state, abilityById('timewarp').duration + 0.1)
    assertEqual(state.runtime.combat.enemySpeedFactor, 1, 'danach wieder normal')
  })

  check('eine Heilung wirkt sofort und nie ueber die volle Huelle hinaus', () => {
    const state = rig()
    ready(state, 'repair')
    const combat = state.runtime.combat

    combat.stationHp = combat.maxStationHp * 0.2
    activateAbility(state, 'repair')
    assertClose(
      combat.stationHp,
      combat.maxStationHp * 0.5,
      1e-6,
      'dreissig Prozent des Maximums dazu',
    )

    // Aus der Abklingzeit heraus und bei fast voller Huelle noch einmal.
    stepAbilities(state, abilityById('repair').cooldown + 0.1)
    combat.stationHp = combat.maxStationHp - 1
    activateAbility(state, 'repair')
    assertEqual(combat.stationHp, combat.maxStationHp, 'nie darueber hinaus')
  })

  check('ein Flaechenschlag trifft, was im Umkreis steht', () => {
    const state = rig()
    ready(state, 'orbital')
    const combat = state.runtime.combat

    // Einer dicht an der Station, einer weit draussen.
    const near = spawnEnemy(state, 'drone', 0)
    assert(near !== null, 'der nahe Gegner muss erscheinen')
    near.pos.x = 60
    near.pos.y = 0
    near.hp = 10000
    near.maxHp = 10000

    const far = spawnEnemy(state, 'drone', Math.PI)
    assert(far !== null, 'der ferne Gegner muss erscheinen')
    far.pos.x = 4000
    far.pos.y = 0
    far.hp = 10000
    far.maxHp = 10000

    const nearBefore = near.hp
    const farBefore = far.hp
    activateAbility(state, 'orbital')

    assert(near.hp < nearBefore, 'der nahe Gegner muss Schaden nehmen')
    assertEqual(far.hp, farBefore, 'der ferne bleibt unberuehrt')
    assert(combat.enemies.length >= 1, 'die Liste bleibt in Ordnung')
  })

  check('zuruecksetzen raeumt Abklingzeiten und Wirkungen weg', () => {
    const state = rig()
    ready(state, 'overload')
    activateAbility(state, 'overload')

    resetAbilities(state)
    assertEqual(cooldownLeft(state, 'overload'), 0)
    assertEqual(state.runtime.combat.damageReduction, 0)
    assertEqual(state.runtime.combat.enemySpeedFactor, 1)
    assertEqual(Object.keys(state.runtime.combat.abilityBonus).length, 0)
  })

  check('eine gekaufte Faehigkeit ueberlebt den Spielstand, ihre Abklingzeit nicht', () => {
    const state = rig()
    ready(state, 'shield')
    activateAbility(state, 'shield')

    // Was gespeichert wird, sind Besitz und Belegung - nicht der laufende Zustand.
    assert(state.run.abilities.includes('shield'), 'Besitz gehoert in den Spielstand')
    assert(state.run.equipped.includes('shield'), 'Belegung auch')
    assert(cooldownLeft(state, 'shield') > 0, 'die Abklingzeit dagegen ist Laufzeit')
  })

  check('das Freischalten laeuft ueber dieselbe Handlung wie im Spiel', () => {
    const state = rig()
    assertEqual(buyAbility(state, 'timewarp'), true)
    assertEqual(isUnlocked(state, 'timewarp'), true)
  })
}

