input.content:
/**
 * Beweis aus E12.
 *
 * Der Plan verlangt dreierlei: die Eigenschaftsanzahl je Raritaet, die Kostenkurve, und
 * dass geschmolzene Tuerme **endgueltig** weg sind und nirgends wieder auftauchen.
 *
 * Dazu kommt die Regel, die keine Funktion ist, sondern eine Abwesenheit: Es gibt **keinen
 * Verkauf gegen Gold** (GDD 06 Abschnitt 4). Geprueft wird sie als Wirkung - Schmelzen
 * bringt kein Gold, sondern einen Wurf.
 */

import { assert, assertClose, assertEqual, check, suite } from '../../core/assert.ts'
import { createRng } from '../../core/rng.ts'
import { MELT_COST, TOWER_BASE_COST, TOWER_COST_FACTOR } from '../../data/balance.ts'
import { RARITY_CHANCE, rarityWeights, TRAIT_SLOTS } from '../../data/rarities.ts'
import { traitById } from '../../data/traits.ts'
import { RARITIES, type Rarity } from '../../data/types.ts'
import { createInitialState, type GameState } from '../../app/state.ts'
import { invalidateStationView, resetStationViewCache, stationView } from '../../app/view.ts'
import { syncStation } from '../../sim/battle.ts'
import { createCombatState } from '../../sim/combat.ts'
import {
  discardTowerOffer,
  meltTowers,
  rollTowerOffer,
  rollTraits,
  startTowerPurchase,
  takeTowerOffer,
  towerCost,
} from '../../sim/shop.ts'
import { newModule } from '../../sim/station.ts'

function rig(gold = 100000): GameState {
  resetStationViewCache()
  const state = createInitialState(777)
  state.runtime.combat = createCombatState()
  state.run.gold = gold
  invalidateStationView(state)
  const view = stationView(state)
  syncStation(state, view.modules, view.buffs)
  return state
}

/** Alles bis zu dieser Stufe freischalten - Raritaeten **und** Eigenschaften. */
function unlockUpTo(state: GameState, rarity: Rarity): void {
  const order: Rarity[] = ['rare', 'epic', 'legendary', 'mythic']
  for (const step of order) {
    state.permanent.prestigeNodes.push(`rarity.${step}`, `trait.${step}`)
    if (step === rarity) break
  }
}

function fillInventory(state: GameState, count: number): string[] {
  const uids: string[] = []
  for (let i = 0; i < count; i++) {
    const module = newModule(state.run.station, 'autocannon', 'common')
    state.run.station.inventory.push(module)
    uids.push(module.uid)
  }
  return uids
}

export function shopSuite(): void {
  suite('sim/shop')

  // -------------------------------------------------------------------------
  // Kostenkurve (GDD 06 Abschnitt 2)
  // -------------------------------------------------------------------------

  check('der Preis folgt Grundpreis x 1,5 je gekauftem Turm', () => {
    const state = rig()
    for (const bought of [0, 1, 2, 3, 8]) {
      state.run.towersBought = bought
      assertEqual(
        towerCost(state),
        Math.round(TOWER_BASE_COST * Math.pow(TOWER_COST_FACTOR, bought)),
        `nach ${bought} Kaeufen`,
      )
    }
  })

  check('die Reihe entspricht der Tabelle des GDD', () => {
    // GDD 06 Abschnitt 2 nennt 100 / 150 / 225 / 337.
    const state = rig()
    const seen: number[] = []
    for (let i = 0; i < 4; i++) {
      state.run.towersBought = i
      seen.push(towerCost(state))
    }
    assertEqual(seen.join(','), '100,150,225,338', 'die letzte Stelle rundet auf statt ab')
  })

  check('der Preis steigt erst mit der Annahme, nicht mit dem Angebot', () => {
    const state = rig()
    const before = towerCost(state)

    assertEqual(startTowerPurchase(state), true)
    assertEqual(towerCost(state), before, 'ein offenes Angebot aendert den Preis nicht')

    takeTowerOffer(state, 0)
    assert(towerCost(state) > before, 'erst die Annahme verteuert den naechsten')
  })

  check('bezahlt wird der Wurf, nicht der Turm', () => {
    const state = rig(150)
    const cost = towerCost(state)

    assertEqual(startTowerPurchase(state), true)
    assertEqual(state.run.gold, 150 - cost, 'das Gold ist beim Wuerfeln weg')

    discardTowerOffer(state)
    assertEqual(state.run.gold, 150 - cost, 'verwerfen gibt nichts zurueck')
    assertEqual(state.run.station.inventory.length, 3, 'und bringt keinen Turm')
  })

  check('ohne genug Gold aendert sich nichts', () => {
    const state = rig(10)
    assertEqual(startTowerPurchase(state), false)
    assertEqual(state.run.gold, 10)
    assertEqual(state.run.towerOffer.length, 0)
  })

  // -------------------------------------------------------------------------
  // Raritaet und Eigenschaften (GDD 06 Abschnitt 8 und 10)
  // -------------------------------------------------------------------------

  check('ohne Freischaltung faellt nur Common', () => {
    const state = rig()
    const rng = createRng(5)
    for (let i = 0; i < 200; i++) {
      for (const offer of rollTowerOffer(state, rng)) {
        assertEqual(offer.rarity, 'common', 'ohne Prestige gibt es nichts anderes')
      }
    }
  })

  check('freigeschaltete Stufen erscheinen, hoehere nicht', () => {
    const state = rig()
    unlockUpTo(state, 'epic')
    const rng = createRng(11)

    const seen = new Set<string>()
    for (let i = 0; i < 800; i++) {
      for (const offer of rollTowerOffer(state, rng)) seen.add(offer.rarity)
    }

    assert(seen.has('common') && seen.has('rare') && seen.has('epic'), `gesehen: ${[...seen]}`)
    assert(!seen.has('legendary'), 'Legendary ist nicht freigeschaltet')
    assert(!seen.has('mythic'), 'Mythic ist nicht freigeschaltet')
  })

  check('die Chancen entsprechen der Tabelle des GDD', () => {
    // GDD 06 Abschnitt 8: bei Rare-Freischaltung 80 % Common, 20 % Rare.
    const state = rig()
    unlockUpTo(state, 'rare')
    const rng = createRng(23)

    let common = 0
    let rare = 0
    const rounds = 20000
    for (let i = 0; i < rounds; i++) {
      for (const offer of rollTowerOffer(state, rng, 1)) {
        if (offer.rarity === 'common') common += 1
        if (offer.rarity === 'rare') rare += 1
      }
    }
    // Grosszuegige Schranke: Der Test sichert die Groessenordnung, nicht den Generator.
    assertClose(rare / (common + rare), 0.2, 0.02, `gemessen ${rare}/${common + rare}`)
  })

  check('die Raritaetsgrenze einer Turmart wird eingehalten', () => {
    // Die Kanone reicht laut GDD 06 Abschnitt 9 nur bis Legendary.
    const weights = rarityWeights('cannon', 'mythic')
    assert(
      weights.every((entry) => entry.rarity !== 'mythic'),
      'die Kanone darf nicht mythisch werden',
    )
    assert(
      rarityWeights('autocannon', 'mythic').some((entry) => entry.rarity === 'mythic'),
      'das Maschinengewehr dagegen schon',
    )
  })

  check('jede Stufe der Chancentabelle summiert sich auf hundert', () => {
    for (const rarity of RARITIES) {
      let total = 0
      for (const value of Object.values(RARITY_CHANCE[rarity])) total += value ?? 0
      assertEqual(total, 100, `Stufe ${rarity}`)
    }
  })

  check('die Anzahl der Eigenschaften folgt der Raritaet (GDD 06 Abschnitt 10)', () => {
    const state = rig()
    unlockUpTo(state, 'mythic')
    const rng = createRng(31)

    for (const rarity of RARITIES) {
      const traits = rollTraits(state, 'autocannon', rarity, rng)
      assertEqual(traits.length, TRAIT_SLOTS[rarity], `Stufe ${rarity}`)
    }
    assertEqual(TRAIT_SLOTS.common, 0, 'Common ist die reine Basisversion')
  })

  check('ohne freigeschaltete Eigenschaften bleiben die Plaetze leer', () => {
    const state = rig()
    // Nur die Raritaet, nicht die Eigenschaften: genau der Fall aus GDD 06 Abschnitt 10.
    state.permanent.prestigeNodes.push('rarity.rare', 'rarity.epic', 'rarity.legendary')
    const traits = rollTraits(state, 'autocannon', 'legendary', createRng(3))
    assertEqual(traits.length, 0, 'die Ebene der Eigenschaften ist eine eigene Freischaltung')
  })

  check('ein Turm zieht keine Eigenschaft doppelt', () => {
    const state = rig()
    unlockUpTo(state, 'mythic')
    const rng = createRng(41)
    for (let i = 0; i < 500; i++) {
      const traits = rollTraits(state, 'autocannon', 'mythic', rng)
      assertEqual(new Set(traits).size, traits.length, `Runde ${i}`)
    }
  })

  check('ein Verstaerker zieht nur Verstaerker-Eigenschaften', () => {
    const state = rig()
    unlockUpTo(state, 'mythic')
    const rng = createRng(53)
    for (let i = 0; i < 200; i++) {
      for (const id of rollTraits(state, 'amplifier', 'legendary', rng)) {
        assertEqual(
          traitById(id).effect.kind,
          'buffPower',
          'ein Schadensbonus waere bei ihm wirkungslos',
        )
      }
    }
  })

  check('eine Karte traegt ihre Eigenschaften schon vor der Wahl', () => {
    const state = rig()
    unlockUpTo(state, 'legendary')
    assertEqual(startTowerPurchase(state), true)

    const offer = state.run.towerOffer[0]
    assert(offer !== undefined, 'es muss eine Karte geben')
    assertEqual(offer.traits.length, TRAIT_SLOTS[offer.rarity], 'die Karte ist fertig gewuerfelt')

    const before = state.run.station.inventory.length
    takeTowerOffer(state, 0)
    const module = state.run.station.inventory[before]
    assert(module !== undefined, 'der Turm muss im Lager liegen')
    assertEqual(module.rarity, offer.rarity, 'was auf der Karte stand, kommt auch heraus')
    assertEqual(module.traits.join(','), offer.traits.join(','))
  })

  // -------------------------------------------------------------------------
  // Schmelzen (GDD 06 Abschnitt 5)
  // -------------------------------------------------------------------------

  check('drei Tuerme ergeben ein kostenloses Angebot', () => {
    const state = rig(0)
    const uids = fillInventory(state, 3)
    const before = state.run.station.inventory.length

    const result = meltTowers(state, uids)
    assert(result !== null, 'der Schmelzgang muss greifen')
    assertEqual(result.melted, MELT_COST)
    assertEqual(state.run.gold, 0, 'Schmelzen bringt kein Gold, sondern einen Wurf')
    assertEqual(state.run.station.inventory.length, before - MELT_COST)
    assert(state.run.towerOffer.length > 0, 'und ein Angebot')
  })

  check('geschmolzene Tuerme sind endgueltig weg', () => {
    const state = rig()
    const uids = fillInventory(state, 3)
    meltTowers(state, uids)
    takeTowerOffer(state, 0)

    const station = state.run.station
    for (const uid of uids) {
      assert(
        !station.inventory.some((module) => module.uid === uid),
        `${uid} darf nicht im Lager sein`,
      )
      assert(
        !station.placed.some((module) => module.uid === uid),
        `${uid} darf nicht auf der Station sein`,
      )
    }
  })

  check('weniger oder mehr als drei schmilzt nicht', () => {
    const state = rig()
    const uids = fillInventory(state, 4)
    assertEqual(meltTowers(state, uids.slice(0, 2)), null, 'zwei sind zu wenig')
    assertEqual(meltTowers(state, uids), null, 'vier sind zu viel')
    assertEqual(state.run.station.inventory.length, 3 + 4, 'nichts ist verschwunden')
  })

  check('derselbe Turm zaehlt nicht dreimal', () => {
    const state = rig()
    const uids = fillInventory(state, 3)
    const twice = [uids[0] as string, uids[0] as string, uids[1] as string]
    assertEqual(meltTowers(state, twice), null, 'ein Turm ist ein Turm')
  })

  check('platzierte Tuerme lassen sich nicht einschmelzen', () => {
    const state = rig()
    const uids = fillInventory(state, 3)
    // Einen davon so tun lassen, als staende er auf der Station.
    const module = state.run.station.inventory.find((entry) => entry.uid === uids[0])
    assert(module !== undefined, 'der Turm muss existieren')
    state.run.station.inventory = state.run.station.inventory.filter((entry) => entry !== module)
    state.run.station.placed.push(module)

    assertEqual(meltTowers(state, uids), null, 'nur aus dem Lager')
  })

  check('bei offenem Angebot wird nicht geschmolzen', () => {
    const state = rig()
    const uids = fillInventory(state, 3)
    startTowerPurchase(state)
    assertEqual(meltTowers(state, uids), null, 'sonst ueberschriebe der Gang das Angebot')
  })
}

/**
 * Beweis aus E13.
 *
 * Der Implementierungsplan nennt genau eine Abnahmebedingung, und er nennt sie die
 * **fehleranfaelligste Stelle des ganzen Spiels**:
 *
 *   "Eine Liste aller Zustandsfelder wird im Test gegen 'bleibt / wird zurueckgesetzt'
 *   geprueft."
 *
 * Genau das steht unten. Der Test geht **Feld fuer Feld** durch beide Bloecke und prueft
 * jedes einzeln - nicht stichprobenartig, nicht "der Run ist neu". Ein Feld, das
 * faelschlich zurueckgesetzt wird, kostet den Spieler dauerhaften Fortschritt; ein Feld,
 * das faelschlich bleibt, macht das Zuruecksetzen sinnlos. Beides faellt hier auf.
 *
 * Damit der Test nicht mitwaechst, ohne dass jemand hinsieht, arbeitet er gegen dieselben
 * Feldlisten wie `suites/save.ts`: Kommt ein Feld dazu, schlaegt dort die Feldliste an und
 * hier die Zuordnung.
 */

import { assert, assertEqual, check, suite } from '../../core/assert.ts'
import { PRESTIGE_MIN_GOLD } from '../../data/balance.ts'
import { PRESTIGE_NODES, prestigeNodeById } from '../../data/prestige.ts'
import { createInitialState, type GameState } from '../../app/state.ts'
import { invalidateStationView, resetStationViewCache, stationView } from '../../app/view.ts'
import { syncStation } from '../../sim/battle.ts'
import { createCombatState } from '../../sim/combat.ts'
import {
  abilitySlots,
  availableSpeeds,
  buyNode,
  canPrestige,
  doPrestige,
  goldLostOnPrestige,
  isAvailable,
  isUnlocked,
  prestigePoints,
  syncUnlocks,
  towerSlots,
  unlockedRarity,
  unlockedTraitTier,
} from '../../sim/prestige.ts'
import { newModule } from '../../sim/station.ts'

function rig(): GameState {
  resetStationViewCache()
  const state = createInitialState(9001)
  state.runtime.combat = createCombatState()
  invalidateStationView(state)
  const view = stationView(state)
  syncStation(state, view.modules, view.buffs)
  return state
}

/** Einen Run mit Fortschritt in jedem Feld, damit das Zuruecksetzen etwas zu tun hat. */
function playedRun(): GameState {
  const state = rig()
  state.run.wave = 42
  state.run.waveRecord = 57
  state.run.gold = 4321
  state.run.goldEarned = 98765
  state.run.towersBought = 6
  state.run.towerOffer = [{ defId: 'autocannon', rarity: 'common', traits: [] }]
  state.run.coins = [{ x: 10, y: 20, value: 500, count: 3 }]
  state.run.level = 7
  state.run.xp = 12345
  state.run.perks = ['perk.damage.1', 'perk.rate.1']
  state.run.perkOffer = ['perk.gold.1']
  state.run.abilities = ['overload', 'shield']
  state.run.equipped = ['overload']
  state.run.upgrades = { 'core.damage': 4 }
  state.run.autoWaves = false
  state.run.rngState = 555
  state.run.station.inventory.push(newModule(state.run.station, 'cannon', 'rare', ['trait.damage.r']))
  return state
}

export function prestigeSuite(): void {
  suite('sim/prestige')

  // -------------------------------------------------------------------------
  // Freischaltungen als Datenabfrage (GDD 16 Abschnitt 2)
  // -------------------------------------------------------------------------

  check('ohne gekaufte Knoten ist alles auf Anfang', () => {
    const state = rig()
    assertEqual(unlockedRarity(state), 'common')
    assertEqual(unlockedTraitTier(state), null)
    assertEqual(availableSpeeds(state).join(','), '1', 'x2 und x4 sind Freischaltungen')
    assertEqual(abilitySlots(state), 1)
  })

  check('jeder Knoten des Baums ist erreichbar', () => {
    // Ein Knoten, dessen Voraussetzung es nicht gibt, waere totes Kapital im Baum.
    for (const node of PRESTIGE_NODES) {
      for (const required of node.requires) {
        assert(
          PRESTIGE_NODES.some((candidate) => candidate.id === required),
          `${node.id} verlangt ${required}, das es nicht gibt`,
        )
      }
    }
  })

  check('Voraussetzungen sperren, bis sie erfuellt sind', () => {
    const state = rig()
    assertEqual(isAvailable(state, 'rarity.rare'), true, 'der erste Knoten steht frei')
    assertEqual(isAvailable(state, 'rarity.epic'), false, 'der zweite noch nicht')

    state.permanent.prestigePoints = 100000
    assertEqual(buyNode(state, 'rarity.epic'), false, 'auch mit Punkten nicht')

    buyNode(state, 'rarity.rare')
    assertEqual(isAvailable(state, 'rarity.epic'), true, 'jetzt schon')
  })

  check('ohne genug Punkte aendert sich nichts', () => {
    const state = rig()
    state.permanent.prestigePoints = 10
    assertEqual(buyNode(state, 'rarity.rare'), false, 'Rare kostet 50')
    assertEqual(state.permanent.prestigePoints, 10)
    assertEqual(isUnlocked(state, 'rarity.rare'), false)
  })

  check('ein Kauf zieht genau die Kosten ab', () => {
    const state = rig()
    state.permanent.prestigePoints = 1000
    const cost = prestigeNodeById('rarity.rare').cost
    assertEqual(buyNode(state, 'rarity.rare'), true)
    assertEqual(state.permanent.prestigePoints, 1000 - cost)
    assertEqual(buyNode(state, 'rarity.rare'), false, 'zweimal geht nicht')
  })

  check('Turmplaetze und Slots wirken sofort, nicht erst im naechsten Run', () => {
    const state = rig()
    state.permanent.prestigePoints = 100000
    const slotsBefore = state.run.station.slots

    buyNode(state, 'towers.slot1')
    assertEqual(towerSlots(state), slotsBefore + 1)
    assertEqual(state.run.station.slots, slotsBefore + 1, 'die Station weiss es schon')

    buyNode(state, 'towers.ability2')
    assertEqual(abilitySlots(state), 2)
    assertEqual(state.run.abilitySlots, 2)
  })

  check('Tempo x2 und x4 haengen am Baum (GDD 10, Bereich 2b)', () => {
    const state = rig()
    state.permanent.prestigePoints = 100000
    buyNode(state, 'speed.x2')
    assertEqual(availableSpeeds(state).join(','), '1,2')
    buyNode(state, 'speed.x4')
    assertEqual(availableSpeeds(state).join(','), '1,2,4')
  })

  check('eine geschrumpfte Slotzahl kuerzt die Belegung', () => {
    const state = rig()
    state.run.equipped = ['overload', 'shield', 'repair']
    syncUnlocks(state)
    assertEqual(state.run.equipped.length, 1, 'ohne Freischaltung passt nur einer')
  })

  // -------------------------------------------------------------------------
  // Punkte und Voraussetzung (GDD 10 Abschnitt 3 und 5)
  // -------------------------------------------------------------------------

  check('unter tausend verdientem Gold gibt es kein Prestige', () => {
    const state = rig()
    state.run.goldEarned = PRESTIGE_MIN_GOLD - 1
    assertEqual(canPrestige(state), false)
    assertEqual(doPrestige(state), false, 'und der Versuch aendert nichts')

    state.run.goldEarned = PRESTIGE_MIN_GOLD
    assertEqual(canPrestige(state), true)
  })

  check('gezaehlt wird verdientes Gold, nicht der Kontostand', () => {
    const state = rig()
    state.run.goldEarned = 5000
    state.run.gold = 0
    assertEqual(canPrestige(state), true, 'ausgegebenes Gold zaehlt mit')

    state.run.goldEarned = 0
    state.run.gold = 5000
    assertEqual(canPrestige(state), false, 'geschenktes Gold zaehlt nicht')
  })

  check('die Punkte folgen den Richtwerten des GDD', () => {
    const state = rig()
    state.run.goldEarned = 0
    const at = (wave: number): number => {
      state.run.waveRecord = wave
      return prestigePoints(state)
    }
    // GDD 10 Abschnitt 5 nennt 5-10 / 50-100 / 500 als Richtwerte und die Formel
    // ausdruecklich als Balancing-Wert. Geprueft wird die Groessenordnung.
    assert(at(100) >= 2 && at(100) <= 12, `Welle 100 ergab ${at(100)}`)
    assert(at(500) >= 50 && at(500) <= 150, `Welle 500 ergab ${at(500)}`)
    assert(at(1000) >= 400 && at(1000) <= 600, `Welle 1000 ergab ${at(1000)}`)
  })

  check('weiter kommen bringt ueberproportional mehr', () => {
    const state = rig()
    state.run.goldEarned = 0
    const at = (wave: number): number => {
      state.run.waveRecord = wave
      return prestigePoints(state)
    }
    // Doppelte Welle muss mehr als das Doppelte bringen (GDD 10 Abschnitt 5).
    assert(at(400) > at(200) * 2, `${at(400)} gegen ${at(200)}`)
  })

  check('liegendes Gold zaehlt in die Warnung', () => {
    const state = rig()
    state.run.gold = 100
    state.run.coins = [{ x: 0, y: 0, value: 250, count: 1 }]
    assertEqual(goldLostOnPrestige(state), 350, 'Kontostand plus Feld (GDD 10 Abschnitt 3)')
  })

  // -------------------------------------------------------------------------
  // Zuruecksetzen - Feld fuer Feld
  // -------------------------------------------------------------------------

  check('jedes Run-Feld wird zurueckgesetzt (E13-Kernabsicherung)', () => {
    const state = playedRun()
    const fresh = createInitialState(1)

    assertEqual(doPrestige(state), true)

    // Feld fuer Feld gegen einen frischen Run. Der Startwert des Generators darf und soll
    // abweichen - zwei Runs sollen sich nicht gleich anfuehlen.
    const skip = new Set(['seed', 'rngState', 'station'])
    for (const key of Object.keys(fresh.run)) {
      if (skip.has(key)) continue
      const actual = state.run[key as keyof typeof state.run]
      const expected = fresh.run[key as keyof typeof fresh.run]
      assertEqual(
        JSON.stringify(actual),
        JSON.stringify(expected),
        `run.${key} muss zurueckgesetzt sein`,
      )
    }
  })

  check('die Station wird zurueckgesetzt, aber nicht die Turmplaetze', () => {
    const state = playedRun()
    state.permanent.prestigePoints = 100000
    buyNode(state, 'towers.slot1')

    doPrestige(state)

    assertEqual(state.run.station.placed.length, 0, 'nichts steht mehr')
    assertEqual(state.run.station.inventory.length, 3, 'nur das Startlager')
    assertEqual(state.run.station.slots, towerSlots(state), 'der gekaufte Platz bleibt')
  })

  check('jedes permanente Feld bleibt erhalten (E13-Kernabsicherung)', () => {
    const state = playedRun()
    state.permanent.prestigeNodes = ['rarity.rare']
    state.permanent.prestigePoints = 500
    state.permanent.unlockedTowers = ['autocannon', 'cannon']
    state.permanent.unlockedCores = ['sentinel']
    state.permanent.seenHints = ['hint.build']
    state.permanent.totalPlaySeconds = 3600
    state.permanent.bestWaveEver = 20
    const countBefore = state.permanent.prestigeCount

    const earned = prestigePoints(state)
    assertEqual(doPrestige(state), true)

    assertEqual(state.permanent.prestigeNodes.join(','), 'rarity.rare', 'Baum bleibt')
    assertEqual(state.permanent.prestigePoints, 500 + earned, 'Punkte bleiben und wachsen')
    assertEqual(state.permanent.unlockedTowers.join(','), 'autocannon,cannon')
    assertEqual(state.permanent.unlockedCores.join(','), 'sentinel')
    assertEqual(state.permanent.seenHints.join(','), 'hint.build')
    assertEqual(state.permanent.totalPlaySeconds, 3600)
    assertEqual(state.permanent.prestigeCount, countBefore + 1, 'der Zaehler steigt')
    assertEqual(state.permanent.bestWaveEver, 57, 'der Bestwert zieht nach')
  })

  check('die Laufzeitdaten gehen mit dem Run', () => {
    const state = playedRun()
    state.runtime.combat.killsThisWave = 99
    state.runtime.abilities.cooldowns.set('overload', 30)
    state.runtime.announcedLevel = 7
    state.runtime.selectedUid = 'irgendwas'

    doPrestige(state)

    assertEqual(state.runtime.combat.killsThisWave, 0, 'ein neues Gefecht')
    assertEqual(state.runtime.abilities.cooldowns.size, 0, 'keine Abklingzeit ueberlebt')
    assertEqual(state.runtime.announcedLevel, -1, 'die Stufe wird neu angesagt')
    assertEqual(state.runtime.selectedUid, null)
  })

  check('der Bestwert faellt nie, auch nach einem schwaecheren Run', () => {
    const state = playedRun()
    state.permanent.bestWaveEver = 300
    doPrestige(state)
    assertEqual(state.permanent.bestWaveEver, 300, 'ein schlechterer Run senkt ihn nicht')
  })

  check('nach dem Prestige ist wieder alles zu verdienen', () => {
    const state = playedRun()
    doPrestige(state)
    assertEqual(canPrestige(state), false, 'der neue Run faengt bei null an')
    assertEqual(state.run.towersBought, 0, 'und der erste Turm kostet wieder den Grundpreis')
  })
}

