  const before = s.run.station.inventory.length;
  document.querySelectorAll('.offer-card')[1].click();
  g.shell.refresh();
  const taken = s.run.station.inventory[s.run.station.inventory.length - 1];
  out.taken = { defId: taken.defId, rarity: taken.rarity, traits: taken.traits };
  out.inventoryGrew = s.run.station.inventory.length === before + 1;
  out.priceRose = act.towerPrice(s);

  // Eigenschaft wirkt? Ein Kampfturm mit Schadens-Eigenschaft
  s.run.gold = 999999;
  let withTrait = null;
  for (let i = 0; i < 40 && !withTrait; i++) {
    act.buyTowerSlot(s);
    const card = s.run.towerOffer.findIndex(o => o.traits.some(t => t.startsWith('trait.damage')));
    if (card >= 0) { act.takeOffer(s, card); withTrait = s.run.station.inventory[s.run.station.inventory.length-1]; }
    else act.dropOffer(s);
  }
  if (withTrait) {
    const mod = { uid: withTrait.uid, kind: 'tower', defId: withTrait.defId, rarity: withTrait.rarity,
                  traits: withTrait.traits, sides: 4, center: {x:0,y:0}, rotation: 0, poly: [], sharedEdges: [] };
    const plain = { ...mod, traits: [] };
    out.traitEffect = {
      traits: withTrait.traits,
      withTrait: +stats.moduleStats(mod, undefined).base.damage.toFixed(3),
      without: +stats.moduleStats(plain, undefined).base.damage.toFixed(3),
    };
  }

  // Schmelzen
  const uids = s.run.station.inventory.slice(0, 3).map(m => m.uid);
  const goldBefore = s.run.gold;
  const invBefore = s.run.station.inventory.length;
  out.melted = act.meltSelection(s, uids);
  out.meltGaveNoGold = s.run.gold === goldBefore;
  out.meltRemoved = invBefore - s.run.station.inventory.length;
  out.meltOffered = s.run.towerOffer.length;
  act.dropOffer(s);

  g.shell.refresh();
  return JSON.stringify(out, null, 1);
})()

