(async () => {
  const g = window.wavebreaker;
  if (!g) return JSON.stringify({ debug: false });
  const s = g.state;
  const pr = await import('/src/sim/prestige.ts');
  const shop = await import('/src/sim/shop.ts');
  const battle = await import('/src/sim/battle.ts');
  const view = await import('/src/app/view.ts');
  const station = await import('/src/sim/station.ts');

  // Alle Techniken freischalten und einen Laser, Tesla und ein Drohnenmodul bauen.
  s.permanent.prestigePoints = 1e6;
  for (const id of ['rarity.rare','rarity.epic','rarity.legendary','trait.rare','trait.epic',
                    'tech.rocket','tech.laser','tech.tesla','tech.drone','towers.slot1','towers.slot2','towers.slot3']) {
    pr.buyNode(s, id);
  }
  s.run.station.slots = 12;

  const built = [];
  for (const defId of ['laser','tesla','dronebay','bulwark','flamer','cryo','rocket','sniper']) {
    const m = station.newModule(s.run.station, defId, 'common');
    s.run.station.inventory.push(m);
    const edge = station.freeEdges(s.run.station).find(e => e.ownerUid === 'core')
             ?? station.freeEdges(s.run.station)[0];
    if (station.place(s.run.station, m.uid, edge) === null) built.push(defId);
  }
  view.invalidateStationView(s);
  const v = view.stationView(s);
  battle.syncStation(s, v.modules, v.buffs);

  const hullBefore = s.runtime.combat.maxStationHp;
  const stats = await import('/src/sim/stats.ts');
  return JSON.stringify({
    built,
    placed: s.run.station.placed.length,
    hull: { base: 1000, withShield: stats.maxStationHp(s) },
    towersAvailable: shop.rollTowerOffer(s, s.runtime.rng, 12).map(o => `${o.defId}:${o.rarity}`),
  }, null, 1);
})()

(async () => {
  const g = window.wavebreaker;
  const s = g.state;
  const battle = await import('/src/sim/battle.ts');
  const enemies = await import('/src/sim/enemies.ts');
  const waves = await import('/src/sim/waves.ts');

  waves.startWave(s, 60);            // Welle 60: Elites moeglich, Schild-Einheiten dabei
  s.runtime.combat.phase = 'running';

  const seen = { beams: 0, drones: 0, burning: 0, chilled: 0, elites: 0, shielded: 0, kinds: new Set() };
  for (let i = 0; i < 60 * 25; i++) {           // 25 Simulationssekunden
    battle.stepBattle(s, 1/60);
    const c = s.runtime.combat;
    seen.beams = Math.max(seen.beams, c.beams.filter(b => b.active).length);
    seen.drones = Math.max(seen.drones, c.drones.length);
    for (const e of c.enemies) {
      seen.kinds.add(e.defId);
      if (e.burnLeft > 0) seen.burning++;
      if (e.chillLeft > 0) seen.chilled++;
      if (e.elite.length) seen.elites++;
      if (e.shield > 0) seen.shielded++;
    }
  }
  const c = s.runtime.combat;
  return JSON.stringify({
    maxBeamsAtOnce: seen.beams,
    drones: seen.drones,
    sawBurning: seen.burning > 0, sawChilled: seen.chilled > 0,
    sawElite: seen.elites > 0, sawShielded: seen.shielded > 0,
    enemyKinds: [...seen.kinds],
    kills: c.killsThisWave, aliveNow: c.enemies.length,
    stationHp: Math.round(c.stationHp), maxHp: c.maxStationHp,
    gold: Math.round(s.run.gold), coins: s.run.coins.length,
  }, null, 1);
})()

(async () => {
  const g = window.wavebreaker;
  const s = g.state;
  const battle = await import('/src/sim/battle.ts');
  const waves = await import('/src/sim/waves.ts');
  const en = await import('/src/sim/enemies.ts');

  waves.startWave(s, 320);
  s.runtime.combat.phase = 'running';
  const elites = new Set(), kinds = new Set();
  let multi = 0;
  for (let i = 0; i < 60 * 20; i++) {
    battle.stepBattle(s, 1/60);
    for (const e of s.runtime.combat.enemies) {
      kinds.add(e.defId);
      for (const m of e.elite) elites.add(m);
      if (e.elite.length > 1) multi++;
    }
  }
  return JSON.stringify({
    wave: s.run.wave,
    eliteChanceAt320: +en.eliteChance(320).toFixed(3),
    eliteModifiersSeen: [...elites],
    sawMultipleModifiers: multi > 0,
    enemyKinds: [...kinds],
    boss: (await import('/src/data/enemies.ts')).bossForWave(320).name,
  }, null, 1);
})()

