  entry(returnList, t('offline.gold'), `+${formatNumber(summary.gold)}`)
  entry(returnList, t('offline.xp'), `+${formatNumber(summary.xp)}`)
  if (summary.levels > 0) {
    entry(returnList, t('hud.level', { level: '' }).trim(), t('offline.levels', { count: summary.levels }))
  }
}

