/*
 * Das Ereignisfenster (GDD 11 Abschnitt 3).
 *
 * Dieselben grossen Karten wie beim Turmangebot - es ist dieselbe Handlung: Der Spieler
 * bekommt etwas vorgelegt und waehlt. Nur der Rahmen traegt eine andere Farbe, damit man
 * die beiden Fenster nicht verwechselt: Ein Turmangebot ist ein Kauf, ein Ereignis eine
 * Entscheidung mit Folgen.
 */
.event-panel {
  width: min(620px, calc(100% - 28px));
  border-color: color-mix(in srgb, var(--violet) 55%, var(--line));
  box-shadow: 0 0 34px -8px var(--violet), var(--shadow-card);
}

.event-panel h2 {
  color: var(--violet);
  text-shadow: 0 0 26px rgba(180, 92, 255, 0.6), 0 0 8px rgba(180, 92, 255, 0.9);
}

.event-panel .offer-card {
  --rarity: var(--violet);
}

/*
 * Der Bericht ueber die Abwesenheit (GDD 12 Abschnitt 5).
 *
 * Er verlangt keine Wahl, also gibt es keine Karten - nur eine Liste aus Beschriftung und
 * Zahl. Die Zahlen stehen rechtsbuendig in der Ziffernschrift: So liegen sie untereinander
 * und lassen sich vergleichen, statt an unterschiedlichen Stellen zu beginnen.
 */
.return-panel {
  width: min(400px, calc(100% - 28px));
}

.return-list {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 6px 16px;
  margin: 4px 0 16px;
  text-align: left;
}

.return-list dt {
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.return-list dd {
  margin: 0;
  font-family: var(--font-number);
  font-size: 13px;
  text-align: right;
  color: var(--edge);
}

/*
 * Der Hinweiszettel (GDD 14 Abschnitt 4a).
 *
 * Er liegt am **unteren Rand ueber der Leiste** und nicht in der Mitte: Ein Hinweis haelt
 * nichts an, also darf er auch nicht in der Bahn stehen. `pointer-events` bleibt am Knopf
 * und nicht am Zettel - wer daneben klickt, klickt auf das Spielfeld.
 */
.hint-card {
  position: absolute;
  left: 50%;
  bottom: 14px;
  z-index: 8;
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: min(520px, calc(100% - 32px));
  padding: 10px 12px 10px 16px;
  border: 1px solid color-mix(in srgb, var(--gold) 45%, var(--line));
  border-radius: 12px;
  background: var(--fill-panel);
  box-shadow: 0 0 26px -8px var(--gold), var(--shadow-card);
  transform: translateX(-50%);
  pointer-events: none;
}

.hint-card[hidden] {
  display: none;
}

.hint-card.enter {
  animation: enter-up var(--dur-card) var(--ease-out);
}

.hint-card p {
  margin: 0;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text);
}

.hint-card .chip {
  flex: 0 0 auto;
  pointer-events: auto;
}

