input.content:
/**
 * Beweis aus E16 (Ereignisse und Versorgungskapseln).
 *
 * Die Abnahmebedingung der Etappe ist dieselbe wie bei Tuermen und Gegnern: **Ein neues
 * Ereignis ist ein Datensatz.** Diese Datei prueft deshalb nicht, ob ein bestimmtes
 * Ereignis das Richtige tut, sondern ob der Weg vom Datensatz zur Wirkung fuer **jedes**
 * Ereignis und **jede** Option traegt. Dafuer laufen die wichtigsten Zusicherungen ueber
 * die vollstaendige Tabelle statt ueber ein Beispiel.
 *
 * Der zweite Schwerpunkt ist der Rhythmus: Ereignisse duerfen sich nicht stauen und nicht
 * ausbleiben, und ein Neuladen darf keines neu wuerfeln.
 *
 * Achtung bei der Namensgleichheit: `core/events.ts` ist der Ereignisbus des Programms,
 * `data/events.ts` sind die Spielereignisse. Dieser Test meint die zweiten - der Bus hat
 * seine eigene Suite in `suites/format.ts`.
 */

import { assert, assertEqual, check, suite } from '../../core/assert.ts'
import { createRng } from '../../core/rng.ts'
import {
  EVENT_WAVE_MAX,
  EVENT_WAVE_MIN,
  MAX_PODS,
  POD_DROP_CHANCE,
  POD_DROP_CHANCE_BOSS,
  POD_DROP_CHANCE_ELITE,
  eventRewardFor,
} from '../../data/balance.ts'
import { EVENTS, PODS, eventsForWave, podsForWave } from '../../data/events.ts'
import { createInitialState, type GameState } from '../../app/state.ts'
import { invalidateStationView, stationView } from '../../app/view.ts'
import { syncStation } from '../../sim/battle.ts'
import {
  boonLeft,
  collectPod,
  collectPodsAt,
  currentEvent,
  dismissEvent,
  dropPod,
  isValidPod,
  maybeTriggerEvent,
  podChanceFor,
  resetBoons,
  resolveEvent,
  rollPodKind,
  stepEvents,
} from '../../sim/events.ts'
import { spawnEnemy } from '../../sim/enemies.ts'
import { startWave } from '../../sim/waves.ts'

/** Ein Zustand mit stehender Station - Ereignisse, die Gegner erscheinen lassen, brauchen sie. */
function ready(seed = 11): GameState {
  const state = createInitialState(seed)
  invalidateStationView(state)
  const view = stationView(state)
  syncStation(state, view.modules, view.buffs)
  return state
}

export function eventsSuite(): void {
  suite('sim/events · Ereignisse')

  check('jedes Ereignis hat mindestens zwei Optionen', () => {
    // Ein Ereignis mit einer Option ist keine Entscheidung, sondern eine Meldung
    // (GDD 11 Abschnitt 4).
    for (const event of EVENTS) {
      assert(event.choices.length >= 2, `${event.id} hat nur ${event.choices.length} Optionen`)
    }
  })

  check('jede Option hat eine Wirkung und einen Text dazu', () => {
    for (const event of EVENTS) {
      for (const choice of event.choices) {
        assert(choice.effects.length > 0, `${event.id}/${choice.id} bewirkt nichts`)
        assert(choice.detail.length > 0, `${event.id}/${choice.id} nennt seine Folge nicht`)
      }
    }
  })

  check('Optionskennungen sind innerhalb eines Ereignisses eindeutig', () => {
    for (const event of EVENTS) {
      const ids = new Set(event.choices.map((choice) => choice.id))
      assertEqual(ids.size, event.choices.length, `${event.id} hat doppelte Optionen`)
    }
  })

  check('jede Option laesst sich waehlen und schliesst das Ereignis', () => {
    // Der Durchlauf ueber **alle** Optionen ist die eigentliche Abnahme: Ein neuer
    // Datensatz muss ohne neuen Code funktionieren.
    for (const event of EVENTS) {
      for (const choice of event.choices) {
        const state = ready()
        startWave(state, Math.max(1, event.minWave))
        state.run.eventId = event.id

        assertEqual(resolveEvent(state, choice.id), true, `${event.id}/${choice.id}`)
        assertEqual(state.run.eventId, null)
        assertEqual(currentEvent(state), null)
      }
    }
  })

  check('eine unbekannte Option aendert nichts', () => {
    const state = ready()
    state.run.eventId = 'alientech'
    assertEqual(resolveEvent(state, 'gibtesnicht'), false)
    assertEqual(state.run.eventId, 'alientech')
  })

  check('ohne offenes Ereignis laesst sich nichts waehlen', () => {
    const state = ready()
    assertEqual(resolveEvent(state, 'sell'), false)
  })

  check('eine Belohnungsoption zahlt aus, und zwar wellenabhaengig', () => {
    const early = ready()
    startWave(early, 5)
    early.run.eventId = 'alientech'
    resolveEvent(early, 'sell')

    const late = ready()
    startWave(late, 60)
    late.run.eventId = 'alientech'
    resolveEvent(late, 'sell')

    assert(early.run.gold > 0, 'auf Welle 5 muss etwas herauskommen')
    assert(
      late.run.gold > early.run.gold * 5,
      'auf Welle 60 muss deutlich mehr herauskommen - sonst ist das Ereignis spaeter wertlos',
    )
    assertEqual(early.run.gold, eventRewardFor(5) * 6)
  })

  check('ein Bonus wirkt auf die Kampfwerte und laeuft ab', () => {
    const state = ready()
    state.run.eventId = 'powersurge'
    resolveEvent(state, 'surge')

    // Die Wirkung steht als fertige Zahl im Kampfzustand - Werte und Kampf lesen sie dort.
    assertEqual(state.runtime.combat.eventBonus.attackSpeed, 0.5)
    assertEqual(state.runtime.combat.enemyPower, 1.5)
    assert(boonLeft(state, 'powersurge') > 0, 'die Wirkung muss laufen')

    // Nach Ablauf muessen **beide** Zahlen zurueckgenommen sein. Genau hier faellt ein
    // fortgeschriebener statt neu aufgebauter Wert auf.
    stepEvents(state, 46)
    assertEqual(state.runtime.combat.eventBonus.attackSpeed, undefined)
    assertEqual(state.runtime.combat.enemyPower, 1)
    assertEqual(boonLeft(state, 'powersurge'), 0)
  })

  check('dasselbe Ereignis zweimal verlaengert, statt sich zu verdoppeln', () => {
    const state = ready()
    state.run.eventId = 'powersurge'
    resolveEvent(state, 'surge')
    stepEvents(state, 20)

    state.run.eventId = 'powersurge'
    resolveEvent(state, 'surge')

    assertEqual(state.runtime.combat.eventBonus.attackSpeed, 0.5, 'nicht 1.0')
    assertEqual(state.runtime.combat.enemyPower, 1.5, 'nicht 2.25')
  })

  check('ein staerkerer Gegner erscheint wirklich', () => {
    const state = ready()
    startWave(state, 30)
    const before = state.runtime.combat.enemies.length

    state.run.eventId = 'mutation'
    resolveEvent(state, 'engage')

    assertEqual(state.runtime.combat.enemies.length, before + 10)
  })

  check('ein verstaerkter Gegner erscheint staerker als ohne Ereignis', () => {
    const plain = ready()
    startWave(plain, 20)
    const normal = spawnEnemy(plain, 'drone', 0)

    const hazard = ready()
    startWave(hazard, 20)
    hazard.run.eventId = 'singularity'
    resolveEvent(hazard, 'absorb')
    const stronger = spawnEnemy(hazard, 'drone', 0)

    assert(normal !== null && stronger !== null, 'beide Gegner muessen erscheinen')
    assertEqual(stronger.maxHp, normal.maxHp * 1.5)
    assertEqual(stronger.damage, normal.damage * 1.5)
  })

  check('resetBoons nimmt jede laufende Wirkung zurueck', () => {
    const state = ready()
    state.run.eventId = 'alientech'
    resolveEvent(state, 'install')
    assert(state.runtime.boons.length > 0, 'es muss eine Wirkung laufen')

    resetBoons(state)
    assertEqual(state.runtime.boons.length, 0)
    assertEqual(state.runtime.combat.eventBonus.damage, undefined)
    assertEqual(state.runtime.combat.enemyPower, 1)
  })

  check('verwerfen schliesst das Ereignis ohne Belohnung', () => {
    const state = ready()
    startWave(state, 10)
    state.run.eventId = 'alientech'
    const gold = state.run.gold

    dismissEvent(state)
    assertEqual(state.run.eventId, null)
    assertEqual(state.run.gold, gold)
  })

  suite('sim/events · Rhythmus')

  check('das erste Ereignis liegt 15 bis 25 Wellen voraus', () => {
    const state = ready()
    const rng = createRng(3)

    startWave(state, 40)
    maybeTriggerEvent(state, rng)

    const gap = state.run.nextEventWave - 40
    assert(
      gap >= EVENT_WAVE_MIN && gap <= EVENT_WAVE_MAX,
      `Abstand ${gap} liegt ausserhalb von ${EVENT_WAVE_MIN}..${EVENT_WAVE_MAX}`,
    )
    assertEqual(state.run.eventId, null, 'der erste Aufruf setzt nur den Termin')
  })

  check('auf der faelligen Welle faellt genau ein Ereignis', () => {
    const state = ready()
    const rng = createRng(5)

    startWave(state, 40)
    state.run.nextEventWave = 40

    const event = maybeTriggerEvent(state, rng)
    assert(event !== null, 'es muss ein Ereignis fallen')
    assertEqual(state.run.eventId, event.id)

    // Ein zweiter Aufruf darf das offene Ereignis nicht ueberschreiben - zwei Fenster
    // uebereinander waeren ein Stau und keine Abwechslung.
    assertEqual(maybeTriggerEvent(state, rng), null)
    assertEqual(state.run.eventId, event.id)
  })

  check('der Termin wird auch dann weitergesetzt, wenn kein Ereignis passt', () => {
    const state = ready()
    const rng = createRng(9)

    // Welle 1: Kein Ereignis hat eine so niedrige Mindestwelle.
    startWave(state, 1)
    state.run.nextEventWave = 1
    assertEqual(eventsForWave(1).length, 0, 'Voraussetzung dieses Tests')

    assertEqual(maybeTriggerEvent(state, rng), null)
    assert(state.run.nextEventWave > 1, 'sonst prueft der naechste Takt sofort wieder')
  })

  check('ein Ereignis erscheint nie vor seiner Mindestwelle', () => {
    const rng = createRng(21)
    for (let wave = 1; wave <= 30; wave++) {
      for (const event of eventsForWave(wave)) {
        assert(wave >= event.minWave, `${event.id} auf Welle ${wave}`)
      }
    }
    // Und der Wurf zieht wirklich nur aus dieser Menge.
    const state = ready()
    startWave(state, 12)
    state.run.nextEventWave = 12
    const event = maybeTriggerEvent(state, rng)
    assert(event !== null && event.minWave <= 12, 'gewuerfelt wurde ein zu fruehes Ereignis')
  })

  suite('sim/events · Versorgungskapseln')

  check('Bosse lassen immer eine Kapsel fallen, Elites deutlich haeufiger', () => {
    const state = ready()
    startWave(state, 60)
    const enemy = spawnEnemy(state, 'drone', 0)
    assert(enemy !== null, 'Gegner muss erscheinen')

    assertEqual(podChanceFor(enemy, false), POD_DROP_CHANCE)
    enemy.elite.push('elite.swift')
    assertEqual(podChanceFor(enemy, false), POD_DROP_CHANCE_ELITE)
    assertEqual(podChanceFor(enemy, true), POD_DROP_CHANCE_BOSS)
  })

  check('eine Kapselart erscheint nie vor ihrer Mindestwelle', () => {
    const rng = createRng(13)
    for (const wave of [1, 5, 10, 25, 50]) {
      for (let i = 0; i < 50; i++) {
        const pod = rollPodKind(wave, rng)
        assert(pod !== null, `Welle ${wave} muss eine Kapselart hergeben`)
        assert(wave >= pod.minWave, `${pod.id} auf Welle ${wave}`)
      }
    }
  })

  check('jede Kapselart hat ein Gewicht und eine Wirkung', () => {
    for (const pod of PODS) {
      assert(pod.weight > 0, `${pod.id} kann nie fallen`)
      assert(pod.minWave >= 1, `${pod.id} hat eine unsinnige Mindestwelle`)
    }
    assert(podsForWave(1).length > 0, 'auf Welle 1 muss etwas fallen koennen')
  })

  check('eine Goldkapsel zahlt beim Einsammeln aus, nicht beim Fallen', () => {
    const state = ready()
    startWave(state, 10)

    const pod = dropPod(state, { x: 40, y: 0 }, 'pod.gold')
    assert(pod !== null, 'die Kapsel muss entstehen')
    assertEqual(state.run.gold, 0, 'das Fallen selbst darf nichts einbringen')

    assertEqual(collectPod(state, pod.id), true)
    assertEqual(state.run.gold, eventRewardFor(10) * 3)
    assertEqual(state.run.pods.length, 0)
  })

  check('der Wert richtet sich nach der Welle des Einsammelns', () => {
    const state = ready()
    startWave(state, 5)
    const pod = dropPod(state, { x: 0, y: 0 }, 'pod.gold')
    assert(pod !== null, 'die Kapsel muss entstehen')

    // Liegen lassen, weiterspielen, dann aufheben: Eine Kapsel darf keine Falle sein.
    startWave(state, 45)
    collectPod(state, pod.id)
    assertEqual(state.run.gold, eventRewardFor(45) * 3)
  })

  check('eine Upgrade-Kapsel verschenkt genau eine Stufe', () => {
    const state = ready()
    startWave(state, 10)
    const before = Object.values(state.run.upgrades).reduce((sum, level) => sum + level, 0)

    const pod = dropPod(state, { x: 0, y: 0 }, 'pod.upgrade')
    assert(pod !== null, 'die Kapsel muss entstehen')
    collectPod(state, pod.id)

    const after = Object.values(state.run.upgrades).reduce((sum, level) => sum + level, 0)
    assertEqual(after, before + 1)
  })

  check('eine Turmkapsel legt ein Angebot vor - und ueberschreibt keines', () => {
    const state = ready()
    startWave(state, 40)

    const first = dropPod(state, { x: 0, y: 0 }, 'pod.tower')
    assert(first !== null, 'die Kapsel muss entstehen')
    collectPod(state, first.id)
    assert(state.run.towerOffer.length > 0, 'es muss ein Angebot vorliegen')

    // Die zweite Kapsel darf das laufende Angebot nicht wegwerfen - der Spieler hat es
    // sonst verloren, ohne gewaehlt zu haben.
    const signature = JSON.stringify(state.run.towerOffer)
    const gold = state.run.gold
    const second = dropPod(state, { x: 0, y: 0 }, 'pod.tower')
    assert(second !== null, 'die zweite Kapsel muss entstehen')
    collectPod(state, second.id)

    assertEqual(JSON.stringify(state.run.towerOffer), signature)
    assert(state.run.gold > gold, 'stattdessen muss sie in Gold auszahlen')
  })

  check('die seltene Turmkapsel hebt die Untergrenze der Raritaet', () => {
    const state = ready()
    startWave(state, 50)
    // Ohne freigeschaltete Raritaeten kann sie nichts anheben - dann muss sie trotzdem
    // etwas liefern statt leer aufzugehen.
    const pod = dropPod(state, { x: 0, y: 0 }, 'pod.towerRare')
    assert(pod !== null, 'die Kapsel muss entstehen')
    collectPod(state, pod.id)
    assert(state.run.towerOffer.length > 0, 'auch bei Common muss ein Angebot herauskommen')

    // Mit freigeschalteten Raritaeten liegt jede Karte mindestens auf Epic.
    const rich = ready(4)
    startWave(rich, 50)
    rich.permanent.prestigeNodes.push('rarity.rare', 'rarity.epic', 'rarity.legendary')
    const better = dropPod(rich, { x: 0, y: 0 }, 'pod.towerRare')
    assert(better !== null, 'die Kapsel muss entstehen')
    collectPod(rich, better.id)
    for (const offer of rich.run.towerOffer) {
      assert(
        offer.rarity === 'epic' || offer.rarity === 'legendary' || offer.rarity === 'mythic',
        `${offer.defId} kam als ${offer.rarity}`,
      )
    }
  })

  check('Kapseln lassen sich mit dem Zeiger aufheben - aber nur in Reichweite', () => {
    const state = ready()
    startWave(state, 10)
    dropPod(state, { x: 0, y: 0 }, 'pod.gold')

    assertEqual(collectPodsAt(state, { x: 500, y: 500 }), 0, 'zu weit weg')
    assertEqual(state.run.pods.length, 1)

    assertEqual(collectPodsAt(state, { x: 0, y: 0 }), 1)
    assertEqual(state.run.pods.length, 0)
  })

  check('mehr als die Obergrenze liegt nie im Feld', () => {
    const state = ready()
    for (let i = 0; i < MAX_PODS + 8; i++) dropPod(state, { x: i * 40, y: 0 }, 'pod.gold')
    assertEqual(state.run.pods.length, MAX_PODS)
  })

  check('eine unbekannte Kapselart entsteht gar nicht erst', () => {
    const state = ready()
    assertEqual(dropPod(state, { x: 0, y: 0 }, 'pod.gibtesnicht'), null)
    assertEqual(state.run.pods.length, 0)
  })

  check('eine gelesene Kapsel wird geprueft, nicht geglaubt', () => {
    assertEqual(isValidPod({ id: 1, defId: 'pod.gold', x: 0, y: 0 }), true)
    assertEqual(isValidPod({ id: 1, defId: 'pod.weg', x: 0, y: 0 }), false)
    assertEqual(isValidPod({ id: 1, defId: 'pod.gold', x: 'nein', y: 0 }), false)
    assertEqual(isValidPod(null), false)
  })
}

/**
 * Beweis aus E16 (Ereignisse und Versorgungskapseln).
 *
 * Die Abnahmebedingung der Etappe ist dieselbe wie bei Tuermen und Gegnern: **Ein neues
 * Ereignis ist ein Datensatz.** Diese Datei prueft deshalb nicht, ob ein bestimmtes
 * Ereignis das Richtige tut, sondern ob der Weg vom Datensatz zur Wirkung fuer **jedes**
 * Ereignis und **jede** Option traegt. Dafuer laufen die wichtigsten Zusicherungen ueber
 * die vollstaendige Tabelle statt ueber ein Beispiel.
 *
 * Der zweite Schwerpunkt ist der Rhythmus: Ereignisse duerfen sich nicht stauen und nicht
 * ausbleiben, und ein Neuladen darf keines neu wuerfeln.
 *
 * Die Datei heisst `encounters` und nicht `events`, weil `suites/events.ts` schon vergeben
 * ist - an den Ereignis**bus** des Programms. Zwei Dinge mit demselben Namen sind in diesem
 * Projekt sonst nirgends, und hier waere die Verwechslung besonders teuer.
 */

import { assert, assertEqual, check, suite } from '../../core/assert.ts'
import { createRng } from '../../core/rng.ts'
import {
  EVENT_WAVE_MAX,
  EVENT_WAVE_MIN,
  MAX_PODS,
  POD_DROP_CHANCE,
  POD_DROP_CHANCE_BOSS,
  POD_DROP_CHANCE_ELITE,
  eventRewardFor,
} from '../../data/balance.ts'
import { EVENTS, PODS, eventsForWave, podsForWave } from '../../data/events.ts'
import { createInitialState, type GameState } from '../../app/state.ts'
import { invalidateStationView, stationView } from '../../app/view.ts'
import { syncStation } from '../../sim/battle.ts'
import {
  boonLeft,
  collectPod,
  collectPodsAt,
  currentEvent,
  dismissEvent,
  dropPod,
  isValidPod,
  maybeTriggerEvent,
  podChanceFor,
  resetBoons,
  resolveEvent,
  rollPodKind,
  stepEvents,
} from '../../sim/events.ts'
import { spawnEnemy } from '../../sim/enemies.ts'
import { startWave } from '../../sim/waves.ts'

/** Ein Zustand mit stehender Station - Ereignisse, die Gegner erscheinen lassen, brauchen sie. */
function ready(seed = 11): GameState {
  const state = createInitialState(seed)
  invalidateStationView(state)
  const view = stationView(state)
  syncStation(state, view.modules, view.buffs)
  return state
}

export function encountersSuite(): void {
  suite('sim/events · Ereignisse')

  check('jedes Ereignis hat mindestens zwei Optionen', () => {
    // Ein Ereignis mit einer Option ist keine Entscheidung, sondern eine Meldung
    // (GDD 11 Abschnitt 4).
    for (const event of EVENTS) {
      assert(event.choices.length >= 2, `${event.id} hat nur ${event.choices.length} Optionen`)
    }
  })

  check('jede Option hat eine Wirkung und nennt ihre Folge', () => {
    for (const event of EVENTS) {
      for (const choice of event.choices) {
        assert(choice.effects.length > 0, `${event.id}/${choice.id} bewirkt nichts`)
        assert(choice.detail.length > 0, `${event.id}/${choice.id} nennt seine Folge nicht`)
      }
    }
  })

  check('Optionskennungen sind innerhalb eines Ereignisses eindeutig', () => {
    for (const event of EVENTS) {
      const ids = new Set(event.choices.map((choice) => choice.id))
      assertEqual(ids.size, event.choices.length, `${event.id} hat doppelte Optionen`)
    }
  })

  check('jede Option laesst sich waehlen und schliesst das Ereignis', () => {
    // Der Durchlauf ueber **alle** Optionen ist die eigentliche Abnahme: Ein neuer
    // Datensatz muss ohne neuen Code funktionieren.
    for (const event of EVENTS) {
      for (const choice of event.choices) {
        const state = ready()
        startWave(state, Math.max(1, event.minWave))
        state.run.eventId = event.id

        assertEqual(resolveEvent(state, choice.id), true, `${event.id}/${choice.id}`)
        assertEqual(state.run.eventId, null)
        assertEqual(currentEvent(state), null)
      }
    }
  })

  check('eine unbekannte Option aendert nichts', () => {
    const state = ready()
    state.run.eventId = 'alientech'
    assertEqual(resolveEvent(state, 'gibtesnicht'), false)
    assertEqual(state.run.eventId, 'alientech')
  })

  check('ohne offenes Ereignis laesst sich nichts waehlen', () => {
    const state = ready()
    assertEqual(resolveEvent(state, 'sell'), false)
  })

  check('eine Belohnungsoption zahlt aus, und zwar wellenabhaengig', () => {
    const early = ready()
    startWave(early, 5)
    early.run.eventId = 'alientech'
    resolveEvent(early, 'sell')

    const late = ready()
    startWave(late, 60)
    late.run.eventId = 'alientech'
    resolveEvent(late, 'sell')

    assert(early.run.gold > 0, 'auf Welle 5 muss etwas herauskommen')
    assert(
      late.run.gold > early.run.gold * 5,
      'auf Welle 60 muss deutlich mehr herauskommen - sonst ist das Ereignis spaet wertlos',
    )
    assertEqual(early.run.gold, eventRewardFor(5) * 6)
  })

  check('ein Bonus wirkt auf die Kampfwerte und laeuft ab', () => {
    const state = ready()
    state.run.eventId = 'powersurge'
    resolveEvent(state, 'surge')

    // Die Wirkung steht als fertige Zahl im Kampfzustand - Werte und Kampf lesen sie dort.
    assertEqual(state.runtime.combat.eventBonus.attackSpeed, 0.5)
    assertEqual(state.runtime.combat.enemyPower, 1.5)
    assert(boonLeft(state, 'powersurge') > 0, 'die Wirkung muss laufen')

    // Nach Ablauf muessen **beide** Zahlen zurueckgenommen sein. Genau hier faellt ein
    // fortgeschriebener statt neu aufgebauter Wert auf.
    stepEvents(state, 46)
    assertEqual(state.runtime.combat.eventBonus.attackSpeed, undefined)
    assertEqual(state.runtime.combat.enemyPower, 1)
    assertEqual(boonLeft(state, 'powersurge'), 0)
  })

  check('dasselbe Ereignis zweimal verlaengert, statt sich zu verdoppeln', () => {
    const state = ready()
    state.run.eventId = 'powersurge'
    resolveEvent(state, 'surge')
    stepEvents(state, 20)

    state.run.eventId = 'powersurge'
    resolveEvent(state, 'surge')

    assertEqual(state.runtime.combat.eventBonus.attackSpeed, 0.5, 'nicht 1.0')
    assertEqual(state.runtime.combat.enemyPower, 1.5, 'nicht 2.25')
  })

  check('zusaetzliche Gegner erscheinen wirklich', () => {
    const state = ready()
    startWave(state, 30)
    const before = state.runtime.combat.enemies.length

    state.run.eventId = 'mutation'
    resolveEvent(state, 'engage')

    assertEqual(state.runtime.combat.enemies.length, before + 10)
  })

  check('ein verstaerkter Gegner erscheint staerker als ohne Ereignis', () => {
    const plain = ready()
    startWave(plain, 20)
    const normal = spawnEnemy(plain, 'drone', 0)

    const hazard = ready()
    startWave(hazard, 20)
    hazard.run.eventId = 'singularity'
    resolveEvent(hazard, 'absorb')
    const stronger = spawnEnemy(hazard, 'drone', 0)

    assert(normal !== null && stronger !== null, 'beide Gegner muessen erscheinen')
    assertEqual(stronger.maxHp, normal.maxHp * 1.5)
    assertEqual(stronger.damage, normal.damage * 1.5)
  })

  check('resetBoons nimmt jede laufende Wirkung zurueck', () => {
    const state = ready()
    state.run.eventId = 'alientech'
    resolveEvent(state, 'install')
    assert(state.runtime.boons.length > 0, 'es muss eine Wirkung laufen')

    resetBoons(state)
    assertEqual(state.runtime.boons.length, 0)
    assertEqual(state.runtime.combat.eventBonus.damage, undefined)
    assertEqual(state.runtime.combat.enemyPower, 1)
  })

  check('verwerfen schliesst das Ereignis ohne Belohnung', () => {
    const state = ready()
    startWave(state, 10)
    state.run.eventId = 'alientech'
    const gold = state.run.gold

    dismissEvent(state)
    assertEqual(state.run.eventId, null)
    assertEqual(state.run.gold, gold)
  })

  suite('sim/events · Rhythmus')

  check('das erste Ereignis liegt 15 bis 25 Wellen voraus', () => {
    const state = ready()
    const rng = createRng(3)

    startWave(state, 40)
    maybeTriggerEvent(state, rng)

    const gap = state.run.nextEventWave - 40
    assert(
      gap >= EVENT_WAVE_MIN && gap <= EVENT_WAVE_MAX,
      `Abstand ${gap} liegt ausserhalb von ${EVENT_WAVE_MIN}..${EVENT_WAVE_MAX}`,
    )
    assertEqual(state.run.eventId, null, 'der erste Aufruf setzt nur den Termin')
  })

  check('auf der faelligen Welle faellt genau ein Ereignis', () => {
    const state = ready()
    const rng = createRng(5)

    startWave(state, 40)
    state.run.nextEventWave = 40

    const event = maybeTriggerEvent(state, rng)
    assert(event !== null, 'es muss ein Ereignis fallen')
    assertEqual(state.run.eventId, event.id)

    // Ein zweiter Aufruf darf das offene Ereignis nicht ueberschreiben - zwei Fenster
    // uebereinander waeren ein Stau und keine Abwechslung.
    assertEqual(maybeTriggerEvent(state, rng), null)
    assertEqual(state.run.eventId, event.id)
  })

  check('der Termin wird auch dann weitergesetzt, wenn kein Ereignis passt', () => {
    const state = ready()
    const rng = createRng(9)

    // Welle 1: Kein Ereignis hat eine so niedrige Mindestwelle.
    startWave(state, 1)
    state.run.nextEventWave = 1
    assertEqual(eventsForWave(1).length, 0, 'Voraussetzung dieses Tests')

    assertEqual(maybeTriggerEvent(state, rng), null)
    assert(state.run.nextEventWave > 1, 'sonst prueft der naechste Takt sofort wieder')
  })

  check('ein Ereignis erscheint nie vor seiner Mindestwelle', () => {
    for (let wave = 1; wave <= 30; wave++) {
      for (const event of eventsForWave(wave)) {
        assert(wave >= event.minWave, `${event.id} auf Welle ${wave}`)
      }
    }

    // Und der Wurf zieht wirklich nur aus dieser Menge.
    const state = ready()
    const rng = createRng(21)
    startWave(state, 12)
    state.run.nextEventWave = 12
    const event = maybeTriggerEvent(state, rng)
    assert(event !== null && event.minWave <= 12, 'gewuerfelt wurde ein zu fruehes Ereignis')
  })

  suite('sim/events · Versorgungskapseln')

  check('Bosse lassen immer eine Kapsel fallen, Elites deutlich haeufiger', () => {
    const state = ready()
    startWave(state, 60)
    const enemy = spawnEnemy(state, 'drone', 0)
    assert(enemy !== null, 'Gegner muss erscheinen')

    assertEqual(podChanceFor(enemy, false), POD_DROP_CHANCE)
    enemy.elite.push('elite.swift')
    assertEqual(podChanceFor(enemy, false), POD_DROP_CHANCE_ELITE)
    assertEqual(podChanceFor(enemy, true), POD_DROP_CHANCE_BOSS)
  })

  check('eine Kapselart erscheint nie vor ihrer Mindestwelle', () => {
    const rng = createRng(13)
    for (const wave of [1, 5, 10, 25, 50]) {
      for (let i = 0; i < 50; i++) {
        const pod = rollPodKind(wave, rng)
        assert(pod !== null, `Welle ${wave} muss eine Kapselart hergeben`)
        assert(wave >= pod.minWave, `${pod.id} auf Welle ${wave}`)
      }
    }
  })

  check('jede Kapselart hat ein Gewicht und eine sinnvolle Mindestwelle', () => {
    for (const pod of PODS) {
      assert(pod.weight > 0, `${pod.id} kann nie fallen`)
      assert(pod.minWave >= 1, `${pod.id} hat eine unsinnige Mindestwelle`)
    }
    assert(podsForWave(1).length > 0, 'auf Welle 1 muss etwas fallen koennen')
  })

  check('eine Goldkapsel zahlt beim Einsammeln aus, nicht beim Fallen', () => {
    const state = ready()
    startWave(state, 10)

    const pod = dropPod(state, { x: 40, y: 0 }, 'pod.gold')
    assert(pod !== null, 'die Kapsel muss entstehen')
    assertEqual(state.run.gold, 0, 'das Fallen selbst darf nichts einbringen')

    assertEqual(collectPod(state, pod.id), true)
    assertEqual(state.run.gold, eventRewardFor(10) * 3)
    assertEqual(state.run.pods.length, 0)
  })

  check('der Wert richtet sich nach der Welle des Einsammelns', () => {
    const state = ready()
    startWave(state, 5)
    const pod = dropPod(state, { x: 0, y: 0 }, 'pod.gold')
    assert(pod !== null, 'die Kapsel muss entstehen')

    // Liegen lassen, weiterspielen, dann aufheben: Eine Kapsel darf keine Falle sein.
    startWave(state, 45)
    collectPod(state, pod.id)
    assertEqual(state.run.gold, eventRewardFor(45) * 3)
  })

  check('eine Upgrade-Kapsel verschenkt genau eine Stufe', () => {
    const state = ready()
    startWave(state, 10)
    const before = Object.values(state.run.upgrades).reduce((sum, level) => sum + level, 0)

    const pod = dropPod(state, { x: 0, y: 0 }, 'pod.upgrade')
    assert(pod !== null, 'die Kapsel muss entstehen')
    collectPod(state, pod.id)

    const after = Object.values(state.run.upgrades).reduce((sum, level) => sum + level, 0)
    assertEqual(after, before + 1)
  })

  check('eine Turmkapsel legt ein Angebot vor - und ueberschreibt keines', () => {
    const state = ready()
    startWave(state, 40)

    const first = dropPod(state, { x: 0, y: 0 }, 'pod.tower')
    assert(first !== null, 'die Kapsel muss entstehen')
    collectPod(state, first.id)
    assert(state.run.towerOffer.length > 0, 'es muss ein Angebot vorliegen')

    // Die zweite Kapsel darf das laufende Angebot nicht wegwerfen - der Spieler haette es
    // sonst verloren, ohne gewaehlt zu haben.
    const signature = JSON.stringify(state.run.towerOffer)
    const gold = state.run.gold
    const second = dropPod(state, { x: 0, y: 0 }, 'pod.tower')
    assert(second !== null, 'die zweite Kapsel muss entstehen')
    collectPod(state, second.id)

    assertEqual(JSON.stringify(state.run.towerOffer), signature)
    assert(state.run.gold > gold, 'stattdessen muss sie in Gold auszahlen')
  })

  check('die seltene Turmkapsel hebt die Untergrenze der Raritaet', () => {
    // Ohne freigeschaltete Raritaeten kann sie nichts anheben - dann muss sie trotzdem
    // etwas liefern statt leer aufzugehen.
    const state = ready()
    startWave(state, 50)
    const pod = dropPod(state, { x: 0, y: 0 }, 'pod.towerRare')
    assert(pod !== null, 'die Kapsel muss entstehen')
    collectPod(state, pod.id)
    assert(state.run.towerOffer.length > 0, 'auch bei Common muss ein Angebot herauskommen')

    // Mit freigeschalteten Raritaeten liegt jede Karte mindestens auf Epic.
    const rich = ready(4)
    startWave(rich, 50)
    rich.permanent.prestigeNodes.push('rarity.rare', 'rarity.epic', 'rarity.legendary')
    const better = dropPod(rich, { x: 0, y: 0 }, 'pod.towerRare')
    assert(better !== null, 'die Kapsel muss entstehen')
    collectPod(rich, better.id)
    assert(rich.run.towerOffer.length > 0, 'es muss ein Angebot herauskommen')
    for (const offer of rich.run.towerOffer) {
      assert(
        offer.rarity === 'epic' || offer.rarity === 'legendary' || offer.rarity === 'mythic',
        `${offer.defId} kam als ${offer.rarity}`,
      )
    }
  })

  check('Kapseln lassen sich mit dem Zeiger aufheben - aber nur in Reichweite', () => {
    const state = ready()
    startWave(state, 10)
    dropPod(state, { x: 0, y: 0 }, 'pod.gold')

    assertEqual(collectPodsAt(state, { x: 500, y: 500 }), 0, 'zu weit weg')
    assertEqual(state.run.pods.length, 1)

    assertEqual(collectPodsAt(state, { x: 0, y: 0 }), 1)
    assertEqual(state.run.pods.length, 0)
  })

  check('mehr als die Obergrenze liegt nie im Feld', () => {
    const state = ready()
    for (let i = 0; i < MAX_PODS + 8; i++) dropPod(state, { x: i * 40, y: 0 }, 'pod.gold')
    assertEqual(state.run.pods.length, MAX_PODS)
  })

  check('eine unbekannte Kapselart entsteht gar nicht erst', () => {
    const state = ready()
    assertEqual(dropPod(state, { x: 0, y: 0 }, 'pod.gibtesnicht'), null)
    assertEqual(state.run.pods.length, 0)
  })

  check('eine gelesene Kapsel wird geprueft, nicht geglaubt', () => {
    assertEqual(isValidPod({ id: 1, defId: 'pod.gold', x: 0, y: 0 }), true)
    assertEqual(isValidPod({ id: 1, defId: 'pod.weg', x: 0, y: 0 }), false)
    assertEqual(isValidPod({ id: 1, defId: 'pod.gold', x: 'nein', y: 0 }), false)
    assertEqual(isValidPod(null), false)
  })
}

/**
 * Beweis aus E17 (Abwesenheitsertrag und Helfer) und E18 (Hinweise).
 *
 * Der Plan nennt fuer E17 genau eine Abnahme:
 *
 *   "Eine Stunde offline liefert (bis auf Zufall) dasselbe Ergebnis wie eine Stunde im
 *   Vordergrund bei x1."
 *
 * Genau das steht unten - und zwar als Vergleich zweier Laeufe, nicht als Vergleich gegen
 * eine erwartete Zahl. Eine erwartete Zahl waere eine zweite Rechnung neben der
 * Simulation, und der ganze Sinn dieser Etappe ist, dass es keine zweite Rechnung gibt.
 *
 * Der Vergleich laeuft gegen einen Vordergrundlauf mit **derselben Taktrate**, weil die
 * Offline-Rechnung mit einem groeberen Schritt arbeitet. Die Zusicherung darunter zeigt,
 * dass auch der groebere Schritt in derselben Groessenordnung landet - das ist die
 * eigentliche Frage: Ist der Schnelldurchlauf noch dasselbe Spiel?
 */

import { assert, assertEqual, check, suite } from '../../core/assert.ts'
import { MELT_COST, OFFLINE_MAX_SECONDS, OFFLINE_MIN_SECONDS, TICK_RATE } from '../../data/balance.ts'
import { createInitialState, type GameState } from '../../app/state.ts'
import { invalidateStationView, stationView } from '../../app/view.ts'
import { stepBattle, syncStation } from '../../sim/battle.ts'
import { collectAll } from '../../sim/economy.ts'
import { HINTS, markHintSeen, pendingHint, resetHints } from '../../sim/hints.ts'
import { collectorLevel, helperCount, helperRadius, helperSpeed, stepHelpers } from '../../sim/helpers.ts'
import {
  capOfflineTime,
  offlineEfficiency,
  offlineUnlocked,
  simulateOffline,
} from '../../sim/offline.ts'
import { place } from '../../sim/station.ts'
import { startWave } from '../../sim/waves.ts'

/** Ein Zustand mit stehender Station, bereit fuer echten Kampf. */
function ready(seed = 17): GameState {
  const state = createInitialState(seed)
  refresh(state)
  return state
}

function refresh(state: GameState): void {
  invalidateStationView(state)
  const view = stationView(state)
  syncStation(state, view.modules, view.buffs)
}

/** Einen Run so vorbereiten, dass Offline ueberhaupt erlaubt ist. */
function withOffline(state: GameState, ...nodes: string[]): GameState {
  state.permanent.prestigeNodes.push('eco.offline', ...nodes)
  return state
}

export function idleSuite(): void {
  suite('sim/offline · Freischaltung und Grenzen')

  check('ohne Freischaltung passiert gar nichts', () => {
    const state = ready()
    assertEqual(offlineUnlocked(state), false)
    assertEqual(simulateOffline(state, 3600, stationView(state)), null)
    assertEqual(state.run.gold, 0, 'der Zustand darf sich nicht anfassen lassen')
  })

  check('sehr kurze Abwesenheit wird verworfen', () => {
    assertEqual(capOfflineTime(OFFLINE_MIN_SECONDS - 1), 0)
    assertEqual(capOfflineTime(OFFLINE_MIN_SECONDS), OFFLINE_MIN_SECONDS)
    assertEqual(capOfflineTime(Number.NaN), 0)
    assertEqual(capOfflineTime(-500), 0)
  })

  check('lange Abwesenheit wird gedeckelt', () => {
    assertEqual(capOfflineTime(OFFLINE_MAX_SECONDS * 4), OFFLINE_MAX_SECONDS)
  })

  check('der Wirkungsgrad steigt mit den Freischaltungen, bleibt aber unter eins', () => {
    const plain = withOffline(ready())
    const base = offlineEfficiency(plain)

    const better = withOffline(ready(), 'eco.offline2')
    assert(offlineEfficiency(better) > base, 'die bessere Simulation muss etwas bringen')

    // Der Goldsammler zaehlt nur, wenn er auch **gekauft** ist (GDD 12 Abschnitt 10).
    const withNode = withOffline(ready(), 'eco.offline2', 'helper.collector')
    assertEqual(offlineEfficiency(withNode), offlineEfficiency(better))
    withNode.run.upgrades['global.collector'] = 1
    assert(offlineEfficiency(withNode) > offlineEfficiency(better), 'der Sammler muss zaehlen')

    // Aktives Spielen bleibt immer besser (GDD 12 Abschnitt 7).
    assert(offlineEfficiency(withNode) < 1, 'Offline darf nie voll zaehlen')
  })

  suite('sim/offline · dieselbe Logik')

  check('eine Stunde offline liefert dasselbe wie eine Stunde im Vordergrund', () => {
    /*
     * Beide Seiten laufen ueber **dasselbe** `stepBattle`. Verglichen wird deshalb nicht
     * gegen eine Formel, sondern gegen den Vordergrund - und mit demselben Startwert des
     * Generators, damit "bis auf Zufall" hier wirklich "gar nicht" heisst.
     *
     * Der Vordergrundlauf benutzt die Offline-Taktrate: Der Schnelldurchlauf rechnet
     * groeber, und dieser Test soll die Gleichheit der **Logik** zeigen, nicht die
     * Gleichheit zweier Schrittweiten. Die steht in der naechsten Zusicherung.
     */
    const seconds = 600
    const rate = 20

    const foreground = withOffline(ready(3))
    startWave(foreground, foreground.run.wave)
    for (let i = 0; i < seconds * rate; i++) stepBattle(foreground, 1 / rate)
    collectAll(foreground)

    const offline = withOffline(ready(3))
    // Der Wirkungsgrad kuerzt die Zeit - fuer den Vergleich muss er heraus.
    const efficiency = offlineEfficiency(offline)
    const result = simulateOffline(offline, seconds / efficiency, stationView(offline))

    assert(result !== null, 'die Rechnung muss ein Ergebnis liefern')
    assertEqual(offline.run.wave, foreground.run.wave, 'dieselbe Welle')
    assertEqual(Math.round(offline.run.gold), Math.round(foreground.run.gold), 'dasselbe Gold')
    assertEqual(Math.round(offline.run.xp), Math.round(foreground.run.xp), 'dieselbe Erfahrung')
  })

  check('der groebere Schritt landet in derselben Groessenordnung wie 60 Hz', () => {
    /*
     * Die eigentliche Frage des Schnelldurchlaufs: Ist er noch dasselbe Spiel?
     *
     * Geprueft wird die Wellenhoehe, nicht das Gold - sie ist die Groesse, an der der
     * Spieler den Unterschied merken wuerde. Eine Abweichung von einer Welle auf zehn
     * Minuten ist Rundung; zwei Wellen waeren eine andere Simulation.
     */
    const seconds = 600

    const fine = withOffline(ready(8))
    startWave(fine, fine.run.wave)
    for (let i = 0; i < seconds * TICK_RATE; i++) stepBattle(fine, 1 / TICK_RATE)

    const coarse = withOffline(ready(8))
    startWave(coarse, coarse.run.wave)
    for (let i = 0; i < seconds * 20; i++) stepBattle(coarse, 1 / 20)

    const drift = Math.abs(fine.run.wave - coarse.run.wave)
    assert(drift <= 1, `Wellen liefen um ${drift} auseinander (${fine.run.wave}/${coarse.run.wave})`)
  })

  check('der Bericht nennt, was wirklich passiert ist', () => {
    const state = withOffline(ready(5), 'eco.offline2')
    const before = state.run.wave

    const result = simulateOffline(state, 3600, stationView(state))
    assert(result !== null, 'die Rechnung muss ein Ergebnis liefern')

    assertEqual(result.seconds, 3600)
    assert(result.simulated < result.seconds, 'nur ein Teil der Zeit zaehlt')
    assertEqual(result.waveFrom, before)
    assertEqual(result.waveTo, state.run.wave)
    assert(result.kills > 0, 'in einer Stunde muss etwas gefallen sein')
    assert(result.gold > 0, 'und Gold gebracht haben')
    assert(result.xp > 0, 'und Erfahrung')
  })

  check('das Feld ist nach der Abwesenheit abgeraeumt', () => {
    // Waehrend niemand da ist, sammelt auch niemand ein (GDD 12 Abschnitt 3).
    const state = withOffline(ready(6))
    simulateOffline(state, 3600, stationView(state))
    assertEqual(state.run.coins.length, 0)
    assert(state.run.gold > 0, 'das Gold muss auf dem Konto sein')
  })

  check('die Abwesenheit verschenkt keine Welle', () => {
    // Ohne Anstoss der laufenden Welle stuende das Gefecht in der Pause ohne Plan da, und
    // der erste Takt liesse die naechste Welle beginnen.
    const state = withOffline(ready(7))
    state.run.wave = 12
    state.run.waveRecord = 12

    const result = simulateOffline(state, OFFLINE_MIN_SECONDS, stationView(state))
    assert(result !== null, 'die Rechnung muss ein Ergebnis liefern')
    assert(result.waveTo >= 12, 'die Welle darf nicht zurueckfallen')
    assert(result.kills > 0, 'es muss wirklich gekaempft worden sein')
  })

  suite('sim/helpers · Goldsammler')

  check('ohne beide Stufen der Freischaltung gibt es keinen Helfer', () => {
    // GDD 12 Abschnitt 10: Der Prestige-Baum macht kaufbar, gekauft wird mit Gold.
    const state = ready()
    assertEqual(collectorLevel(state), 0)
    assertEqual(helperCount(state), 0)

    // Nur der Knoten: noch kein Helfer.
    state.permanent.prestigeNodes.push('helper.collector')
    assertEqual(helperCount(state), 0)

    // Nur die Stufe ohne Knoten: ebenfalls keiner.
    const bought = ready()
    bought.run.upgrades['global.collector'] = 3
    assertEqual(collectorLevel(bought), 0)
    assertEqual(helperCount(bought), 0)

    // Beides: jetzt faehrt einer.
    state.run.upgrades['global.collector'] = 1
    assertEqual(helperCount(state), 1)
  })

  check('Radius, Tempo und Anzahl wachsen mit den Stufen', () => {
    const state = ready()
    state.permanent.prestigeNodes.push('helper.collector')
    state.run.upgrades['global.collector'] = 1

    const radius = helperRadius(state)
    const speed = helperSpeed(state)

    state.run.upgrades['global.collector'] = 5
    assert(helperRadius(state) > radius, 'der Radius muss mit der Stufe wachsen')
    assert(helperSpeed(state) > speed, 'das Tempo ebenso')

    state.permanent.prestigeNodes.push('helper.better')
    assertEqual(helperRadius(state), (helperRadius(state) / 2) * 2, 'Verdopplung ist stetig')

    state.permanent.prestigeNodes.push('helper.fast')
    assertEqual(helperCount(state), 2)
    state.permanent.prestigeNodes.push('helper.elite')
    assertEqual(helperCount(state), 3)
  })

  check('ein Helfer faehrt zur naechsten Muenze und hebt sie auf', () => {
    const state = ready()
    state.permanent.prestigeNodes.push('helper.collector')
    state.run.upgrades['global.collector'] = 1
    state.run.coins.push({ x: 260, y: 0, value: 50, count: 1 })

    // Genug Takte, um die Strecke zu fahren - bei 120 Einheiten je Sekunde sind das rund
    // zwei Sekunden fuer 260 Einheiten.
    for (let i = 0; i < 60 * 4; i++) stepHelpers(state, 1 / 60)

    assertEqual(state.run.coins.length, 0, 'die Muenze muss aufgehoben sein')
    assertEqual(state.run.gold, 50)
  })

  check('ein Helfer verlaesst das Feld nicht', () => {
    const state = ready()
    state.permanent.prestigeNodes.push('helper.collector')
    state.run.upgrades['global.collector'] = 1
    // Eine Muenze weit ausserhalb: Der Helfer darf ihr nicht aus dem Bild folgen.
    state.run.coins.push({ x: 40_000, y: 0, value: 1, count: 1 })

    for (let i = 0; i < 60 * 30; i++) stepHelpers(state, 1 / 60)

    const helper = state.runtime.helpers[0]
    assert(helper !== undefined, 'der Helfer muss existieren')
    assert(Math.hypot(helper.x, helper.y) <= 901, `er stand bei ${Math.round(helper.x)}`)
  })

  check('ueberzaehlige Helfer verschwinden von selbst', () => {
    const state = ready()
    state.permanent.prestigeNodes.push('helper.collector', 'helper.better', 'helper.fast')
    state.run.upgrades['global.collector'] = 1
    stepHelpers(state, 1 / 60)
    assertEqual(state.runtime.helpers.length, 2)

    // Ein Prestige nimmt die Stufe weg - die Liste muss dem von selbst folgen.
    state.run.upgrades['global.collector'] = 0
    stepHelpers(state, 1 / 60)
    assertEqual(state.runtime.helpers.length, 0)
  })

  suite('sim/hints · einmalige Hinweise')

  check('jeder Hinweis hat eine eindeutige Kennung', () => {
    const ids = new Set(HINTS.map((hint) => hint.id))
    assertEqual(ids.size, HINTS.length)
  })

  check('ein gesehener Hinweis kommt nicht wieder', () => {
    const state = ready()
    state.run.coins.push({ x: 0, y: 0, value: 1, count: 1 })

    const first = pendingHint(state)
    assert(first !== null, 'liegendes Gold muss einen Hinweis ausloesen')
    assertEqual(first.id, 'hint.collect')

    assertEqual(markHintSeen(state, first.id), true)
    assertEqual(markHintSeen(state, first.id), false, 'zweimal ablegen ist kein Fehler, aber wirkungslos')
    assert(pendingHint(state)?.id !== 'hint.collect', 'er darf nicht wiederkommen')
  })

  check('ein unbekannter Hinweis laesst sich nicht ablegen', () => {
    const state = ready()
    assertEqual(markHintSeen(state, 'hint.gibtesnicht'), false)
    assertEqual(state.permanent.seenHints.length, 0)
  })

  check('Hinweise erscheinen erst, wenn ihre Bedingung zutrifft', () => {
    const state = ready()
    // Frischer Zustand: kein Gold im Feld, kein Gold auf dem Konto, keine drei Tuerme.
    // Der Schmelz-Hinweis darf hier noch nicht kommen.
    state.permanent.seenHints.push('hint.melt')
    assertEqual(state.run.station.inventory.length, MELT_COST, 'Startlager hat genau drei')

    const state2 = ready()
    state2.run.gold = 0
    state2.run.station.inventory.length = 0
    const hint = pendingHint(state2)
    assert(hint === null || hint.id !== 'hint.melt', 'ohne drei Tuerme kein Schmelz-Hinweis')
  })

  check('Zuruecksetzen zeigt alle Hinweise wieder', () => {
    const state = ready()
    for (const hint of HINTS) state.permanent.seenHints.push(hint.id)
    assertEqual(pendingHint(state), null)

    resetHints(state)
    assertEqual(state.permanent.seenHints.length, 0)
  })

  check('der Hinweis zum Buff-Turm nennt den Zeitpunkt', () => {
    // GDD 14 Abschnitt 4a nennt den Zeitpunkt des Buff-Turms das groesste
    // Verstaendnisrisiko des Spiels - der Text muss ihn deshalb ausdruecklich ansprechen.
    const state = ready()
    const hint = HINTS.find((entry) => entry.id === 'hint.buff')
    assert(hint !== undefined, 'den Hinweis muss es geben')
    assert(hint.when(state), 'das Startlager enthaelt einen Verstaerker')
  })

  check('ein Buff-Turm im Lager loest den Hinweis aus, ein platzierter nicht mehr', () => {
    const state = ready()
    const hint = HINTS.find((entry) => entry.id === 'hint.buff')
    assert(hint !== undefined, 'den Hinweis muss es geben')
    assertEqual(hint.when(state), true)

    // Alle Verstaerker platzieren: Der Hinweis hat seinen Zweck erfuellt.
    refresh(state)
    for (const module of [...state.run.station.inventory]) {
      const edges = stationView(state).freeEdges
      const edge = edges[0]
      if (!edge) break
      place(state.run.station, module.uid, edge)
      invalidateStationView(state)
    }
    assertEqual(state.run.station.inventory.length, 0)
    assertEqual(hint.when(state), false)
  })
}

