  const cam = w.camera
  const { width, height } = w.size()
  const ctx = document.getElementById('stage').getContext('2d')
  const zoom = cam.zoom * cam.pulse

  const read = (wx, wy) => {
    const sx = Math.round((wx - cam.center.x) * zoom + width / 2)
    const sy = Math.round((wy - cam.center.y) * zoom + height / 2)
    if (sx < 1 || sy < 1 || sx > width - 2 || sy > height - 2) return { sx, sy, out: true }
    const d = ctx.getImageData(sx, sy, 1, 1).data
    return { sx, sy, rgb: [d[0], d[1], d[2]] }
  }

  return JSON.stringify({
    zoom: Number(zoom.toFixed(3)),
    center: cam.center,
    pods: s.run.pods.map((p) => ({ kind: p.defId, ...read(p.x, p.y) })),
  })
})()

