100	export type EventName = keyof EventMap
101	export type EventHandler<K extends EventName> = (payload: EventMap[K]) => void
102	export type Unsubscribe = () => void
103	
104	type HandlerSet = Set<(payload: unknown) => void>
105	
106	const handlers = new Map<EventName, HandlerSet>()
107	
108	/**
109	 * Ein Fehler in einem Zuhoerer darf niemals das Bild anhalten. Er wird gemeldet und
110	 * der naechste Zuhoerer laeuft weiter. Tests koennen die Meldung umlenken.
111	 */
112	let reportError: (name: EventName, error: unknown) => void = (name, error) => {
113	  console.error(`[events] Zuhoerer fuer "${name}" ist gescheitert:`, error)
114	}
115	
116	export function on<K extends EventName>(name: K, handler: EventHandler<K>): Unsubscribe {
117	  let set = handlers.get(name)
118	  if (!set) {
119	    set = new Set()
120	    handlers.set(name, set)
121	  }
122	  const erased = handler as (payload: unknown) => void
123	  set.add(erased)
124	  return () => {
125	    set.delete(erased)
126	  }
127	}
128	
129	export function emit<K extends EventName>(name: K, payload: EventMap[K]): void {
130	  const set = handlers.get(name)
131	  if (!set || set.size === 0) return
132	  // Kopie: ein Zuhoerer darf sich waehrend der Zustellung abmelden.
133	  for (const handler of [...set]) {
134	    try {
135	      handler(payload)
136	    } catch (error) {
137	      reportError(name, error)
138	    }
139	  }
140	}
141	
142	export function listenerCount(name: EventName): number {
143	  return handlers.get(name)?.size ?? 0
144	}
145	
146	/** Alle Zuhoerer entfernen. Wird zwischen Selbsttests gebraucht. */
147	export function resetEvents(): void {
148	  handlers.clear()
149	}
150	
151	/** Fehlerbehandlung umlenken - im Selbsttest, damit erwartete Fehler nicht die Konsole fluten. */
152	export function setEventErrorReporter(reporter: (name: EventName, error: unknown) => void): void {
153	  reportError = reporter
154	}
