1	/**
2	 * Einstellungen des Geraets (GDD 13 Abschnitt 3).
3	 *
4	 * Sie liegen **nicht im Spielstand**, sondern in einer eigenen Ablage. Der Grund ist keine
5	 * Bequemlichkeit: Lautstaerke, Effektstufe und Bewegungsdaempfung sagen etwas ueber das
6	 * Geraet aus, an dem gerade gespielt wird - nicht ueber den Fortschritt. Ein Spielstand,
7	 * der spaeter auf ein anderes Geraet wandert, soll dessen Regler nicht ueberschreiben.
8	 *
9	 * Sie ueberleben deshalb auch das Loeschen des Spielstands und jedes Prestige.
10	 *
11	 * Ein fehlender oder kaputter Eintrag faellt auf den Startwert zurueck. Einstellungen sind
12	 * die Stelle, an der ein Fehler am wenigsten kosten darf: Wer den Ton leiser gestellt hat
13	 * und beim naechsten Start volle Lautstaerke bekommt, aergert sich - wer nichts hat, dem
14	 * fehlt nur eine Bequemlichkeit.
15	 */
16	
17	export type Settings = {
18	  /** Buff-Linien dauerhaft zeigen, nicht nur bei Auswahl. */
19	  buffLines: boolean
20	  /** Kampfeffekte zeichnen: Splitter, Druckwellen, Muendungsfeuer (GDD 13 Abschnitt 10). */
21	  effects: boolean
22	  /** Bewegte Uebergaenge zwischen den Bereichen. Aus fuer wen sie stoeren. */
23	  motion: boolean
24	  /** Lautstaerke von 0 bis 1. */
25	  volume: number
26	}
27	
28	export const SETTINGS_KEY = 'wavebreaker.settings'
29	
30	export function defaultSettings(): Settings {
31	  return { buffLines: true, effects: true, motion: true, volume: 0.5 }
32	}
33	
34	type Storage = {
35	  getItem(key: string): string | null
36	  setItem(key: string, value: string): void
37	}
38	
39	function storage(): Storage | null {
40	  try {
41	    if (typeof localStorage === 'undefined') return null
42	    return localStorage
43	  } catch {
44	    return null
45	  }
46	}
47	
48	export function loadSettings(): Settings {
49	  const base = defaultSettings()
50	  const store = storage()
51	  if (!store) return base
52	
53	  let raw: unknown
54	  try {
55	    const text = store.getItem(SETTINGS_KEY)
56	    if (text === null) return base
57	    raw = JSON.parse(text)
58	  } catch {
59	    return base
60	  }
61	
62	  if (typeof raw !== 'object' || raw === null) return base
63	  const entry = raw as Record<string, unknown>
64	
65	  return {
66	    buffLines: readBoolean(entry['buffLines'], base.buffLines),
67	    effects: readBoolean(entry['effects'], base.effects),
68	    motion: readBoolean(entry['motion'], base.motion),
69	    volume: readVolume(entry['volume'], base.volume),
70	  }
71	}
72	
73	export function saveSettings(settings: Settings): void {
74	  const store = storage()
75	  if (!store) return
76	  try {
77	    store.setItem(SETTINGS_KEY, JSON.stringify(settings))
78	  } catch {
79	    // Speicher gesperrt oder voll - das Spiel laeuft weiter, nur ohne gemerkte Regler.
80	  }
81	}
82	
83	function readBoolean(value: unknown, fallback: boolean): boolean {
84	  return typeof value === 'boolean' ? value : fallback
85	}
86	
87	function readVolume(value: unknown, fallback: number): number {
88	  if (typeof value !== 'number' || !Number.isFinite(value)) return fallback
89	  return Math.max(0, Math.min(1, value))
90	}
