    (() => {
      const box = document.createElement('pre'); box.id = '__probe'; box.style.display = 'none'; document.body.appendChild(box);
      const p = window.proto;
      const readout = document.getElementById('readout');
      const lines = [];
      const hop = (to, label) => { p.layout.timeline?.pause(); p.goTo(to); lines.push(label.padEnd(24) + readout.textContent); };
      // busy-Sperre umgehen: jede Bewegung sofort ans Ende spulen, dann die naechste
      const finish = () => { const l = p.timeline(); if (l) l.seek(l.duration); };
      p.goTo('base');      lines.push('combat -> base'.padEnd(24) + readout.textContent); finish();
      p.goTo('prestige');  lines.push('base -> prestige'.padEnd(24) + readout.textContent); finish();
      p.goTo('settings');  lines.push('prestige -> settings'.padEnd(24) + readout.textContent); finish();
      p.goTo('combat');    lines.push('settings -> combat'.padEnd(24) + readout.textContent); finish();
      box.textContent = lines.join('\\n');
    })();
  `;
  document.documentElement.appendChild(s);
  s.remove();
  setTimeout(() => resolve(document.getElementById('__probe')?.textContent || 'leer'), 400);
})

