/*
 * Staffelung.
 *
 * Alle Kacheln zugleich auffahren zu lassen sieht aus wie ein Block, der eingeblendet wird.
 * Ein Versatz von rund 40 ms je Nachbar macht daraus eine Welle, die durch das Raster
 * laeuft - man liest die Reihenfolge, ohne sie zu bemerken. Ueber die achte Kachel hinaus
 * wird nicht weiter gestaffelt: Sonst warteten die letzten Eintraege einer langen Liste
 * spuerbar lange.
 */
.upgrade-grid > *,
ul.inventory > *,
.cat-tabs > * {
  animation: card-rise var(--dur-card) var(--ease-out) backwards;
}

.upgrade-grid > *:nth-child(1),
ul.inventory > *:nth-child(1),
.cat-tabs > *:nth-child(1) {
  animation-delay: 0ms;
}
.upgrade-grid > *:nth-child(2),
ul.inventory > *:nth-child(2),
.cat-tabs > *:nth-child(2) {
  animation-delay: var(--stagger);
}
.upgrade-grid > *:nth-child(3),
ul.inventory > *:nth-child(3),
.cat-tabs > *:nth-child(3) {
  animation-delay: calc(2 * var(--stagger));
}
.upgrade-grid > *:nth-child(4),
ul.inventory > *:nth-child(4),
.cat-tabs > *:nth-child(4) {
  animation-delay: calc(3 * var(--stagger));
}
.upgrade-grid > *:nth-child(5),
ul.inventory > *:nth-child(5) {
  animation-delay: calc(4 * var(--stagger));
}
.upgrade-grid > *:nth-child(6),
ul.inventory > *:nth-child(6) {
  animation-delay: calc(5 * var(--stagger));
}
.upgrade-grid > *:nth-child(7),
ul.inventory > *:nth-child(7) {
  animation-delay: calc(6 * var(--stagger));
}
.upgrade-grid > *:nth-child(n + 8),
ul.inventory > *:nth-child(n + 8) {
  animation-delay: calc(7 * var(--stagger));
}

/* Der gewaehlte Reiter quittiert den Wechsel mit einem kurzen Stupser. */
