/* Der gewaehlte Reiter quittiert den Wechsel mit einem kurzen Stupser. */
.nav-button.active .pix {
  animation: pop var(--dur-icon) var(--ease-spring);
}

/*
 * Bewegung aus - auf zwei Wegen zum selben Ziel.
 *
 * Der erste ist die Einstellung des Betriebssystems, der zweite der Schalter im Spiel
 * (E18, GDD 13 Abschnitt 3). Beide fuehren auf **dieselben** Regeln: Wer die Bewegung
 * abschaltet, soll dieselbe ruhige Oberflaeche bekommen, egal wo er es getan hat.
 *
 * Das Merkmal sitzt am Wurzelknoten wie `data-view`. Die Alternative waere, in jeder Regel
 * eine Bedingung zu fuehren - und dann bliebe irgendwo eine Bewegung stehen.
 */
@media (prefers-reduced-motion: reduce) {
  :root {
    --motion: 0;
  }

  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    animation-delay: 0ms !important;
    transition-duration: 1ms !important;
  }

  /*
   * Endlos laufende Bewegungen brauchen die harte Abschaltung. Nur die Dauer zu kuerzen
   * macht aus einer ruhig fliessenden Schraffur ein Flackern mit tausend Bildern je
   * Sekunde - also genau das Gegenteil dessen, was hier gewuenscht ist.
   */
  #app::after,
  .bar i::after,
  .outcome .caret {
    animation: none !important;
  }

  /*
   * Das Wanderlicht ist reine Bewegung. Es stehenzulassen ergaebe keinen ruhigen Rahmen,
   * sondern einen hellen Fleck, der in einer Ecke klebt - also nimmt der Ring seine Farbe
   * zurueck. Uebrig bleibt die ruhige Grundlinie darunter: Der Rahmen bleibt, nur das
   * Licht darin geht aus.
   */
  :root {
    --shine: linear-gradient(transparent, transparent);
  }
}

#app[data-motion='off'] {
  --motion: 0;
}

#app[data-motion='off'],
#app[data-motion='off'] *,
#app[data-motion='off'] *::before,
#app[data-motion='off'] *::after {
  animation-duration: 1ms !important;
  animation-delay: 0ms !important;
  transition-duration: 1ms !important;
}

#app[data-motion='off'] {
  --shine: linear-gradient(transparent, transparent);
}

