251	/* --- Bewegung: auftreten und abtreten ------------------------------------ */
252	
253	/*
254	 * Ein Bereichswechsel ist eine Bewegung, kein Schnitt (GDD 13 Abschnitt 10).
255	 *
256	 * Jedes Panel faehrt aus der Richtung auf, in der es sitzt, und zieht in dieselbe Richtung
257	 * wieder ab. Dabei laufen immer **mehrere** Groessen zugleich: Ort, Groesse, Weichzeichnung
258	 * und Deckkraft. Nur zu blenden liest sich als Bildwechsel; erst die Verschiebung um wenige
259	 * Pixel und die Skalierung von 0,985 auf 1 machen daraus eine Bewegung im Raum.
260	 *
261	 * Die Weichzeichnung ist der Teil, den man am wenigsten bewusst sieht und am meisten spuert:
262	 * Sie ersetzt die Bewegungsunschaerfe, die es auf einem Bildschirm nicht gibt.
263	 */
264	
265	@keyframes enter-up {
266	  from {
267	    opacity: 0;
268	    transform: translateY(16px) scale(0.985);
269	    filter: blur(6px);
270	  }
271	}
272	
273	@keyframes enter-left {
274	  from {
275	    opacity: 0;
276	    transform: translateX(-18px) scale(0.985);
277	    filter: blur(6px);
278	  }
279	}
280	
281	@keyframes enter-right {
282	  from {
283	    opacity: 0;
284	    transform: translateX(18px) scale(0.985);
285	    filter: blur(6px);
286	  }
287	}
288	
289	@keyframes enter-down {
290	  from {
291	    opacity: 0;
292	    transform: translateY(-14px) scale(0.985);
293	    filter: blur(6px);
294	  }
295	}
296	
297	/* Mittig gesetzte Elemente behalten ihre Verschiebung, sonst springen sie aus der Mitte. */
298	@keyframes enter-center {
299	  from {
300	    opacity: 0;
301	    transform: translate(-50%, calc(-50% + 14px)) scale(0.97);
302	    filter: blur(8px);
303	  }
304	}
305	
306	@keyframes enter-title {
307	  from {
308	    opacity: 0;
309	    transform: translateX(-50%) translateY(-10px);
310	    filter: blur(5px);
311	  }
312	}
313	
314	@keyframes leave-up {
315	  to {
316	    opacity: 0;
317	    transform: translateY(10px) scale(0.99);
318	    filter: blur(5px);
319	  }
320	}
321	
322	@keyframes leave-left {
323	  to {
324	    opacity: 0;
325	    transform: translateX(-14px) scale(0.99);
326	    filter: blur(5px);
327	  }
328	}
329	
330	@keyframes leave-right {
331	  to {
332	    opacity: 0;
333	    transform: translateX(14px) scale(0.99);
334	    filter: blur(5px);
335	  }
336	}
337	
338	@keyframes leave-down {
339	  to {
340	    opacity: 0;
341	    transform: translateY(-10px) scale(0.99);
342	    filter: blur(5px);
343	  }
344	}
345	
346	@keyframes leave-center {
347	  to {
348	    opacity: 0;
349	    transform: translate(-50%, -50%) scale(0.96);
350	    filter: blur(7px);
351	  }
352	}
353	
354	@keyframes leave-title {
355	  to {
356	    opacity: 0;
357	    transform: translateX(-50%) translateY(-8px);
358	    filter: blur(5px);
359	  }
360	}
361	
362	/* Karten und Listeneintraege innerhalb eines Panels - gestaffelt, siehe unten. */
363	@keyframes card-rise {
364	  from {
365	    opacity: 0;
366	    transform: translateY(10px) scale(0.98);
367	    filter: blur(4px);
368	  }
369	}
370	
371	@keyframes pop {
372	  0% {
373	    transform: scale(0.8);
374	  }
375	  60% {
376	    transform: scale(1.14);
377	  }
378	}
