380	/* Auftritt: aus der Richtung, in der das Panel sitzt. */
381	.upgrade-panel,
382	.hull-bar {
383	  animation: enter-up var(--dur-view) var(--ease-out);
384	}
385	
386	.nav {
387	  animation: enter-up var(--dur-view) var(--ease-out) 60ms backwards;
388	}
389	
390	.inventory-panel {
391	  animation: enter-left var(--dur-view) var(--ease-out);
392	}
393	
394	.rail,
395	.meta-card,
396	.wave-card {
397	  animation: enter-right var(--dur-view) var(--ease-out);
398	}
399	
400	.resource-bar {
401	  animation: enter-down var(--dur-view) var(--ease-out);
402	}
403	
404	.speed-control {
405	  animation: enter-up var(--dur-card) var(--ease-out) 80ms backwards;
406	}
407	
408	.settings-panel {
409	  animation: enter-center var(--dur-view) var(--ease-out);
410	}
411	
412	.prestige-panel {
