420	/*
421	 * Abtritt. `data-leaving` steht am `#app`, solange der alte Bereich noch zu sehen ist
422	 * (siehe `goTo` in `ui/shell.ts`). Die Dauer ist kuerzer als der Auftritt: Wegtreten darf
423	 * schnell gehen, Ankommen soll man sehen.
424	 *
425	 * `forwards` haelt den Endzustand, damit das Panel nicht im letzten Bild noch einmal
426	 * aufblitzt, bevor der Bereich wirklich wechselt.
427	 */
428	#app[data-leaving] .upgrade-panel,
429	#app[data-leaving] .hull-bar,
430	#app[data-leaving] .nav {
431	  animation: leave-up 150ms var(--ease-out) forwards;
432	}
433	
434	#app[data-leaving] .inventory-panel {
435	  animation: leave-left 150ms var(--ease-out) forwards;
436	}
437	
438	#app[data-leaving] .rail,
439	#app[data-leaving] .meta-card,
440	#app[data-leaving] .wave-card {
441	  animation: leave-right 150ms var(--ease-out) forwards;
442	}
443	
444	#app[data-leaving] .resource-bar,
445	#app[data-leaving] .speed-control {
446	  animation: leave-down 150ms var(--ease-out) forwards;
447	}
448	
449	#app[data-leaving] .settings-panel {
450	  animation: leave-center 150ms var(--ease-out) forwards;
451	}
452	
453	#app[data-leaving] .prestige-panel {
454	  animation: leave-up 150ms var(--ease-out) forwards;
455	}
