461	/*
462	 * Staffelung.
463	 *
464	 * Alle Kacheln zugleich auffahren zu lassen sieht aus wie ein Block, der eingeblendet wird.
465	 * Ein Versatz von rund 40 ms je Nachbar macht daraus eine Welle, die durch das Raster
466	 * laeuft - man liest die Reihenfolge, ohne sie zu bemerken. Ueber die achte Kachel hinaus
467	 * wird nicht weiter gestaffelt: Sonst warteten die letzten Eintraege einer langen Liste
468	 * spuerbar lange.
469	 */
470	.upgrade-grid > *,
471	ul.inventory > *,
472	.cat-tabs > * {
473	  animation: card-rise var(--dur-card) var(--ease-out) backwards;
474	}
475	
476	.upgrade-grid > *:nth-child(1),
477	ul.inventory > *:nth-child(1),
478	.cat-tabs > *:nth-child(1) {
479	  animation-delay: 0ms;
480	}
481	.upgrade-grid > *:nth-child(2),
482	ul.inventory > *:nth-child(2),
483	.cat-tabs > *:nth-child(2) {
484	  animation-delay: var(--stagger);
485	}
486	.upgrade-grid > *:nth-child(3),
487	ul.inventory > *:nth-child(3),
488	.cat-tabs > *:nth-child(3) {
489	  animation-delay: calc(2 * var(--stagger));
490	}
491	.upgrade-grid > *:nth-child(4),
492	ul.inventory > *:nth-child(4),
493	.cat-tabs > *:nth-child(4) {
494	  animation-delay: calc(3 * var(--stagger));
495	}
496	.upgrade-grid > *:nth-child(5),
497	ul.inventory > *:nth-child(5) {
498	  animation-delay: calc(4 * var(--stagger));
499	}
500	.upgrade-grid > *:nth-child(6),
501	ul.inventory > *:nth-child(6) {
502	  animation-delay: calc(5 * var(--stagger));
503	}
504	.upgrade-grid > *:nth-child(7),
505	ul.inventory > *:nth-child(7) {
506	  animation-delay: calc(6 * var(--stagger));
507	}
508	.upgrade-grid > *:nth-child(n + 8),
509	ul.inventory > *:nth-child(n + 8) {
510	  animation-delay: calc(7 * var(--stagger));
511	}
512	
513	/* Der gewaehlte Reiter quittiert den Wechsel mit einem kurzen Stupser. */
514	.nav-button.active .pix {
515	  animation: pop var(--dur-icon) var(--ease-spring);
516	}
