518	/*
519	 * Bewegung aus - auf zwei Wegen zum selben Ziel.
520	 *
521	 * Der erste ist die Einstellung des Betriebssystems, der zweite der Schalter im Spiel
522	 * (E18, GDD 13 Abschnitt 3). Beide fuehren auf **dieselben** Regeln: Wer die Bewegung
523	 * abschaltet, soll dieselbe ruhige Oberflaeche bekommen, egal wo er es getan hat.
524	 *
525	 * Das Merkmal sitzt am Wurzelknoten wie `data-view`. Die Alternative waere, in jeder Regel
526	 * eine Bedingung zu fuehren - und dann bliebe irgendwo eine Bewegung stehen.
527	 */
528	@media (prefers-reduced-motion: reduce) {
529	  *,
530	  *::before,
531	  *::after {
532	    animation-duration: 1ms !important;
533	    animation-delay: 0ms !important;
534	    transition-duration: 1ms !important;
535	  }
536	
537	  /*
538	   * Endlos laufende Bewegungen brauchen die harte Abschaltung. Nur die Dauer zu kuerzen
539	   * macht aus einer ruhig fliessenden Schraffur ein Flackern mit tausend Bildern je
540	   * Sekunde - also genau das Gegenteil dessen, was hier gewuenscht ist.
541	   */
542	  .bar i::after,
543	  .outcome .caret {
544	    animation: none !important;
545	  }
546	}
547	
548	#app[data-motion='off'],
549	#app[data-motion='off'] *,
550	#app[data-motion='off'] *::before,
551	#app[data-motion='off'] *::after {
552	  animation-duration: 1ms !important;
553	  animation-delay: 0ms !important;
554	  transition-duration: 1ms !important;
555	}
556	
557	#app[data-motion='off'] .bar i::after,
558	#app[data-motion='off'] .outcome .caret {
559	  animation: none !important;
560	}
