562	/* --- Gemeinsame Bausteine ------------------------------------------------ */
563	
564	/*
565	 * Panel und Schild sind dasselbe in zwei Groessen: Ein Panel traegt Inhalt, ein Schild
566	 * traegt eine Zahl. Beide sind dunkle Flaechen mit leuchtender Kante.
567	 */
568	.panel,
569	.plate {
570	  border: 1px solid var(--line);
571	  border-radius: 12px;
572	  background: var(--fill-panel);
573	  box-shadow: var(--glow), var(--shadow-panel);
574	  backdrop-filter: blur(7px);
575	}
576	
577	.panel {
578	  padding: 12px 14px;
579	  overflow-y: auto;
580	}
581	
582	.plate {
583	  padding: 7px 12px;
584	}
585	
586	.panel header {
587	  display: flex;
588	  align-items: center;
589	  justify-content: space-between;
590	  gap: 8px;
591	  margin-bottom: 10px;
592	}
593	
594	.panel h2 {
595	  margin: 0;
596	  font-size: 12px;
597	  font-weight: 800;
598	  letter-spacing: 0.16em;
