601	  text-shadow: 0 0 10px rgba(127, 216, 255, 0.5);
602	}
603	
604	.panel h3 {
605	  margin: 12px 0 4px;
606	  font-size: 11px;
607	  font-weight: 700;
608	  letter-spacing: 0.14em;
609	  text-transform: uppercase;
610	  color: var(--text-dim);
611	}
612	
613	.panel p {
614	  margin: 6px 0 0;
615	  font-size: 12px;
616	  line-height: 1.5;
617	}
