633	/*
634	 * Symbol aus dem Anlagensatz. Die Datei liefert nur die Form - die Farbe kommt aus
635	 * `currentColor`, damit dasselbe Zeichen je nach Bedeutung anders leuchtet.
636	 */
637	.pix {
638	  display: inline-block;
639	  flex: none;
640	  width: var(--pix-size, 16px);
641	  height: var(--pix-size, 16px);
642	  background-color: currentColor;
643	  -webkit-mask: var(--icon) center / contain no-repeat;
644	  mask: var(--icon) center / contain no-repeat;
