647	/* Raritaetsrahmen mit Symbol darin. Pixelgenau skaliert, sonst franst der Rahmen aus. */
648	.tile {
649	  display: inline-grid;
650	  place-items: center;
651	  flex: none;
652	  width: 32px;
653	  height: 32px;
654	  background: var(--frame) center / contain no-repeat;
655	  image-rendering: pixelated;
656	}
