658	/*
659	 * Kleine Schaltflaeche - Tempo, Auto-Modus, Einstellungen.
660	 *
661	 * Der Rahmen leuchtet erst beim Beruehren richtig auf: Ein Knopf, der immer schon leuchtet,
662	 * sagt nichts mehr, wenn man ihn erreicht.
663	 */
664	.chip,
665	.wave-controls button,
666	.speed-control button {
667	  min-height: 30px;
668	  padding: 4px 11px;
669	  border: 1px solid var(--line-soft);
670	  border-radius: 8px;
671	  background: rgba(10, 20, 54, 0.65);
672	  color: var(--text-dim);
673	  font: inherit;
674	  font-size: 12px;
675	  font-weight: 700;
676	  letter-spacing: 0.08em;
677	  cursor: pointer;
678	  transition: color var(--dur-tap) var(--ease-out),
679	    border-color var(--dur-tap) var(--ease-out), box-shadow var(--dur-tap) var(--ease-out),
680	    transform var(--dur-tap) var(--ease-out);
681	}
682	
683	.chip:hover:not(:disabled),
684	.wave-controls button:hover:not(:disabled),
685	.speed-control button:hover:not(:disabled) {
686	  color: var(--text);
687	  border-color: var(--line);
688	  box-shadow: var(--glow-soft);
689	}
690	
691	.chip:active:not(:disabled),
692	.wave-controls button:active:not(:disabled),
693	.speed-control button:active:not(:disabled) {
694	  transform: scale(0.94);
695	}
696	
697	.chip.active,
698	.wave-controls button.active {
699	  border-color: var(--lime);
700	  color: var(--lime);
701	  box-shadow: 0 0 14px rgba(127, 232, 63, 0.35), inset 0 0 12px rgba(127, 232, 63, 0.12);
702	  text-shadow: 0 0 8px rgba(127, 232, 63, 0.6);
703	}
704	
705	.chip:disabled,
706	.wave-controls button:disabled,
707	.speed-control button:disabled {
708	  opacity: 0.28;
709	  cursor: default;
710	}
711	
712	/* Schaltflaeche, deren ganzer Inhalt ein Symbol ist. */
713	.icon-button {
714	  display: grid;
715	  place-items: center;
716	  width: 34px;
717	  padding: 0;
718	}
719	
720	/*
721	 * --- Rollende Beschriftung (siehe ui/slide.ts) ---------------------------
722	 *
723	 * Unter dem Zeiger faehrt die Beschriftung eine Zeile nach oben, und dieselbe Beschriftung
724	 * kommt von unten nach. Der Rahmen schneidet ab, was dabei aus ihm herausfaehrt - ohne den
725	 * Schnitt haenge die abtretende Fassung ueber der Oberkante des Knopfes.
726	 *
727	 * Der Schnitt steht an den Knopfarten und nicht an `.slide`: Ein Schnitt an der Beschriftung
728	 * selbst laege genau auf der Zeile und naehme den Unterlaengen ihre Spitzen.
729	 */
730	.chip,
731	.wave-controls button,
732	.speed-control button,
733	.wide-button,
734	.cat-tab {
735	  overflow: hidden;
736	}
737	
738	/* Die aeussere Huelle faehrt. */
739	.slide {
740	  position: relative;
741	  display: inline-block;
742	  transition: transform var(--dur-slide) var(--ease-out);
743	}
744	
745	/* Die innere blendet ab - getrennt, weil Durchsichtigkeit sich auf `::after` vererbte. */
746	.slide > span {
747	  display: block;
748	  transition: opacity var(--dur-slide) var(--ease-out);
749	}
750	
751	/* Die Zweitfassung: eine Zeile tiefer und unsichtbar, bis der Zeiger kommt. */
752	.slide::after {
753	  content: attr(data-slide);
754	  position: absolute;
755	  top: 100%;
756	  left: 0;
757	  right: 0;
758	  opacity: 0;
759	  transition: opacity var(--dur-slide) var(--ease-out);
760	}
761	
762	button:hover:not(:disabled) .slide {
763	  transform: translateY(-100%);
764	}
765	
766	button:hover:not(:disabled) .slide > span {
767	  opacity: 0;
768	}
769	
770	button:hover:not(:disabled) .slide::after {
771	  opacity: 1;
772	}
773	
774	/*
775	 * Leiste mit Fuellung und mittiger Beschriftung.
776	 *
777	 * Die Fuellung traegt eine laufende Schraffur aus dem Anlagensatz - dadurch sieht man auch
778	 * bei stehender Leiste, dass Energie darin ist, und nicht nur einen farbigen Balken.
779	 */
780	.bar {
781	  position: relative;
782	  height: 17px;
783	  border: 1px solid var(--line-soft);
784	  border-radius: 6px;
785	  background: rgba(3, 5, 13, 0.85);
786	  overflow: hidden;
787	}
788	
789	/*
790	 * Die Fuellung leuchtet in ihrer eigenen Farbe. `color` traegt dieselbe Farbe wie
791	 * `background`, damit der Schein ueber `currentColor` mitwandert - sonst leuchtete eine rote
792	 * Lebensleiste weiterhin tuerkis, weil `currentColor` sonst die Textfarbe waere.
793	 */
794	.bar i {
795	  position: absolute;
796	  inset: 0 auto 0 0;
797	  display: block;
798	  color: var(--ok);
799	  background: currentColor;
800	  box-shadow: 0 0 12px currentColor;
801	  transition: width 160ms var(--ease-out);
802	}
803	
804	/* Die Schraffur laeuft langsam durch die Fuellung - Energie in Bewegung. */
805	.bar i::after {
806	  content: '';
807	  position: absolute;
808	  inset: 0;
809	  background: url('/ui/bar-hatch.png') left center / auto 100% repeat-x;
810	  opacity: 0.35;
811	  mix-blend-mode: overlay;
812	  animation: hatch-flow 1.6s linear infinite;
813	}
