@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    animation-delay: 0ms !important;
    transition-duration: 1ms !important;
  }

  /*
   * Endlos laufende Bewegungen brauchen die harte Abschaltung. Nur die Dauer zu kuerzen
   * macht aus einer ruhig fliessenden Schraffur ein Flackern mit tausend Bildern je
   * Sekunde - also genau das Gegenteil dessen, was hier gewuenscht ist.
   */
  #app,
  .bar i::after,
  .outcome .caret {
    animation: none !important;
  }

  /*
   * Das Wanderlicht ist reine Bewegung. Es stehenzulassen ergaebe keinen ruhigen Rahmen,
   * sondern einen hellen Fleck, der irgendwo in einer Ecke klebt - also nimmt der Ring
   * seine Farbe zurueck, und uebrig bleibt die ruhige Grundkante darunter.
   */
  :root {
    --shine: linear-gradient(transparent, transparent);
  }
}

