(async () => {
  const backdrop = await import('/src/render/backdrop.ts')
  const { THEME } = await import('/src/render/theme.ts')

  const W = 900, H = 520
  const cv = document.createElement('canvas')
  cv.width = W; cv.height = H
  const ctx = cv.getContext('2d')

  function background() {
    const g = ctx.createLinearGradient(0, 0, 0, H)
    g.addColorStop(0, THEME.bgTop); g.addColorStop(1, THEME.bgBottom)
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H)
    ctx.strokeStyle = THEME.grid; ctx.lineWidth = 1; ctx.beginPath()
    for (let x = 0; x < W; x += THEME.gridSpacing) { ctx.moveTo(Math.round(x)+0.5, 0); ctx.lineTo(Math.round(x)+0.5, H) }
    for (let y = 0; y < H; y += THEME.gridSpacing) { ctx.moveTo(0, Math.round(y)+0.5); ctx.lineTo(W, Math.round(y)+0.5) }
    ctx.stroke()
    const cx = W/2, cy = H/2, reach = Math.min(W,H)*THEME.glowRadius
    const glow = ctx.createRadialGradient(cx, cy, 0, cx, cy, reach)
    glow.addColorStop(0, THEME.glowCore); glow.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = glow; ctx.fillRect(0, 0, W, H)
    const corner = Math.hypot(cx, cy)
    const shade = ctx.createRadialGradient(cx, cy, corner*0.55, cx, cy, corner)
    shade.addColorStop(0, 'rgba(0,0,0,0)'); shade.addColorStop(1, THEME.vignette)
    ctx.fillStyle = shade; ctx.fillRect(0, 0, W, H)
  }

  // Blende hochfahren, dann das letzte Bild behalten.
  for (let i = 0; i <= 40; i++) { background(); backdrop.drawLightBeams(ctx, W, H, i * 0.1, 1) }
  const withBeams = cv.toDataURL('image/png')

  background()
  const plain = cv.toDataURL('image/png')

  await fetch('http://localhost:45997/beams', { method: 'POST', mode: 'no-cors', body: withBeams })
  await fetch('http://localhost:45997/plain', { method: 'POST', mode: 'no-cors', body: plain })
  return 'ok'
})()

