    .map(r => ({ sel: r.sel, css: r.css, matchesWithoutHover: [s, s.firstElementChild].some(n => n && n.matches(r.sel.replace(/:hover/g, ''))) }));
  return { alle: wanted.map(r => r.sel), hoverRegeln: probe };
})()

