/*
 * Grundgeruest der Seite. Die eigentliche Gestaltung (GDD 13) entsteht ab E1 in
 * render/theme.ts fuer das Canvas und ab E3 hier fuer die Panels.
 */

:root {
  /*
   * Palette aus dem Referenzbild - dieselben Werte stehen als PALETTE in
   * src/render/theme.ts. Canvas und DOM liegen uebereinander; wer hier etwas aendert,
   * aendert es dort mit, sonst laufen Spielfeld und Oberflaeche farblich auseinander.
   */
  --ink: #0a0d1a;
  --ink-deep: #06080f;
  --panel: #122354;
  --panel-deep: #0f1b40;
  --edge: #7fd8ff;
  --cyan: #46c8ff;
  --teal: #2ee0c0;
  --lime: #7fe83f;
  --magenta: #ff2d78;
  --gold: #ffcc33;
  /* Sektionsbalken ueber Listen - vorgesehen fuer das HUD aus E9. */
  --section: #29a3f5;

  /* Rollen. Im Spiel wird auf diese Namen verwiesen, nicht auf die Farben darueber. */
  --bg: var(--ink);
  --bg-panel: var(--panel);
  --line: rgba(127, 216, 255, 0.5);
  --text: #ffffff;
  --text-dim: #8fa8d4;
  --accent: var(--cyan);
  --ok: var(--teal);
  --fail: var(--magenta);
  --warn: var(--gold);
  --glow: 0 0 14px rgba(70, 200, 255, 0.14);
  --font: 'Segoe UI', system-ui, sans-serif;
  --mono: ui-monospace, 'Cascadia Mono', 'Consolas', monospace;
}

