const c = document.querySelector('#stage');
const w = 520, h = Math.round(c.height / c.width * 520);
const o = document.createElement('canvas'); o.width = w; o.height = h;
o.getContext('2d').drawImage(c, 0, 0, w, h);
const url = o.toDataURL('image/png');
JSON.stringify({ src: [c.width, c.height], out: [w, h], len: url.length, tabs: [...document.querySelectorAll('.tabs button')].map(b => b.textContent + (b.classList.contains('active') ? '*' : '')) })

(() => {
  const src = document.querySelector('#stage');
  const w = 420, h = Math.round(src.height / src.width * 420);
  const o = document.createElement('canvas'); o.width = w; o.height = h;
  const g = o.getContext('2d'); g.drawImage(src, 0, 0, w, h);
  const d = g.getImageData(0, 0, w, h).data;
  let lit = 0; for (let i = 0; i < d.length; i += 4) { if (d[i] + d[i+1] + d[i+2] > 90) lit++ }
  const url = o.toDataURL('image/png');
  return JSON.stringify({ out: [w, h], litPixels: lit, len: url.length, visibility: document.visibilityState })
})()

