471	li.upgrade button {
472	  min-width: 92px;
473	  padding: 4px 8px;
474	  border: 1px solid var(--line);
475	  border-radius: 4px;
476	  background: transparent;
477	  color: var(--text);
478	  font: inherit;
479	  font-family: var(--mono);
480	  font-size: 11px;
481	  cursor: pointer;
482	}
483	
484	li.upgrade button:hover:not(:disabled) {
485	  border-color: var(--accent);
486	  color: var(--accent);
487	}
488	
489	li.upgrade button:disabled {
490	  opacity: 0.35;
491	  cursor: default;
492	}
493	
494	.tooltip {
495	  position: fixed;
496	  z-index: 20;
497	  max-width: 260px;
498	  padding: 6px 9px;
499	  border: 1px solid var(--line);
500	  border-radius: 8px;
501	  background: var(--panel-deep);
502	  box-shadow: var(--glow);
503	  color: var(--text);
504	  font-size: 12px;

input.content:
/**
 * Rahmen der Oberflaeche: Bereiche, Navileiste, Panels (GDD 13 Abschnitt 3 und 4).
 *
 * Der Aufbau folgt den Entwurfsbildern:
 *
 *   Kampf                              Basis
 *   +--------------------------+       +--------------------------+
 *   |        Spielfeld         |       | Lager |  Feld  |  Welle  |
 *   |                          |       |       |        |  Detail |
 *   +--------------------------+       |       |        |  Kaufen |
 *   | Werte-Karte | Wellenkarte|       +--------------------------+
 *   | Navi | Upgrade-Kacheln   |       | Navi                     |
 *   +--------------------------+       +--------------------------+
 *
 * Zwei Regeln halten das zusammen:
 *   - **Der Bereich steht am `#app`**, nicht in jedem Knoten. Was sichtbar ist, entscheidet
 *     das Stilblatt ueber `[data-view]`. Deshalb muss hier nichts ein- und ausgeblendet
 *     werden, und die HUD-Anzeigen koennen stumpf weiterrechnen.
 *   - **Panels bauen sich nur auf Anforderung neu.** `refresh()` nach einer Handlung,
 *     `update()` pro Bild - sonst spraenge bei jedem eingesammelten Goldstapel die
 *     Bildlaufposition zurueck.
 */

import { t } from '../data/strings.ts'
import { setView } from '../app/actions.ts'
import type { GameState, View } from '../app/state.ts'
import { renderInventory, renderModuleDetail, renderShop } from './base.ts'
import { icon, type IconName } from './icons.ts'
import { mountSettings, type SettingsControls } from './settings.ts'
import { mountUpgradeMenu, type UpgradeMenu } from './upgrades.ts'

export type ShellTargets = {
  /** Traegt `data-view` - daran haengt die gesamte Sichtbarkeit. */
  app: HTMLElement
  /** Schwebende Anzeigen ueber dem Spielfeld. */
  overlay: HTMLElement
  /** Untere Leiste: Statuskarten, Navileiste, Upgrade-Panel. */
  dock: HTMLElement
}

export type Shell = {
  /** Panels neu aufbauen. Nach jeder Handlung aufrufen, nicht pro Bild. */
  refresh(): void
  /** Pro Bild aufrufen - aktualisiert nur, was sich staendig aendert. */
  update(): void
  /** Zeile fuer die Statuskarten. Das HUD haengt sich hier ein. */
  statusRow: HTMLElement
  detach(): void
}

const NAV: readonly { id: View; icon: IconName; label: 'view.combat' | 'view.base' | 'view.upgrades' | 'view.settings' }[] = [
  { id: 'combat', icon: 'combat', label: 'view.combat' },
  { id: 'base', icon: 'base', label: 'view.base' },
  { id: 'upgrades', icon: 'upgrades', label: 'view.upgrades' },
  { id: 'settings', icon: 'settings', label: 'view.settings' },
]

export function mountShell(
  state: GameState,
  targets: ShellTargets,
  controls: SettingsControls,
): Shell {
  const { app, overlay, dock } = targets

  // --- Ueber dem Spielfeld ---
  const title = element('h1', 'view-title')
  const inventory = element('section', 'panel inventory-panel')
  const rail = element('div', 'rail')
  const detail = element('section', 'panel detail-panel')
  const shop = element('section', 'panel shop-panel')
  const settings = element('section', 'panel settings-panel')

  // Die Wellen- und Goldkarte der Basis fuellt das HUD - sie steht hier nur im Aufbau.
  const meta = element('section', 'card meta-card')

  rail.append(meta, detail, shop)
  overlay.append(title, inventory, rail, settings)

  // --- Untere Leiste ---
  const statusRow = element('div', 'status-row')
  const dockRow = element('div', 'dock-row')
  const nav = element('nav', 'nav')
  const upgrades = element('section', 'panel upgrade-panel')

  dockRow.append(nav, upgrades)
  dock.append(statusRow, dockRow)

  const buttons = new Map<View, HTMLButtonElement>()
  for (const entry of NAV) {
    const button = document.createElement('button')
    button.type = 'button'
    button.className = `nav-button nav-${entry.id}`
    button.title = t(entry.label)
    button.setAttribute('aria-label', t(entry.label))
    button.innerHTML = icon(entry.icon, 26)
    button.addEventListener('click', () => {
      setView(state, entry.id)
      refresh()
    })
    buttons.set(entry.id, button)
    nav.appendChild(button)
  }

  const settingsPanel = mountSettings(settings, controls)
  let menu: UpgradeMenu | null = null

  function refresh(): void {
    const view = state.runtime.view
    app.dataset['view'] = view
    title.textContent = t(view === 'base' ? 'view.base' : 'view.settings')

    for (const [id, button] of buttons) button.classList.toggle('active', view === id)

    // Nur der sichtbare Bereich wird aufgebaut - alles zugleich waere Arbeit fuer nichts.
    if (view === 'base') {
      renderInventory(state, inventory, refresh)
      renderModuleDetail(state, detail)
      renderShop(shop)
    } else if (view === 'combat' || view === 'upgrades') {
      if (!menu) menu = mountUpgradeMenu(state, upgrades, refresh)
      menu.setMode(view === 'upgrades' ? 'full' : 'compact')
      menu.update()
    } else if (view === 'settings') {
      settingsPanel.update()
    }
  }

  refresh()

  return {
    refresh,
    statusRow,
    update() {
      const view = state.runtime.view
      if (view === 'combat' || view === 'upgrades') menu?.update()
    },
    detach() {
      for (const node of [title, inventory, rail, settings, statusRow, dockRow]) node.remove()
    },
  }
}

function element(tag: string, className: string): HTMLElement {
  const node = document.createElement(tag)
  node.className = className
  return node
}

/**
 * Einstellungen (GDD 13 Abschnitt 3).
 *
 * Hier steht **nur, was es wirklich schon gibt**: Tempo, Buff-Linien, Kamera. Lautstaerke,
 * Sprache und Grafikstufen kommen mit E18 dazu - ein Regler ohne Wirkung waere schlimmer
 * als ein fehlender.
 *
 * Alle drei Schalter bedienen Dinge, die bisher nur auf der Tastatur lagen (1/2/4, B, F).
 * Der Bereich macht sie sichtbar, er erfindet nichts.
 */

import { SPEED_FACTORS } from '../data/balance.ts'
import type { SpeedFactor } from '../core/loop.ts'
import { t } from '../data/strings.ts'

export type SettingsControls = {
  speed(): SpeedFactor
  setSpeed(factor: SpeedFactor): void
  buffLines(): boolean
  setBuffLines(on: boolean): void
  resetCamera(): void
}

export type SettingsPanel = {
  /** Nach jedem Bereichswechsel aufrufen - der Zustand kann sich per Tastatur geaendert haben. */
  update(): void
}

export function mountSettings(root: HTMLElement, controls: SettingsControls): SettingsPanel {
  root.replaceChildren()

  const header = document.createElement('header')
  const title = document.createElement('h2')
  title.textContent = t('view.settings')
  header.appendChild(title)
  root.appendChild(header)

  // --- Tempo ---
  const speedButtons = new Map<SpeedFactor, HTMLButtonElement>()
  const speedRow = row(root, t('settings.speed'))
  for (const factor of SPEED_FACTORS) {
    const button = document.createElement('button')
    button.type = 'button'
    button.className = 'chip'
    button.textContent = `x${factor}`
    button.addEventListener('click', () => {
      controls.setSpeed(factor)
      update()
    })
    speedButtons.set(factor, button)
    speedRow.appendChild(button)
  }

  // --- Buff-Linien ---
  const buffButton = document.createElement('button')
  buffButton.type = 'button'
  buffButton.className = 'chip'
  buffButton.addEventListener('click', () => {
    controls.setBuffLines(!controls.buffLines())
    update()
  })
  row(root, t('settings.buffLines')).appendChild(buffButton)

  // --- Kamera ---
  const cameraButton = document.createElement('button')
  cameraButton.type = 'button'
  cameraButton.className = 'chip'
  cameraButton.textContent = t('settings.reset')
  cameraButton.addEventListener('click', () => controls.resetCamera())
  row(root, t('settings.camera')).appendChild(cameraButton)

  const hint = document.createElement('p')
  hint.className = 'muted'
  hint.textContent = t('settings.hint')
  root.appendChild(hint)

  function update(): void {
    const current = controls.speed()
    for (const [factor, button] of speedButtons) button.classList.toggle('active', factor === current)

    const on = controls.buffLines()
    buffButton.textContent = on ? t('settings.on') : t('settings.off')
    buffButton.classList.toggle('active', on)
  }

  update()
  return { update }
}

/** Eine Zeile aus Beschriftung links und Bedienelementen rechts. */
function row(root: HTMLElement, label: string): HTMLElement {
  const line = document.createElement('div')
  line.className = 'setting'

  const name = document.createElement('span')
  name.className = 'label'
  name.textContent = label

  const controls = document.createElement('span')
  controls.className = 'chips'

  line.append(name, controls)
  root.appendChild(line)
  return controls
}

/**
 * Upgrade-Panel (GDD 08 Abschnitt 5, GDD 13 Abschnitt 6).
 *
 * Es sitzt dauerhaft unten rechts in der Kampfansicht - Verbessern ist die Handlung, die
 * der Spieler waehrend einer Welle staendig ausfuehrt, und sie soll keinen Bereichswechsel
 * kosten. Jede Kachel traegt links ihren Namen und rechts einen eigenen Kasten mit
 * bisheriger Wirkung oben und Preis unten.
 *
 * Turm-Upgrades stehen bewusst **je Turmart** und nicht je Exemplar (GDD 08 Abschnitt 5.2):
 * Bei 15 Tuermen bliebe das Menue sonst nicht ueberschaubar, und die eigentliche
 * Entscheidung - in welchen Turmtyp investiere ich? - gaebe es gar nicht.
 *
 * Zwei Darstellungen, eine Liste:
 *   compact  eine Kategorie, oben die Reiter    (Kampfansicht, Panel unten rechts)
 *   full     alle Kategorien untereinander      (Bereich "Upgrades", volle Breite)
 *
 * Aufgebaut wird nur bei einem Wechsel von Kategorie oder Darstellung. Gold aendert sich
 * mit jedem eingesammelten Stapel - wuerde das Panel dabei neu entstehen, spraenge bei
 * jedem Klick die Bildlaufposition zurueck.
 */

import { formatNumber, formatPercent } from '../core/format.ts'
import { t } from '../data/strings.ts'
import { TOWERS } from '../data/towers.ts'
import {
  globalUpgrades,
  upgradesForCore,
  upgradesForTower,
  type UpgradeDef,
} from '../data/upgrades.ts'
import { buyUpgrade, nextUpgradeCost } from '../app/actions.ts'
import type { GameState } from '../app/state.ts'
import { upgradeLevel } from '../sim/stats.ts'
import { PALETTE } from '../render/theme.ts'

export type UpgradeMode = 'compact' | 'full'

export type UpgradeMenu = {
  /** Pro Bild aufrufen - schreibt nur, wenn sich etwas geaendert hat. */
  update(): void
  setMode(mode: UpgradeMode): void
}

type Category = {
  id: string
  name: string
  /** Leitfarbe des Reiters - dieselbe, in der der Turm auf dem Feld leuchtet. */
  accent: string
  paths: readonly UpgradeDef[]
}

type Row = { def: UpgradeDef; value: HTMLElement; cost: HTMLElement; card: HTMLButtonElement }

/** Kern, jede Turmart mit eigenen Pfaden, zuletzt die Station. */
function categories(): Category[] {
  const list: Category[] = [
    { id: 'core', name: t('upgrades.core'), accent: PALETTE.edge, paths: upgradesForCore() },
  ]

  for (const tower of TOWERS) {
    const paths = upgradesForTower(tower.id)
    if (paths.length > 0) list.push({ id: tower.id, name: tower.name, accent: tower.accent, paths })
  }

  list.push({
    id: 'global',
    name: t('upgrades.global'),
    accent: PALETTE.gold,
    paths: globalUpgrades(),
  })
  return list
}

export function mountUpgradeMenu(
  state: GameState,
  root: HTMLElement,
  onChange: () => void,
): UpgradeMenu {
  const groups = categories()
  let mode: UpgradeMode = 'compact'
  let activeId = groups[0]?.id ?? 'core'
  let rows: Row[] = []

  root.replaceChildren()

  const tabs = document.createElement('div')
  tabs.className = 'cat-tabs'
  const body = document.createElement('div')
  body.className = 'cat-body'
  root.append(tabs, body)

  const tabButtons = new Map<string, HTMLButtonElement>()
  for (const group of groups) {
    const button = document.createElement('button')
    button.type = 'button'
    button.className = 'cat-tab'
    button.textContent = group.name
    button.style.setProperty('--accent', group.accent)
    button.addEventListener('click', () => {
      activeId = group.id
      build()
    })
    tabButtons.set(group.id, button)
    tabs.appendChild(button)
  }

  function build(): void {
    rows = []
    body.replaceChildren()

    const shown = mode === 'full' ? groups : groups.filter((group) => group.id === activeId)
    for (const group of shown) body.appendChild(section(group, state, rows, onChange))

    for (const [id, button] of tabButtons) {
      button.classList.toggle('active', mode === 'compact' && id === activeId)
    }
    last = ''
    update()
  }

  let last = ''

  function update(): void {
    const signature = `${Math.floor(state.run.gold)}|${JSON.stringify(state.run.upgrades)}`
    if (signature === last) return
    last = signature

    for (const row of rows) {
      const level = upgradeLevel(state.run.upgrades, row.def.id)
      const cost = nextUpgradeCost(state, row.def.id)

      row.value.textContent = formatPercent(row.def.amount * level, { sign: true })
      row.cost.textContent =
        cost === null ? t('upgrades.max') : t('hud.costs', { amount: formatNumber(cost) })

      const affordable = cost !== null && state.run.gold >= cost
      row.card.disabled = !affordable
      row.card.classList.toggle('affordable', affordable)
    }
  }

  build()

  return {
    update,
    setMode(next) {
      if (next === mode) return
      mode = next
      root.classList.toggle('wide', mode === 'full')
      build()
    },
  }
}

/** Sektionsbalken und Kachelraster einer Kategorie. */
function section(
  group: Category,
  state: GameState,
  rows: Row[],
  onChange: () => void,
): HTMLElement {
  const wrapper = document.createElement('div')
  wrapper.className = 'cat-section'
  wrapper.style.setProperty('--accent', group.accent)

  const bar = document.createElement('div')
  bar.className = 'section-bar'
  bar.textContent = t('upgrades.section', { name: group.name })
  wrapper.appendChild(bar)

  const grid = document.createElement('div')
  grid.className = 'upgrade-grid'

  for (const def of group.paths) {
    const card = document.createElement('button')
    card.type = 'button'
    card.className = 'upgrade-card'

    const label = document.createElement('span')
    label.className = 'label'
    label.textContent = def.label

    const box = document.createElement('span')
    box.className = 'value-box'
    const value = document.createElement('span')
    value.className = 'value'
    const cost = document.createElement('span')
    cost.className = 'cost'
    box.append(value, cost)

    card.append(label, box)
    card.addEventListener('click', () => {
      if (buyUpgrade(state, def.id)) onChange()
    })

    grid.appendChild(card)
    rows.push({ def, value, cost, card })
  }

  wrapper.appendChild(grid)
  return wrapper
}

/**
 * Alle laufenden Zahlen der Oberflaeche (GDD 13 Abschnitt 4).
 *
 * Verteilt auf vier Stellen, aber bewusst in **einer** Datei: Sie alle lesen denselben
 * Zustand und muessen im selben Bild dasselbe zeigen.
 *
 *   Ressourcenleiste  oben links ueber dem Feld - Gold und liegendes Gold
 *   Boss-Leiste       oben mittig, nur solange ein Boss lebt (GDD 07 Abschnitt 7)
 *   Tempo             unten rechts im Feld
 *   Statuskarten      untere Leiste - Kampfwerte links, Welle rechts
 *   Wellenkarte       in der Basis oben rechts, wo kein Kampf zu sehen ist
 *
 * **Eine** Lebensleiste fuer die gesamte Station, keine HP je Modul (GDD 03 Abschnitt 5).
 * Das ist keine Vereinfachung der Anzeige, sondern die Spielregel: Module koennen nicht
 * zerstoert werden, und der Schaden geht immer auf dieselbe Leiste.
 *
 * Geschrieben wird nur, wenn sich etwas geaendert hat - die Signatur unten vergleicht alles
 * Sichtbare auf einmal. Ohne sie schriebe jedes Bild dieselben Zeichenketten neu.
 */

import { formatNumber } from '../core/format.ts'
import type { SpeedFactor } from '../core/loop.ts'
import { SPEED_FACTORS } from '../data/balance.ts'
import { t } from '../data/strings.ts'
import { goToNextWave, goToPreviousWave, toggleAutoWaves } from '../app/actions.ts'
import type { GameState } from '../app/state.ts'
import { activeBoss } from '../sim/enemies.ts'
import { goldOnField } from '../sim/economy.ts'
import { CORE_UID } from '../sim/station.ts'
import { effectiveTowerStats, globalMultiplier } from '../sim/stats.ts'
import { canSkipTo } from '../sim/waves.ts'
import { icon } from './icons.ts'
import type { SettingsControls } from './settings.ts'

export type HudTargets = {
  /** Schwebende Anzeigen ueber dem Spielfeld. */
  overlay: HTMLElement
  /** Zeile fuer die Statuskarten in der unteren Leiste. */
  statusRow: HTMLElement
}

export type Hud = {
  /** Pro Bild aufrufen - schreibt nur, wenn sich etwas geaendert hat. */
  update(): void
  detach(): void
}

export function mountHud(state: GameState, targets: HudTargets, controls: SettingsControls): Hud {
  const { overlay, statusRow } = targets

  // --- Ressourcen, oben links ---
  const resources = div('resource-bar')
  const gold = figure('gold', 'res')
  const onField = figure('coin', 'res dim')
  resources.append(gold.node, onField.node)

  // --- Boss, oben mittig ---
  const bossBar = div('boss-bar')
  bossBar.hidden = true
  const bossName = document.createElement('span')
  const bossOuter = div('boss-hp')
  const bossFill = document.createElement('i')
  const bossText = document.createElement('span')
  bossOuter.append(bossFill, bossText)
  bossBar.append(bossName, bossOuter)

  // --- Tempo, unten rechts im Feld ---
  const speedBar = div('speed-control')
  const slower = stepButton('-', t('settings.speed'), () => stepSpeed(-1))
  const speedValue = document.createElement('span')
  speedValue.className = 'speed-value'
  const faster = stepButton('+', t('settings.speed'), () => stepSpeed(1))
  speedBar.append(slower, speedValue, faster)

  // --- Wellenkarte der Basis, oben rechts ---
  const metaCard = div('card meta-card')
  const metaWave = metaRow(metaCard, t('hud.waveShort'))
  const metaGold = metaRow(metaCard, t('hud.gold'))

  overlay.append(resources, bossBar, speedBar, metaCard)

  // --- Statuskarte links: Kampfwerte und Stations-HP ---
  const statCard = div('card stat-card')
  const figures = div('figures')
  const damage = figure('damage', 'fig')
  const goldFactor = figure('coin', 'fig')
  figures.append(damage.node, goldFactor.node)
  const hp = bar('hp')
  statCard.append(figures, hp.node)

  // --- Statuskarte rechts: Welle, Wellensteuerung, Fortschritt ---
  const waveCard = div('card wave-card')
  const head = div('head')
  const waveLabel = document.createElement('span')
  waveLabel.className = 'wave-label'
  const scales = div('scales')
  const waveDamage = figure('damage', 'fig')
  const waveHp = figure('hp', 'fig')
  waveDamage.node.title = t('status.waveDamage')
  waveHp.node.title = t('status.waveHp')
  scales.append(waveDamage.node, waveHp.node)
  head.append(waveLabel, scales)

  const waveControls = div('wave-controls')
  const previous = stepButton('(<)', t('hud.prevWave'), () => goToPreviousWave(state))
  const auto = stepButton('(+)', t('hud.autoOn'), () => toggleAutoWaves(state))
  const next = stepButton('(>)', t('hud.nextWave'), () => goToNextWave(state))
  waveControls.append(previous, auto, next)

  const progress = bar('progress')
  waveCard.append(head, waveControls, progress.node)

  statusRow.append(statCard, waveCard)

  function stepSpeed(direction: number): void {
    const index = SPEED_FACTORS.indexOf(controls.speed())
    const target = SPEED_FACTORS[Math.min(SPEED_FACTORS.length - 1, Math.max(0, index + direction))]
    if (target !== undefined) controls.setSpeed(target as SpeedFactor)
  }

  let last = ''

  return {
    update() {
      const combat = state.runtime.combat
      const boss = activeBoss(state)
      const field = goldOnField(state)
      const plan = combat.plan
      const total = plan ? plan.spawns.length : 0

      const signature = [
        state.run.wave,
        Math.round(combat.stationHp),
        Math.round(state.run.gold),
        Math.round(field),
        combat.phase,
        combat.killsThisWave,
        state.run.autoWaves,
        state.run.waveRecord,
        JSON.stringify(state.run.upgrades),
        controls.speed(),
        boss ? Math.round(boss.hp) : 'none',
      ].join('|')
      if (signature === last) return
      last = signature

      gold.value.textContent = formatNumber(Math.floor(state.run.gold))
      onField.value.textContent = formatNumber(Math.floor(field))
      metaWave.textContent = formatNumber(state.run.wave)
      metaGold.textContent = formatNumber(Math.floor(state.run.gold))

      speedValue.textContent = t('hud.speedShort', { factor: controls.speed() })
      slower.disabled = controls.speed() === SPEED_FACTORS[0]
      faster.disabled = controls.speed() === SPEED_FACTORS[SPEED_FACTORS.length - 1]

      // Kampfwerte: der Schaden des Hauptturms und der Goldfaktor - dieselben zwei Zahlen,
      // an denen der Spieler ablesen soll, ob sich ein Upgrade gelohnt hat.
      const core = effectiveTowerStats(state, CORE_UID)
      damage.value.textContent = core ? formatNumber(Math.round(core.damage)) : formatNumber(0)
      damage.node.title = t('status.damage')
      goldFactor.value.textContent = t('hud.factor', {
        value: globalMultiplier(state.run.upgrades, 'goldBonus').toFixed(2),
      })
      goldFactor.node.title = t('status.goldFactor')

      const hpFraction = combat.maxStationHp > 0 ? combat.stationHp / combat.maxStationHp : 0
      hp.set(hpFraction, `${formatNumber(Math.ceil(combat.stationHp))} / ${formatNumber(combat.maxStationHp)}`)
      hp.fill.classList.toggle('low', hpFraction <= 0.3)
      hp.node.title = t('status.stationHp')

      waveLabel.textContent =
        combat.phase === 'pause'
          ? t('hud.wavePause', { wave: state.run.wave + 1 })
          : t('hud.wave', { wave: state.run.wave })
      waveDamage.value.textContent = plan ? plan.damageScale.toFixed(2) : formatNumber(1)
      waveHp.value.textContent = plan ? plan.hpScale.toFixed(2) : formatNumber(1)

      const done = Math.min(combat.killsThisWave, total)
      progress.set(total > 0 ? done / total : 0, t('status.progress', { done, total }))

      previous.disabled = !canSkipTo(state, state.run.wave - 1)
      next.disabled = state.run.wave + 1 > state.run.waveRecord + 1
      auto.classList.toggle('active', state.run.autoWaves)
      auto.title = state.run.autoWaves ? t('hud.autoOn') : t('hud.autoOff')

      bossBar.hidden = boss === null
      if (boss) {
        const fraction = boss.maxHp > 0 ? boss.hp / boss.maxHp : 0
        bossName.textContent = t('hud.boss')
        bossFill.style.width = `${clamp(fraction) * 100}%`
        bossText.textContent = `${formatNumber(Math.ceil(boss.hp))} / ${formatNumber(Math.ceil(boss.maxHp))}`
      }
    },
    detach() {
      for (const node of [resources, bossBar, speedBar, metaCard, statCard, waveCard]) node.remove()
    },
