/**
 * Hover-Informationen statt Dauertext (GDD 13 Abschnitt 9).
 *
 * Ein einziges Element, das umgehaengt wird - kein Element je Ziel.
 */

let element: HTMLDivElement | null = null

function ensure(): HTMLDivElement {
  if (element) return element
  element = document.createElement('div')
  element.className = 'tooltip'
  element.hidden = true
  document.body.appendChild(element)
  return element
}

export type TooltipAnchor = { x: number; y: number }

export function showTooltip(anchor: TooltipAnchor, content: string): void {
  const node = ensure()
  node.innerHTML = content
  node.hidden = false

  // Am Rand kippt der Hinweis auf die andere Seite, statt aus dem Bild zu laufen.
  const box = node.getBoundingClientRect()
  const left = Math.min(anchor.x + 14, window.innerWidth - box.width - 8)
  const top = Math.min(anchor.y + 16, window.innerHeight - box.height - 8)
  node.style.left = `${Math.max(8, left)}px`
  node.style.top = `${Math.max(8, top)}px`

