    `<span class="tile" style="--frame:url('/frames/${frame}.png')">${icon(name, 16)}</span>`
  )
}

input.content:
/*
 * Gestalt der Oberflaeche (GDD 13).
 *
 * Aufbau in zwei Zonen, wie in den Entwurfsbildern:
 *
 *   #field   Spielfeld. Das Canvas fuellt es ganz, Panels schweben darueber.
 *   #dock    Untere Leiste. Statuskarten, Navileiste, Upgrade-Kacheln.
 *
 * Was sichtbar ist, entscheidet **allein** `#app[data-view]`. Kein Skript blendet Panels
 * ein oder aus - es setzt nur den Bereich, der Rest steht hier. Damit gibt es genau eine
 * Stelle, an der man nachliest, was ein Bereich zeigt.
 */

:root {
  /*
   * Palette aus dem Referenzbild - dieselben Werte stehen als PALETTE in
   * src/render/theme.ts. Canvas und DOM liegen uebereinander; wer hier etwas aendert,
   * aendert es dort mit, sonst laufen Spielfeld und Oberflaeche farblich auseinander.
   */
  --ink: #0a0d1a;
  --ink-deep: #06080f;
  --panel: #122354;
  --panel-deep: #0f1b40;
  --edge: #7fd8ff;
  --cyan: #46c8ff;
  --teal: #2ee0c0;
  --lime: #7fe83f;
  --magenta: #ff2d78;
  --gold: #ffcc33;
  --violet: #b45cff;
  --section: #29a3f5;

  /* Rollen. Im Spiel wird auf diese Namen verwiesen, nicht auf die Farben darueber. */
  --bg: var(--ink);
  --bg-panel: var(--panel);
  --line: rgba(127, 216, 255, 0.5);
  --line-soft: rgba(127, 216, 255, 0.24);
  --text: #ffffff;
  --text-dim: #8fa8d4;
  --accent: var(--cyan);
  --ok: var(--teal);
  --fail: var(--magenta);
  --warn: var(--gold);
  --glow: 0 0 14px rgba(70, 200, 255, 0.14);
  --font: 'Segoe UI', system-ui, sans-serif;
  --mono: ui-monospace, 'Cascadia Mono', 'Consolas', monospace;
  /* Zahlenschrift aus dem Anlagensatz. Nur ab 14 px verwenden - darunter zerfaellt sie. */
  --font-pixel: 'monogram', var(--mono);
}

@font-face {
  font-family: 'monogram';
  src: url('/fonts/monogram.ttf') format('truetype');
  font-display: swap;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
}

button {
  font-family: inherit;
}

/* --- Zonen --------------------------------------------------------------- */

#app {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
}

#field {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
}

#stage {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

#overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

#overlay > * {
  pointer-events: auto;
}

#dock {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px 12px 12px;
  /* Die helle Kante trennt Feld und Bedienung - sie steht so in beiden Entwuerfen. */
  border-top: 2px solid var(--cyan);
  background: linear-gradient(180deg, rgba(18, 35, 84, 0.35), var(--ink));
}

/* --- Sichtbarkeit je Bereich --------------------------------------------- */

.resource-bar,
.speed-control,
.status-row,
.upgrade-panel,
.meta-card,
.inventory-panel,
.rail,
.settings-panel,
.view-title {
  display: none;
}

#app[data-view='combat'] .resource-bar,
#app[data-view='upgrades'] .resource-bar,
#app[data-view='combat'] .speed-control,
#app[data-view='upgrades'] .speed-control {
  display: flex;
}

#app[data-view='combat'] .status-row,
#app[data-view='upgrades'] .status-row {
  display: grid;
}

#app[data-view='combat'] .upgrade-panel,
#app[data-view='upgrades'] .upgrade-panel {
  display: flex;
}

#app[data-view='base'] .meta-card,
#app[data-view='base'] .inventory-panel,
#app[data-view='base'] .rail {
  display: flex;
}

#app[data-view='settings'] .settings-panel {
  display: block;
}

#app[data-view='base'] .view-title,
#app[data-view='settings'] .view-title {
  display: block;
}

/* Die Boss-Leiste haengt an ihrem eigenen Schalter - sie gehoert nur in den Kampf. */
#app:not([data-view='combat']) .boss-bar {
  display: none;
}

/* --- Gemeinsame Bausteine ------------------------------------------------ */

.panel,
.card {
  border: 2px solid var(--line);
  border-radius: 12px;
  background: var(--bg-panel);
  box-shadow: var(--glow);
}

.panel {
  padding: 12px 14px;
  overflow-y: auto;
}

.panel header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}

.panel h2 {
  margin: 0;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text);
}

.panel h3 {
  margin: 12px 0 4px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.panel p {
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.5;
}

.panel .slots {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--text-dim);
}

.muted {
  color: var(--text-dim);
}

.warn {
  color: var(--warn);
}

/*
 * Symbol aus dem Anlagensatz. Die Datei liefert nur die Form - die Farbe kommt aus
 * `currentColor`, damit dasselbe Zeichen je nach Bedeutung anders leuchtet.
 */
.pix {
  display: inline-block;
  flex: none;
  width: var(--pix-size, 16px);
  height: var(--pix-size, 16px);
  background-color: currentColor;
  -webkit-mask: var(--icon) center / contain no-repeat;
  mask: var(--icon) center / contain no-repeat;
}

/* Raritaetsrahmen mit Symbol darin. Pixelgenau skaliert, sonst franst der Rahmen aus. */
.tile {
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 32px;
  height: 32px;
  background: var(--frame) center / contain no-repeat;
  image-rendering: pixelated;
}

/* Schaltflaeche, die vollstaendig aus einer Bilddatei besteht. */
.art-button {
  width: 34px;
  height: 34px;
  padding: 0;
  border: 0;
  background: var(--art) center / contain no-repeat;
  image-rendering: pixelated;
  cursor: pointer;
}

.art-button:disabled {
  opacity: 0.3;
  cursor: default;
}

.art-button:hover:not(:disabled) {
  filter: brightness(1.25);
}

/* Kleine Schaltflaeche mit Text - Tempo, Auto-Modus, Einstellungen. */
.chip,
.wave-controls button:not(.art-button),
.speed-control button {
  padding: 4px 10px;
  border: 2px solid var(--line-soft);
  border-radius: 8px;
  background: transparent;
  color: var(--text-dim);
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  cursor: pointer;
}

.chip:hover:not(:disabled),
.wave-controls button:not(.art-button):hover:not(:disabled),
.speed-control button:hover:not(:disabled) {
  color: var(--text);
  border-color: var(--line);
}

.chip.active,
.wave-controls button.active {
  border-color: var(--lime);
  color: var(--lime);
  text-shadow: 0 0 8px rgba(127, 232, 63, 0.5);
}

.chip:disabled,
.speed-control button:disabled {
  opacity: 0.3;
  cursor: default;
}

/* Leiste mit Fuellung und mittiger Beschriftung. */
.bar {
  position: relative;
  height: 20px;
  border: 2px solid var(--line-soft);
  border-radius: 7px;
  background: var(--ink-deep);
  overflow: hidden;
}

.bar i {
  position: absolute;
  inset: 0 auto 0 0;
  display: block;
  background: var(--ok);
  transition: width 120ms linear;
}

.bar i.low {
  background: var(--fail);
}

.bar span {
  position: relative;
  display: block;
  width: 100%;
  font-family: var(--font-pixel);
  font-size: 16px;
  line-height: 16px;
  text-align: center;
  color: var(--text);
  text-shadow: 0 0 4px rgba(0, 0, 0, 0.9);
}

.bar.progress i {
  background: var(--cyan);
}

/* Sektionsbalken ueber einer Liste - der breite blaue Streifen aus der Vorlage. */
.section-bar {
  padding: 6px 12px;
  background: var(--section);
  color: #ffffff;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

/* --- Ueber dem Spielfeld ------------------------------------------------- */

.view-title {
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--edge);
  text-shadow: 0 0 18px rgba(127, 216, 255, 0.35);
}

.resource-bar {
  position: absolute;
  top: 12px;
  left: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.resource-bar .res {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--gold);
  font-family: var(--font-pixel);
  font-size: 28px;
  line-height: 1;
  text-shadow: 0 0 12px rgba(255, 204, 51, 0.35);
}

.resource-bar .res.dim {
  font-size: 20px;
  opacity: 0.7;
}

.speed-control {
  position: absolute;
  right: 12px;
  bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.speed-control button {
  min-width: 34px;
  border-color: var(--lime);
  color: var(--lime);
  font-size: 15px;
}

.speed-control .speed-value {
  min-width: 46px;
  font-family: var(--font-pixel);
  font-size: 20px;
  text-align: center;
  color: var(--text);
}

.boss-bar {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 14px;
  border: 2px solid var(--magenta);
  border-radius: 10px;
  background: var(--bg-panel);
  box-shadow: 0 0 16px rgba(255, 45, 120, 0.25);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--magenta);
}

.boss-bar[hidden] {
  display: none;
}

.boss-hp {
  position: relative;
  width: 260px;
  height: 14px;
  border: 1px solid var(--magenta);
  border-radius: 4px;
  overflow: hidden;
}

.boss-hp i {
  position: absolute;
  inset: 0 auto 0 0;
  display: block;
  background: var(--magenta);
  transition: width 120ms linear;
}

.boss-hp span {
  position: relative;
  display: block;
  font-family: var(--font-pixel);
  font-size: 14px;
  line-height: 14px;
  text-align: center;
  color: var(--text);
}

/* --- Untere Leiste: Statuskarten ---------------------------------------- */

.status-row {
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.status-row .card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
}

.stat-card .figures {
  display: flex;
  align-items: center;
  gap: 18px;
}

.fig,
.res {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.fig {
  color: var(--cyan);
}

.fig b {
  font-family: var(--font-pixel);
  font-size: 20px;
  font-weight: 400;
  color: var(--text);
}

.res b {
  font-weight: 400;
}

.wave-card .head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.wave-label {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: var(--text);
}

.scales {
  display: flex;
  gap: 12px;
}

/* Werte des Gegners - in der Gegnerfarbe, damit sie nicht wie eigene Werte wirken. */
.scales.enemy .fig {
  color: var(--magenta);
}

.scales .fig b {
  font-size: 16px;
}

.wave-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* --- Untere Leiste: Navigation und Upgrades ------------------------------ */

.dock-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: end;
}

.nav {
  display: flex;
  gap: 8px;
  padding: 8px;
  border: 2px solid var(--line);
  border-radius: 12px;
  background: var(--bg-panel);
  box-shadow: var(--glow);
}

.nav-button {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  padding: 0;
  border: 2px solid var(--line-soft);
  border-radius: 10px;
  background: var(--panel-deep);
  color: var(--text-dim);
  cursor: pointer;
}

.nav-button:hover {
  color: var(--text);
  border-color: var(--line);
}

.nav-button.active {
  border-color: var(--cyan);
  color: var(--cyan);
  background: rgba(70, 200, 255, 0.14);
  box-shadow: 0 0 14px rgba(70, 200, 255, 0.3);
}

.upgrade-panel {
  flex-direction: column;
  gap: 0;
  max-height: 32vh;
  padding: 0;
  overflow: hidden;
}

.cat-tabs {
  display: flex;
  gap: 6px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--line-soft);
}

.cat-tab {
  padding: 4px 12px;
  border: 2px solid var(--line-soft);
  border-radius: 8px;
  background: transparent;
  color: var(--text-dim);
  font: inherit;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
}

.cat-tab:hover {
  color: var(--text);
}

.cat-tab.active {
  border-color: var(--accent);
  color: var(--accent);
  box-shadow: 0 0 12px rgba(70, 200, 255, 0.22);
}

/* In der vollen Ansicht steht jede Kategorie untereinander - die Reiter entfallen. */
.upgrade-panel.wide {
  max-height: 46vh;
}

.upgrade-panel.wide .cat-tabs {
  display: none;
}

.cat-body {
  overflow-y: auto;
}

.upgrade-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 10px;
}

.upgrade-card {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 2px solid var(--line-soft);
  border-radius: 10px;
  background: var(--panel-deep);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.upgrade-card.affordable {
  border-color: var(--line);
}

.upgrade-card:hover.affordable {
  border-color: var(--accent);
  box-shadow: 0 0 14px rgba(70, 200, 255, 0.22);
}

.upgrade-card:disabled {
  opacity: 0.45;
  cursor: default;
}

.upgrade-card .label {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--accent);
}

.upgrade-card .label span {
  color: var(--text);
}

.upgrade-card .value-box {
  display: grid;
  min-width: 78px;
  border: 2px solid var(--line-soft);
  border-radius: 7px;
  overflow: hidden;
  text-align: center;
}

.upgrade-card .value {
  padding: 1px 6px;
  font-family: var(--font-pixel);
  font-size: 17px;
  color: var(--text);
}

.upgrade-card .cost {
  padding: 1px 6px;
  border-top: 2px solid var(--line-soft);
  font-family: var(--font-pixel);
  font-size: 15px;
  color: var(--cyan);
}

/* Jede Kategorie faerbt ihre Kacheln in der Farbe, in der ihr Turm auf dem Feld leuchtet. */
.cat-section .upgrade-card .label {
  color: var(--accent);
}

.cat-tab {
  --accent: var(--cyan);
}

.cat-section {
  --accent: var(--cyan);
}

/* --- Basis --------------------------------------------------------------- */

.inventory-panel {
  position: absolute;
  top: 56px;
  left: 12px;
  bottom: 12px;
  width: 232px;
  flex-direction: column;
}

.rail {
  position: absolute;
  top: 132px;
  right: 12px;
  bottom: 12px;
  width: 260px;
  flex-direction: column;
  gap: 10px;
}

.rail .detail-panel {
  flex: 1 1 auto;
  min-height: 0;
}

.rail .shop-panel {
  flex: 0 0 auto;
}

.meta-card {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 260px;
  flex-direction: column;
  gap: 6px;
  padding: 12px 14px;
}

.meta-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.meta-row span {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.meta-row b {
  font-family: var(--font-pixel);
  font-size: 24px;
  font-weight: 400;
  color: var(--text);
}

.wide-button {
  width: 100%;
  padding: 10px;
  border: 2px solid var(--line);
  border-radius: 10px;
  background: var(--panel-deep);
  color: var(--text);
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
}

.wide-button:disabled {
  opacity: 0.4;
  cursor: default;
}

ul.inventory {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

ul.inventory .card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 2px 10px;
  padding: 7px 9px;
  border: 2px solid var(--line-soft);
  border-radius: 10px;
  background: var(--panel-deep);
  box-shadow: none;
  cursor: pointer;
}

ul.inventory .card:hover {
  border-color: var(--line);
}

ul.inventory .card.active {
  border-color: var(--accent);
  background: rgba(70, 200, 255, 0.14);
}

ul.inventory .tile {
  grid-row: 1 / 3;
}

ul.inventory .name {
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
}

ul.inventory .rarity {
  font-size: 11px;
  font-weight: 700;
  color: var(--rarity, var(--text-dim));
}

ul.inventory .shape {
  grid-column: 2 / -1;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
}

.detail-panel header {
  align-items: center;
  gap: 10px;
}

.detail-panel h2 {
  flex: 1 1 auto;
}

.detail-panel .rarity {
  font-size: 11px;
  font-weight: 700;
  color: var(--rarity, var(--text-dim));
}

table.stats {
  width: 100%;
  margin-top: 10px;
  border-collapse: collapse;
  font-size: 12px;
}

table.stats th {
  padding: 2px 0;
  font-weight: 400;
  text-align: left;
  color: var(--text-dim);
}

table.stats td {
  padding: 2px 0 2px 6px;
  font-family: var(--mono);
  text-align: right;
  white-space: nowrap;
}

table.stats .arrow {
  padding: 0 4px;
  color: var(--text-dim);
}

table.stats .final {
  color: var(--ok);
}

table.stats em {
  font-size: 10px;
  font-style: normal;
  color: var(--warn);
}

ul.sources {
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
  color: var(--text-dim);
}

ul.sources li {
  padding: 1px 0;
}

/* --- Einstellungen ------------------------------------------------------- */

.settings-panel {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(420px, calc(100% - 24px));
}

.setting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 8px 0;
  border-bottom: 1px solid var(--line-soft);
}

.setting .label {
  font-size: 13px;
  color: var(--text);
}

.setting .chips {
  display: flex;
  gap: 6px;
}

/* --- Hinweise, Entwickleranzeige, Selbsttest ----------------------------- */

.tooltip {
  position: fixed;
  z-index: 20;
  max-width: 260px;
  padding: 6px 9px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel-deep);
  box-shadow: var(--glow);
  color: var(--text);
  font-size: 12px;
  line-height: 1.45;
  pointer-events: none;
}

.tooltip[hidden] {
  display: none;
}

/* Nur mit ?debug sichtbar - im normalen Bild hat sie nichts verloren. */
.devbar {
  position: absolute;
  bottom: 12px;
  left: 12px;
  padding: 8px 12px;
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  background: var(--bg-panel);
  color: var(--text-dim);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.7;
  letter-spacing: 0.02em;
}

.devbar b {
  color: var(--accent);
  font-weight: 600;
}

.devbar .hint {
  color: rgba(143, 168, 212, 0.6);
}

.report {
  position: fixed;
  inset: 0;
  z-index: 40;
  overflow: auto;
  padding: 32px clamp(16px, 5vw, 64px) 64px;
