}

import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { defineConfig } from 'vite'

const root = dirname(fileURLToPath(import.meta.url))

export default defineConfig({
  root,
  server: { port: 5173, open: false },
  build: {
    outDir: resolve(root, 'dist'),
    emptyOutDir: true,
  },
  // Der Ordner "prototypes" ist ein eigenes, abgeschlossenes Projekt und gehoert
  // nicht zum Spiel. Ohne diese Einschraenkung durchsucht Vite ihn beim Start mit.
  optimizeDeps: { entries: ['index.html'] },
})

/**
 * Die Zeitquelle des Spiels.
 *
 * Regel aus dem Implementierungsplan (Abschnitt 3): Niemand ausserhalb dieser Datei
 * ruft `Date.now()` oder `performance.now()` auf. Alles, was Zeit braucht, bekommt sie
 * als `dt` in den Tick gereicht oder fragt `Loop.now()`.
 *
 * Die Simulation laeuft mit festen Schritten (Standard 60/s), entkoppelt vom Zeichnen.
 * Geschwindigkeit x2/x4 bedeutet **mehr Ticks pro Bild**, niemals groessere Schritte
 * (GDD 16 Abschnitt 12).
 */

export type SpeedFactor = 1 | 2 | 4

export type TickFn = (dt: number) => void
/** `alpha` ist der Rest im Akkumulator, 0..1 - fuer weiche Zwischenbilder. */
export type RenderFn = (alpha: number) => void

/**
 * Quelle fuer Einzelbilder. Im Browser `requestAnimationFrame`, im Test ein
 * handgesteuerter Ersatz. Der Zeitstempel kommt aus dem Aufruf, damit die Schleife
 * selbst keine Uhr befragen muss.
 */
export type FrameScheduler = {
  request(callback: (timestampMs: number) => void): number
  cancel(handle: number): void
}

export type LoopOptions = {
  /** Simulationsschritte pro Sekunde. Standard 60. */
  tickRate?: number
  /**
   * Groesste Zeitspanne, die ein einzelnes Bild nachholen darf. Schuetzt davor, dass
   * ein weggeschalteter Tab beim Zurueckkommen tausende Ticks am Stueck ausloest.
   */
  maxFrameSeconds?: number
  /** Harte Obergrenze an Ticks je Bild. Verhindert die Todesspirale bei Ueberlast. */
  maxTicksPerFrame?: number
  scheduleFrame?: FrameScheduler
  /** Echte Uhrzeit in Millisekunden. Nur fuer die Offline-Berechnung. */
  wallClock?: () => number
}

export type Loop = {
  start(tick: TickFn, render: RenderFn): void
  stop(): void
  isRunning(): boolean
  setSpeed(factor: SpeedFactor): void
  getSpeed(): SpeedFactor
  /** Die Spielzeit in Sekunden seit Start der Schleife. Steigt mit der Geschwindigkeit. */
  now(): number
  /** Echte Uhrzeit in Millisekunden. Ausschliesslich fuer Abwesenheitsberechnung. */
  wallClock(): number
  /** Anzahl ausgefuehrter Simulationsschritte seit Start. */
  tickCount(): number
  /** Gemessene Bilder pro Sekunde, gleitend. */
  fps(): number
  /** Laenge eines Simulationsschritts in Sekunden. */
  readonly stepSeconds: number
  readonly tickRate: number
}

const DEFAULT_TICK_RATE = 60
const DEFAULT_MAX_FRAME_SECONDS = 0.25
const DEFAULT_MAX_TICKS_PER_FRAME = 300

function browserScheduler(): FrameScheduler {
  return {
    request: (cb) => requestAnimationFrame(cb),
    cancel: (handle) => cancelAnimationFrame(handle),
  }
}

export function createLoop(options: LoopOptions = {}): Loop {
  const tickRate = options.tickRate ?? DEFAULT_TICK_RATE
  const stepSeconds = 1 / tickRate
  const maxFrameSeconds = options.maxFrameSeconds ?? DEFAULT_MAX_FRAME_SECONDS
  const maxTicksPerFrame = options.maxTicksPerFrame ?? DEFAULT_MAX_TICKS_PER_FRAME
  const scheduler = options.scheduleFrame ?? browserScheduler()
  const clock = options.wallClock ?? (() => Date.now())

  let speed: SpeedFactor = 1
  let simTime = 0
  let ticks = 0
  let accumulator = 0
  let running = false
  let handle = 0
  let lastTimestamp: number | null = null
  let smoothedFps = 0

  let onTick: TickFn = () => {}
  let onRender: RenderFn = () => {}

  function frame(timestampMs: number): void {
    if (!running) return

    // Das erste Bild setzt nur den Nullpunkt - es darf keinen Sprung erzeugen.
    if (lastTimestamp === null) {
      lastTimestamp = timestampMs
      handle = scheduler.request(frame)
      return
    }

    const rawSeconds = (timestampMs - lastTimestamp) / 1000
    lastTimestamp = timestampMs

    if (rawSeconds > 0) {
      const instantFps = 1 / rawSeconds
      smoothedFps = smoothedFps === 0 ? instantFps : smoothedFps * 0.9 + instantFps * 0.1
    }

    const frameSeconds = Math.min(Math.max(rawSeconds, 0), maxFrameSeconds)
    accumulator += frameSeconds * speed

    let ticksThisFrame = 0
    while (accumulator >= stepSeconds) {
      if (ticksThisFrame >= maxTicksPerFrame) {
        // Ueberlast: den Rest verwerfen statt ihn vor sich herzuschieben.
        accumulator = 0
        break
      }
      accumulator -= stepSeconds
      simTime += stepSeconds
      ticks += 1
      ticksThisFrame += 1
      onTick(stepSeconds)
    }

    onRender(accumulator / stepSeconds)
    handle = scheduler.request(frame)
  }

  return {
    start(tick, render) {
      if (running) return
      onTick = tick
      onRender = render
      running = true
      lastTimestamp = null
      handle = scheduler.request(frame)
    },
    stop() {
      if (!running) return
      running = false
      scheduler.cancel(handle)
      lastTimestamp = null
    },
    isRunning: () => running,
    setSpeed(factor) {
      speed = factor
    },
    getSpeed: () => speed,
    now: () => simTime,
    wallClock: () => clock(),
    tickCount: () => ticks,
    fps: () => smoothedFps,
    stepSeconds,
    tickRate,
  }
}

/**
 * Bildquelle fuer Tests: Bilder werden von Hand ausgeloest, die Zeit springt genau so
 * weit, wie der Test es vorgibt. Damit ist "60 Ticks pro Sekunde" pruefbar statt
 * geschaetzt.
 */
export type ManualScheduler = FrameScheduler & {
  /** Ein einzelnes Bild, `deltaMs` nach dem vorherigen. */
  advance(deltaMs: number): void
  /** Mehrere gleich lange Bilder hintereinander. */
  advanceBy(totalMs: number, frameMs: number): void
  timestamp(): number
}

export function createManualScheduler(startMs = 0): ManualScheduler {
  let time = startMs
  let pending: ((timestampMs: number) => void) | null = null
  let nextHandle = 1

  return {
    request(callback) {
      pending = callback
      return nextHandle++
    },
    cancel() {
      pending = null
    },
    advance(deltaMs) {
      time += deltaMs
      const callback = pending
      pending = null
      callback?.(time)
    },
    advanceBy(totalMs, frameMs) {
      const frames = Math.round(totalMs / frameMs)
      for (let i = 0; i < frames; i++) this.advance(frameMs)
    },
    timestamp: () => time,
  }
}

/**
 * Ereignisbus.
 *
 * Jedes bedeutsame Spielereignis wird gemeldet, auch wenn zunaechst niemand zuhoert
 * (Implementierungsplan Abschnitt 3). In E18 haengt sich der Klang daran - das ist dann
 * ein Anschluss, kein Umbau (GDD 13 Abschnitt 11).
 *
 * `EventMap` ist bewusst die einzige Stelle, an der die Ereignisnamen samt Nutzlast
 * stehen. Wer ein Ereignis meldet, das hier fehlt, bekommt einen Typfehler.
 */

/** Nutzlast einer Belohnung. `app/rewards.ts` leitet seinen `Reward`-Typ hiervon ab. */
export type RewardPayload = {
  gold?: number
  xp?: number
  prestigePoints?: number
}

export type EventMap = {
  'loop.speedChanged': { factor: 1 | 2 | 4 }
  'reward.granted': { reward: RewardPayload; source: string }
  'save.written': { bytes: number }
  'save.loaded': { fresh: boolean; version: number }
  'save.cleared': Record<string, never>
  'save.corrupt': { reason: string }
}

export type EventName = keyof EventMap
export type EventHandler<K extends EventName> = (payload: EventMap[K]) => void
export type Unsubscribe = () => void

type HandlerSet = Set<(payload: unknown) => void>

const handlers = new Map<EventName, HandlerSet>()

/**
 * Ein Fehler in einem Zuhoerer darf niemals das Bild anhalten. Er wird gemeldet und
 * der naechste Zuhoerer laeuft weiter. Tests koennen die Meldung umlenken.
 */
let reportError: (name: EventName, error: unknown) => void = (name, error) => {
  console.error(`[events] Zuhoerer fuer "${name}" ist gescheitert:`, error)
}

export function on<K extends EventName>(name: K, handler: EventHandler<K>): Unsubscribe {
  let set = handlers.get(name)
  if (!set) {
    set = new Set()
    handlers.set(name, set)
  }
  const erased = handler as (payload: unknown) => void
  set.add(erased)
  return () => {
    set.delete(erased)
  }
}

export function emit<K extends EventName>(name: K, payload: EventMap[K]): void {
  const set = handlers.get(name)
  if (!set || set.size === 0) return
  // Kopie: ein Zuhoerer darf sich waehrend der Zustellung abmelden.
  for (const handler of [...set]) {
    try {
      handler(payload)
    } catch (error) {
      reportError(name, error)
    }
  }
}

export function listenerCount(name: EventName): number {
  return handlers.get(name)?.size ?? 0
}

/** Alle Zuhoerer entfernen. Wird zwischen Selbsttests gebraucht. */
export function resetEvents(): void {
  handlers.clear()
}

/** Fehlerbehandlung umlenken - im Selbsttest, damit erwartete Fehler nicht die Konsole fluten. */
export function setEventErrorReporter(reporter: (name: EventName, error: unknown) => void): void {
  reportError = reporter
}

/**
 * Deterministischer Zufall.
 *
 * Regel aus dem Implementierungsplan (Abschnitt 3 und 9): `Math.random()` kommt im
 * ganzen Spiel nur in dieser Datei vor, und zwar ausschliesslich zum Ziehen eines
 * Startwerts fuer einen neuen Run. Alles andere laeuft ueber einen Generator mit Seed,
 * dessen Zustand im Spielstand liegt - sonst ist ein Balancing-Fehler nicht nachstellbar.
 *
 * Verfahren: mulberry32. Ein einziger 32-Bit-Zustand, damit der Spielstand ihn als
 * eine Zahl mitfuehren kann.
 */

export type Rng = {
  /** Gleichverteilt in [0, 1). */
  next(): number
  /** Ganze Zahl von `min` bis `max`, **beide Grenzen eingeschlossen**. */
  int(min: number, max: number): number
  /** Gleitkommazahl in [min, max). */
  range(min: number, max: number): number
  /** Ein Element der Liste. Wirft bei leerer Liste. */
  pick<T>(items: readonly T[]): T
  /** `true` mit Wahrscheinlichkeit `p` (0..1). */
  chance(p: number): boolean
  /** Liste an Ort und Stelle mischen (Fisher-Yates). Gibt dieselbe Liste zurueck. */
  shuffle<T>(items: T[]): T[]
  /** Aktueller Zustand - gehoert in den Spielstand. */
  state(): number
  /** Zustand setzen, z. B. beim Laden. */
  setState(state: number): void
  /**
   * Abgeleiteter Generator. Wichtig, damit unabhaengige Systeme (Wellenaufbau,
   * Raritaeten, Ereignisse) sich nicht gegenseitig die Zahlenfolge verschieben.
   */
  fork(salt: number): Rng
}

const UINT32 = 4294967296

export function createRng(seed: number): Rng {
  let state = seed >>> 0

  function next(): number {
    state = (state + 0x6d2b79f5) >>> 0
    let t = Math.imul(state ^ (state >>> 15), 1 | state)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / UINT32
  }

  const rng: Rng = {
    next,
    int(min, max) {
      if (max < min) [min, max] = [max, min]
      const lo = Math.ceil(min)
      const hi = Math.floor(max)
      if (hi < lo) return lo
      return lo + Math.floor(next() * (hi - lo + 1))
    },
    range(min, max) {
      return min + next() * (max - min)
    },
    pick(items) {
      if (items.length === 0) throw new Error('rng.pick: leere Liste')
      const item = items[Math.floor(next() * items.length)]
      // Der Index liegt immer im Bereich; die Pruefung beruhigt nur den Typpruefer.
      return item as (typeof items)[number]
    },
    chance(p) {
      if (p <= 0) return false
      if (p >= 1) return true
      return next() < p
    },
    shuffle(items) {
      for (let i = items.length - 1; i > 0; i--) {
        const j = Math.floor(next() * (i + 1))
        const a = items[i] as (typeof items)[number]
        const b = items[j] as (typeof items)[number]
        items[i] = b
        items[j] = a
      }
      return items
    },
    state: () => state,
    setState(value) {
      state = value >>> 0
    },
    fork(salt) {
      return createRng((state ^ Math.imul(salt + 1, 0x9e3779b9)) >>> 0)
    },
  }

  return rng
}

/**
 * Startwert fuer einen neuen Run. Die **einzige** erlaubte Verwendung von
 * `Math.random()` im Spiel.
 */
export function randomSeed(): number {
  return Math.floor(Math.random() * UINT32) >>> 0
}

/**
 * Zahlendarstellung (GDD 13 Abschnitt 8).
 *
 * Diese Datei ist die einzige Stelle, an der aus einer Zahl ein Text wird. Das ist die
 * Absicherung fuer die Entscheidung "normales `number`" aus Abschnitt 3 des
 * Implementierungsplans: Sollte spaeter doch ein eigener Zahlentyp noetig werden,
 * aendert sich nur diese Datei.
 *
 * Regeln:
 *   bis 9.999      vollstaendig, englische Tausendertrennung -> "4,250"
 *   ab 10.000      abgekuerzt mit einer Nachkommastelle      -> "12.5K", "3.8M"
 *   ab 1e15        wissenschaftliche Kurzform                -> "4.1e18"
 * Prozentwerte immer als Prozent, nie als Multiplikator.
 */

const SUFFIXES = ['', 'K', 'M', 'B', 'T'] as const
const ABBREVIATE_FROM = 10_000
/** Ab hier reichen die Suffixe nicht mehr: 1000 * 1e12. */
const SCIENTIFIC_FROM = 1e15

export function formatNumber(value: number): string {
  if (!Number.isFinite(value)) return '-'

  const sign = value < 0 ? '-' : ''
  const n = Math.abs(value)

  if (n < ABBREVIATE_FROM) {
    // Ganze Zahlen ohne Nachkommastelle, gebrochene mit einer.
    const rounded = Number.isInteger(n) ? n : Math.round(n * 10) / 10
    return sign + groupThousands(rounded)
  }

  if (n >= SCIENTIFIC_FROM) {
    return sign + toScientific(n)
  }

  const tier = Math.min(SUFFIXES.length - 1, Math.floor(Math.log10(n) / 3))
  const scaled = n / Math.pow(1000, tier)
  // 999.95K wuerde sonst als "1000.0K" erscheinen statt als "1.0M".
  const shown = Math.floor(scaled * 10) / 10
  return `${sign}${shown.toFixed(1)}${SUFFIXES[tier]}`
}

function groupThousands(value: number): string {
  const [whole = '0', fraction] = String(value).split('.')
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',')
  return fraction === undefined ? grouped : `${grouped}.${fraction}`
}

function toScientific(value: number): string {
  const exponent = Math.floor(Math.log10(value))
  const mantissa = value / Math.pow(10, exponent)
  return `${(Math.floor(mantissa * 10) / 10).toFixed(1)}e${exponent}`
}

export type PercentOptions = {
  /** Vorzeichen auch bei positiven Werten zeigen: "+15%". */
  sign?: boolean
  /** Nachkommastellen, Standard 0. */
  decimals?: number
}

/** `value` ist ein Anteil: 0.15 -> "15%". Niemals ein Multiplikator wie "x1.15". */
export function formatPercent(value: number, options: PercentOptions = {}): string {
  if (!Number.isFinite(value)) return '-'
  const decimals = options.decimals ?? 0
  const percent = value * 100
  const body = `${percent.toFixed(decimals)}%`
  if (options.sign && percent > 0) return `+${body}`
  return body
}

/** Sekunden als Spielzeit: "8s", "1:05", "2:14:03". */
export function formatDuration(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return '-'
  const total = Math.floor(seconds)
  const s = total % 60
  const m = Math.floor(total / 60) % 60
  const h = Math.floor(total / 3600)

  if (h > 0) return `${h}:${pad(m)}:${pad(s)}`
  if (m > 0) return `${m}:${pad(s)}`
  return `${s}s`
}

/** Grobe Angabe fuer die Rueckkehr-Zusammenfassung: "2h 14m", "45m", "30s". */
export function formatDurationCoarse(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return '-'
  const total = Math.floor(seconds)
  const h = Math.floor(total / 3600)
  const m = Math.floor(total / 60) % 60
  if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`
  if (m > 0) return `${m}m`
  return `${total}s`
}

function pad(value: number): string {
  return value < 10 ? `0${value}` : String(value)
}

/**
 * Bausteine der Selbsttests.
 *
 * Bewusst kein Testframework: Die Pruefungen laufen im Spiel selbst ueber `?selftest`
 * (Implementierungsplan E0) und zusaetzlich headless ueber `npm run selftest`. Beide
 * Wege fuehren durch denselben Code.
 *
 * `check` faengt Fehler ab und schreibt das Ergebnis in eine Sammlung; ein gescheiterter
 * Test bricht den Durchlauf also nicht ab.
 */

export type TestResult = {
  suite: string
  name: string
  ok: boolean
  message?: string
}

let results: TestResult[] = []
let currentSuite = 'allgemein'

export class AssertionError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'AssertionError'
  }
}

export function suite(name: string): void {
  currentSuite = name
}

export function check(name: string, fn: () => void): void {
  try {
    fn()
    results.push({ suite: currentSuite, name, ok: true })
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    results.push({ suite: currentSuite, name, ok: false, message })
  }
}

export function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new AssertionError(message)
}

export function assertEqual<T>(actual: T, expected: T, message = ''): void {
  if (!Object.is(actual, expected)) {
    throw new AssertionError(
      `${message ? message + ': ' : ''}erwartet ${format(expected)}, war ${format(actual)}`,
    )
  }
}

export function assertClose(actual: number, expected: number, epsilon = 1e-9, message = ''): void {
  if (!(Math.abs(actual - expected) <= epsilon)) {
    throw new AssertionError(
      `${message ? message + ': ' : ''}erwartet ${expected} (+-${epsilon}), war ${actual}`,
    )
  }
}

export function assertDeepEqual(actual: unknown, expected: unknown, message = ''): void {
  const a = JSON.stringify(actual)
  const b = JSON.stringify(expected)
  if (a !== b) {
    throw new AssertionError(`${message ? message + ': ' : ''}\n  erwartet ${b}\n  war      ${a}`)
  }
}

export function assertThrows(fn: () => unknown, message = 'sollte werfen'): void {
  try {
    fn()
  } catch {
    return
  }
  throw new AssertionError(message)
}

function format(value: unknown): string {
  if (typeof value === 'string') return `"${value}"`
  return String(value)
}

/** Gesammelte Ergebnisse abholen und die Sammlung leeren. */
export function takeResults(): TestResult[] {
  const taken = results
  results = []
  currentSuite = 'allgemein'
  return taken
}

/**
 * Alle Kurven, Faktoren und Obergrenzen an einem Ort.
