/** PLATZHALTER - zentralster Balancing-Wert, GDD 15 Abschnitt 16. */
export const WAVE_SCALING = 1.1

/** PLATZHALTER - Boss alle n Wellen (GDD 07). */
export const BOSS_WAVE_INTERVAL = 10

/**
 * Alle Spielertexte an einer Stelle.
 *
 * Spielsprache ist Englisch (GDD 16 Abschnitt 1), Dokumentationssprache Deutsch. Kein
 * Text steht im Code von `ui/` oder `render/` - jeder laeuft ueber `t()`. Eine deutsche
 * Fassung ist damit spaeter eine zweite Tabelle, keine Codeaenderung.
 *
 * Platzhalter in geschweiften Klammern: `t('wave.current', { wave: 12 })`.
 */

export const STRINGS = {
  'game.title': 'WAVEBREAKER',

  'hud.gold': 'Gold',
  'hud.wave': 'Wave {wave}',
  'hud.level': 'Level {level}',
  'hud.speed': 'Speed x{factor}',

  'save.restored': 'Progress restored.',
  'save.fresh': 'New station initialised.',
  'save.corrupt': 'Saved game could not be read. Starting fresh.',
} as const

export type StringKey = keyof typeof STRINGS
export type StringParams = Record<string, string | number>

export function t(key: StringKey, params?: StringParams): string {
  const template: string = STRINGS[key]
  if (!params) return template
  return template.replace(/\{(\w+)\}/g, (match, name: string) => {
    const value = params[name]
    return value === undefined ? match : String(value)
  })
}

/** Existiert der Schluessel? Fuer den Selbsttest, der die UI gegen Tippfehler absichert. */
export function hasString(key: string): key is StringKey {
  return Object.prototype.hasOwnProperty.call(STRINGS, key)
}

/**
 * GameState - die eine Wahrheit.
 *
 * Die Aufteilung ist die wichtigste Entscheidung dieser Datei und laut GDD 16 Abschnitt 8
 * spaeter nur mit Umbau zu aendern:
 *
 *   permanent  ueberlebt Prestige   - Punkte, Freischaltungen, Statistik
 *   run        wird bei Prestige zurueckgesetzt - Welle, Gold, Tuerme, Upgrades, Level
 *   runtime    wird **nie** gespeichert - Generator, laufende Simulation, Anzeigezustand
 *
 * Fuer E13 (Prestige) ist genau diese Trennung die fehleranfaelligste Stelle des Spiels.
 * Deshalb steht sie ab E0 und wird im Selbsttest gegen eine Feldliste geprueft.
 */

import { createRng, randomSeed, type Rng } from '../core/rng.ts'
import {
  START_ABILITY_SLOTS,
  START_CORE_ID,
  START_GOLD,
  START_LEVEL,
  START_TOWER_IDS,
  START_TOWER_SLOTS,
  START_WAVE,
} from '../data/balance.ts'

/** Ueberlebt Prestige. */
export type PermanentState = {
  prestigePoints: number
  /** Gekaufte Knoten im Prestige-Baum. */
  prestigeNodes: string[]
  unlockedTowers: string[]
  unlockedCores: string[]
  /** Einmalige Hinweise, die der Spieler schon gesehen hat (GDD 14 Abschnitt 4a). */
  seenHints: string[]
  bestWaveEver: number
  prestigeCount: number
  totalPlaySeconds: number
}

/** Wird bei Prestige zurueckgesetzt. */
export type RunState = {
  /** Startwert des Generators fuer diesen Run - macht Fehlerberichte nachstellbar. */
  seed: number
  /** Fortgeschriebener Zustand des Generators. */
  rngState: number
  coreId: string
  wave: number
  /** Hoechste in diesem Run erreichte Welle - begrenzt das Vorspulen (E9). */
  waveRecord: number
  gold: number
  level: number
  xp: number
  towerSlots: number
  abilitySlots: number
  perks: string[]
  /** Upgrade-Pfad -> gekaufte Stufe. */
  upgrades: Record<string, number>
}

/** Existiert nur zur Laufzeit. Nichts hiervon geht in den Spielstand. */
export type RuntimeState = {
  rng: Rng
  /** Spielzeit der letzten Sicherung, in Sekunden. */
  lastSaveAt: number
  /** Es gibt ungesicherte Aenderungen. */
  dirty: boolean
}

export type GameState = {
  permanent: PermanentState
  run: RunState
  runtime: RuntimeState
}

export function createInitialPermanent(): PermanentState {
  return {
    prestigePoints: 0,
    prestigeNodes: [],
    unlockedTowers: [...START_TOWER_IDS],
    unlockedCores: [START_CORE_ID],
    seenHints: [],
    bestWaveEver: 0,
    prestigeCount: 0,
    totalPlaySeconds: 0,
  }
}

export function createInitialRun(seed: number = randomSeed()): RunState {
  return {
    seed,
    rngState: seed,
    coreId: START_CORE_ID,
    wave: START_WAVE,
    waveRecord: START_WAVE,
    gold: START_GOLD,
    level: START_LEVEL,
    xp: 0,
    towerSlots: START_TOWER_SLOTS,
    abilitySlots: START_ABILITY_SLOTS,
    perks: [],
    upgrades: {},
  }
}

export function createInitialState(seed: number = randomSeed()): GameState {
  const run = createInitialRun(seed)
  return {
    permanent: createInitialPermanent(),
    run,
    runtime: createRuntime(run),
  }
}

export function createRuntime(run: RunState): RuntimeState {
  const rng = createRng(run.seed)
  rng.setState(run.rngState)
  return { rng, lastSaveAt: 0, dirty: false }
}

/**
 * Den fortgeschriebenen Generatorzustand in die Run-Daten zurueckschreiben. Muss vor
 * jedem Speichern passieren, sonst laeuft der Zufall nach dem Laden von vorn.
 */
export function syncRngState(state: GameState): void {
  state.run.rngState = state.runtime.rng.state()
}

/** Aenderung vormerken, damit die naechste Sicherung sie mitnimmt. */
export function markDirty(state: GameState): void {
  state.runtime.dirty = true
}

/**
 * Serialisierung, Version, Migration.
 *
 * Eine einzige Stelle (GDD 16 Abschnitt 8). Der Spielstand ist ein klar getrenntes,
 * versioniertes Datenobjekt - Voraussetzung fuer spaeteren Server-Abgleich und fuer die
 * Offline-Berechnung, die den Zeitstempel der letzten Sicherung braucht.
 *
 * Regel aus dem Implementierungsplan Abschnitt 9: Wer ein Feld hinzufuegt, erhoeht
 * `SAVE_VERSION` und traegt eine Migration in `MIGRATIONS` ein - auch waehrend der
 * Entwicklung. Der Selbsttest prueft, dass die Kette luckenlos ist.
 *
 * Abweichung von der Signatur im Plan: `serialize`/`save` bekommen die echte Uhrzeit
 * uebergeben, statt sie selbst zu holen. Sonst muesste diese Datei `Date.now()` aufrufen,
 * und die Zeitquelle waere nicht mehr allein `core/loop.ts`.
 */

import { emit } from '../core/events.ts'
import { AUTOSAVE_INTERVAL_SECONDS } from '../data/balance.ts'
import type { Loop } from '../core/loop.ts'
import {
  createInitialPermanent,
  createInitialRun,
  createRuntime,
  syncRngState,
  type GameState,
  type PermanentState,
  type RunState,
} from './state.ts'

export const SAVE_VERSION = 1
export const STORAGE_KEY = 'wavebreaker.save'

export type SaveData = {
  version: number
  /** Echte Uhrzeit in Millisekunden - Grundlage der Offline-Berechnung (E17). */
  savedAt: number
  permanent: PermanentState
  run: RunState
}

// ---------------------------------------------------------------------------
// Ablage
// ---------------------------------------------------------------------------

export type SaveStorage = {
  getItem(key: string): string | null
  setItem(key: string, value: string): void
  removeItem(key: string): void
}

function createMemoryStorage(): SaveStorage {
  const map = new Map<string, string>()
  return {
    getItem: (key) => map.get(key) ?? null,
    setItem: (key, value) => void map.set(key, value),
    removeItem: (key) => void map.delete(key),
  }
}

let storage: SaveStorage | null = null

function resolveStorage(): SaveStorage {
  if (storage) return storage
  try {
    if (typeof localStorage !== 'undefined') {
      // Probeschreiben: im privaten Modus existiert localStorage, wirft aber beim Schreiben.
      localStorage.setItem('wavebreaker.probe', '1')
      localStorage.removeItem('wavebreaker.probe')
      storage = localStorage
      return storage
    }
  } catch {
    // faellt unten auf den Speicher im Arbeitsspeicher zurueck
  }
  storage = createMemoryStorage()
  return storage
}

/** Ablage ersetzen - fuer Selbsttests und den headless-Lauf. */
export function setStorage(next: SaveStorage | null): void {
  storage = next
}

// ---------------------------------------------------------------------------
// Serialisieren und Pruefen
// ---------------------------------------------------------------------------

export function serialize(state: GameState, nowMs: number): SaveData {
  syncRngState(state)
  return {
    version: SAVE_VERSION,
    savedAt: nowMs,
    permanent: {
      prestigePoints: state.permanent.prestigePoints,
      prestigeNodes: [...state.permanent.prestigeNodes],
      unlockedTowers: [...state.permanent.unlockedTowers],
      unlockedCores: [...state.permanent.unlockedCores],
      seenHints: [...state.permanent.seenHints],
      bestWaveEver: state.permanent.bestWaveEver,
      prestigeCount: state.permanent.prestigeCount,
      totalPlaySeconds: state.permanent.totalPlaySeconds,
    },
    run: {
      seed: state.run.seed,
      rngState: state.run.rngState,
      coreId: state.run.coreId,
      wave: state.run.wave,
      waveRecord: state.run.waveRecord,
      gold: state.run.gold,
      level: state.run.level,
      xp: state.run.xp,
      towerSlots: state.run.towerSlots,
      abilitySlots: state.run.abilitySlots,
      perks: [...state.run.perks],
      upgrades: { ...state.run.upgrades },
    },
  }
}

export function deserialize(data: unknown): GameState | null {
  if (!isRecord(data)) return null

  const version = data['version']
  if (typeof version !== 'number' || !Number.isInteger(version) || version < 1) return null
  // Ein Spielstand aus einer neueren Fassung wird nicht geraten, sondern abgelehnt.
  if (version > SAVE_VERSION) return null

  const migrated = version === SAVE_VERSION ? data : migrate(data, version)
  if (!migrated) return null

  if (!isRecord(migrated['permanent']) || !isRecord(migrated['run'])) return null

  const permanent = readPermanent(migrated['permanent'])
  const run = readRun(migrated['run'])

  return { permanent, run, runtime: createRuntime(run) }
}

/**
 * Fehlende oder kaputte Einzelfelder werden mit dem Startwert aufgefuellt, statt den
 * ganzen Spielstand zu verwerfen. Die Migrationskette bleibt trotzdem Pflicht - sie ist
 * der geplante Weg, das hier ist nur das Netz darunter.
 */
function readPermanent(raw: Record<string, unknown>): PermanentState {
  const base = createInitialPermanent()
  return {
    prestigePoints: readNumber(raw['prestigePoints'], base.prestigePoints),
    prestigeNodes: readStringArray(raw['prestigeNodes'], base.prestigeNodes),
    unlockedTowers: readStringArray(raw['unlockedTowers'], base.unlockedTowers),
    unlockedCores: readStringArray(raw['unlockedCores'], base.unlockedCores),
    seenHints: readStringArray(raw['seenHints'], base.seenHints),
    bestWaveEver: readNumber(raw['bestWaveEver'], base.bestWaveEver),
    prestigeCount: readNumber(raw['prestigeCount'], base.prestigeCount),
    totalPlaySeconds: readNumber(raw['totalPlaySeconds'], base.totalPlaySeconds),
  }
}

function readRun(raw: Record<string, unknown>): RunState {
  const base = createInitialRun(readNumber(raw['seed'], 1))
  return {
    seed: base.seed,
    rngState: readNumber(raw['rngState'], base.rngState),
    coreId: readString(raw['coreId'], base.coreId),
    wave: readNumber(raw['wave'], base.wave),
    waveRecord: readNumber(raw['waveRecord'], base.waveRecord),
    gold: readNumber(raw['gold'], base.gold),
    level: readNumber(raw['level'], base.level),
    xp: readNumber(raw['xp'], base.xp),
    towerSlots: readNumber(raw['towerSlots'], base.towerSlots),
    abilitySlots: readNumber(raw['abilitySlots'], base.abilitySlots),
    perks: readStringArray(raw['perks'], base.perks),
    upgrades: readNumberRecord(raw['upgrades'], base.upgrades),
  }
}

// ---------------------------------------------------------------------------
// Migration
// ---------------------------------------------------------------------------

type Migration = (data: Record<string, unknown>) => Record<string, unknown>

/**
 * Schluessel `n` fuehrt von Version `n` auf `n + 1`. Immer Schritt fuer Schritt, nie
 * ein Sprung ueber mehrere Fassungen.
 *
 * Beispiel fuer spaeter:
 *   2: (data) => ({ ...data, version: 3, run: { ...(data.run as object), helpers: [] } }),
 */
const MIGRATIONS: Record<number, Migration> = {}

export function migrate(data: Record<string, unknown>, fromVersion: number): SaveData | null {
  let current = data
  for (let v = fromVersion; v < SAVE_VERSION; v++) {
    const step = MIGRATIONS[v]
    if (!step) return null
    current = step(current)
    current['version'] = v + 1
  }
  return current as unknown as SaveData
}

/** Fuer den Selbsttest: ist die Kette von Version 1 bis heute lueckenlos? */
export function migrationChainComplete(): boolean {
  for (let v = 1; v < SAVE_VERSION; v++) {
    if (!MIGRATIONS[v]) return false
  }
  return true
}

// ---------------------------------------------------------------------------
// localStorage
// ---------------------------------------------------------------------------

export function save(state: GameState, nowMs: number): boolean {
  const data = serialize(state, nowMs)
  const text = JSON.stringify(data)
  try {
    resolveStorage().setItem(STORAGE_KEY, text)
  } catch {
    // Speicher voll oder gesperrt - das Spiel laeuft weiter, nur ohne Sicherung.
    return false
  }
  state.runtime.dirty = false
  emit('save.written', { bytes: text.length })
  return true
}

export function load(): GameState | null {
  let text: string | null = null
  try {
    text = resolveStorage().getItem(STORAGE_KEY)
  } catch {
    text = null
  }
  if (text === null) return null

  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    emit('save.corrupt', { reason: 'kein gueltiges JSON' })
    return null
  }

  const state = deserialize(parsed)
  if (!state) {
    emit('save.corrupt', { reason: 'unbekannte Fassung oder kaputte Struktur' })
    return null
  }
  return state
}

/** Zeitstempel der letzten Sicherung, ohne den Spielstand zu laden (Offline-Rechnung, E17). */
export function lastSavedAt(): number | null {
  try {
    const text = resolveStorage().getItem(STORAGE_KEY)
    if (text === null) return null
    const parsed: unknown = JSON.parse(text)
    if (!isRecord(parsed)) return null
    const savedAt = parsed['savedAt']
    return typeof savedAt === 'number' && Number.isFinite(savedAt) ? savedAt : null
  } catch {
    return null
  }
}

export function clearSave(): void {
  try {
    resolveStorage().removeItem(STORAGE_KEY)
  } catch {
    // nichts zu tun
  }
  emit('save.cleared', {})
}

// ---------------------------------------------------------------------------
// Automatische Sicherung
// ---------------------------------------------------------------------------

export type Autosave = {
  /** Aus dem Tick der Hauptschleife aufrufen. */
  tick(): void
  /** Sofort sichern, z. B. nach einem Kauf oder Wellenwechsel. */
  saveNow(): void
  stop(): void
}

/**
 * Sichert alle paar Sekunden Spielzeit und beim Schliessen des Tabs (GDD 16 Abschnitt 8).
 * Der Zeitstempel beim Schliessen ist zugleich der Nullpunkt der Offline-Berechnung.
 *
 * Ereignisgesteuerte Sicherungen (Kauf, Levelaufstieg, Wellenwechsel, Prestige) haengen
 * sich ab E7 an `saveNow()` - die Ereignisse dafuer gibt es in E0 noch nicht.
 */
export function startAutosave(state: GameState, loop: Loop): Autosave {
  const saveNow = (): void => {
    save(state, loop.wallClock())
    state.runtime.lastSaveAt = loop.now()
  }

  const onLeave = (): void => saveNow()
  const onVisibility = (): void => {
    if (typeof document !== 'undefined' && document.visibilityState === 'hidden') saveNow()
  }

  if (typeof window !== 'undefined') {
    window.addEventListener('beforeunload', onLeave)
    window.addEventListener('pagehide', onLeave)
  }
  if (typeof document !== 'undefined') {
    document.addEventListener('visibilitychange', onVisibility)
  }

  return {
    tick() {
      if (!state.runtime.dirty) return
      if (loop.now() - state.runtime.lastSaveAt < AUTOSAVE_INTERVAL_SECONDS) return
      saveNow()
    },
    saveNow,
    stop() {
      if (typeof window !== 'undefined') {
        window.removeEventListener('beforeunload', onLeave)
        window.removeEventListener('pagehide', onLeave)
      }
      if (typeof document !== 'undefined') {
        document.removeEventListener('visibilitychange', onVisibility)
      }
    },
  }
}

// ---------------------------------------------------------------------------
// Lesehilfen
// ---------------------------------------------------------------------------

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function readNumber(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback
}

function readString(value: unknown, fallback: string): string {
  return typeof value === 'string' ? value : fallback
}

function readStringArray(value: unknown, fallback: string[]): string[] {
  if (!Array.isArray(value)) return [...fallback]
  return value.filter((entry): entry is string => typeof entry === 'string')
}

function readNumberRecord(value: unknown, fallback: Record<string, number>): Record<string, number> {
  if (!isRecord(value)) return { ...fallback }
  const result: Record<string, number> = {}
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === 'number' && Number.isFinite(entry)) result[key] = entry
  }
  return result
}

/**
 * Beweis aus E0: "120 Ticks bei x2 in einer Sekunde, 60 bei x1 - als Test, nicht per
 * Augenmass." Moeglich wird das durch die austauschbare Bildquelle: der Test loest die
 * Bilder selbst aus und bestimmt, wie weit die Zeit springt.
 */

import { assert, assertClose, assertEqual, check, suite } from '../../core/assert.ts'
import { createLoop, createManualScheduler, type SpeedFactor } from '../../core/loop.ts'
import { TICK_RATE } from '../../data/balance.ts'

/** Eine Sekunde in zehn Bildern zu 100 ms - ohne Gleitkomma-Rest im Akkumulator. */
function ticksInOneSecond(speed: SpeedFactor): number {
  const scheduler = createManualScheduler()
  const loop = createLoop({ tickRate: TICK_RATE, scheduleFrame: scheduler })
  let ticks = 0
  loop.setSpeed(speed)
  loop.start(
    () => ticks++,
    () => {},
  )
  scheduler.advance(0) // Nullpunkt setzen
  scheduler.advanceBy(1000, 100)
  loop.stop()
  return ticks
}

export function loopSuite(): void {
  suite('core/loop')

  check('x1 ergibt 60 Ticks pro Sekunde', () => {
    assertEqual(ticksInOneSecond(1), 60)
  })

  check('x2 ergibt 120 Ticks pro Sekunde', () => {
    assertEqual(ticksInOneSecond(2), 120)
  })

  check('x4 ergibt 240 Ticks pro Sekunde', () => {
    assertEqual(ticksInOneSecond(4), 240)
  })

  check('60 unregelmaessige Bilder liefern 60 Ticks (+-1)', () => {
    const scheduler = createManualScheduler()
    const loop = createLoop({ scheduleFrame: scheduler })
    let ticks = 0
    loop.start(
      () => ticks++,
      () => {},
    )
    scheduler.advance(0)
    scheduler.advanceBy(1000, 1000 / 60)
    loop.stop()
    assert(Math.abs(ticks - 60) <= 1, `erwartet 60 +-1, war ${ticks}`)
  })

  check('Schrittweite bleibt konstant, egal bei welcher Geschwindigkeit', () => {
    const scheduler = createManualScheduler()
    const loop = createLoop({ scheduleFrame: scheduler })
    const steps = new Set<number>()
    loop.setSpeed(4)
    loop.start(
      (dt) => steps.add(dt),
      () => {},
    )
    scheduler.advance(0)
    scheduler.advanceBy(500, 100)
    loop.stop()
    assertEqual(steps.size, 1, 'x4 darf keine groesseren Schritte erzeugen')
    assertClose([...steps][0] ?? 0, 1 / TICK_RATE)
  })

  check('das erste Bild erzeugt keinen Zeitsprung', () => {
    const scheduler = createManualScheduler(123456)
    const loop = createLoop({ scheduleFrame: scheduler })
    let ticks = 0
    loop.start(
      () => ticks++,
      () => {},
    )
    scheduler.advance(0)
    assertEqual(ticks, 0)
  })

  check('now() entspricht der Anzahl Ticks', () => {
    const scheduler = createManualScheduler()
    const loop = createLoop({ scheduleFrame: scheduler })
    loop.start(
      () => {},
      () => {},
    )
    scheduler.advance(0)
    scheduler.advanceBy(1000, 100)
    assertClose(loop.now(), loop.tickCount() / TICK_RATE, 1e-9)
    loop.stop()
  })

  check('ein langer Ausfall wird gedeckelt statt nachgeholt', () => {
    const scheduler = createManualScheduler()
    const loop = createLoop({ scheduleFrame: scheduler, maxFrameSeconds: 0.25 })
    let ticks = 0
    loop.start(
      () => ticks++,
      () => {},
    )
    scheduler.advance(0)
    scheduler.advance(10_000) // Tab war zehn Sekunden weg
    loop.stop()
    assertEqual(ticks, 15, '0,25 s x 60 Ticks/s')
  })

  check('Ueberlast verwirft den Rest, statt sich aufzuschaukeln', () => {
    const scheduler = createManualScheduler()
    const loop = createLoop({
      scheduleFrame: scheduler,
      maxFrameSeconds: 10,
      maxTicksPerFrame: 20,
    })
    let ticks = 0
    loop.start(
      () => ticks++,
      () => {},
    )
    scheduler.advance(0)
    scheduler.advance(1000)
    scheduler.advance(16)
    loop.stop()
    assertEqual(ticks, 20, 'zweites Bild darf keinen Rueckstand nachholen')
  })

  check('render laeuft einmal je Bild, auch ohne Tick', () => {
    const scheduler = createManualScheduler()
    const loop = createLoop({ scheduleFrame: scheduler })
    let frames = 0
    let ticks = 0
    loop.start(
      () => ticks++,
      () => frames++,
    )
    scheduler.advance(0)
    scheduler.advance(1) // zu kurz fuer einen Tick
    scheduler.advance(1)
    loop.stop()
    assertEqual(ticks, 0)
    assertEqual(frames, 2)
  })

  check('stop() haelt die Schleife an', () => {
    const scheduler = createManualScheduler()
    const loop = createLoop({ scheduleFrame: scheduler })
    let ticks = 0
    loop.start(
      () => ticks++,
      () => {},
    )
    scheduler.advance(0)
    scheduler.advance(100)
    const before = ticks
    loop.stop()
    scheduler.advance(1000)
    assertEqual(ticks, before)
    assertEqual(loop.isRunning(), false)
  })

  check('wallClock ist von der Spielzeit unabhaengig', () => {
    const scheduler = createManualScheduler()
    const loop = createLoop({ scheduleFrame: scheduler, wallClock: () => 1_700_000_000_000 })
    loop.setSpeed(4)
    loop.start(
      () => {},
      () => {},
    )
    scheduler.advance(0)
    scheduler.advanceBy(1000, 100)
    assertEqual(loop.wallClock(), 1_700_000_000_000)
    assertClose(loop.now(), 4, 1e-9, 'x4 laesst die Spielzeit vierfach laufen')
    loop.stop()
  })
}

/**
 * Der Zufall muss reproduzierbar sein, sonst ist ein Balancing-Fehler nicht nachstellbar
 * (Implementierungsplan Abschnitt 3).
 */

import { assert, assertDeepEqual, assertEqual, assertThrows, check, suite } from '../../core/assert.ts'
import { createRng } from '../../core/rng.ts'

function take(seed: number, count: number): number[] {
  const rng = createRng(seed)
  return Array.from({ length: count }, () => rng.next())
}

export function rngSuite(): void {
  suite('core/rng')

  check('gleicher Seed liefert gleiche Folge', () => {
    assertDeepEqual(take(42, 20), take(42, 20))
  })

  check('anderer Seed liefert andere Folge', () => {
    const a = take(1, 10)
    const b = take(2, 10)
    assert(a.some((value, i) => value !== b[i]), 'Folgen duerfen nicht identisch sein')
  })

  check('next() liegt in [0, 1)', () => {
    const rng = createRng(7)
    for (let i = 0; i < 5000; i++) {
      const value = rng.next()
      assert(value >= 0 && value < 1, `ausserhalb des Bereichs: ${value}`)
    }
  })

  check('int() schliesst beide Grenzen ein', () => {
    const rng = createRng(9)
    const seen = new Set<number>()
    for (let i = 0; i < 6000; i++) {
      const value = rng.int(1, 6)
      assert(Number.isInteger(value), 'muss ganzzahlig sein')
      assert(value >= 1 && value <= 6, `ausserhalb 1..6: ${value}`)
      seen.add(value)
    }
    assertEqual(seen.size, 6, 'alle sechs Werte muessen vorkommen')
  })

  check('int() mit gleicher Ober- und Untergrenze', () => {
    assertEqual(createRng(3).int(5, 5), 5)
  })

  check('int() vertauschte Grenzen werden gedreht', () => {
    const value = createRng(3).int(9, 2)
    assert(value >= 2 && value <= 9, `ausserhalb 2..9: ${value}`)
  })

  check('chance(0) und chance(1) sind eindeutig', () => {
    const rng = createRng(11)
    for (let i = 0; i < 100; i++) {
      assertEqual(rng.chance(0), false)
      assertEqual(rng.chance(1), true)
    }
  })

  check('chance(0.25) trifft ungefaehr ein Viertel', () => {
    const rng = createRng(13)
    let hits = 0
    const rounds = 20_000
    for (let i = 0; i < rounds; i++) if (rng.chance(0.25)) hits++
    const ratio = hits / rounds
    assert(Math.abs(ratio - 0.25) < 0.02, `erwartet ~0,25, war ${ratio}`)
  })

  check('pick() wirft bei leerer Liste', () => {
    assertThrows(() => createRng(1).pick([]))
  })

  check('pick() liefert nur Elemente der Liste', () => {
    const rng = createRng(5)
    const items = ['a', 'b', 'c'] as const
    for (let i = 0; i < 500; i++) {
      assert(items.includes(rng.pick(items)), 'fremdes Element')
    }
  })

  check('shuffle() ist eine echte Umordnung', () => {
    const rng = createRng(17)
    const source = Array.from({ length: 50 }, (_, i) => i)
    const shuffled = rng.shuffle([...source])
    assertEqual(shuffled.length, source.length)
    assertDeepEqual([...shuffled].sort((a, b) => a - b), source)
  })

  check('Zustand laesst sich sichern und wiederherstellen', () => {
    const rng = createRng(99)
    for (let i = 0; i < 37; i++) rng.next()
    const saved = rng.state()
    const expected = Array.from({ length: 10 }, () => rng.next())

    const restored = createRng(0)
    restored.setState(saved)
    assertDeepEqual(
      Array.from({ length: 10 }, () => restored.next()),
      expected,
    )
  })

  check('fork() erzeugt einen eigenen, aber reproduzierbaren Strom', () => {
    const a = createRng(21)
    const forkA = a.fork(1)
    const b = createRng(21)
    const forkB = b.fork(1)
    assertDeepEqual(
      Array.from({ length: 10 }, () => forkA.next()),
      Array.from({ length: 10 }, () => forkB.next()),
    )
  })

  check('fork() verschiebt den Strom des Erzeugers nicht', () => {
    const rng = createRng(31)
    const before = rng.state()
    rng.fork(7)
    assertEqual(rng.state(), before)
  })

  check('verschiedene Salze liefern verschiedene Stroeme', () => {
    const rng = createRng(31)
    const one = rng.fork(1).next()
    const two = rng.fork(2).next()
    assert(one !== two, 'Salz muss wirken')
  })
}

/**
 * Zahlendarstellung nach GDD 13 Abschnitt 8. Diese Datei ist zugleich die Absicherung
 * fuer die Entscheidung "normales `number`": Wenn spaeter doch ein eigener Zahlentyp
 * kommt, muessen diese Erwartungen unveraendert gelten.
 */

import { assertEqual, check, suite } from '../../core/assert.ts'
import {
  formatDuration,
  formatDurationCoarse,
  formatNumber,
  formatPercent,
} from '../../core/format.ts'

export function formatSuite(): void {
  suite('core/format')

  check('bis 9.999 vollstaendig mit Tausendertrennung', () => {
    assertEqual(formatNumber(0), '0')
    assertEqual(formatNumber(7), '7')
    assertEqual(formatNumber(999), '999')
    assertEqual(formatNumber(4250), '4,250')
    assertEqual(formatNumber(9999), '9,999')
  })

  check('ab 10.000 abgekuerzt mit einer Nachkommastelle', () => {
    assertEqual(formatNumber(10_000), '10.0K')
    assertEqual(formatNumber(12_500), '12.5K')
    assertEqual(formatNumber(3_800_000), '3.8M')
    assertEqual(formatNumber(1_200_000_000), '1.2B')
    assertEqual(formatNumber(1e12), '1.0T')
  })

  check('die Abkuerzung springt sauber in die naechste Stufe', () => {
    assertEqual(formatNumber(999_949), '999.9K', 'darf nie "1000.0K" ergeben')
    assertEqual(formatNumber(1_000_000), '1.0M')
  })

  check('sehr grosse Werte wissenschaftlich', () => {
    assertEqual(formatNumber(1e15), '1.0e15')
    assertEqual(formatNumber(4.19e18), '4.1e18')
  })

  check('negative Werte behalten das Vorzeichen', () => {
    assertEqual(formatNumber(-4250), '-4,250')
    assertEqual(formatNumber(-12_500), '-12.5K')
  })

  check('gebrochene Werte bekommen eine Nachkommastelle', () => {
    assertEqual(formatNumber(0.5), '0.5')
    assertEqual(formatNumber(12.34), '12.3')
  })

  check('unbrauchbare Werte stuerzen nicht ab', () => {
    assertEqual(formatNumber(Number.NaN), '-')
    assertEqual(formatNumber(Number.POSITIVE_INFINITY), '-')
  })

  check('Prozent nie als Multiplikator', () => {
    assertEqual(formatPercent(0.15), '15%')
    assertEqual(formatPercent(0.15, { sign: true }), '+15%')
    assertEqual(formatPercent(-0.2, { sign: true }), '-20%')
    assertEqual(formatPercent(0.075, { decimals: 1 }), '7.5%')
    assertEqual(formatPercent(1), '100%')
  })

  check('Dauer als Spielzeit', () => {
    assertEqual(formatDuration(0), '0s')
    assertEqual(formatDuration(8), '8s')
    assertEqual(formatDuration(65), '1:05')
    assertEqual(formatDuration(8043), '2:14:03')
    assertEqual(formatDuration(-1), '-')
  })

  check('grobe Dauer fuer die Rueckkehr-Zusammenfassung', () => {
    assertEqual(formatDurationCoarse(30), '30s')
    assertEqual(formatDurationCoarse(2700), '45m')
    assertEqual(formatDurationCoarse(8043), '2h 14m')
    assertEqual(formatDurationCoarse(7200), '2h')
  })
}

/**
 * Beweis aus E0: Speicher-Rundlauf ist verlustfrei, kaputte Spielstaende liefern `null`
 * statt eines Absturzes.
 *
 * Zusaetzlich steht hier bereits die Absicherung fuer E13: eine feste Liste aller
 * Zustandsfelder je Bereich. Wer ein Feld hinzufuegt, muss sich hier bewusst
 * entscheiden, ob es Prestige ueberlebt - genau das ist laut Plan die fehleranfaelligste
 * Stelle des ganzen Spiels.
 */

import { assert, assertDeepEqual, assertEqual, check, suite } from '../../core/assert.ts'
import { createLoop, createManualScheduler } from '../../core/loop.ts'
import { on, resetEvents } from '../../core/events.ts'
import { AUTOSAVE_INTERVAL_SECONDS } from '../../data/balance.ts'
import {
  clearSave,
  deserialize,
  lastSavedAt,
  load,
  migrationChainComplete,
  save,
  serialize,
  setStorage,
  startAutosave,
  STORAGE_KEY,
  SAVE_VERSION,
  type SaveStorage,
} from '../../app/save.ts'
import { createInitialPermanent, createInitialRun, createInitialState } from '../../app/state.ts'

const PERMANENT_FIELDS = [
  'bestWaveEver',
  'prestigeCount',
  'prestigeNodes',
  'prestigePoints',
  'seenHints',
  'totalPlaySeconds',
  'unlockedCores',
  'unlockedTowers',
]

const RUN_FIELDS = [
  'abilitySlots',
  'coreId',
  'gold',
  'level',
  'perks',
  'rngState',
  'seed',
  'towerSlots',
  'upgrades',
  'wave',
  'waveRecord',
  'xp',
]

function memoryStorage(): SaveStorage {
  const map = new Map<string, string>()
  return {
    getItem: (key) => map.get(key) ?? null,
    setItem: (key, value) => void map.set(key, value),
    removeItem: (key) => void map.delete(key),
  }
}

export function saveSuite(): void {
  suite('app/save')

  check('deserialize(serialize(x)) ist gleich x', () => {
    const state = createInitialState(4242)
    state.run.gold = 1234
    state.run.wave = 17
    state.run.upgrades['core.damage'] = 3
    state.permanent.prestigePoints = 9
    state.permanent.seenHints.push('hint.gold')

    const first = serialize(state, 1000)
    const restored = deserialize(first)
    assert(restored !== null, 'Spielstand muss lesbar sein')
    assertDeepEqual(serialize(restored, 1000), first)
  })

  check('der Zufall laeuft nach dem Laden weiter, statt von vorn', () => {
    const state = createInitialState(777)
    for (let i = 0; i < 25; i++) state.runtime.rng.next()
    const expected = Array.from({ length: 5 }, () => state.runtime.rng.next())

    const state2 = createInitialState(777)
    for (let i = 0; i < 25; i++) state2.runtime.rng.next()
    const restored = deserialize(serialize(state2, 0))
    assert(restored !== null, 'Spielstand muss lesbar sein')
    assertDeepEqual(
      Array.from({ length: 5 }, () => restored.runtime.rng.next()),
      expected,
    )
  })

  check('Laufzeitdaten landen nie im Spielstand', () => {
    const text = JSON.stringify(serialize(createInitialState(1), 0))
    assert(!text.includes('runtime'), 'runtime darf nicht serialisiert werden')
    assert(!text.includes('dirty'), 'dirty darf nicht serialisiert werden')
  })

  check('kaputte Eingaben liefern null statt eines Absturzes', () => {
    const broken: unknown[] = [
      null,
      undefined,
      'nein',
      42,
      [],
      {},
      { version: 0 },
      { version: -1 },
      { version: 1.5 },
      { version: 1 }, // permanent und run fehlen
      { version: 1, permanent: 'kaputt', run: {} },
      { version: SAVE_VERSION + 1, permanent: {}, run: {} }, // aus der Zukunft
    ]
    for (const input of broken) {
      assertEqual(deserialize(input), null, `haette null liefern muessen: ${JSON.stringify(input)}`)
    }
  })

  check('einzelne kaputte Felder werden aufgefuellt, nicht verworfen', () => {
    const restored = deserialize({
      version: SAVE_VERSION,
      savedAt: 0,
      permanent: { prestigePoints: 'viel', unlockedTowers: ['autocannon', 7, 'cannon'] },
      run: { gold: Number.NaN, wave: 12, upgrades: { 'core.damage': 2, kaputt: 'x' } },
    })
    assert(restored !== null, 'darf nicht verworfen werden')
    assertEqual(restored.permanent.prestigePoints, 0, 'Startwert statt Text')
    assertDeepEqual(restored.permanent.unlockedTowers, ['autocannon', 'cannon'])
    assertEqual(restored.run.gold, 0, 'NaN faellt auf den Startwert zurueck')
    assertEqual(restored.run.wave, 12, 'gueltige Felder bleiben erhalten')
    assertDeepEqual(restored.run.upgrades, { 'core.damage': 2 })
  })

  check('unbekannte Zusatzfelder stoeren nicht', () => {
    const restored = deserialize({
      version: SAVE_VERSION,
      savedAt: 0,
      zukunft: { irgendwas: true },
      permanent: { ...createInitialPermanent(), zusatz: 1 },
      run: { ...createInitialRun(5), zusatz: 1 },
    })
    assert(restored !== null, 'darf nicht verworfen werden')
  })

  check('die Migrationskette ist lueckenlos', () => {
    assert(
      migrationChainComplete(),
      `es fehlt eine Migration unterhalb von Version ${SAVE_VERSION}`,
    )
  })

  check('Rundlauf ueber die Ablage', () => {
    setStorage(memoryStorage())
    const state = createInitialState(2024)
    state.run.gold = 555
    assertEqual(save(state, 1_700_000_000_000), true)
    const loaded = load()
    assert(loaded !== null, 'Spielstand muss geladen werden')
    assertEqual(loaded.run.gold, 555)
    assertEqual(lastSavedAt(), 1_700_000_000_000)
    setStorage(null)
  })

  check('Speichern loescht die Aenderungsmarke', () => {
    setStorage(memoryStorage())
    const state = createInitialState(1)
    state.runtime.dirty = true
    save(state, 0)
    assertEqual(state.runtime.dirty, false)
    setStorage(null)
  })

  check('kaputter Text in der Ablage meldet sich und liefert null', () => {
    resetEvents()
    const storage = memoryStorage()
    storage.setItem(STORAGE_KEY, '{ das ist kein json')
    setStorage(storage)
    let reported = 0
    on('save.corrupt', () => reported++)
    assertEqual(load(), null)
    assertEqual(reported, 1)
    resetEvents()
    setStorage(null)
  })

  check('clearSave entfernt den Spielstand', () => {
    setStorage(memoryStorage())
    save(createInitialState(1), 0)
    clearSave()
    assertEqual(load(), null)
    assertEqual(lastSavedAt(), null)
    setStorage(null)
  })

  check('ohne Spielstand liefert load() null, ohne Fehlermeldung', () => {
    resetEvents()
    setStorage(memoryStorage())
    let reported = 0
    on('save.corrupt', () => reported++)
    assertEqual(load(), null)
    assertEqual(reported, 0, 'ein leerer Speicher ist kein Fehler')
    resetEvents()
    setStorage(null)
  })

  check('die automatische Sicherung wartet auf Abstand und Aenderung', () => {
    setStorage(memoryStorage())
    const scheduler = createManualScheduler()
    const loop = createLoop({ scheduleFrame: scheduler })
    const state = createInitialState(1)
    const autosave = startAutosave(state, loop)

    let written = 0
    resetEvents()
    on('save.written', () => written++)

    loop.start(
      () => autosave.tick(),
      () => {},
    )
    scheduler.advance(0)

    scheduler.advanceBy((AUTOSAVE_INTERVAL_SECONDS + 1) * 1000, 100)
    assertEqual(written, 0, 'ohne Aenderung wird nicht gesichert')

    state.runtime.dirty = true
    scheduler.advanceBy(1000, 100)
    assertEqual(written, 1, 'nach einer Aenderung wird gesichert')

    state.runtime.dirty = true
    scheduler.advanceBy(1000, 100)
    assertEqual(written, 1, 'der Abstand wird eingehalten')

    scheduler.advanceBy(AUTOSAVE_INTERVAL_SECONDS * 1000, 100)
    assertEqual(written, 2)

    loop.stop()
    autosave.stop()
    resetEvents()
    setStorage(null)
  })

  check('die Feldliste von permanent ist unveraendert (E13-Absicherung)', () => {
    assertDeepEqual(Object.keys(createInitialPermanent()).sort(), PERMANENT_FIELDS)
  })

  check('die Feldliste von run ist unveraendert (E13-Absicherung)', () => {
    assertDeepEqual(Object.keys(createInitialRun(1)).sort(), RUN_FIELDS)
  })

  check('permanent und run ueberschneiden sich nicht', () => {
    const overlap = PERMANENT_FIELDS.filter((field) => RUN_FIELDS.includes(field))
    assertDeepEqual(overlap, [], 'ein Feld gehoert genau einem Bereich')
  })
}

/**
 * Beweis aus E0: `grantReward` erhoeht genau die genannte Ressource und meldet ein
 * Ereignis. Das ist der Haken, an dem spaeter Werbe-Belohnungen haengen (GDD 16
 * Abschnitt 2) - er muss von Anfang an dicht sein.
 */

import { assertDeepEqual, assertEqual, check, suite } from '../../core/assert.ts'
import { on, resetEvents } from '../../core/events.ts'
import { grantReward } from '../../app/rewards.ts'
import { createInitialState } from '../../app/state.ts'

export function rewardsSuite(): void {
  suite('app/rewards')

  check('Gold landet in den Run-Daten', () => {
    const state = createInitialState(1)
    grantReward(state, { gold: 250 }, 'test')
    assertEqual(state.run.gold, 250)
    assertEqual(state.run.xp, 0, 'nur die genannte Ressource steigt')
    assertEqual(state.permanent.prestigePoints, 0)
  })

  check('XP landet in den Run-Daten', () => {
    const state = createInitialState(1)
    grantReward(state, { xp: 40 }, 'test')
    assertEqual(state.run.xp, 40)
    assertEqual(state.run.gold, 0)
  })

  check('Prestige-Punkte landen in den permanenten Daten', () => {
    const state = createInitialState(1)
    grantReward(state, { prestigePoints: 3 }, 'test')
    assertEqual(state.permanent.prestigePoints, 3)
    assertEqual(state.run.gold, 0)
  })

  check('mehrere Ressourcen auf einmal', () => {
    const state = createInitialState(1)
    grantReward(state, { gold: 10, xp: 5, prestigePoints: 1 }, 'test')
    assertEqual(state.run.gold, 10)
    assertEqual(state.run.xp, 5)
    assertEqual(state.permanent.prestigePoints, 1)
  })

  check('Belohnungen summieren sich', () => {
    const state = createInitialState(1)
    grantReward(state, { gold: 10 }, 'test')
    grantReward(state, { gold: 15 }, 'test')
    assertEqual(state.run.gold, 25)
  })

  check('unbrauchbare Betraege vernichten keinen Fortschritt', () => {
    const state = createInitialState(1)
    state.run.gold = 100
    grantReward(state, { gold: -50 }, 'test')
    grantReward(state, { gold: Number.NaN }, 'test')
    grantReward(state, { gold: Number.POSITIVE_INFINITY }, 'test')
    grantReward(state, { gold: 0 }, 'test')
    assertEqual(state.run.gold, 100)
  })

  check('jede Belohnung meldet ein Ereignis mit Herkunft', () => {
    resetEvents()
    const state = createInitialState(1)
    const seen: unknown[] = []
    on('reward.granted', (payload) => seen.push(payload))
    grantReward(state, { gold: 7 }, 'enemy.kill')
    assertDeepEqual(seen, [{ reward: { gold: 7, xp: 0, prestigePoints: 0 }, source: 'enemy.kill' }])
    resetEvents()
  })

  check('eine leere Belohnung meldet nichts', () => {
    resetEvents()
    const state = createInitialState(1)
    let calls = 0
    on('reward.granted', () => calls++)
    grantReward(state, {}, 'test')
    grantReward(state, { gold: 0, xp: 0 }, 'test')
    assertEqual(calls, 0)
    resetEvents()
  })

  check('eine Belohnung merkt die Aenderung fuer die Sicherung vor', () => {
    const state = createInitialState(1)
    assertEqual(state.runtime.dirty, false)
    grantReward(state, { gold: 1 }, 'test')
    assertEqual(state.runtime.dirty, true)
  })
}

/**
 * Alle Spielertexte laufen ueber `t()` (GDD 16 Abschnitt 1). Der Test sichert die
 * Platzhalter-Ersetzung ab - sie ist die Stelle, an der eine spaetere deutsche Fassung
 * bricht, wenn sie unsauber ist.
 */

import { assert, assertEqual, check, suite } from '../../core/assert.ts'
import { hasString, STRINGS, t } from '../../data/strings.ts'

export function stringsSuite(): void {
  suite('data/strings')

  check('Text ohne Platzhalter kommt unveraendert', () => {
    assertEqual(t('game.title'), 'WAVEBREAKER')
  })

  check('Platzhalter werden ersetzt', () => {
    assertEqual(t('hud.wave', { wave: 12 }), 'Wave 12')
    assertEqual(t('hud.speed', { factor: 4 }), 'Speed x4')
  })

  check('fehlende Werte bleiben sichtbar stehen, statt zu verschwinden', () => {
    assertEqual(t('hud.wave', {}), 'Wave {wave}')
  })

  check('jeder Text ist englisch und nicht leer', () => {
    for (const [key, value] of Object.entries(STRINGS)) {
      assert(value.trim().length > 0, `leerer Text: ${key}`)
      assert(
        !/[äöüßÄÖÜ]/.test(value),
        `Spielsprache ist Englisch, "${key}" enthaelt deutsche Zeichen`,
      )
    }
  })

  check('hasString erkennt unbekannte Schluessel', () => {
    assertEqual(hasString('game.title'), true)
    assertEqual(hasString('gibt.es.nicht'), false)
  })
}

/**
 * Die Querschnittsregeln aus Abschnitt 9 des Implementierungsplans, als Pruefung statt
 * als Vorsatz. Sie gehoeren zur Abnahme **jeder** Etappe.
 *
 * Braucht das Dateisystem und laeuft deshalb nur im headless-Lauf (`npm run selftest`),
 * nicht im Browser. Kommentare werden vor der Suche entfernt - sonst schlaegt jede Regel
 * an, die irgendwo erklaert wird.
 */

import { readdirSync, readFileSync } from 'node:fs'
import { dirname, join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import type { TestResult } from '../core/assert.ts'

const SRC = resolve(dirname(fileURLToPath(import.meta.url)), '..')

type Rule = {
  name: string
  /** Ordner unterhalb von `src/`, die geprueft werden. */
  folders: string[]
  pattern: RegExp
  /** Pfade (relativ zu `src/`), an denen das Muster erlaubt ist. */
  allow: string[]
  hint: string
}

const RULES: Rule[] = [
  {
    name: 'sim/ und core/ fassen kein DOM und kein Canvas an',
    folders: ['core', 'sim'],
    pattern: /\b(document|getElementById|querySelector|HTMLCanvasElement|getContext)\b/,
    allow: [],
    hint: 'Die Offline-Simulation und die Selbsttests muessen ohne Browser laufen.',
  },
  {
    name: 'Zeit kommt nur aus core/loop.ts',
    folders: ['core', 'sim', 'app', 'data', 'render', 'ui'],
    pattern: /\b(Date\.now|performance\.now)\s*\(/,
    allow: ['core/loop.ts'],
    hint: 'Voraussetzung fuer x2/x4, Offline-Berechnung und reproduzierbare Tests.',
  },
  {
    name: 'Zufall kommt nur aus core/rng.ts',
    folders: ['core', 'sim', 'app', 'data', 'render', 'ui'],
    pattern: /\bMath\.random\s*\(/,
    allow: ['core/rng.ts'],
    hint: 'Ohne Seed ist ein Balancing-Fehler nicht nachstellbar.',
  },
  {
    name: 'Belohnungen entstehen nur in app/rewards.ts',
    folders: ['core', 'sim', 'app', 'data', 'render', 'ui'],
    pattern: /\.\s*(gold|xp|prestigePoints)\s*(\+=|-=|=[^=])/,
    allow: ['app/rewards.ts'],
    hint: 'Spaetere Werbe-Belohnungen haengen sich an grantReward (GDD 16 Abschnitt 2).',
  },
]

function listFiles(folder: string): string[] {
  const root = join(SRC, folder)
  const found: string[] = []
  let entries
  try {
    entries = readdirSync(root, { withFileTypes: true })
  } catch {
    return found // Ordner gibt es in dieser Etappe noch nicht
  }
  for (const entry of entries) {
    const full = join(root, entry.name)
    if (entry.isDirectory()) found.push(...listFiles(join(folder, entry.name)))
    else if (entry.name.endsWith('.ts')) found.push(full)
  }
  return found
}

/** Kommentare entfernen, damit erklaerender Text keine Regel ausloest. */
function stripComments(source: string): string {
  return source.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1')
}

export function runGuards(): TestResult[] {
  const results: TestResult[] = []

  for (const rule of RULES) {
    const offenders: string[] = []

    for (const folder of rule.folders) {
      for (const file of listFiles(folder)) {
        const relativePath = relative(SRC, file).replace(/\\/g, '/')
        if (rule.allow.includes(relativePath)) continue

        const lines = stripComments(readFileSync(file, 'utf8')).split('\n')
        lines.forEach((line, index) => {
          if (rule.pattern.test(line)) offenders.push(`${relativePath}:${index + 1}  ${line.trim()}`)
        })
      }
    }

    results.push({
      suite: 'querschnittsregeln',
      name: rule.name,
      ok: offenders.length === 0,
      ...(offenders.length > 0 ? { message: `${rule.hint}\n      ${offenders.join('\n      ')}` } : {}),
    })
  }

  return results
}

/*
 * Grundgeruest der Seite. Die eigentliche Gestaltung (GDD 13) entsteht ab E1 in
 * render/theme.ts fuer das Canvas und ab E3 hier fuer die Panels.
 */

:root {
  --bg: #060a14;
  --bg-panel: rgba(12, 20, 38, 0.82);
  --line: rgba(90, 150, 220, 0.28);
  --text: #cfe2ff;
  --text-dim: #7c93b8;
  --accent: #47d5ff;
  --ok: #57e2a5;
  --fail: #ff5f7e;
  --font: 'Segoe UI', system-ui, sans-serif;
  --mono: ui-monospace, 'Cascadia Mono', 'Consolas', monospace;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
}

#stage {
  position: fixed;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

#ui {
  position: fixed;
  inset: 0;
  pointer-events: none;
}

#ui > * {
  pointer-events: auto;
}

/* --- Entwickleranzeige aus E0. Wird in E9 vom echten HUD abgeloest. --- */

.devbar {
  position: absolute;
  top: 12px;
  left: 12px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--bg-panel);
  color: var(--text-dim);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.7;
  letter-spacing: 0.02em;
  backdrop-filter: blur(6px);
}

.devbar b {
  color: var(--accent);
  font-weight: 600;
}

.devbar .hint {
  color: rgba(124, 147, 184, 0.65);
}

/* --- Selbsttest-Bericht (?selftest) --- */

.report {
  position: absolute;
  inset: 0;
  overflow: auto;
  padding: 32px clamp(16px, 5vw, 64px) 64px;
  background: var(--bg);
  font-family: var(--mono);
  font-size: 13px;
  line-height: 1.6;
}

.report h1 {
  margin: 0 0 4px;
  font-size: 20px;
  letter-spacing: 0.12em;
  color: var(--text);
}

.report .summary {
  margin-bottom: 24px;
  font-size: 15px;
}

.report .summary.ok {
  color: var(--ok);
}

.report .summary.fail {
  color: var(--fail);
}

.report h2 {
  margin: 24px 0 6px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.report ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.report li {
  padding: 2px 0 2px 22px;
  text-indent: -22px;
}

.report li.ok::before {
  content: '+  ';
  color: var(--ok);
}

.report li.fail {
  color: var(--fail);
}

.report li.fail::before {
  content: 'x  ';
}

.report pre {
  margin: 2px 0 8px 22px;
  color: var(--fail);
  text-indent: 0;
  white-space: pre-wrap;
  opacity: 0.85;
}

/**
 * Einstieg: Zustand laden, Schleife starten, Bereiche verdrahten.
 *
 * In E0 gibt es noch keine Bereiche - die Buehne ist leer und zeigt nur, dass die
 * Schleife mit festen Schritten laeuft und der Zustand einen Neuladen ueberlebt.
 * Das Zeichnen zieht in E1 nach `render/`, die Anzeige in E9 ins echte HUD.
 */

import { createLoop, type SpeedFactor } from './core/loop.ts'
import { emit } from './core/events.ts'
import { formatDuration, formatNumber } from './core/format.ts'
import { SPEED_FACTORS, TICK_RATE } from './data/balance.ts'
import { t } from './data/strings.ts'
import { load, startAutosave } from './app/save.ts'
import { createInitialState, markDirty } from './app/state.ts'
import { runSelfTests, summarize } from './selftest/index.ts'

const stage = document.getElementById('stage') as HTMLCanvasElement | null
const ui = document.getElementById('ui')

if (!stage || !ui) throw new Error('Buehne oder Bedienflaeche fehlt in index.html')

if (new URLSearchParams(location.search).has('selftest')) {
  showSelfTestReport(stage, ui)
} else {
  startGame(stage, ui)
}

// ---------------------------------------------------------------------------
// Spiel
// ---------------------------------------------------------------------------

function startGame(canvas: HTMLCanvasElement, root: HTMLElement): void {
  const context = canvas.getContext('2d')
  if (!context) throw new Error('Canvas-Kontext nicht verfuegbar')

  const loaded = load()
  const state = loaded ?? createInitialState()
  emit('save.loaded', { fresh: loaded === null, version: 1 })

  const loop = createLoop({ tickRate: TICK_RATE })
  const autosave = startAutosave(state, loop)
  const devbar = createDevbar(root)

  let viewWidth = 0
  let viewHeight = 0

  const resize = (): void => {
    const ratio = Math.min(window.devicePixelRatio || 1, 2)
    viewWidth = canvas.clientWidth
    viewHeight = canvas.clientHeight
    canvas.width = Math.round(viewWidth * ratio)
    canvas.height = Math.round(viewHeight * ratio)
    context.setTransform(ratio, 0, 0, ratio, 0, 0)
  }
  resize()
  window.addEventListener('resize', resize)

  window.addEventListener('keydown', (event) => {
    const factor = Number(event.key)
    if ((SPEED_FACTORS as readonly number[]).includes(factor)) {
      loop.setSpeed(factor as SpeedFactor)
      emit('loop.speedChanged', { factor: factor as SpeedFactor })
    }
  })

  // Die Spielzeit ist bereits jetzt Teil des Spielstands - sie zaehlt ab E17 in die
  // Abwesenheitsberechnung hinein.
  let untracked = 0

  loop.start(
    (dt) => {
      untracked += dt
      if (untracked >= 1) {
        state.permanent.totalPlaySeconds += Math.floor(untracked)
        untracked -= Math.floor(untracked)
        markDirty(state)
      }
      autosave.tick()
    },
    () => {
      drawEmptyStage(context, viewWidth, viewHeight)
      devbar.update(
        `<b>${t('game.title')}</b>  ${loop.tickRate} Hz\n` +
          `Speed   <b>x${loop.getSpeed()}</b>\n` +
          `Ticks   ${formatNumber(loop.tickCount())}\n` +
          `Sim     ${formatDuration(loop.now())}\n` +
          `Bilder  ${loop.fps().toFixed(0)}/s\n` +
          `Gespielt ${formatDuration(state.permanent.totalPlaySeconds)}\n` +
          `<span class="hint">1 / 2 / 4 = Geschwindigkeit  ·  ?selftest</span>`,
      )
    },
  )
}

/**
 * Leere Buehne: dunkelblau mit einem dezenten Raster (GDD 13 Abschnitt 2 - der
 * Hintergrund soll nur auffallen, wenn man bewusst hinsieht).
 */
function drawEmptyStage(ctx: CanvasRenderingContext2D, width: number, height: number): void {
  ctx.fillStyle = '#060a14'
  ctx.fillRect(0, 0, width, height)

  const spacing = 64
  ctx.strokeStyle = 'rgba(70, 120, 190, 0.07)'
  ctx.lineWidth = 1
  ctx.beginPath()
  for (let x = ((width / 2) % spacing) - spacing; x < width; x += spacing) {
    ctx.moveTo(Math.round(x) + 0.5, 0)
    ctx.lineTo(Math.round(x) + 0.5, height)
  }
  for (let y = ((height / 2) % spacing) - spacing; y < height; y += spacing) {
    ctx.moveTo(0, Math.round(y) + 0.5)
    ctx.lineTo(width, Math.round(y) + 0.5)
  }
  ctx.stroke()
}

function createDevbar(root: HTMLElement): { update(html: string): void } {
  const element = document.createElement('pre')
  element.className = 'devbar'
  root.appendChild(element)

  let last = ''
  let lastUpdate = 0
  return {
    update(html) {
      // Nur viermal pro Sekunde neu setzen - die Anzeige darf die Messung nicht stoeren.
      lastUpdate += 1
      if (lastUpdate % 15 !== 0) return
      if (html === last) return
      last = html
      element.innerHTML = html
    },
  }
}

// ---------------------------------------------------------------------------
// Selbsttests
// ---------------------------------------------------------------------------

function showSelfTestReport(canvas: HTMLCanvasElement, root: HTMLElement): void {
  canvas.style.display = 'none'

  const summary = summarize(runSelfTests())
  const report = document.createElement('div')
  report.className = 'report'

  const parts: string[] = [
    `<h1>${t('game.title')} · Selbsttests</h1>`,
    `<div class="summary ${summary.ok ? 'ok' : 'fail'}">` +
      `${summary.passed}/${summary.total} bestanden` +
      (summary.failed > 0 ? ` · ${summary.failed} fehlgeschlagen` : '') +
      `</div>`,
  ]

  let currentSuite = ''
  for (const result of summary.results) {
    if (result.suite !== currentSuite) {
      if (currentSuite !== '') parts.push('</ul>')
      currentSuite = result.suite
      parts.push(`<h2>${escapeHtml(currentSuite)}</h2><ul>`)
    }
    parts.push(`<li class="${result.ok ? 'ok' : 'fail'}">${escapeHtml(result.name)}</li>`)
    if (!result.ok && result.message) parts.push(`<pre>${escapeHtml(result.message)}</pre>`)
  }
  if (currentSuite !== '') parts.push('</ul>')

  report.innerHTML = parts.join('')
  root.appendChild(report)

  document.title = `${summary.ok ? 'OK' : 'FEHLER'} · Selbsttests`
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[char] ?? char)
}

