/**
 * Vektorrechnung. Reine Mathematik ohne Spielwissen.
 *
 * Uebernommen aus Prototyp 01 - dort ueber 34.708 Platzierungen erprobt und im Spiel
 * unveraendert gueltig.
 */

export type Vec2 = { x: number; y: number }

export const vec = (x: number, y: number): Vec2 => ({ x, y })

export const add = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x + b.x, y: a.y + b.y })
export const sub = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x - b.x, y: a.y - b.y })
export const scale = (a: Vec2, factor: number): Vec2 => ({ x: a.x * factor, y: a.y * factor })
export const mid = (a: Vec2, b: Vec2): Vec2 => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 })

export const len = (a: Vec2): number => Math.hypot(a.x, a.y)
export const dist = (a: Vec2, b: Vec2): number => Math.hypot(a.x - b.x, a.y - b.y)
export const dot = (a: Vec2, b: Vec2): number => a.x * b.x + a.y * b.y

export function normalize(a: Vec2): Vec2 {
  const length = len(a)
  return length < 1e-12 ? { x: 0, y: 0 } : { x: a.x / length, y: a.y / length }
}

/** Senkrechte nach rechts. Bei positiv orientierten Polygonen zeigt sie nach aussen. */
export const perp = (a: Vec2): Vec2 => ({ x: a.y, y: -a.x })

export const samePoint = (a: Vec2, b: Vec2, epsilon: number): boolean => dist(a, b) < epsilon

/**
 * Rahmenratenunabhaengige Annaeherung. `rate` ist die Geschwindigkeit der Annaeherung;
 * das Ergebnis haengt nur von der verstrichenen Zeit ab, nicht von der Anzahl Schritte.
 */
export function approach(current: number, target: number, rate: number, dt: number): number {
  const k = 1 - Math.exp(-rate * dt)
  return current + (target - current) * k
}

/**
 * Geometrie des Ansteck-Systems. Kennt weder DOM noch Canvas.
 *
 * Uebernommen aus Prototyp 01 (GDD 16 Abschnitt 7). E1 braucht nur die Erzeugung und
 * Vermessung regelmaessiger Vielecke; das Andocken, die Ueberlappungspruefung und die
 * Kantennachbarschaft kommen in E2 dazu.
 *
 * Konvention: Alle Module sind regelmaessige n-Ecke mit **einheitlicher Seitenlaenge**
 * und positiv orientierten Ecken (Flaeche > 0). Kante i verlaeuft von v[i] nach
 * v[(i+1) % n]; die Aussennormale einer solchen Kante ist (d.y, -d.x).
 */

import { add, scale, sub, type Vec2 } from './vec.ts'

/**
 * Einheitliche Seitenlaenge aller Module in Welteinheiten.
 *
 * Keine Balance-Groesse, sondern die Systemkonstante, auf der das ganze Ansteck-System
 * beruht: Weil alle Vielecke dieselbe Seitenlaenge haben, passt jede Form an jede Kante.
 * Reichweiten und Geschwindigkeiten in `data/balance.ts` sind Vielfache hiervon.
 */
export const MODULE_SIDE = 56

/** Toleranz fuer Kanten- und Punktvergleiche. Die Gleitkomma-Drift liegt weit darunter. */
export const EPS = MODULE_SIDE * 1e-3

export type Edge = { a: Vec2; b: Vec2 }
export type Bounds = { minX: number; minY: number; maxX: number; maxY: number }

/** Abstand Mittelpunkt -> Kantenmitte. */
export const apothem = (sides: number): number => MODULE_SIDE / (2 * Math.tan(Math.PI / sides))

/** Abstand Mittelpunkt -> Ecke. */
export const circumradius = (sides: number): number => MODULE_SIDE / (2 * Math.sin(Math.PI / sides))

/** Ecken eines n-Ecks. Die erste Ecke liegt bei `rotation`, die weiteren im Winkel steigend. */
export function polygonAt(sides: number, center: Vec2, rotation: number): Vec2[] {
  const r = circumradius(sides)
  const points: Vec2[] = []
  for (let k = 0; k < sides; k++) {
    const angle = rotation + (k * 2 * Math.PI) / sides
    points.push({ x: center.x + r * Math.cos(angle), y: center.y + r * Math.sin(angle) })
  }
  return points
}

export function edgesOf(poly: readonly Vec2[]): Edge[] {
  return poly.map((a, i) => ({ a, b: poly[(i + 1) % poly.length] as Vec2 }))
}

export function centroid(poly: readonly Vec2[]): Vec2 {
  let x = 0
  let y = 0
  for (const point of poly) {
    x += point.x
    y += point.y
  }
  return { x: x / poly.length, y: y / poly.length }
}

/** Vorzeichenbehaftete Flaeche. Positiv bei korrekter Orientierung. */
export function signedArea(poly: readonly Vec2[]): number {
  let sum = 0
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i] as Vec2
    const b = poly[(i + 1) % poly.length] as Vec2
    sum += a.x * b.y - b.x * a.y
  }
  return sum / 2
}

/** Umschliessendes Rechteck mehrerer Vielecke. Grundlage des Auto-Zooms. */
export function boundsOf(polys: readonly (readonly Vec2[])[]): Bounds | null {
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity

  for (const poly of polys) {
    for (const point of poly) {
      if (point.x < minX) minX = point.x
      if (point.y < minY) minY = point.y
      if (point.x > maxX) maxX = point.x
      if (point.y > maxY) maxY = point.y
    }
  }

  return minX === Infinity ? null : { minX, minY, maxX, maxY }
}

/** Vieleck zum Mittelpunkt hin schrumpfen. Fuer Innenrahmen und die Ueberlappungspruefung. */
export function inset(poly: readonly Vec2[], factor: number): Vec2[] {
  const c = centroid(poly)
  return poly.map((point) => add(c, scale(sub(point, c), factor)))
}

/**
 * Hauptturm-Kerne (GDD 04).
 *
 * In E1 stehen nur Identitaet und Form - genug, damit der Hauptturm sichtbar wird. Die
 * Kampfwerte kommen in E6 dazu, die weiteren Kerne mit dem Prestige-Baum in E13.
 *
 * Der Kern ist laut GDD 04 Abschnitt 1 immer ein **Hexagon** im Zentrum, nicht entfernbar,
 * und liefert damit die ersten sechs Bauplaetze.
 */

import type { Emblem, FootprintSides } from './types.ts'

export type CoreDef = {
  id: string
  /** Englisch - Spielsprache laut GDD 16 Abschnitt 1. */
  name: string
  sides: FootprintSides
  emblem: Emblem
  /** Leitfarbe fuer Emblem und Leuchten. */
  accent: string
}

export const CORES: readonly CoreDef[] = [
  {
    id: 'sentinel',
    name: 'Sentinel Core',
    sides: 6,
    emblem: 'core',
    accent: '#7cf3ff',
  },
]

export function coreById(id: string): CoreDef {
  const found = CORES.find((core) => core.id === id)
  if (!found) throw new Error(`Unbekannter Kern: ${id}`)
  return found
}

/**
 * Farben, Linienstaerken und Leuchtstaerken an einem Ort (GDD 13 Abschnitt 2 und 7).
 *
 * Der praegende Look entsteht aus den **hellen Fugen** zwischen den Modulen - also aus den
 * geteilten Kanten, nicht aus den Fuellflaechen. Aussenkanten bleiben dunkel. So liest sich
 * eine gewachsene Station als eine zusammenhaengende Maschine statt als Haufen Vielecke
 * (Befund aus Prototyp 01).
 */

import type { Rarity } from '../data/types.ts'

export const THEME = {
  /** Hintergrund: dunkelblau, minimalistisch. Faellt nur auf, wenn man hinsieht. */
  bgTop: '#0d1531',
  bgBottom: '#05080f',
  grid: 'rgba(120, 150, 255, 0.045)',
  gridSpacing: 64,

  /** Fuellflaeche des Hauptturms. */
  fillCore: '#1d2a53',

  /** Geteilte Kante zweier Module - hell und leicht leuchtend. */
  edgeShared: '#93a3e0',
  edgeSharedGlow: 'rgba(147, 163, 224, 0.7)',
  edgeSharedWidth: 2,
  edgeSharedBlur: 6,

  /** Freie Aussenkante - dunkel und duenn. */
  edgeFree: '#2b3767',
  edgeFreeWidth: 1.2,

  /** Innenrahmen: leicht nach innen versetzt, damit die Fugen unberuehrt bleiben. */
  frameInset: 0.86,
  frameWidthCore: 2.2,
  frameWidthModule: 1.4,

  /** Emblemgroesse als Anteil des Umkreisradius. */
  emblemRadiusFactor: 0.32,
} as const

/** GDD 13 Abschnitt 7: die Neon-Umrandung zeigt die Seltenheit. */
export const RARITY_COLOR: Record<Rarity, string> = {
  common: '#9aa4bf',
  rare: '#3ddc84',
  epic: '#4aa3ff',
  legendary: '#ffc34a',
  mythic: '#ff3b6b',
}

/** Leuchtstaerke: von "leichter Rand" bis "pulsierende Neonenergie". */
export const RARITY_GLOW: Record<Rarity, number> = {
  common: 0,
  rare: 5,
  epic: 9,
  legendary: 14,
  mythic: 18,
}

/** Der Hauptturm hat keine Raritaet, atmet aber dezent (GDD 04 Abschnitt 2, GDD 13 Abschnitt 10). */
export const CORE_GLOW_BASE = 12
export const CORE_GLOW_PULSE = 6

/**
 * Auto-Zoom: Die Station bleibt immer vollstaendig im Bild (GDD 13 Abschnitt 4). Der
 * Spieler soll seine Basis jederzeit als Ganzes sehen - das ist der Kern der Spielfantasie.
 *
 * **Reichweiten gehen nicht in den Bildausschnitt ein.** Am Prototyp gemessen: Nimmt die
 * Kamera die volle Reichweite eines Scharfschuetzen auf, faellt der Zoom von 1,19 auf 0,43
 * und die Embleme schrumpfen auf 11 px - die Station ist dann nicht mehr lesbar. Der
 * Parameter `extra` bleibt fuer einen spaeteren **Bruchteil** der Reichweite erhalten,
 * bekommt aber nie die volle (GDD 13 Abschnitt 4, korrigiert nach Prototyp 01 / F4).
 *
 * Der Zoom springt nie, sondern naehert sich exponentiell an - rahmenratenunabhaengig,
 * damit 144 Hz und 60 Hz dieselbe Bewegung zeigen.
 */

import { approach, type Vec2 } from '../core/vec.ts'
import { boundsOf } from '../core/geometry.ts'

export type Camera = {
  center: Vec2
  zoom: number
  targetCenter: Vec2
  targetZoom: number
  /** true, sobald der Spieler selbst gezoomt hat - dann kein Auto-Fit mehr bis `resetAuto`. */
  manual: boolean
}

export const MIN_ZOOM = 0.25
export const MAX_ZOOM = 2.2
/** Fester Rand um die Station, in Welteinheiten. */
export const FIT_MARGIN = 90
/** Geschwindigkeit der Annaeherung. Groesser = strammer. */
export const FOLLOW_RATE = 8

export function createCamera(): Camera {
  return {
    center: { x: 0, y: 0 },
    zoom: 1,
    targetCenter: { x: 0, y: 0 },
    targetZoom: 1,
    manual: false,
  }
}

/**
 * Zielausschnitt setzen, sodass alle uebergebenen Vielecke samt Rand hineinpassen.
 * Bewegt die Kamera nicht selbst - das macht `step`.
 */
export function fitTo(
  camera: Camera,
  polys: readonly (readonly Vec2[])[],
  viewWidth: number,
  viewHeight: number,
  extra = 0,
  margin = FIT_MARGIN,
): void {
  if (camera.manual || viewWidth < 1 || viewHeight < 1) return

  const bounds = boundsOf(polys)
  if (!bounds) return

  const padding = (margin + extra) * 2
  const width = bounds.maxX - bounds.minX + padding
  const height = bounds.maxY - bounds.minY + padding

  camera.targetCenter = {
    x: (bounds.minX + bounds.maxX) / 2,
    y: (bounds.minY + bounds.maxY) / 2,
  }
  camera.targetZoom = clampZoom(Math.min(viewWidth / width, viewHeight / height))
}

/**
 * `dt` ist **echte** Zeit, nicht Simulationszeit: Die Kamera bewegt sich bei x4 nicht
 * viermal so schnell, sondern gleich weich.
 */
export function step(camera: Camera, dt: number): void {
  camera.center.x = approach(camera.center.x, camera.targetCenter.x, FOLLOW_RATE, dt)
  camera.center.y = approach(camera.center.y, camera.targetCenter.y, FOLLOW_RATE, dt)
  camera.zoom = approach(camera.zoom, camera.targetZoom, FOLLOW_RATE, dt)
}

/** Kamera ohne Bewegung auf ihr Ziel setzen. Fuer den ersten Bildaufbau nach dem Laden. */
export function snapToTarget(camera: Camera): void {
  camera.center = { ...camera.targetCenter }
  camera.zoom = camera.targetZoom
}

export function zoomBy(camera: Camera, factor: number): void {
  camera.manual = true
  camera.targetZoom = clampZoom(camera.targetZoom * factor)
}

/** Zurueck zum automatischen Ausschnitt. */
export function resetAuto(camera: Camera): void {
  camera.manual = false
}

export function clampZoom(zoom: number): number {
  return Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, zoom))
}

export const worldToScreen = (
  camera: Camera,
  point: Vec2,
  viewWidth: number,
  viewHeight: number,
): Vec2 => ({
  x: (point.x - camera.center.x) * camera.zoom + viewWidth / 2,
  y: (point.y - camera.center.y) * camera.zoom + viewHeight / 2,
})

export const screenToWorld = (
  camera: Camera,
  point: Vec2,
  viewWidth: number,
  viewHeight: number,
): Vec2 => ({
  x: (point.x - viewWidth / 2) / camera.zoom + camera.center.x,
  y: (point.y - viewHeight / 2) / camera.zoom + camera.center.y,
})

/**
 * Die Station als Menge platzierter Module.
 *
 * In E1 besteht sie nur aus dem Hauptturm: Er steht immer im Zentrum, ist nicht
 * entfernbar und ist ein Hexagon mit sechs Anschlusskanten (GDD 04 Abschnitt 1). Die
 * Bauregeln - Andocken, Ueberlappung, Nachbarschaft, Zusammenhang - kommen in E2 dazu.
 *
 * Kein DOM, kein Canvas. Das Zeichnen liest diese Beschreibung nur aus.
 */

import { polygonAt } from '../core/geometry.ts'
import type { Vec2 } from '../core/vec.ts'
import { coreById } from '../data/cores.ts'
import type { FootprintSides, Rarity } from '../data/types.ts'

export type PlacedModule = {
  uid: string
  kind: 'core' | 'tower'
  /** Verweist je nach `kind` auf einen Eintrag in `data/cores.ts` oder `data/towers.ts`. */
  defId: string
  /** Haupttuerme haben keine Raritaet (GDD 04 Abschnitt 2). */
  rarity: Rarity | null
  sides: FootprintSides
  center: Vec2
  rotation: number
  poly: Vec2[]
  /**
   * Indizes der Kanten, die mit einem Nachbarmodul geteilt werden - die "Fugen".
   * In E1 immer leer, weil es nur ein Modul gibt; E2 fuellt sie aus der Nachbarschaft.
   */
  sharedEdges: readonly number[]
}

/** Der Hauptturm hat eine feste Kennung - es gibt genau einen je Run. */
export const CORE_UID = 'core'

/** Er steht immer im Zentrum der Welt. */
export const CORE_CENTER: Vec2 = { x: 0, y: 0 }
export const CORE_ROTATION = 0

export function coreModule(coreId: string): PlacedModule {
  const def = coreById(coreId)
  return {
    uid: CORE_UID,
    kind: 'core',
    defId: def.id,
    rarity: null,
    sides: def.sides,
    center: CORE_CENTER,
    rotation: CORE_ROTATION,
    poly: polygonAt(def.sides, CORE_CENTER, CORE_ROTATION),
    sharedEdges: [],
  }
}

/**
 * Alle Module der Station, Hauptturm zuerst. Ab E2 kommen die angebauten Module dazu.
 */
export function stationModules(coreId: string): PlacedModule[] {
  return [coreModule(coreId)]
}

/**
 * Module zeichnen: Flaechen, Fugen, Raritaetsrahmen, Embleme.
 *
 * Reihenfolge ist Absicht - erst alle Flaechen, dann alle Kanten. Wuerde jedes Modul
 * seine eigenen Kanten direkt nach seiner Flaeche zeichnen, uebermalte das naechste Modul
 * die Fuge des vorherigen und der praegende Look ginge verloren.
 */

import { circumradius, edgesOf, inset } from '../core/geometry.ts'
import type { Vec2 } from '../core/vec.ts'
import { coreById } from '../data/cores.ts'
import type { Emblem } from '../data/types.ts'
import type { PlacedModule } from '../sim/station.ts'
import { worldToScreen, type Camera } from './camera.ts'
import { drawEmblem } from './emblems.ts'
import { CORE_GLOW_BASE, CORE_GLOW_PULSE, RARITY_COLOR, RARITY_GLOW, THEME } from './theme.ts'

export type ModuleLook = { emblem: Emblem; accent: string }

/** Aussehen aus den Daten holen. Ab E3 kommen hier auch Tuerme aus `data/towers.ts` her. */
function lookOf(module: PlacedModule): ModuleLook {
  const def = coreById(module.defId)
  return { emblem: def.emblem, accent: def.accent }
}

export function drawModules(
  ctx: CanvasRenderingContext2D,
  modules: readonly PlacedModule[],
  camera: Camera,
  width: number,
  height: number,
  time: number,
): void {
  for (const module of modules) drawFill(ctx, module, camera, width, height, time)
  for (const module of modules) drawEdges(ctx, module, camera, width, height)
  for (const module of modules) drawSymbol(ctx, module, camera, width, height)
}

function toScreen(
  camera: Camera,
  poly: readonly Vec2[],
  width: number,
  height: number,
): Vec2[] {
  return poly.map((point) => worldToScreen(camera, point, width, height))
}

function trace(ctx: CanvasRenderingContext2D, points: readonly Vec2[]): void {
  ctx.beginPath()
  points.forEach((point, index) => {
    if (index === 0) ctx.moveTo(point.x, point.y)
    else ctx.lineTo(point.x, point.y)
  })
  ctx.closePath()
}

function drawFill(
  ctx: CanvasRenderingContext2D,
  module: PlacedModule,
  camera: Camera,
  width: number,
  height: number,
  time: number,
): void {
  const points = toScreen(camera, module.poly, width, height)

  trace(ctx, points)
  ctx.fillStyle = THEME.fillCore
  ctx.fill()

  // Innenrahmen: nach innen versetzt, damit er die Fugen nicht beruehrt. Der Hauptturm
  // hat keine Raritaet und atmet stattdessen dezent (GDD 13 Abschnitt 10).
  const pulse = 0.5 + 0.5 * Math.sin(time * 3)
  const isCore = module.kind === 'core'
  const color = module.rarity ? RARITY_COLOR[module.rarity] : lookOf(module).accent
  const glow = isCore
    ? CORE_GLOW_BASE + CORE_GLOW_PULSE * pulse
    : module.rarity
      ? RARITY_GLOW[module.rarity]
      : 0

  ctx.save()
  trace(ctx, inset(points, THEME.frameInset))
  ctx.strokeStyle = color
  ctx.lineWidth = isCore ? THEME.frameWidthCore : THEME.frameWidthModule
  ctx.shadowColor = color
  ctx.shadowBlur = glow
  ctx.stroke()
  ctx.restore()
}

/** Geteilte Kanten hell und leuchtend (Fugen), freie Kanten dunkel (Aussenkontur). */
function drawEdges(
  ctx: CanvasRenderingContext2D,
  module: PlacedModule,
  camera: Camera,
  width: number,
  height: number,
): void {
  const shared = new Set(module.sharedEdges)

  ctx.save()
  edgesOf(module.poly).forEach((edge, index) => {
    const isShared = shared.has(index)
    const a = worldToScreen(camera, edge.a, width, height)
    const b = worldToScreen(camera, edge.b, width, height)

    ctx.beginPath()
    ctx.moveTo(a.x, a.y)
    ctx.lineTo(b.x, b.y)
    ctx.strokeStyle = isShared ? THEME.edgeShared : THEME.edgeFree
    ctx.lineWidth = isShared ? THEME.edgeSharedWidth : THEME.edgeFreeWidth
    ctx.shadowColor = isShared ? THEME.edgeSharedGlow : 'transparent'
    ctx.shadowBlur = isShared ? THEME.edgeSharedBlur : 0
    ctx.stroke()
  })
  ctx.restore()
}

function drawSymbol(
  ctx: CanvasRenderingContext2D,
  module: PlacedModule,
  camera: Camera,
  width: number,
  height: number,
): void {
  const look = lookOf(module)
  const center = worldToScreen(camera, module.center, width, height)
  const radius = circumradius(module.sides) * camera.zoom * THEME.emblemRadiusFactor
  drawEmblem(ctx, look.emblem, center, radius, look.accent)
}

/**
 * Zeichenreihenfolge - eine Stelle.
 *
 * Wer eine neue Ebene hinzufuegt (Gegner in E4, Geschosse in E5, Bauhilfen in E3),
 * traegt sie hier ein und nirgends sonst. Damit bleibt die Reihenfolge nachlesbar,
 * statt sich aus Aufrufreihenfolgen quer durch die Dateien zu ergeben.
 */

import type { GameState } from '../app/state.ts'
import { stationModules } from '../sim/station.ts'
import { fitTo, type Camera } from './camera.ts'
import { drawModules } from './station.ts'
import { THEME } from './theme.ts'

export function render(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  camera: Camera,
  width: number,
  height: number,
  time: number,
): void {
  const modules = stationModules(state.run.coreId)

  // Der Ausschnitt richtet sich nach der Station plus festem Rand - Reichweiten gehen
  // bewusst nicht ein (GDD 13 Abschnitt 4).
  fitTo(
    camera,
    modules.map((module) => module.poly),
    width,
    height,
  )

  drawBackground(ctx, width, height)
  drawModules(ctx, modules, camera, width, height, time)
}

/** Dunkelblau mit dezentem Raster. Soll nur auffallen, wenn man hinsieht (GDD 13 Abschnitt 2). */
function drawBackground(ctx: CanvasRenderingContext2D, width: number, height: number): void {
  const gradient = ctx.createLinearGradient(0, 0, 0, height)
  gradient.addColorStop(0, THEME.bgTop)
  gradient.addColorStop(1, THEME.bgBottom)
  ctx.fillStyle = gradient
  ctx.fillRect(0, 0, width, height)

  const spacing = THEME.gridSpacing
  ctx.strokeStyle = THEME.grid
  ctx.lineWidth = 1
  ctx.beginPath()
  for (let x = 0; x < width; x += spacing) {
    ctx.moveTo(Math.round(x) + 0.5, 0)
    ctx.lineTo(Math.round(x) + 0.5, height)
  }
  for (let y = 0; y < height; y += spacing) {
    ctx.moveTo(0, Math.round(y) + 0.5)
    ctx.lineTo(width, Math.round(y) + 0.5)
  }
  ctx.stroke()
}

