/**
 * Vektoren und regelmaessige Vielecke. Die Grundlage, auf der ab E2 das gesamte
 * Ansteck-System steht - Fehler hier sind spaeter kaum zu finden.
 */

import { assert, assertClose, assertEqual, check, suite } from '../../core/assert.ts'
import {
  add,
  approach,
  dist,
  len,
  normalize,
  perp,
  samePoint,
  scale,
  sub,
  type Vec2,
} from '../../core/vec.ts'
import {
  apothem,
  boundsOf,
  centroid,
  circumradius,
  edgesOf,
  EPS,
  inset,
  MODULE_SIDE,
  polygonAt,
  signedArea,
} from '../../core/geometry.ts'

const ORIGIN: Vec2 = { x: 0, y: 0 }
const SIDES = [3, 4, 5, 6] as const

export function geometrySuite(): void {
  suite('core/vec')

  check('Grundrechnung', () => {
    assertClose(add({ x: 1, y: 2 }, { x: 3, y: 4 }).x, 4)
    assertClose(sub({ x: 3, y: 4 }, { x: 1, y: 2 }).y, 2)
    assertClose(scale({ x: 2, y: 3 }, 2).y, 6)
    assertClose(len({ x: 3, y: 4 }), 5)
    assertClose(dist({ x: 0, y: 0 }, { x: 3, y: 4 }), 5)
  })

  check('normalize liefert Laenge 1', () => {
    assertClose(len(normalize({ x: 7, y: -3 })), 1, 1e-12)
  })

  check('normalize des Nullvektors bleibt der Nullvektor', () => {
    assertEqual(len(normalize({ x: 0, y: 0 })), 0)
  })

  check('perp steht senkrecht und behaelt die Laenge', () => {
    const v = { x: 3, y: 4 }
    const p = perp(v)
    assertClose(v.x * p.x + v.y * p.y, 0, 1e-12)
    assertClose(len(p), len(v), 1e-12)
  })

  check('samePoint arbeitet mit Toleranz', () => {
    assertEqual(samePoint({ x: 0, y: 0 }, { x: EPS / 2, y: 0 }, EPS), true)
    assertEqual(samePoint({ x: 0, y: 0 }, { x: EPS * 2, y: 0 }, EPS), false)
  })

  check('approach naehert sich an, ohne zu ueberschiessen', () => {
    let value = 0
    for (let i = 0; i < 200; i++) {
      const next = approach(value, 100, 8, 1 / 60)
      assert(next >= value, 'darf nicht zurueckspringen')
      assert(next <= 100, `darf nicht ueberschiessen: ${next}`)
      value = next
    }
    assertClose(value, 100, 0.01)
  })

  check('approach ist rahmenratenunabhaengig', () => {
    // Dieselbe verstrichene Zeit muss dasselbe Ergebnis liefern, egal in wie vielen
    // Schritten sie vergeht. Sonst laeuft die Kamera bei 144 Hz anders als bei 60 Hz.
    let slow = 0
    for (let i = 0; i < 60; i++) slow = approach(slow, 100, 8, 1 / 60)

    let fast = 0
    for (let i = 0; i < 144; i++) fast = approach(fast, 100, 8, 1 / 144)

    assertClose(slow, fast, 0.01)
  })

  suite('core/geometry')

  check('jedes Vieleck hat die richtige Eckenzahl', () => {
    for (const sides of SIDES) {
      assertEqual(polygonAt(sides, ORIGIN, 0).length, sides)
    }
  })

  check('alle Seiten sind gleich lang - und zwar MODULE_SIDE', () => {
    for (const sides of SIDES) {
      for (const edge of edgesOf(polygonAt(sides, ORIGIN, 0))) {
        assertClose(dist(edge.a, edge.b), MODULE_SIDE, 1e-9, `${sides}-Eck`)
      }
    }
  })

  check('Inkreis- und Umkreisradius passen zur Seitenlaenge', () => {
    for (const sides of SIDES) {
      const poly = polygonAt(sides, ORIGIN, 0)
      for (const point of poly) {
        assertClose(dist(ORIGIN, point), circumradius(sides), 1e-9, `Umkreis ${sides}-Eck`)
      }
      for (const edge of edgesOf(poly)) {
        const middle = { x: (edge.a.x + edge.b.x) / 2, y: (edge.a.y + edge.b.y) / 2 }
        assertClose(dist(ORIGIN, middle), apothem(sides), 1e-9, `Inkreis ${sides}-Eck`)
      }
    }
  })

  check('der Umkreis ist immer groesser als der Inkreis', () => {
    for (const sides of SIDES) {
      assert(circumradius(sides) > apothem(sides), `${sides}-Eck`)
    }
  })

  check('mehr Kanten bedeutet groessere Flaeche bei gleicher Seitenlaenge', () => {
    let previous = 0
    for (const sides of SIDES) {
      const area = signedArea(polygonAt(sides, ORIGIN, 0))
      assert(area > previous, `${sides}-Eck muss groesser sein als das vorherige`)
      previous = area
    }
  })

  check('Vielecke sind positiv orientiert', () => {
    for (const sides of SIDES) {
      // Die Orientierung ist die Voraussetzung dafuer, dass die Aussennormale einer
      // Kante nach aussen zeigt - daran haengt in E2 das gesamte Andocken.
      assert(signedArea(polygonAt(sides, ORIGIN, 0)) > 0, `${sides}-Eck`)
    }
  })

  check('Drehung aendert weder Flaeche noch Seitenlaengen', () => {
    for (const sides of SIDES) {
      const plain = signedArea(polygonAt(sides, ORIGIN, 0))
      const turned = signedArea(polygonAt(sides, ORIGIN, 0.7))
      assertClose(turned, plain, 1e-9, `${sides}-Eck`)
    }
  })

  check('Verschiebung wirkt auf den Schwerpunkt', () => {
    const poly = polygonAt(5, { x: 120, y: -40 }, 0.3)
    const c = centroid(poly)
    assertClose(c.x, 120, 1e-9)
    assertClose(c.y, -40, 1e-9)
  })

  check('edgesOf schliesst den Ring', () => {
    const poly = polygonAt(4, ORIGIN, 0)
    const edges = edgesOf(poly)
    assertEqual(edges.length, 4)
    assertEqual(edges[3]?.b, poly[0], 'letzte Kante endet an der ersten Ecke')
  })

  check('boundsOf umschliesst alle Vielecke', () => {
    const bounds = boundsOf([
      polygonAt(6, ORIGIN, 0),
      polygonAt(4, { x: 500, y: 0 }, 0),
    ])
    assert(bounds !== null, 'Bounds muessen existieren')
    assert(bounds.minX < -circumradius(6) + 1e-6, 'linke Kante')
    assert(bounds.maxX > 500, 'rechte Kante')
  })

  check('boundsOf ohne Vielecke liefert null', () => {
    assertEqual(boundsOf([]), null)
  })

  check('inset schrumpft zum Mittelpunkt, ohne ihn zu verschieben', () => {
    const poly = polygonAt(6, { x: 10, y: 20 }, 0)
    const smaller = inset(poly, 0.5)
    const c = centroid(smaller)
    assertClose(c.x, 10, 1e-9)
    assertClose(c.y, 20, 1e-9)
    assertClose(signedArea(smaller), signedArea(poly) * 0.25, 1e-6, 'Flaeche skaliert quadratisch')
  })
}

/**
 * Beweis aus E1: `fitTo` mit vorgegebenen Vielecken liefert die erwarteten Zoomwerte,
 * und die Kamera naehert sich weich an, statt zu springen.
 *
 * Zusaetzlich haelt dieser Test die korrigierte Regel aus GDD 13 Abschnitt 4 fest:
 * Reichweiten gehen **nicht** in den Bildausschnitt ein. Der Test rechnet vor, warum -
 * mit den am Prototyp gemessenen Zahlen (F4).
 */

import { assert, assertClose, assertEqual, check, suite } from '../../core/assert.ts'
import { circumradius, polygonAt } from '../../core/geometry.ts'
import { dist, type Vec2 } from '../../core/vec.ts'
import {
  createCamera,
  fitTo,
  FIT_MARGIN,
  MAX_ZOOM,
  MIN_ZOOM,
  resetAuto,
  screenToWorld,
  snapToTarget,
  step,
  worldToScreen,
  zoomBy,
} from '../../render/camera.ts'

const VIEW_W = 750
const VIEW_H = 680
const ORIGIN: Vec2 = { x: 0, y: 0 }

/** Zwei Hexagone nebeneinander - gross genug, dass der Zoom nicht an die Grenzen stoesst. */
function wideStation(): Vec2[][] {
  return [polygonAt(6, { x: -300, y: 0 }, 0), polygonAt(6, { x: 300, y: 0 }, 0)]
}

export function cameraSuite(): void {
  suite('render/camera')

  check('der Zoom fuellt die Ansicht in der engeren Richtung genau aus', () => {
    const camera = createCamera()
    fitTo(camera, wideStation(), VIEW_W, VIEW_H)

    // Breite: 2 x 300 Versatz + 2 x Umkreisradius + 2 x Rand
    const spanX = 600 + 2 * circumradius(6)
    const expected = VIEW_W / (spanX + 2 * FIT_MARGIN)
    assertClose(camera.targetZoom, expected, 1e-9)
  })

  check('der Ausschnitt wird auf die Station zentriert', () => {
    const camera = createCamera()
    fitTo(camera, [polygonAt(6, { x: 200, y: -80 }, 0)], VIEW_W, VIEW_H)
    assertClose(camera.targetCenter.x, 200, 1e-9)
    assertClose(camera.targetCenter.y, -80, 1e-9)
  })

  check('eine groessere Station bekommt einen kleineren Zoom', () => {
    const small = createCamera()
    const large = createCamera()
    fitTo(small, [polygonAt(6, ORIGIN, 0)], VIEW_W, VIEW_H)
    fitTo(large, wideStation(), VIEW_W, VIEW_H)
    assert(large.targetZoom < small.targetZoom, 'die groessere Station muss weiter herauszoomen')
  })

  check('der Zoom bleibt zwischen den Grenzen', () => {
    const near = createCamera()
    fitTo(near, [polygonAt(6, ORIGIN, 0)], VIEW_W, VIEW_H)
    assertEqual(near.targetZoom, MAX_ZOOM, 'eine winzige Station darf nicht beliebig gross werden')

    const far = createCamera()
    fitTo(far, [polygonAt(6, { x: -5000, y: 0 }, 0), polygonAt(6, { x: 5000, y: 0 }, 0)], VIEW_W, VIEW_H)
    assertEqual(far.targetZoom, MIN_ZOOM, 'eine riesige Station darf nicht beliebig klein werden')
  })

  check('ohne Angabe geht kein Reichweiten-Zuschlag ein (GDD 13 Abschnitt 4)', () => {
    const ohne = createCamera()
    const mitNull = createCamera()
    fitTo(ohne, wideStation(), VIEW_W, VIEW_H)
    fitTo(mitNull, wideStation(), VIEW_W, VIEW_H, 0)
    assertEqual(ohne.targetZoom, mitNull.targetZoom)
  })

  check('warum Reichweiten draussen bleiben: der Zoom haelbte sich sonst', () => {
    // Ein Marksman erreicht bei Epic 432 Einheiten (gemessen in Prototyp 01, F4).
    const normal = createCamera()
    const mitReichweite = createCamera()
    fitTo(normal, wideStation(), VIEW_W, VIEW_H)
    fitTo(mitReichweite, wideStation(), VIEW_W, VIEW_H, 432)

    assert(
      mitReichweite.targetZoom < normal.targetZoom * 0.55,
      `die Station wuerde auf unter die Haelfte schrumpfen: ${mitReichweite.targetZoom} statt ${normal.targetZoom}`,
    )
  })

  check('die Kamera naehert sich an, statt zu springen', () => {
    const camera = createCamera()
    fitTo(camera, wideStation(), VIEW_W, VIEW_H)
    const distance = Math.abs(camera.targetZoom - camera.zoom)

    step(camera, 1 / 60)
    const remaining = Math.abs(camera.targetZoom - camera.zoom)

    assert(remaining < distance, 'sie muss sich bewegen')
    assert(remaining > distance * 0.5, 'ein einzelner Schritt darf kein Sprung sein')
  })

  check('die Kamera erreicht ihr Ziel und schiesst nicht darueber hinaus', () => {
    const camera = createCamera()
    camera.targetCenter = { x: 400, y: -250 }
    camera.targetZoom = 0.6

    let previous = Infinity
    for (let i = 0; i < 600; i++) {
      step(camera, 1 / 60)
      const remaining = dist(camera.center, camera.targetCenter)
      assert(remaining <= previous + 1e-9, 'darf sich nie wieder entfernen')
      previous = remaining
    }

    assertClose(camera.center.x, 400, 0.01)
    assertClose(camera.center.y, -250, 0.01)
    assertClose(camera.zoom, 0.6, 0.001)
  })

  check('die Fahrt haengt an der Zeit, nicht an der Bildrate', () => {
    const slow = createCamera()
    const fast = createCamera()
    slow.targetZoom = 0.5
    fast.targetZoom = 0.5

    for (let i = 0; i < 60; i++) step(slow, 1 / 60)
    for (let i = 0; i < 144; i++) step(fast, 1 / 144)

    assertClose(slow.zoom, fast.zoom, 0.001, '60 Hz und 144 Hz muessen gleich weit kommen')
  })

  check('snapToTarget setzt ohne Fahrt', () => {
    const camera = createCamera()
    fitTo(camera, wideStation(), VIEW_W, VIEW_H)
    snapToTarget(camera)
    assertEqual(camera.zoom, camera.targetZoom)
    assertEqual(camera.center.x, camera.targetCenter.x)
  })

  check('nach eigenem Zoom uebernimmt der Spieler, bis er zuruecksetzt', () => {
    const camera = createCamera()
    fitTo(camera, wideStation(), VIEW_W, VIEW_H)
    const automatisch = camera.targetZoom

    zoomBy(camera, 1.5)
    assert(camera.manual, 'eigener Zoom schaltet den Auto-Ausschnitt ab')
    fitTo(camera, [polygonAt(6, ORIGIN, 0)], VIEW_W, VIEW_H)
    assert(camera.targetZoom !== automatisch, 'fitTo darf jetzt nichts mehr aendern')

    resetAuto(camera)
    fitTo(camera, wideStation(), VIEW_W, VIEW_H)
    assertClose(camera.targetZoom, automatisch, 1e-9)
  })

  check('Welt und Bildschirm rechnen ineinander um', () => {
    const camera = createCamera()
    camera.center = { x: 120, y: -60 }
    camera.zoom = 0.75

    const world = { x: 333, y: 77 }
    const screen = worldToScreen(camera, world, VIEW_W, VIEW_H)
    const back = screenToWorld(camera, screen, VIEW_W, VIEW_H)

    assertClose(back.x, world.x, 1e-9)
    assertClose(back.y, world.y, 1e-9)
  })

  check('der Kameramittelpunkt liegt in der Bildmitte', () => {
    const camera = createCamera()
    camera.center = { x: 40, y: 90 }
    const screen = worldToScreen(camera, camera.center, VIEW_W, VIEW_H)
    assertClose(screen.x, VIEW_W / 2, 1e-9)
    assertClose(screen.y, VIEW_H / 2, 1e-9)
  })

  check('eine Aenderung der Fenstergroesse verzieht nichts', () => {
    // Ein Quadrat in der Welt muss auf dem Bildschirm ein Quadrat bleiben - bei jedem
    // Seitenverhaeltnis. Der Zoom wirkt auf x und y gleich.
    const camera = createCamera()
    const square = [
      { x: 0, y: 0 },
      { x: 100, y: 0 },
      { x: 100, y: 100 },
      { x: 0, y: 100 },
    ]

    for (const [w, h] of [
      [400, 900],
      [1920, 400],
      [800, 800],
    ] as const) {
      fitTo(camera, [polygonAt(6, ORIGIN, 0)], w, h)
      const screen = square.map((point) => worldToScreen(camera, point, w, h))
      const top = dist(screen[0] as Vec2, screen[1] as Vec2)
      const right = dist(screen[1] as Vec2, screen[2] as Vec2)
      assertClose(top, right, 1e-9, `Seitenverhaeltnis ${w}x${h}`)
    }
  })

  check('eine leere Station laesst die Kamera in Ruhe', () => {
    const camera = createCamera()
    const before = camera.targetZoom
    fitTo(camera, [], VIEW_W, VIEW_H)
    assertEqual(camera.targetZoom, before)
  })

  check('eine Ansicht ohne Flaeche laesst die Kamera in Ruhe', () => {
    const camera = createCamera()
    const before = camera.targetZoom
    fitTo(camera, wideStation(), 0, 0)
    assertEqual(camera.targetZoom, before)
  })
}

/**
 * Der Hauptturm steht fest: Hexagon, Zentrum, sechs Anschlusskanten (GDD 04 Abschnitt 1).
 * In E2 kommen die angebauten Module dazu - diese Zusicherungen bleiben dann gueltig.
 */

import { assert, assertClose, assertEqual, check, suite } from '../../core/assert.ts'
import { edgesOf, MODULE_SIDE, signedArea } from '../../core/geometry.ts'
import { dist } from '../../core/vec.ts'
import { CORES, coreById } from '../../data/cores.ts'
import { START_CORE_ID } from '../../data/balance.ts'
import { coreModule, CORE_UID, stationModules } from '../../sim/station.ts'

export function stationSuite(): void {
  suite('sim/station')

  check('der Startkern ist in den Daten hinterlegt', () => {
    const core = coreById(START_CORE_ID)
    assertEqual(core.name, 'Sentinel Core')
  })

  check('ein unbekannter Kern faellt sofort auf', () => {
    let threw = false
    try {
      coreById('gibt-es-nicht')
    } catch {
      threw = true
    }
    assert(threw, 'ein Tippfehler in einer Kern-Kennung darf nicht still durchgehen')
  })

  check('jeder Kern ist ein Hexagon mit sechs Anschlusskanten', () => {
    for (const core of CORES) {
      assertEqual(core.sides, 6, core.name)
    }
  })

  check('der Hauptturm steht im Zentrum', () => {
    const core = coreModule(START_CORE_ID)
    assertEqual(core.center.x, 0)
    assertEqual(core.center.y, 0)
  })

  check('sein Vieleck hat sechs gleich lange Kanten', () => {
    const core = coreModule(START_CORE_ID)
    assertEqual(core.poly.length, 6)
    for (const edge of edgesOf(core.poly)) {
      assertClose(dist(edge.a, edge.b), MODULE_SIDE, 1e-9)
    }
  })

  check('sein Vieleck ist positiv orientiert', () => {
    assert(signedArea(coreModule(START_CORE_ID).poly) > 0)
  })

  check('der Hauptturm hat keine Raritaet (GDD 04 Abschnitt 2)', () => {
    assertEqual(coreModule(START_CORE_ID).rarity, null)
  })

  check('in E1 hat er noch keine Nachbarn, also keine Fugen', () => {
    assertEqual(coreModule(START_CORE_ID).sharedEdges.length, 0)
  })

  check('die Station besteht aus genau einem Modul - dem Kern', () => {
    const modules = stationModules(START_CORE_ID)
    assertEqual(modules.length, 1)
    assertEqual(modules[0]?.uid, CORE_UID)
    assertEqual(modules[0]?.kind, 'core')
  })
}

