(async () => {
  const { render } = await import('/src/render/scene.ts')
  const { createCamera, snapToTarget, worldToScreen } = await import('/src/render/camera.ts')
  const { createInitialState } = await import('/src/app/state.ts')
  const { stationModules } = await import('/src/sim/station.ts')
  const { circumradius, apothem } = await import('/src/core/geometry.ts')

  const W = 900, H = 600
  const cv = document.createElement('canvas'); cv.width = W; cv.height = H
  const ctx = cv.getContext('2d')
  const state = createInitialState(1)
  const cam = createCamera()
  render(ctx, state, cam, W, H, 0)   // setzt das Kameraziel
  snapToTarget(cam)
  render(ctx, state, cam, W, H, 0)   // endgueltiges Bild

  const px = (x, y) => { const d = ctx.getImageData(Math.round(x), Math.round(y), 1, 1).data; return `#${[d[0],d[1],d[2]].map(v=>v.toString(16).padStart(2,'0')).join('')}` }
  const core = stationModules(state.run.coreId)[0]
  const c = worldToScreen(cam, core.center, W, H)
  const ecke = worldToScreen(cam, core.poly[0], W, H)

  return JSON.stringify({
    zoom: +cam.zoom.toFixed(3),
    mittelpunktAufSchirm: [Math.round(c.x), Math.round(c.y)],
    hexagonBreitePx: Math.round(2 * circumradius(6) * cam.zoom),
    kantenlaengePx: Math.round(56 * cam.zoom),
    farben: {
      hintergrundOben: px(4, 4),
      hintergrundUnten: px(4, H - 4),
      kernFuellung: px(c.x + 40, c.y),
      innerhalbNahEcke: px(ecke.x - 6, ecke.y + 6),
      ausserhalbRechts: px(c.x + circumradius(6) * cam.zoom + 12, c.y),
    },
  }, null, 1)
})()

