(async () => {
  const { render } = await import('/src/render/scene.ts')
  const { createCamera, snapToTarget } = await import('/src/render/camera.ts')
  const { createInitialState } = await import('/src/app/state.ts')
  const W = 640, H = 400
  const cv = document.createElement('canvas'); cv.width = W; cv.height = H
  const ctx = cv.getContext('2d')
  const state = createInitialState(1)
  const cam = createCamera()
  render(ctx, state, cam, W, H, 0); snapToTarget(cam); render(ctx, state, cam, W, H, 1.05)
  const img = ctx.getImageData(0, 0, W, H).data
  const cols = 78, rows = 30
  const lum = (x, y) => { const i = ((y * W) + x) * 4; return (img[i] * 0.3 + img[i+1] * 0.59 + img[i+2] * 0.11) }
  let out = []
  for (let r = 0; r < rows; r++) {
    let line = ''
    for (let c = 0; c < cols; c++) {
      // hellsten Wert im Zellbereich nehmen, damit duenne Linien nicht verschwinden
      let best = 0
      for (let dy = 0; dy < H / rows; dy += 2) for (let dx = 0; dx < W / cols; dx += 2) {
        const v = lum(Math.min(W-1, Math.round(c * W / cols + dx)), Math.min(H-1, Math.round(r * H / rows + dy)))
        if (v > best) best = v
      }
      line += best > 120 ? '@' : best > 70 ? '#' : best > 45 ? '+' : best > 28 ? '-' : best > 16 ? '.' : ' '
    }
    out.push(line)
  }
  return out.join('\n')
})()

(async () => {
