  const messen = (W, H) => {
    const cv = document.createElement('canvas'); cv.width = W; cv.height = H
    const ctx = cv.getContext('2d')
    const cam = createCamera()
    render(ctx, state, cam, W, H, 0); snapToTarget(cam); render(ctx, state, cam, W, H, 0)
    const d = ctx.getImageData(0, 0, W, H).data
    // Pixel der Kernfuellung finden (#1d2a53), daraus die Ausdehnung der Flaeche
    let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 4
      if (d[i] === 0x1d && d[i+1] === 0x2a && d[i+2] === 0x53) {
        if (x < minX) minX = x; if (x > maxX) maxX = x
        if (y < minY) minY = y; if (y > maxY) maxY = y
      }
    }
    const bw = maxX - minX, bh = maxY - minY
    return { ansicht: `${W}x${H}`, zoom: +cam.zoom.toFixed(3), breite: bw, hoehe: bh, verhaeltnis: +(bw / bh).toFixed(4),
             mitteX: Math.round((minX + maxX) / 2), mitteY: Math.round((minY + maxY) / 2) }
  }
  return JSON.stringify({
    sollVerhaeltnis: +(2 / Math.sqrt(3)).toFixed(4),
    messungen: [messen(900, 600), messen(400, 900), messen(1600, 380), messen(600, 600)],
  }, null, 1)
})()

