/**
 * Buff-System (GDD 03 Abschnitt 9).
 *
 * Nachbarschaft entsteht ausschliesslich ueber **geteilte Kanten**. Module, die sich nur
 * in einer Ecke beruehren, verstaerken sich nicht - sonst waere die Regel am Bild nicht
 * ablesbar, denn dann fehlt auch die Buff-Linie.
 *
 * Ablauf: Nachbarschaft bestimmen, Boni je Wert **addieren**, danach **deckeln**.
 * Additiv, weil multiplikatives Stapeln die Obergrenze wirkungslos macht und explodiert,
 * sobald mehrere Buff-Tuerme an einem Modul haengen.
 *
 * Bewusst **vollstaendige Neuberechnung** bei jeder Aenderung: kein Cache, keine
 * Invalidierung. Am Prototyp gemessen 0,29 ms bei 21 Modulen, und sie laeuft nur bei
 * Aenderungen, nicht pro Bild. Inkrementelle Buff-Updates sind eine klassische Fehlerquelle.
 */

import { BUFF_CAPS, RARITY_MULT } from '../data/balance.ts'
import { coreById } from '../data/cores.ts'
import { towerById } from '../data/towers.ts'
import { STAT_KEYS, type Category, type StatKey } from '../data/types.ts'
import { adjacency, stationModules, type PlacedModule, type Station } from './station.ts'

export type BuffSource = {
  fromUid: string
  /** Name der Quelle - fuer "Basis -> effektiv mit Quelle" im Detailfenster. */
  fromName: string
  stat: StatKey
  amount: number
}

export type BuffResult = {
  uid: string
  /** Aufsummierte Boni **vor** dem Deckel. */
  raw: Partial<Record<StatKey, number>>
  /** Tatsaechlich wirksame Boni **nach** dem Deckel. */
  applied: Partial<Record<StatKey, number>>
  /** Werte, die am Deckel haengen - die Anzeige soll das zeigen. */
  capped: StatKey[]
  sources: BuffSource[]
  /** Kantennachbarn insgesamt. */
  neighborCount: number
  /** Wie viele Kanten das Modul hat - "Nachbarn n/m" im Detailfenster. */
  edgeCount: number
  /** Nur bei Buff-Modulen: wie viele Module es gerade tatsaechlich verstaerkt. */
  boosted: number
}

/** Der Hauptturm ist ein ganz normales Kampfmodul - er wird gebufft, bufft aber nicht. */
export function categoryOf(module: PlacedModule): Category {
  return module.kind === 'core' ? 'attack' : towerById(module.defId).category
}

export function displayName(module: PlacedModule): string {
  return module.kind === 'core' ? coreById(module.defId).name : towerById(module.defId).name
}

export function computeBuffs(station: Station): Map<string, BuffResult> {
  const modules = stationModules(station)
  const adj = adjacency(station)
  const results = new Map<string, BuffResult>()

  for (const module of modules) {
    results.set(module.uid, {
      uid: module.uid,
      raw: {},
      applied: {},
      capped: [],
      sources: [],
      neighborCount: (adj.get(module.uid) ?? []).length,
      edgeCount: module.sides,
      boosted: 0,
    })
  }

  // Buff-Module wirken auf ihre Kantennachbarn - aber nie auf andere Buff-Module.
  for (const module of modules) {
    if (categoryOf(module) !== 'buff') continue
    const def = towerById(module.defId)
    if (!def.buffs) continue

    // Buff-Module haben keine eigenen Kampfwerte. Ohne diese Regel waere die Raritaet
    // bei ihnen wirkungslos - deshalb wirkt sie hier auf die Buffstaerke.
    const strength = module.rarity ? RARITY_MULT[module.rarity] : 1
    let boosted = 0

    for (const targetUid of adj.get(module.uid) ?? []) {
      const target = modules.find((m) => m.uid === targetUid)
      if (!target || categoryOf(target) === 'buff') continue

      const result = results.get(targetUid)
      if (!result) continue

      boosted += 1
      for (const buff of def.buffs) {
        const amount = buff.amount * strength
        result.raw[buff.stat] = (result.raw[buff.stat] ?? 0) + amount
        result.sources.push({
          fromUid: module.uid,
          fromName: def.name,
          stat: buff.stat,
          amount,
        })
      }
    }

    const own = results.get(module.uid)
    if (own) own.boosted = boosted
  }

  // Erst jetzt deckeln - die Obergrenze greift auf die Summe, nicht auf jede Quelle.
  for (const result of results.values()) {
    for (const key of STAT_KEYS) {
      const sum = result.raw[key]
      if (sum === undefined) continue
      const cap = BUFF_CAPS[key]
      const applied = Math.min(sum, cap)
      result.applied[key] = applied
      if (sum > cap + 1e-9) result.capped.push(key)
    }
  }

  return results
}

/** Verbindungen Buff-Modul -> verstaerktes Modul, je Paar nur einmal. Fuer die Buff-Linien. */
export function buffLinks(results: Map<string, BuffResult>): { from: string; to: string }[] {
  const seen = new Set<string>()
  const links: { from: string; to: string }[] = []

  for (const result of results.values()) {
    for (const source of result.sources) {
      const key = `${source.fromUid}>${result.uid}`
      if (seen.has(key)) continue
      seen.add(key)
      links.push({ from: source.fromUid, to: result.uid })
    }
  }
  return links
}

/**
 * Endwerte aus Basis x Raritaet x Buffs.
 *
 * Die eine Stelle, an der Kampfwerte entstehen. Der Plan sieht diese Datei erst fuer E5
 * vor - sie kommt hier frueher, weil die Basisansicht in E3 bereits "Basis -> effektiv"
 * anzeigen muss. Was fehlt, kommt spaeter dazu, ohne dass sich hier etwas verschiebt:
 * Upgrades (E8), Perks (E10) und Prestige (E13) haengen sich als weitere Faktoren an
 * dieselbe Kette.
 *
 *   Basis x Raritaet  ->  [ + Upgrades ]  ->  [ + Perks ]  ->  [ + Prestige ]  ->  x (1 + Buffs)
 */

import { RARITY_MULT } from '../data/balance.ts'
import { coreById } from '../data/cores.ts'
import { towerById } from '../data/towers.ts'
import { STAT_KEYS, type CombatStats, type Rarity } from '../data/types.ts'
import type { BuffResult } from './buffs.ts'
import type { PlacedModule } from './station.ts'

/** Grundwerte eines Moduls samt Seltenheitsfaktor. */
export function baseStats(defId: string, kind: 'core' | 'tower', rarity: Rarity | null): CombatStats {
  const stats = kind === 'core' ? coreById(defId).stats : towerById(defId).stats
  // Der Hauptturm hat keine Raritaet (GDD 04 Abschnitt 2), also auch keinen Faktor.
  const multiplier = rarity ? RARITY_MULT[rarity] : 1

  const result = {} as CombatStats
  for (const key of STAT_KEYS) result[key] = stats[key] * multiplier
  return result
}

/** Buffs anwenden: Endwert = Basis x (1 + gedeckelte Summe). */
export function applyBuffs(base: CombatStats, buffs: BuffResult | undefined): CombatStats {
  const result = { ...base }
  if (!buffs) return result

  for (const key of STAT_KEYS) {
    const bonus = buffs.applied[key]
    if (bonus !== undefined) result[key] = base[key] * (1 + bonus)
  }
  return result
}

export type ModuleStats = { base: CombatStats; final: CombatStats }

export function moduleStats(module: PlacedModule, buffs: BuffResult | undefined): ModuleStats {
  const base = baseStats(module.defId, module.kind, module.rarity)
  return { base, final: applyBuffs(base, buffs) }
}

/**
 * Vergleichszahl fuer zwei Bauvarianten, bis es echten Kampf gibt (ab E5).
 * Bewertet nur Schaden pro Sekunde - taugt fuer den **relativen** Vergleich, nicht fuer
 * die Turmauswahl (Einschraenkung aus Prototyp 01, F7).
 */
export function theoreticalDps(
  modules: readonly PlacedModule[],
  buffs: Map<string, BuffResult>,
  isBuffModule: (module: PlacedModule) => boolean,
): number {
  let total = 0
  for (const module of modules) {
    if (isBuffModule(module)) continue
    const { final } = moduleStats(module, buffs.get(module.uid))
    total += final.damage * final.attackSpeed * (1 + final.critChance * 0.5)
  }
  return total
}

/**
 * GameState - die eine Wahrheit.
 *
 * Die Aufteilung ist die wichtigste Entscheidung dieser Datei und laut GDD 16 Abschnitt 8
 * spaeter nur mit Umbau zu aendern:
 *
 *   permanent  ueberlebt Prestige   - Punkte, Freischaltungen, Statistik
 *   run        wird bei Prestige zurueckgesetzt - Welle, Gold, Station, Upgrades, Level
 *   runtime    wird **nie** gespeichert - Generator, Auswahl, Bau-Modus, Anzeigezustand
 *
 * Fuer E13 (Prestige) ist genau diese Trennung die fehleranfaelligste Stelle des Spiels.
 * Deshalb steht sie ab E0 und wird im Selbsttest gegen eine Feldliste geprueft.
 */

import { createRng, randomSeed, type Rng } from '../core/rng.ts'
import {
  START_ABILITY_SLOTS,
  START_CORE_ID,
  START_GOLD,
  START_INVENTORY,
  START_LEVEL,
  START_TOWER_IDS,
  START_TOWER_SLOTS,
  START_WAVE,
} from '../data/balance.ts'
import {
  createStation,
  newModule,
  type FreeEdge,
  type Station,
} from '../sim/station.ts'

/** Ueberlebt Prestige. */
export type PermanentState = {
  prestigePoints: number
  /** Gekaufte Knoten im Prestige-Baum. */
  prestigeNodes: string[]
  unlockedTowers: string[]
  unlockedCores: string[]
  /** Einmalige Hinweise, die der Spieler schon gesehen hat (GDD 14 Abschnitt 4a). */
  seenHints: string[]
  bestWaveEver: number
  prestigeCount: number
  totalPlaySeconds: number
}

/** Wird bei Prestige zurueckgesetzt. */
export type RunState = {
  /** Startwert des Generators fuer diesen Run - macht Fehlerberichte nachstellbar. */
  seed: number
  /** Fortgeschriebener Zustand des Generators. */
  rngState: number
  /** Hauptturm, platzierte Module, Inventar und Turmplaetze. */
  station: Station
  wave: number
  /** Hoechste in diesem Run erreichte Welle - begrenzt das Vorspulen (E9). */
  waveRecord: number
  gold: number
  level: number
  xp: number
  abilitySlots: number
  perks: string[]
  /** Upgrade-Pfad -> gekaufte Stufe. */
  upgrades: Record<string, number>
}

/** Bereiche der Oberflaeche (GDD 13 Abschnitt 3). Waechst mit den Etappen. */
export type View = 'combat' | 'base'

/** Existiert nur zur Laufzeit. Nichts hiervon geht in den Spielstand. */
export type RuntimeState = {
  rng: Rng
  /** Spielzeit der letzten Sicherung, in Sekunden. */
  lastSaveAt: number
  /** Es gibt ungesicherte Aenderungen. */
  dirty: boolean
  view: View
  /** Modul aus dem Inventar, das gerade gesetzt werden soll. */
  buildUid: string | null
  /** Platziertes Modul, das gerade umgesetzt wird. */
  dragUid: string | null
  selectedUid: string | null
  hoverUid: string | null
  /** Kante, auf die die Vorschau gerade einrastet. */
  hoverEdge: FreeEdge | null
}

export type GameState = {
  permanent: PermanentState
  run: RunState
  runtime: RuntimeState
}

export function createInitialPermanent(): PermanentState {
  return {
    prestigePoints: 0,
    prestigeNodes: [],
    unlockedTowers: [...START_TOWER_IDS],
    unlockedCores: [START_CORE_ID],
    seenHints: [],
    bestWaveEver: 0,
    prestigeCount: 0,
    totalPlaySeconds: 0,
  }
}

export function createInitialStation(): Station {
  const station = createStation(START_CORE_ID, START_TOWER_SLOTS)
  for (const entry of START_INVENTORY) {
    station.inventory.push(newModule(station, entry.defId, entry.rarity))
  }
  return station
}

export function createInitialRun(seed: number = randomSeed()): RunState {
  return {
    seed,
    rngState: seed,
    station: createInitialStation(),
    wave: START_WAVE,
    waveRecord: START_WAVE,
    gold: START_GOLD,
    level: START_LEVEL,
    xp: 0,
    abilitySlots: START_ABILITY_SLOTS,
    perks: [],
    upgrades: {},
  }
}

export function createInitialState(seed: number = randomSeed()): GameState {
  const run = createInitialRun(seed)
  return {
    permanent: createInitialPermanent(),
    run,
    runtime: createRuntime(run),
  }
}

export function createRuntime(run: RunState): RuntimeState {
  const rng = createRng(run.seed)
  rng.setState(run.rngState)
  return {
    rng,
    lastSaveAt: 0,
    dirty: false,
    view: 'base',
    buildUid: null,
    dragUid: null,
    selectedUid: null,
    hoverUid: null,
    hoverEdge: null,
  }
}

/**
 * Den fortgeschriebenen Generatorzustand in die Run-Daten zurueckschreiben. Muss vor
 * jedem Speichern passieren, sonst laeuft der Zufall nach dem Laden von vorn.
 */
export function syncRngState(state: GameState): void {
  state.run.rngState = state.runtime.rng.state()
}

/** Aenderung vormerken, damit die naechste Sicherung sie mitnimmt. */
export function markDirty(state: GameState): void {
  state.runtime.dirty = true
}

