input.content:
/**
 * Embleme: das Zeichen im Inneren eines Moduls. Reine Wiedererkennung, keine Mechanik -
 * die steckt in der Grundflaeche (Anzahl der Anschlusskanten, GDD 03 Abschnitt 7).
 *
 * Waechst mit den Inhalten. Die restlichen Zeichen kommen mit den Tuermen in E14.
 */

import type { Vec2 } from '../core/vec.ts'
import type { Emblem } from '../data/types.ts'

export function drawEmblem(
  ctx: CanvasRenderingContext2D,
  emblem: Emblem,
  center: Vec2,
  radius: number,
  color: string,
): void {
  ctx.save()
  ctx.strokeStyle = color
  ctx.fillStyle = color
  ctx.lineWidth = Math.max(1, radius * 0.14)
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'

  switch (emblem) {
    case 'core': {
      // Zwei Ringe um einen vollen Kern - liest sich als Reaktor.
      ctx.beginPath()
      ctx.arc(center.x, center.y, radius * 0.9, 0, Math.PI * 2)
      ctx.stroke()
      ctx.beginPath()
      ctx.arc(center.x, center.y, radius * 0.5, 0, Math.PI * 2)
      ctx.stroke()
      ctx.beginPath()
      ctx.arc(center.x, center.y, radius * 0.18, 0, Math.PI * 2)
      ctx.fill()
      break
    }
    case 'bars': {
      // Drei Laeufe - Schnellfeuer.
      const count = 3
      const gap = (radius * 1.5) / (count - 1)
      for (let i = 0; i < count; i++) {
        const x = center.x - radius * 0.75 + i * gap
        ctx.beginPath()
        ctx.moveTo(x, center.y - radius * 0.7)
        ctx.lineTo(x, center.y + radius * 0.7)
        ctx.stroke()
      }
      break
    }
    case 'chevron': {
      // Zwei Winkel - schweres Geschuetz.
      for (let i = 0; i < 2; i++) {
        const offset = -radius * 0.35 + i * radius * 0.7
        ctx.beginPath()
        ctx.moveTo(center.x - radius * 0.7, center.y + offset + radius * 0.3)
        ctx.lineTo(center.x, center.y + offset - radius * 0.3)
        ctx.lineTo(center.x + radius * 0.7, center.y + offset + radius * 0.3)
        ctx.stroke()
      }
      break
    }
    case 'star': {
      ctx.beginPath()
      for (let i = 0; i < 8; i++) {
        const angle = -Math.PI / 2 + (i * Math.PI) / 4
        const r = i % 2 === 0 ? radius : radius * 0.4
        const point = { x: center.x + r * Math.cos(angle), y: center.y + r * Math.sin(angle) }
        if (i === 0) ctx.moveTo(point.x, point.y)
        else ctx.lineTo(point.x, point.y)
      }
      ctx.closePath()
      ctx.stroke()
      break
    }
  }

  ctx.restore()
}

/**
 * Module zeichnen: Flaechen, Fugen, Raritaetsrahmen, Embleme.
 *
 * Reihenfolge ist Absicht - erst alle Flaechen, dann alle Kanten. Wuerde jedes Modul
 * seine eigenen Kanten direkt nach seiner Flaeche zeichnen, uebermalte das naechste Modul
 * die Fuge des vorherigen, und der praegende Look ginge verloren.
 */

import { circumradius, edgesOf, inset } from '../core/geometry.ts'
import type { Vec2 } from '../core/vec.ts'
import { coreById } from '../data/cores.ts'
import { towerById } from '../data/towers.ts'
import type { Emblem } from '../data/types.ts'
import type { PlacedModule } from '../sim/station.ts'
import { worldToScreen, type Camera } from './camera.ts'
import { drawEmblem } from './emblems.ts'
import {
  CORE_GLOW_BASE,
  CORE_GLOW_PULSE,
  FILL_BY_CATEGORY,
  RARITY_COLOR,
  RARITY_GLOW,
  THEME,
} from './theme.ts'

export type ModuleLook = { emblem: Emblem; accent: string; fill: string; frame: string; glow: number }

export type DrawOptions = {
  /** Modul, das gerade umgesetzt wird - es tritt hinter seine Vorschau zurueck. */
  dragUid?: string | null
  selectedUid?: string | null
  hoverUid?: string | null
}

export function lookOf(module: PlacedModule, time: number): ModuleLook {
  if (module.kind === 'core') {
    const def = coreById(module.defId)
    // Der Hauptturm hat keine Raritaet und atmet stattdessen dezent (GDD 13 Abschnitt 10).
    const pulse = 0.5 + 0.5 * Math.sin(time * 3)
    return {
      emblem: def.emblem,
      accent: def.accent,
      fill: THEME.fillCore,
      frame: def.accent,
      glow: CORE_GLOW_BASE + CORE_GLOW_PULSE * pulse,
    }
  }

  const def = towerById(module.defId)
  const rarity = module.rarity ?? 'common'
  // Mythic pulsiert (GDD 13 Abschnitt 7).
  const pulse = 0.5 + 0.5 * Math.sin(time * 3)
  const glow = rarity === 'mythic' ? RARITY_GLOW[rarity] * (0.6 + 0.6 * pulse) : RARITY_GLOW[rarity]

  return {
    emblem: def.emblem,
    accent: def.accent,
    fill: FILL_BY_CATEGORY[def.category],
    frame: RARITY_COLOR[rarity],
    glow,
  }
}

export function drawModules(
  ctx: CanvasRenderingContext2D,
  modules: readonly PlacedModule[],
  camera: Camera,
  width: number,
  height: number,
  time: number,
  options: DrawOptions = {},
): void {
  for (const module of modules) drawFill(ctx, module, camera, width, height, time, options)
  for (const module of modules) drawEdges(ctx, module, camera, width, height, options)
  for (const module of modules) drawSymbol(ctx, module, camera, width, height, time, options)
}

export function toScreen(
  camera: Camera,
  poly: readonly Vec2[],
  width: number,
  height: number,
): Vec2[] {
  return poly.map((point) => worldToScreen(camera, point, width, height))
}

export function trace(ctx: CanvasRenderingContext2D, points: readonly Vec2[]): void {
  ctx.beginPath()
  points.forEach((point, index) => {
    if (index === 0) ctx.moveTo(point.x, point.y)
    else ctx.lineTo(point.x, point.y)
  })
  ctx.closePath()
}

/** Das gezogene Modul bleibt sichtbar, tritt aber hinter seine Vorschau zurueck. */
function alphaFor(module: PlacedModule, options: DrawOptions): number {
  return options.dragUid === module.uid ? 0.3 : 1
}

function drawFill(
  ctx: CanvasRenderingContext2D,
  module: PlacedModule,
  camera: Camera,
  width: number,
  height: number,
  time: number,
  options: DrawOptions,
): void {
  const points = toScreen(camera, module.poly, width, height)
  const look = lookOf(module, time)

  ctx.save()
  ctx.globalAlpha = alphaFor(module, options)

  trace(ctx, points)
  ctx.fillStyle = look.fill
  ctx.fill()

  // Rahmen nach innen versetzt, damit er die Fugen nicht beruehrt.
  trace(ctx, inset(points, THEME.frameInset))
  ctx.strokeStyle = look.frame
  ctx.lineWidth = module.kind === 'core' ? THEME.frameWidthCore : THEME.frameWidthModule
  ctx.shadowColor = look.frame
  ctx.shadowBlur = look.glow
  ctx.stroke()
  ctx.restore()
}

/** Geteilte Kanten hell und leuchtend (Fugen), freie Kanten dunkel (Aussenkontur). */
function drawEdges(
  ctx: CanvasRenderingContext2D,
  module: PlacedModule,
  camera: Camera,
  width: number,
  height: number,
  options: DrawOptions,
): void {
  const shared = new Set(module.sharedEdges)

  ctx.save()
  ctx.globalAlpha = alphaFor(module, options)
  edgesOf(module.poly).forEach((edge, index) => {
    const isShared = shared.has(index)
    const a = worldToScreen(camera, edge.a, width, height)
    const b = worldToScreen(camera, edge.b, width, height)

    ctx.beginPath()
    ctx.moveTo(a.x, a.y)
    ctx.lineTo(b.x, b.y)
    ctx.strokeStyle = isShared ? THEME.edgeShared : THEME.edgeFree
    ctx.lineWidth = isShared ? THEME.edgeSharedWidth : THEME.edgeFreeWidth
    ctx.shadowColor = isShared ? THEME.edgeSharedGlow : 'transparent'
    ctx.shadowBlur = isShared ? THEME.edgeSharedBlur : 0
    ctx.stroke()
  })
  ctx.restore()
}

function drawSymbol(
  ctx: CanvasRenderingContext2D,
  module: PlacedModule,
  camera: Camera,
  width: number,
  height: number,
  time: number,
  options: DrawOptions,
): void {
  const look = lookOf(module, time)
  const center = worldToScreen(camera, module.center, width, height)
  const points = toScreen(camera, module.poly, width, height)

  ctx.save()
  ctx.globalAlpha = alphaFor(module, options)
  drawEmblem(
    ctx,
    look.emblem,
    center,
    circumradius(module.sides) * camera.zoom * THEME.emblemRadiusFactor,
    look.accent,
  )

  // Modul unter dem Mauszeiger dezent hervorheben.
  if (options.hoverUid === module.uid && !options.dragUid) {
    trace(ctx, points)
    ctx.strokeStyle = THEME.hoverOutline
    ctx.lineWidth = 1.5
    ctx.stroke()
  }

  if (options.selectedUid === module.uid) {
    trace(ctx, inset(points, 0.95))
    ctx.strokeStyle = THEME.selectOutline
    ctx.lineWidth = 1.5
    ctx.setLineDash([5, 4])
    ctx.stroke()
    ctx.setLineDash([])
  }
  ctx.restore()
}

