input.content:
/**
 * Zeichenreihenfolge - eine Stelle.
 *
 * Wer eine neue Ebene hinzufuegt (Gegner in E4, Geschosse in E5, Muenzen in E7), traegt
 * sie hier ein und nirgends sonst. Damit bleibt die Reihenfolge nachlesbar, statt sich aus
 * Aufrufreihenfolgen quer durch die Dateien zu ergeben.
 */

import { MODULE_SIDE } from '../core/geometry.ts'
import { screenToWorld } from './camera.ts'
import type { GameState } from '../app/state.ts'
import { stationView } from '../app/view.ts'
import { detached, nearestFreeEdge, previewPolygon } from '../sim/station.ts'
import { placementError } from '../app/actions.ts'
import { fitTo, type Camera } from './camera.ts'
import { drawBuffLines, drawBuildHints, drawDetachPreview, drawGhost } from './overlays.ts'
import { drawModules } from './station.ts'
import { THEME } from './theme.ts'

/** Fangradius der Bauvorschau, in Welteinheiten. Aus Prototyp 01 uebernommen. */
export const SNAP_RADIUS = MODULE_SIDE * 2.5

export type SceneInput = {
  /** Mauszeiger in Bildschirmkoordinaten, oder null wenn er die Flaeche verlassen hat. */
  pointer: { x: number; y: number } | null
  /** Buff-Linien dauerhaft zeigen, nicht nur bei Auswahl. */
  showBuffLines: boolean
}

export function render(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  camera: Camera,
  width: number,
  height: number,
  time: number,
  input: SceneInput = { pointer: null, showBuffLines: true },
): void {
  const view = stationView(state)
  const { buildUid, dragUid, selectedUid, hoverUid } = state.runtime

  // Der Ausschnitt richtet sich nach der Station plus festem Rand - Reichweiten gehen
  // bewusst nicht ein (GDD 13 Abschnitt 4).
  fitTo(camera, view.polys, width, height)

  drawBackground(ctx, width, height)
  drawModules(ctx, view.modules, camera, width, height, time, { dragUid, selectedUid, hoverUid })
  drawBuffLines(
    ctx,
    view.modules,
    view.buffs,
    camera,
    width,
    height,
    selectedUid,
    input.showBuffLines,
  )

  const building = buildUid ?? dragUid
  if (building) {
    drawBuildTools(ctx, state, camera, width, height, time, input, building)
  } else if (hoverUid) {
    drawRemovalPreview(ctx, state, camera, width, height, time, hoverUid)
  }
}

/** Freie Kanten, eingerastete Kante und Vorschau des Moduls. */
function drawBuildTools(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  camera: Camera,
  width: number,
  height: number,
  time: number,
  input: SceneInput,
  buildingUid: string,
): void {
  const { dragUid } = state.runtime
  const view = stationView(state)

  // Beim Umsetzen darf das Modul nicht an sich selbst andocken.
  const edges = dragUid
    ? view.freeEdges.filter((edge) => edge.ownerUid !== dragUid)
    : view.freeEdges

  const active = input.pointer
    ? nearestFreeEdge(edges, screenToWorld(camera, input.pointer, width, height), SNAP_RADIUS)
    : state.runtime.hoverEdge

  drawBuildHints(ctx, camera, width, height, { edges, activeEdge: active, time })
  if (!active) return

  const module =
    state.run.station.inventory.find((m) => m.uid === buildingUid) ??
    state.run.station.placed.find((m) => m.uid === buildingUid)
  if (!module) return

  const { poly } = previewPolygon(module.defId, active)
  drawGhost(ctx, poly, camera, width, height, placementError(state, active) === null)
}

/** Was wuerde mitgehen, wenn dieses Modul entfernt wird (GDD 03 Abschnitt 4). */
function drawRemovalPreview(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  camera: Camera,
  width: number,
  height: number,
  time: number,
  hoverUid: string,
): void {
  if (!state.run.station.placed.some((m) => m.uid === hoverUid)) return

  const view = stationView(state)
  const uids = detached(state.run.station, hoverUid).map((m) => m.uid)
  if (uids.length === 0) return

  drawDetachPreview(ctx, view.modules, hoverUid, uids, camera, width, height, time)
}

/** Dunkelblau mit dezentem Raster. Soll nur auffallen, wenn man hinsieht (GDD 13 Abschnitt 2). */
function drawBackground(ctx: CanvasRenderingContext2D, width: number, height: number): void {
  const gradient = ctx.createLinearGradient(0, 0, 0, height)
  gradient.addColorStop(0, THEME.bgTop)
  gradient.addColorStop(1, THEME.bgBottom)
  ctx.fillStyle = gradient
  ctx.fillRect(0, 0, width, height)

  const spacing = THEME.gridSpacing
  ctx.strokeStyle = THEME.grid
  ctx.lineWidth = 1
  ctx.beginPath()
  for (let x = 0; x < width; x += spacing) {
    ctx.moveTo(Math.round(x) + 0.5, 0)
    ctx.lineTo(Math.round(x) + 0.5, height)
  }
  for (let y = 0; y < height; y += spacing) {
    ctx.moveTo(0, Math.round(y) + 0.5)
    ctx.lineTo(width, Math.round(y) + 0.5)
  }
  ctx.stroke()
}

/**
 * Maus- und Tastaturbedienung der Baufläche.
 *
 * Der Plan nennt fuer E3 keine eigene Eingabedatei; sie steht hier trotzdem, weil sonst
 * `ui/shell.ts` zugleich Bereichswechsel und Zeigerlogik traegt - und weil die Etappe eine
 * pruefbare Bedienung verlangt: Diese Datei ist der Angriffspunkt, an dem der Selbsttest
 * echte Zeigerereignisse abfeuert.
 *
 * Sie enthaelt **keine Regeln**. Jede Entscheidung faellt in `app/actions.ts` und `sim/`.
 */

import type { Vec2 } from '../core/vec.ts'
import { screenToWorld, type Camera } from '../render/camera.ts'
import { SNAP_RADIUS } from '../render/scene.ts'
import {
  cancelBuild,
  hoverEdge,
  hoverModule,
  moveModule,
  placeModule,
  removeModule,
  selectModule,
  startDrag,
} from '../app/actions.ts'
import { stationView } from '../app/view.ts'
import type { GameState } from '../app/state.ts'
import { moduleAt, nearestFreeEdge, type FreeEdge } from '../sim/station.ts'

/** Ab dieser Zeigerbewegung wird aus einem Klick ein Umsetzen. */
const DRAG_THRESHOLD = 6

export type InputOptions = {
  canvas: HTMLCanvasElement
  state: GameState
  camera: Camera
  size(): { width: number; height: number }
  /** Wird nach jeder Aenderung gerufen, damit die Panels neu zeichnen. */
  onChange(): void
}

export type InputHandle = {
  /** Zeigerposition in Bildschirmkoordinaten, oder null ausserhalb der Flaeche. */
  pointer(): Vec2 | null
  detach(): void
}

export function attachInput(options: InputOptions): InputHandle {
  const { canvas, state, camera } = options

  let pointer: Vec2 | null = null
  let pressedAt: Vec2 | null = null
  let pressedUid: string | null = null

  const toLocal = (event: PointerEvent | MouseEvent): Vec2 => {
    const rect = canvas.getBoundingClientRect()
    return { x: event.clientX - rect.left, y: event.clientY - rect.top }
  }

  const toWorld = (point: Vec2): Vec2 => {
    const { width, height } = options.size()
    return screenToWorld(camera, point, width, height)
  }

  /** Kante, auf die die Vorschau gerade einrastet - beim Umsetzen ohne die eigenen Kanten. */
  const snapEdge = (point: Vec2): FreeEdge | null => {
    const view = stationView(state)
    const dragUid = state.runtime.dragUid
    const edges = dragUid
      ? view.freeEdges.filter((edge) => edge.ownerUid !== dragUid)
      : view.freeEdges
    return nearestFreeEdge(edges, toWorld(point), SNAP_RADIUS)
  }

  const onPointerMove = (event: PointerEvent): void => {
    pointer = toLocal(event)
    const world = toWorld(pointer)

    // Aus einem gehaltenen Klick wird ein Umsetzen, sobald der Zeiger weit genug wandert.
    if (
      pressedAt &&
      pressedUid &&
      !state.runtime.dragUid &&
      Math.hypot(pointer.x - pressedAt.x, pointer.y - pressedAt.y) > DRAG_THRESHOLD
    ) {
      startDrag(state, pressedUid)
      options.onChange()
    }

    if (state.runtime.buildUid || state.runtime.dragUid) {
      hoverEdge(state, snapEdge(pointer))
      hoverModule(state, null)
      return
    }

    hoverModule(state, moduleAt(stationView(state).modules, world)?.uid ?? null)
  }

  const onPointerLeave = (): void => {
    pointer = null
    pressedAt = null
    pressedUid = null
    hoverModule(state, null)
    hoverEdge(state, null)
  }

  const onPointerDown = (event: PointerEvent): void => {
    if (event.button !== 0) return
    pointer = toLocal(event)

    // Im Bau-Modus setzt der Klick das Modul an die eingerastete Kante.
    if (state.runtime.buildUid) {
      const edge = snapEdge(pointer)
      if (edge) placeModule(state, state.runtime.buildUid, edge)
      options.onChange()
      return
    }

    const module = moduleAt(stationView(state).modules, toWorld(pointer))
    selectModule(state, module?.uid ?? null)

    // Der Hauptturm kann nicht bewegt werden (GDD 03 Abschnitt 2).
    if (module && module.kind === 'tower') {
      pressedAt = pointer
      pressedUid = module.uid
    }
    options.onChange()
  }

  const onPointerUp = (event: PointerEvent): void => {
    if (event.button !== 0) return
    pointer = toLocal(event)

    if (state.runtime.dragUid) {
      const edge = snapEdge(pointer)
      // Ohne gueltiges Ziel bleibt das Modul, wo es war - ein Zug ist kein Abriss.
      if (edge) moveModule(state, state.runtime.dragUid, edge)
      cancelBuild(state)
      options.onChange()
    }

    pressedAt = null
    pressedUid = null
  }

  /** Rechtsklick entfernt ein Modul oder bricht den Bau ab. */
  const onContextMenu = (event: MouseEvent): void => {
    event.preventDefault()
    const point = toLocal(event)

    if (state.runtime.buildUid || state.runtime.dragUid) {
      cancelBuild(state)
      options.onChange()
      return
    }

    const module = moduleAt(stationView(state).modules, toWorld(point))
    if (module && module.kind === 'tower') {
      removeModule(state, module.uid)
      options.onChange()
    }
  }

  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.key === 'Escape') {
      cancelBuild(state)
      selectModule(state, null)
      options.onChange()
      return
    }
    if (event.key === 'Delete' && state.runtime.selectedUid) {
      removeModule(state, state.runtime.selectedUid)
      options.onChange()
    }
  }

  canvas.addEventListener('pointermove', onPointerMove)
  canvas.addEventListener('pointerleave', onPointerLeave)
  canvas.addEventListener('pointerdown', onPointerDown)
  canvas.addEventListener('pointerup', onPointerUp)
  canvas.addEventListener('contextmenu', onContextMenu)
  window.addEventListener('keydown', onKeyDown)

  return {
    pointer: () => pointer,
    detach() {
      canvas.removeEventListener('pointermove', onPointerMove)
      canvas.removeEventListener('pointerleave', onPointerLeave)
      canvas.removeEventListener('pointerdown', onPointerDown)
      canvas.removeEventListener('pointerup', onPointerUp)
      canvas.removeEventListener('contextmenu', onContextMenu)
      window.removeEventListener('keydown', onKeyDown)
    },
  }
}

/**
 * Hover-Informationen statt Dauertext (GDD 13 Abschnitt 9).
 *
 * Ein einziges Element, das umgehaengt wird - kein Element je Ziel.
 */

let element: HTMLDivElement | null = null

function ensure(): HTMLDivElement {
  if (element) return element
  element = document.createElement('div')
  element.className = 'tooltip'
  element.hidden = true
  document.body.appendChild(element)
  return element
}

export type TooltipAnchor = { x: number; y: number }

export function showTooltip(anchor: TooltipAnchor, content: string): void {
  const node = ensure()
  node.innerHTML = content
  node.hidden = false

  // Am Rand kippt der Hinweis auf die andere Seite, statt aus dem Bild zu laufen.
  const box = node.getBoundingClientRect()
  const left = Math.min(anchor.x + 14, window.innerWidth - box.width - 8)
  const top = Math.min(anchor.y + 16, window.innerHeight - box.height - 8)
  node.style.left = `${Math.max(8, left)}px`
  node.style.top = `${Math.max(8, top)}px`
}

export function hideTooltip(): void {
  if (element) element.hidden = true
}

/**
 * Basisansicht: Inventar und Moduldetails.
 *
 * Zwei Regeln aus GDD 13:
 *   Abschnitt 5 - das Inventar listet **jeden Turm einzeln**, nicht gestapelt. Zwei
 *     Autocannons unterschiedlicher Seltenheit sind zwei verschiedene Dinge.
 *   Abschnitt 9 - Werte werden als `Basis -> effektiv` gezeigt, mit der Quelle des
 *     Unterschieds. Ein Bonus ohne sichtbare Herkunft ist eine Behauptung.
 *
 * Diese Datei liest den Zustand und ruft `app/actions.ts` - sie aendert nie selbst etwas.
 */

import { formatNumber, formatPercent } from '../core/format.ts'
import { towerById } from '../data/towers.ts'
import { STAT_KEYS, type Rarity, type StatKey } from '../data/types.ts'
import { t } from '../data/strings.ts'
import { startBuild } from '../app/actions.ts'
import type { GameState } from '../app/state.ts'
import { stationView } from '../app/view.ts'
import { displayName } from '../sim/buffs.ts'
import { moduleStats } from '../sim/stats.ts'
import { usedSlots } from '../sim/station.ts'
import { RARITY_COLOR } from '../render/theme.ts'

export type BasePanels = { inventory: HTMLElement; detail: HTMLElement }

export function renderInventory(state: GameState, root: HTMLElement, onChange: () => void): void {
  const station = state.run.station
  root.replaceChildren()

  const header = document.createElement('header')
  header.innerHTML =
    `<h2>${t('base.inventory')}</h2>` +
    `<span class="slots">${t('base.slots', { used: usedSlots(station), total: station.slots })}</span>`
  root.appendChild(header)

  if (station.inventory.length === 0) {
    const empty = document.createElement('p')
    empty.className = 'muted'
    empty.textContent = t('base.empty')
    root.appendChild(empty)
    return
  }

  const list = document.createElement('ul')
  list.className = 'inventory'

  // Jeder Turm als eigene Karte - bewusst nicht nach Art gestapelt (GDD 13 Abschnitt 5).
  for (const module of station.inventory) {
    const def = towerById(module.defId)
    const card = document.createElement('li')
    card.className = 'card'
    card.dataset['uid'] = module.uid
    if (state.runtime.buildUid === module.uid) card.classList.add('active')
    card.style.setProperty('--rarity', RARITY_COLOR[module.rarity])

    card.innerHTML =
      `<span class="name">${def.name}</span>` +
      `<span class="rarity">${t(rarityKey(module.rarity))}</span>` +
      `<span class="shape">${def.sides} edges</span>`

    card.addEventListener('click', () => {
      // Nochmal auf dieselbe Karte klicken hebt den Bau-Modus auf.
      if (state.runtime.buildUid === module.uid) state.runtime.buildUid = null
      else startBuild(state, module.uid)
      onChange()
    })

    list.appendChild(card)
  }

  root.appendChild(list)

  const hint = document.createElement('p')
  hint.className = 'muted'
  hint.textContent = state.runtime.buildUid
    ? t('base.building', {
        name: towerById(
          station.inventory.find((m) => m.uid === state.runtime.buildUid)?.defId ?? '',
        ).name,
      })
    : t('base.placeHint')
  root.appendChild(hint)
}

export function renderModuleDetail(state: GameState, root: HTMLElement): void {
  root.replaceChildren()

  const uid = state.runtime.selectedUid
  const view = stationView(state)
  const module = uid ? view.modules.find((m) => m.uid === uid) : undefined

  if (!module) {
    const empty = document.createElement('p')
    empty.className = 'muted'
    empty.textContent = t('detail.none')
    root.appendChild(empty)
    return
  }

  const buffs = view.buffs.get(module.uid)
  const { base, final } = moduleStats(module, buffs)

  const header = document.createElement('header')
  const rarityLabel = module.rarity ? t(rarityKey(module.rarity)) : ''
  header.innerHTML =
    `<h2>${displayName(module)}</h2>` +
    (rarityLabel
      ? `<span class="rarity" style="--rarity:${RARITY_COLOR[module.rarity as Rarity]}">${rarityLabel}</span>`
      : '')
  root.appendChild(header)

  const meta = document.createElement('p')
  meta.className = 'muted'
  meta.textContent = t('detail.neighbours', {
    count: buffs?.neighborCount ?? 0,
    max: module.sides,
  })
  root.appendChild(meta)

  const table = document.createElement('table')
  table.className = 'stats'
  for (const key of STAT_KEYS) {
    if (base[key] === 0 && final[key] === 0) continue
    const row = document.createElement('tr')
    const changed = Math.abs(final[key] - base[key]) > 1e-9
    const isCapped = buffs?.capped.includes(key) ?? false

    row.innerHTML =
      `<th>${t(statKey(key))}</th>` +
      `<td class="base">${formatStat(key, base[key])}</td>` +
      (changed
        ? `<td class="arrow">&rarr;</td><td class="final">${formatStat(key, final[key])}` +
          (isCapped ? ` <em>${t('detail.capped')}</em>` : '') +
          `</td>`
        : `<td class="arrow"></td><td class="final"></td>`)
    table.appendChild(row)
  }
  if (table.childElementCount > 0) root.appendChild(table)

  // Buff-Modul: wie viele Module erreicht es gerade? Das ist die Zahl, an der laut
  // GDD 03 Abschnitt 9 haengt, ob es sich ueberhaupt lohnt (b > 1/k).
  if (module.kind === 'tower' && towerById(module.defId).category === 'buff') {
    const boosted = buffs?.boosted ?? 0
    const note = document.createElement('p')
    note.className = boosted === 0 ? 'warn' : 'muted'
    note.textContent =
      boosted === 0 ? t('detail.boostingNone') : t('detail.boosting', { count: boosted })
    root.appendChild(note)
  }

  // Herkunft der Boni - ohne sie ist ein Bonus nur eine Behauptung.
  if (buffs && buffs.sources.length > 0) {
    const heading = document.createElement('h3')
    heading.textContent = t('detail.sources')
    root.appendChild(heading)

    const list = document.createElement('ul')
    list.className = 'sources'
    for (const source of buffs.sources) {
      const item = document.createElement('li')
      item.textContent = `${source.fromName}: ${t(statKey(source.stat))} ${formatPercent(source.amount, { sign: true })}`
      list.appendChild(item)
    }
    root.appendChild(list)
  }

  if (module.kind === 'core') {
    const note = document.createElement('p')
    note.className = 'muted'
    note.textContent = t('detail.core')
    root.appendChild(note)
  }
}

function formatStat(key: StatKey, value: number): string {
  return key === 'critChance' ? formatPercent(value) : formatNumber(value)
}

function statKey(key: StatKey): 'stat.damage' | 'stat.attackSpeed' | 'stat.range' | 'stat.critChance' | 'stat.projectileSpeed' {
  return `stat.${key}` as const
}

function rarityKey(
  rarity: Rarity,
): 'rarity.common' | 'rarity.rare' | 'rarity.epic' | 'rarity.legendary' | 'rarity.mythic' {
  return `rarity.${rarity}` as const
}

/**
 * Bereichswechsel und Rahmen der Oberflaeche (GDD 13 Abschnitt 3).
 *
 * In Phase A gibt es zwei Bereiche: Kampf (noch leer, ab E4) und Basis. Upgrades,
 * Prestige und Einstellungen kommen in E8, E13 und E18 dazu - sie sind hier je eine
 * weitere Zeile, kein Umbau.
 */

import { t } from '../data/strings.ts'
import { setView } from '../app/actions.ts'
import type { GameState, View } from '../app/state.ts'
import { renderInventory, renderModuleDetail } from './base.ts'

export type Shell = {
  /** Panels neu zeichnen. Nach jeder Handlung aufrufen, nicht pro Bild. */
  refresh(): void
  detach(): void
}

const VIEWS: readonly { id: View; label: 'view.combat' | 'view.base' }[] = [
  { id: 'combat', label: 'view.combat' },
  { id: 'base', label: 'view.base' },
]

export function mountShell(state: GameState, root: HTMLElement): Shell {
  const tabs = document.createElement('nav')
  tabs.className = 'tabs'

  const side = document.createElement('aside')
  side.className = 'side'

  const inventory = document.createElement('section')
  inventory.className = 'panel inventory-panel'

  const detail = document.createElement('section')
  detail.className = 'panel detail-panel'

  side.append(inventory, detail)
  root.append(tabs, side)

  const buttons = new Map<View, HTMLButtonElement>()
  for (const entry of VIEWS) {
    const button = document.createElement('button')
    button.type = 'button'
    button.textContent = t(entry.label)
    button.addEventListener('click', () => {
      setView(state, entry.id)
      refresh()
    })
    buttons.set(entry.id, button)
    tabs.appendChild(button)
  }

  function refresh(): void {
    for (const [id, button] of buttons) {
      button.classList.toggle('active', state.runtime.view === id)
    }
    // Die Baufläche gehoert zur Basis; im Kampf stoert sie nur.
    const inBase = state.runtime.view === 'base'
    side.hidden = !inBase
    if (!inBase) return

    renderInventory(state, inventory, refresh)
    renderModuleDetail(state, detail)
  }

  refresh()

  return {
    refresh,
    detach() {
      tabs.remove()
      side.remove()
    },
  }
}

/**
 * Einstieg: Zustand laden, Schleife starten, Bereiche verdrahten.
 *
 * Diese Datei kennt keine Regeln. Sie verbindet Schleife, Zustand, Zeichnen und Bedienung -
 * jede Entscheidung faellt in `sim/` und `app/`.
 */

import { createLoop, type SpeedFactor } from './core/loop.ts'
import { emit, on } from './core/events.ts'
import { formatDuration, formatNumber } from './core/format.ts'
import { SPEED_FACTORS, TICK_RATE } from './data/balance.ts'
import { t } from './data/strings.ts'
import { load, startAutosave } from './app/save.ts'
import { createInitialState, markDirty } from './app/state.ts'
import { invalidateStationView } from './app/view.ts'
import { createCamera, resetAuto, snapToTarget, step as stepCamera, zoomBy } from './render/camera.ts'
import { render as renderScene } from './render/scene.ts'
import { attachInput } from './ui/input.ts'
import { mountShell } from './ui/shell.ts'
import { runSelfTests, summarize } from './selftest/index.ts'

const stage = document.getElementById('stage') as HTMLCanvasElement | null
const ui = document.getElementById('ui')

if (!stage || !ui) throw new Error('Buehne oder Bedienflaeche fehlt in index.html')

if (new URLSearchParams(location.search).has('selftest')) {
  showSelfTestReport(stage, ui)
} else {
  startGame(stage, ui)
}

// ---------------------------------------------------------------------------
// Spiel
// ---------------------------------------------------------------------------

function startGame(canvas: HTMLCanvasElement, root: HTMLElement): void {
  const context = canvas.getContext('2d')
  if (!context) throw new Error('Canvas-Kontext nicht verfuegbar')

  const loaded = load()
  const state = loaded ?? createInitialState()
  emit('save.loaded', { fresh: loaded === null, version: 1 })

  const loop = createLoop({ tickRate: TICK_RATE })
  const autosave = startAutosave(state, loop)
  const camera = createCamera()
  const shell = mountShell(state, root)
  const devbar = createDevbar(root)

  let viewWidth = 0
  let viewHeight = 0
  let showBuffLines = true

  const resize = (): void => {
    // Das Canvas bekommt echte Geraetepixel, gezeichnet wird trotzdem in CSS-Pixeln.
    // Deshalb verzieht eine Groessenaenderung nichts - sie aendert nur den Ausschnitt.
    const ratio = Math.min(window.devicePixelRatio || 1, 2)
    viewWidth = canvas.clientWidth
    viewHeight = canvas.clientHeight
    canvas.width = Math.round(viewWidth * ratio)
    canvas.height = Math.round(viewHeight * ratio)
    context.setTransform(ratio, 0, 0, ratio, 0, 0)
  }
  resize()
  window.addEventListener('resize', resize)

  const input = attachInput({
    canvas,
    state,
    camera,
    size: () => ({ width: viewWidth, height: viewHeight }),
    onChange: () => shell.refresh(),
  })

  // Bauen ist Fortschritt - er wird sofort gesichert, nicht erst beim naechsten Takt
  // (GDD 16 Abschnitt 8).
  for (const event of ['module.placed', 'module.moved', 'module.removed'] as const) {
    on(event, () => autosave.saveNow())
  }

  window.addEventListener('keydown', (event) => {
    const factor = Number(event.key)
    if ((SPEED_FACTORS as readonly number[]).includes(factor)) {
      loop.setSpeed(factor as SpeedFactor)
      emit('loop.speedChanged', { factor: factor as SpeedFactor })
      return
    }
    if (event.key === 'b' || event.key === 'B') showBuffLines = !showBuffLines
    if (event.key === 'f' || event.key === 'F') resetAuto(camera)
    if (event.key === '+') zoomBy(camera, 1.15)
    if (event.key === '-') zoomBy(camera, 1 / 1.15)
  })

  // Gespielte Zeit ist eine Aussage ueber den Spieler, nicht ueber die Simulation:
  // sie zaehlt echte Sekunden. Bei x4 vergehen je Tick nur ein Viertel davon.
  let untracked = 0
  /** Echte Sekunden seit dem Start - Grundlage aller rein optischen Bewegungen. */
  let viewTime = 0

  loop.start(
    (dt) => {
      untracked += dt / loop.getSpeed()
      if (untracked >= 1) {
        const whole = Math.floor(untracked)
        state.permanent.totalPlaySeconds += whole
        untracked -= whole
        markDirty(state)
      }
      autosave.tick()
    },
    (_alpha, frameSeconds) => {
      // Alles rein Optische rechnet mit echter Zeit, nicht mit Simulationszeit: Die
      // Kamera faehrt bei x4 gleich weich, das Leuchten pulsiert gleich schnell.
      viewTime += frameSeconds
      renderScene(context, state, camera, viewWidth, viewHeight, viewTime, {
        pointer: input.pointer(),
        showBuffLines,
      })
      stepCamera(camera, frameSeconds)

      devbar.update(
        `<b>${t('game.title')}</b>  ${loop.tickRate} Hz\n` +
          `Speed   <b>x${loop.getSpeed()}</b>\n` +
          `Ticks   ${formatNumber(loop.tickCount())}\n` +
          `Sim     ${formatDuration(loop.now())}\n` +
          `Bilder  ${loop.fps().toFixed(0)}/s\n` +
          `Zoom    ${camera.zoom.toFixed(2)}${camera.manual ? ' (manuell)' : ''}\n` +
          `<span class="hint">Linksklick setzt · Ziehen setzt um · Rechtsklick entfernt</span>\n` +
          `<span class="hint">1/2/4 Tempo · B Buff-Linien · +/- Zoom · F Auto · ?selftest</span>`,
      )
    },
  )

  // Erster Bildaufbau ohne Fahrt: die Station steht sofort richtig im Bild.
  invalidateStationView(state)
  renderScene(context, state, camera, viewWidth, viewHeight, 0)
  snapToTarget(camera)
}

function createDevbar(root: HTMLElement): { update(html: string): void } {
  const element = document.createElement('pre')
  element.className = 'devbar'
  root.appendChild(element)

  let last = ''
  let frames = 0
  return {
    update(html) {
      // Nur jedes 15. Bild neu setzen - die Anzeige darf die Messung nicht stoeren.
      frames += 1
      if (frames % 15 !== 0) return
      if (html === last) return
      last = html
      element.innerHTML = html
    },
  }
}

// ---------------------------------------------------------------------------
// Selbsttests
// ---------------------------------------------------------------------------

function showSelfTestReport(canvas: HTMLCanvasElement, root: HTMLElement): void {
  canvas.style.display = 'none'

  const summary = summarize(runSelfTests())
  const report = document.createElement('div')
  report.className = 'report'

  const parts: string[] = [
    `<h1>${t('game.title')} · Selbsttests</h1>`,
    `<div class="summary ${summary.ok ? 'ok' : 'fail'}">` +
      `${summary.passed}/${summary.total} bestanden` +
      (summary.failed > 0 ? ` · ${summary.failed} fehlgeschlagen` : '') +
      `</div>`,
  ]

  let currentSuite = ''
  for (const result of summary.results) {
    if (result.suite !== currentSuite) {
      if (currentSuite !== '') parts.push('</ul>')
      currentSuite = result.suite
      parts.push(`<h2>${escapeHtml(currentSuite)}</h2><ul>`)
    }
    parts.push(`<li class="${result.ok ? 'ok' : 'fail'}">${escapeHtml(result.name)}</li>`)
    if (!result.ok && result.message) parts.push(`<pre>${escapeHtml(result.message)}</pre>`)
  }
  if (currentSuite !== '') parts.push('</ul>')

  report.innerHTML = parts.join('')
  root.appendChild(report)

  document.title = `${summary.ok ? 'OK' : 'FEHLER'} · Selbsttests`
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[char] ?? char)
}

