(async () => {
  const g = window.wavebreaker
  const { worldToScreen } = await import('/src/render/camera.ts')
  const { freeEdges } = await import('/src/sim/station.ts')
  const canvas = document.getElementById('stage')

  const klick = (world, typ) => {
    const { width, height } = g.size()
    const s = worldToScreen(g.camera, world, width, height)
    const r = canvas.getBoundingClientRect()
    canvas.dispatchEvent(new PointerEvent(typ, { clientX: r.left + s.x, clientY: r.top + s.y, button: 0, bubbles: true, cancelable: true }))
  }
  const mitte = e => ({ x: (e.edge.a.x + e.edge.b.x) / 2, y: (e.edge.a.y + e.edge.b.y) / 2 })
  const karte = name => [...document.querySelectorAll('ul.inventory .card')].find(c => c.innerText.includes(name))

  // 1) Amplifier zuerst an eine Kernkante - der Aufbau, der laut GDD 03 Abschnitt 9 gewinnt
  karte('Power Amplifier').click()
  const kernkante = freeEdges(g.state.run.station).find(e => e.ownerUid === 'core')
  klick(mitte(kernkante), 'pointermove')
  klick(mitte(kernkante), 'pointerdown')

  const ampUid = g.state.run.station.placed[0].uid
  // 2) Kampftuerme an die freien Kanten des Amplifiers
  for (const name of ['Autocannon', 'Siege Cannon']) {
    karte(name).click()
    const kante = freeEdges(g.state.run.station).find(e => e.ownerUid === ampUid)
    klick(mitte(kante), 'pointermove')
    klick(mitte(kante), 'pointerdown')
  }

  return JSON.stringify({
    platziert: g.state.run.station.placed.map(m => m.defId),
    imInventar: g.state.run.station.inventory.length,
    slots: document.querySelector('.panel .slots')?.textContent,
    detail: document.querySelector('.detail-panel')?.innerText.split('\n'),
  }, null, 1)
})()

