(async () => {
  const g = window.wavebreaker
  const { render } = await import('/src/render/scene.ts')
  const { createCamera, snapToTarget, worldToScreen } = await import('/src/render/camera.ts')
  const { stationView } = await import('/src/app/view.ts')
  const { edgesOf } = await import('/src/core/geometry.ts')

  const W = 800, H = 520
  const cv = document.createElement('canvas'); cv.width = W; cv.height = H
  const ctx = cv.getContext('2d')
  const cam = createCamera()
  render(ctx, g.state, cam, W, H, 0); snapToTarget(cam); render(ctx, g.state, cam, W, H, 0)
  const d = ctx.getImageData(0, 0, W, H).data
  const lum = (x, y) => { const i = ((y * W) + x) * 4; return d[i] * 0.3 + d[i+1] * 0.59 + d[i+2] * 0.11 }

  // Helligkeit auf der Mitte einer geteilten gegen eine freie Kante des Amplifiers
  const v = stationView(g.state)
  const amp = v.modules.find(m => m.defId === 'amplifier')
  const kanten = edgesOf(amp.poly)
  const geteilt = new Set(amp.sharedEdges)
  const messen = i => {
    const e = kanten[i]
    const m = worldToScreen(cam, { x: (e.a.x + e.b.x) / 2, y: (e.a.y + e.b.y) / 2 }, W, H)
    return +lum(Math.round(m.x), Math.round(m.y)).toFixed(1)
  }
  const fugen = kanten.map((_, i) => i).filter(i => geteilt.has(i)).map(messen)
  const frei = kanten.map((_, i) => i).filter(i => !geteilt.has(i)).map(messen)

  const cols = 78, rows = 26
  const out = []
  for (let r = 0; r < rows; r++) {
    let line = ''
    for (let c = 0; c < cols; c++) {
      let best = 0
      for (let dy = 0; dy < H / rows; dy += 2) for (let dx = 0; dx < W / cols; dx += 2) {
        const val = lum(Math.min(W-1, Math.round(c * W / cols + dx)), Math.min(H-1, Math.round(r * H / rows + dy)))
        if (val > best) best = val
      }
      line += best > 120 ? '@' : best > 70 ? '#' : best > 45 ? '+' : best > 28 ? '-' : best > 16 ? '.' : ' '
    }
    out.push(line)
  }
  return `Fugen (geteilte Kanten): ${fugen.join(', ')}\nFreie Kanten:            ${frei.join(', ')}\n\n` + out.join('\n')
})()

