/**
 * Wellenerzeugung und Wellenzustand (GDD 07).
 *
 * Wellen werden **dynamisch erzeugt**, nicht einzeln definiert (GDD 16 Abschnitt 6).
 * `buildWave` ist dabei eine reine Funktion: gleiche Welle plus gleicher Seed ergibt
 * dieselbe Welle. Ohne das waere ein Balancing-Fehler nicht nachstellbar.
 *
 * Der gesamte Ablauf einer Welle steckt im Plan, auch die Richtung, aus der jeder Gegner
 * kommt - der Zufall wird also **einmal** gezogen und nicht ueber die Welle verteilt.
 */

import type { Rng } from '../core/rng.ts'
import {
  MAX_SPEED_SCALE,
  REWARD_SCALING,
  WAVE_BASE_COUNT,
  WAVE_COUNT_GROWTH,
  WAVE_DAMAGE_SCALING,
  WAVE_PAUSE_SECONDS,
  WAVE_SCALING,
  WAVE_SPAWN_WINDOW_SECONDS,
  WAVE_SPEED_SCALING,
} from '../data/balance.ts'
import { enemiesForWave, type EnemyDef } from '../data/enemies.ts'

export type WaveSpawn = {
  defId: string
  /** Zeitpunkt innerhalb der Welle, in Sekunden. */
  at: number
  /** Richtung auf dem Ring rund um die Station, im Bogenmass. */
  angle: number
}

export type WavePlan = {
  wave: number
  spawns: WaveSpawn[]
  /** Faktoren, mit denen die Grundwerte der Gegnerarten multipliziert werden. */
  hpScale: number
  damageScale: number
  speedScale: number
  rewardScale: number
}

/** Anzahl Gegner einer Welle. Waechst linear - die Haerte kommt aus den Werten. */
export function enemyCount(wave: number): number {
  return Math.max(1, Math.round(WAVE_BASE_COUNT + (wave - 1) * WAVE_COUNT_GROWTH))
}

/**
 * Wachstum je Welle. Bewusst nicht linear (GDD 07 Abschnitt 12): fruehe Wellen steigen
 * langsam, spaete extrem.
 */
export function scaleFor(wave: number, factor: number): number {
  return Math.pow(factor, Math.max(0, wave - 1))
}

/**
 * Erzeugt den vollstaendigen Ablauf einer Welle. Rein - keine Nebenwirkung, kein Zugriff
 * auf den Spielzustand.
 */
export function buildWave(wave: number, rng: Rng): WavePlan {
  const available = enemiesForWave(wave)
  const count = enemyCount(wave)
  const spawns: WaveSpawn[] = []

  // Gleichmaessig ueber das Zeitfenster verteilt, mit leichtem Versatz - es soll nie
  // Leerlauf entstehen, aber auch kein Gleichschritt (GDD 07 Abschnitt 2).
  const step = WAVE_SPAWN_WINDOW_SECONDS / count
  for (let i = 0; i < count; i++) {
    const def = pickWeighted(available, rng)
    spawns.push({
      defId: def.id,
      at: i * step + rng.range(0, step * 0.6),
      angle: rng.range(0, Math.PI * 2),
    })
  }
  spawns.sort((a, b) => a.at - b.at)

  return {
    wave,
    spawns,
    hpScale: scaleFor(wave, WAVE_SCALING),
    damageScale: scaleFor(wave, WAVE_DAMAGE_SCALING),
    speedScale: Math.min(MAX_SPEED_SCALE, scaleFor(wave, WAVE_SPEED_SCALING)),
    rewardScale: scaleFor(wave, REWARD_SCALING),
  }
}

function pickWeighted(candidates: readonly EnemyDef[], rng: Rng): EnemyDef {
  if (candidates.length === 0) throw new Error('Keine Gegnerart fuer diese Welle')

  let total = 0
  for (const candidate of candidates) total += candidate.weight

  let roll = rng.range(0, total)
  for (const candidate of candidates) {
    roll -= candidate.weight
    if (roll <= 0) return candidate
  }
  return candidates[candidates.length - 1] as EnemyDef
}

/** Kurze Pause zwischen zwei Wellen (GDD 07 Abschnitt 10). */
export const wavePause = (): number => WAVE_PAUSE_SECONDS

/**
 * Gegnerinstanzen, Bewegung und Andocken (GDD 07 Abschnitt 2).
 *
 * Zwei Regeln praegen alles hier:
 *   - Gegner laufen auf das **naechstgelegene Modul** zu, nicht auf den Mittelpunkt der
 *     Station. Erst dadurch wird die Platzierung eines Turms zu einer Entscheidung.
 *   - Wer die Station erreicht, **bleibt stehen und schlaegt weiter**, bis er zerstoert
 *     ist. Durchgekommene Gegner sammeln sich also an - das ist der Druck, aus dem eine
 *     Welle verloren geht.
 *
 * Gegner werden **wiederverwendet** statt neu erzeugt (GDD 16 Abschnitt 12): Bei
 * hunderten Gegnern pro Welle ist die Speicherbereinigung sonst im Bild sichtbar.
 */

import { boundsOf, edgesOf, pointSegmentDistance } from '../core/geometry.ts'
import { dist, type Vec2 } from '../core/vec.ts'
import {
  ENEMY_ATTACK_INTERVAL,
  ENEMY_BASE_DAMAGE,
  ENEMY_BASE_HP,
  ENEMY_BASE_SPEED,
  MAX_ENEMIES,
  SPAWN_RING_MARGIN,
} from '../data/balance.ts'
import { enemyById } from '../data/enemies.ts'
import type { GameState } from '../app/state.ts'
import { damageStation } from './combat.ts'
import type { PlacedModule } from './station.ts'

export type Enemy = {
  id: number
  defId: string
  pos: Vec2
  hp: number
  maxHp: number
  /** Welteinheiten pro Sekunde. */
  speed: number
  /** Schaden je Schlag an der Station. */
  damage: number
  radius: number
  gold: number
  xp: number
  /** Kennung des Moduls, an dem er andockt. Angedockte Gegner stehen still. */
  dockedTo: string | null
  attackTimer: number
  /** false = liegt im Pool und wird nicht simuliert. */
  active: boolean
}

function blankEnemy(id: number): Enemy {
  return {
    id,
    defId: '',
    pos: { x: 0, y: 0 },
    hp: 0,
    maxHp: 0,
    speed: 0,
    damage: 0,
    radius: 0,
    gold: 0,
    xp: 0,
    dockedTo: null,
    attackTimer: 0,
    active: false,
  }
}

/** Ring, auf dem Gegner erscheinen: um die Station herum, ausserhalb des Bildes. */
export function spawnRadius(modules: readonly PlacedModule[]): number {
  const bounds = boundsOf(modules.map((module) => module.poly))
  if (!bounds) return SPAWN_RING_MARGIN

  const half = Math.max(
    Math.abs(bounds.maxX),
    Math.abs(bounds.minX),
    Math.abs(bounds.maxY),
    Math.abs(bounds.minY),
  )
  return half + SPAWN_RING_MARGIN
}

/**
 * Erzeugt einen Gegner aus dem Pool. Gibt `null` zurueck, wenn die Obergrenze erreicht
 * ist - die Welle verliert dadurch keinen Gegner, er erscheint nur spaeter.
 */
export function spawnEnemy(state: GameState, defId: string, angle: number): Enemy | null {
  const combat = state.runtime.combat
  if (combat.enemies.length >= MAX_ENEMIES) return null

  const def = enemyById(defId)
  const plan = combat.plan
  const hpScale = plan?.hpScale ?? 1
  const damageScale = plan?.damageScale ?? 1
  const speedScale = plan?.speedScale ?? 1
  const rewardScale = plan?.rewardScale ?? 1

  const enemy = combat.enemyPool.pop() ?? blankEnemy(combat.nextId++)
  const radius = spawnRadius(combat.modules)

  enemy.defId = def.id
  enemy.pos = { x: Math.cos(angle) * radius, y: Math.sin(angle) * radius }
  enemy.maxHp = def.hp * ENEMY_BASE_HP * hpScale
  enemy.hp = enemy.maxHp
  enemy.speed = def.speed * ENEMY_BASE_SPEED * speedScale
  enemy.damage = def.damage * ENEMY_BASE_DAMAGE * damageScale
  enemy.radius = def.size
  enemy.gold = def.gold * rewardScale
  enemy.xp = def.xp * rewardScale
  enemy.dockedTo = null
  enemy.attackTimer = 0
  enemy.active = true

  combat.enemies.push(enemy)
  return enemy
}

/** Zurueck in den Pool. Der Gegner behaelt seine Kennung, damit Ereignisse zuordenbar bleiben. */
export function releaseEnemy(state: GameState, enemy: Enemy): void {
  const combat = state.runtime.combat
  const index = combat.enemies.indexOf(enemy)
  if (index >= 0) combat.enemies.splice(index, 1)

  enemy.active = false
  enemy.dockedTo = null
  combat.enemyPool.push(enemy)
}

/** Modul, das einem Punkt am naechsten liegt - gemessen am Mittelpunkt des Moduls. */
export function nearestModule(
  modules: readonly PlacedModule[],
  point: Vec2,
): PlacedModule | null {
  let best: PlacedModule | null = null
  let bestDistance = Infinity

  for (const module of modules) {
    const distance = dist(point, module.center)
    if (distance < bestDistance) {
      bestDistance = distance
      best = module
    }
  }
  return best
}

/** Abstand eines Punktes zur Aussenkante eines Moduls. Null oder weniger = beruehrt. */
export function distanceToModule(module: PlacedModule, point: Vec2): number {
  let closest = Infinity
  for (const edge of edgesOf(module.poly)) {
    const distance = pointSegmentDistance(point, edge)
    if (distance < closest) closest = distance
  }
  return closest
}

export function stepEnemies(state: GameState, dt: number): void {
  const combat = state.runtime.combat
  const modules = combat.modules
  if (modules.length === 0) return

  for (const enemy of combat.enemies) {
    if (enemy.dockedTo !== null) continue

    const target = nearestModule(modules, enemy.pos)
    if (!target) continue

    // Andocken, sobald die Aussenkante beruehrt wird.
    if (distanceToModule(target, enemy.pos) <= enemy.radius) {
      enemy.dockedTo = target.uid
      enemy.attackTimer = 0
      continue
    }

    const dx = target.center.x - enemy.pos.x
    const dy = target.center.y - enemy.pos.y
    const length = Math.hypot(dx, dy)
    if (length < 1e-6) continue

    const stride = enemy.speed * dt
    enemy.pos = { x: enemy.pos.x + (dx / length) * stride, y: enemy.pos.y + (dy / length) * stride }
  }
}

/**
 * Angedockte Gegner schlagen fortlaufend zu. Der Schaden geht immer auf die gemeinsame
 * Stations-HP, nie auf ein einzelnes Modul (GDD 03 Abschnitt 5).
 */
export function dockedDamage(state: GameState, dt: number): void {
  const combat = state.runtime.combat

  for (const enemy of combat.enemies) {
    if (enemy.dockedTo === null) continue

    enemy.attackTimer -= dt
    if (enemy.attackTimer > 0) continue

    enemy.attackTimer += ENEMY_ATTACK_INTERVAL
    damageStation(state, enemy.damage, enemy.pos)
  }
}

/**
 * Module, an denen niemand mehr andocken kann, weil sie nicht mehr existieren - etwa
 * nachdem der Spieler mitten im Kampf umgebaut hat. Die Gegner suchen sich neu ein Ziel.
 */
export function releaseStaleDocks(state: GameState): void {
  const combat = state.runtime.combat
  const alive = new Set(combat.modules.map((module) => module.uid))

  for (const enemy of combat.enemies) {
    if (enemy.dockedTo !== null && !alive.has(enemy.dockedTo)) enemy.dockedTo = null
  }
}

