/**
 * Schaden, Tod und der Zustand eines Gefechts.
 *
 * Die Station hat **eine gemeinsame Lebensleiste** (GDD 03 Abschnitt 5): Es gibt keine
 * HP je Modul, kein Modul kann zerstoert werden, und jeder Treffer geht auf dieselbe
 * Leiste - unabhaengig davon, wo er ankam.
 *
 * Diese Datei importiert bewusst nur nach unten (`enemies`, `station`, `data`). Die
 * Orchestrierung eines Ticks steht in `sim/battle.ts`, damit hier kein Kreis entsteht.
 */

import { emit } from '../core/events.ts'
import type { Vec2 } from '../core/vec.ts'
import { BASE_STATION_HP, CRIT_MULTIPLIER, ENEMY_ATTACK_INTERVAL } from '../data/balance.ts'
import { grantReward } from '../app/rewards.ts'
import type { GameState } from '../app/state.ts'
import { releaseEnemy, type Enemy } from './enemies.ts'
import type { Projectile } from './projectiles.ts'
import type { PlacedModule } from './station.ts'
import type { WavePlan } from './waves.ts'

/** Kurzes Aufblitzen am Trefferort (GDD 13 Abschnitt 4). */
export type Hit = { pos: Vec2; age: number; kind: 'enemy' | 'station' }

export type CombatPhase = 'pause' | 'running'

export type CombatState = {
  phase: CombatPhase
  /** In der Pause die Restzeit, in der Welle die verstrichene Zeit - beides in Sekunden. */
  timer: number
  plan: WavePlan | null
  /** Wie viele Eintraege des Plans bereits erschienen sind. */
  spawnIndex: number

  enemies: Enemy[]
  enemyPool: Enemy[]
  projectiles: Projectile[]
  projectilePool: Projectile[]
  /** Restliche Nachladezeit je Modul, in Sekunden. */
  cooldowns: Map<string, number>

  stationHp: number
  maxStationHp: number

  /**
   * Geometrie der Station fuer diesen Tick. Wird einmal je Tick gesetzt, statt in jeder
   * Funktion neu berechnet - bei 200 Gegnern waere das sonst der teuerste Posten.
   */
  modules: PlacedModule[]
  hits: Hit[]
  nextId: number

  killsThisWave: number
  /** Wie oft die aktuelle Welle bereits verloren ging. Nur Anzeige. */
  lostAttempts: number
}

export function createCombatState(): CombatState {
  return {
    phase: 'pause',
    timer: 0,
    plan: null,
    spawnIndex: 0,
    enemies: [],
    enemyPool: [],
    projectiles: [],
    projectilePool: [],
    cooldowns: new Map(),
    stationHp: BASE_STATION_HP,
    maxStationHp: BASE_STATION_HP,
    modules: [],
    hits: [],
    nextId: 1,
    killsThisWave: 0,
    lostAttempts: 0,
  }
}

// ---------------------------------------------------------------------------
// Schaden an der Station
// ---------------------------------------------------------------------------

/** Ein Treffer auf die Station. `atPos` dient nur dem Aufblitzen an der Trefferstelle. */
export function damageStation(state: GameState, amount: number, atPos: Vec2): void {
  const combat = state.runtime.combat
  if (!Number.isFinite(amount) || amount <= 0) return
  if (combat.stationHp <= 0) return

  combat.stationHp = Math.max(0, combat.stationHp - amount)
  combat.hits.push({ pos: { ...atPos }, age: 0, kind: 'station' })
  emit('station.damaged', { amount, remaining: combat.stationHp })

  if (combat.stationHp === 0) emit('station.destroyed', { wave: state.run.wave })
}

/**
 * Angedockte Gegner schlagen fortlaufend zu, bis sie zerstoert sind (GDD 07 Abschnitt 2).
 * Sie stehen dabei still - deshalb sind sie zugleich das bevorzugte Ziel der Tuerme.
 */
export function dockedDamage(state: GameState, dt: number): void {
  for (const enemy of state.runtime.combat.enemies) {
    if (enemy.dockedTo === null) continue

    enemy.attackTimer -= dt
    if (enemy.attackTimer > 0) continue

    enemy.attackTimer += ENEMY_ATTACK_INTERVAL
    damageStation(state, enemy.damage, enemy.pos)
  }
}

// ---------------------------------------------------------------------------
// Schaden an Gegnern
// ---------------------------------------------------------------------------

export type DamageFlags = { crit?: boolean }

/** Schaden auf einen Gegner. Toetet ihn, wenn seine HP auf null fallen. */
export function applyDamage(
  state: GameState,
  enemy: Enemy,
  amount: number,
  flags: DamageFlags = {},
): void {
  if (!enemy.active || amount <= 0) return

  const dealt = flags.crit ? amount * CRIT_MULTIPLIER : amount
  enemy.hp -= dealt
  state.runtime.combat.hits.push({ pos: { ...enemy.pos }, age: 0, kind: 'enemy' })

  if (enemy.hp <= 0) killEnemy(state, enemy)
}

/**
 * Belohnung ueber `grantReward` - die einzige Stelle, an der Gold und XP entstehen
 * (GDD 16 Abschnitt 2). Ab E7 faellt das Gold stattdessen als Muenze auf das Feld;
 * dann aendert sich hier genau eine Zeile.
 */
export function killEnemy(state: GameState, enemy: Enemy): void {
  if (!enemy.active) return

  const combat = state.runtime.combat
  combat.killsThisWave += 1

  grantReward(state, { gold: enemy.gold, xp: enemy.xp }, 'enemy.kill')
  emit('enemy.killed', { defId: enemy.defId, gold: enemy.gold, xp: enemy.xp })

  releaseEnemy(state, enemy)
}

/** Trefferblitze altern lassen und ausgebrannte entfernen. */
export function stepHits(state: GameState, dt: number): void {
  const hits = state.runtime.combat.hits
  for (let i = hits.length - 1; i >= 0; i--) {
    const hit = hits[i] as Hit
    hit.age += dt
    if (hit.age > 0.35) hits.splice(i, 1)
  }
}

/**
 * Geschosse mit Wiederverwendung (GDD 16 Abschnitt 12).
 *
 * Geschosse sind die haeufigsten Objekte im Spiel - ein Autocannon allein erzeugt sechs
 * pro Sekunde. Sie werden deshalb aus einem Pool geholt und dorthin zurueckgegeben,
 * nicht laufend neu erzeugt.
 *
 * Sie fliegen ihrem Ziel nach. Stirbt das Ziel unterwegs, verfaellt das Geschoss - der
 * Schaden geht verloren. Das ist Absicht: Ueberschuss bei hoher Feuerrate ist ein echter
 * Nachteil schneller Tuerme und gehoert zum Kraefteverhaeltnis der Turmarten.
 */

import type { Vec2 } from '../core/vec.ts'
import { MAX_PROJECTILES, PROJECTILE_MAX_LIFETIME } from '../data/balance.ts'
import type { GameState } from '../app/state.ts'
import { applyDamage } from './combat.ts'
import type { Enemy } from './enemies.ts'

export type Projectile = {
  id: number
  pos: Vec2
  /** Kennung des verfolgten Gegners. */
  targetId: number
  speed: number
  damage: number
  crit: boolean
  color: string
  /** Bisherige Flugzeit in Sekunden. */
  life: number
  active: boolean
}

export type ProjectileSpec = {
  damage: number
  speed: number
  crit: boolean
  color: string
}

function blankProjectile(id: number): Projectile {
  return {
    id,
    pos: { x: 0, y: 0 },
    targetId: -1,
    speed: 0,
    damage: 0,
    crit: false,
    color: '#ffffff',
    life: 0,
    active: false,
  }
}

export function spawnProjectile(
  state: GameState,
  from: Vec2,
  target: Enemy,
  spec: ProjectileSpec,
): Projectile | null {
  const combat = state.runtime.combat
  if (combat.projectiles.length >= MAX_PROJECTILES) return null

  const projectile = combat.projectilePool.pop() ?? blankProjectile(combat.nextId++)
  projectile.pos = { x: from.x, y: from.y }
  projectile.targetId = target.id
  projectile.speed = spec.speed
  projectile.damage = spec.damage
  projectile.crit = spec.crit
  projectile.color = spec.color
  projectile.life = 0
  projectile.active = true

  combat.projectiles.push(projectile)
  return projectile
}

export function releaseProjectile(state: GameState, projectile: Projectile): void {
  const combat = state.runtime.combat
  const index = combat.projectiles.indexOf(projectile)
  if (index >= 0) combat.projectiles.splice(index, 1)

  projectile.active = false
  projectile.targetId = -1
  combat.projectilePool.push(projectile)
}

export function stepProjectiles(state: GameState, dt: number): void {
  const combat = state.runtime.combat
  if (combat.projectiles.length === 0) return

  const byId = new Map<number, Enemy>()
  for (const enemy of combat.enemies) byId.set(enemy.id, enemy)

  // Rueckwaerts, weil getroffene Geschosse aus der Liste entfernt werden.
  for (let i = combat.projectiles.length - 1; i >= 0; i--) {
    const projectile = combat.projectiles[i] as Projectile
    projectile.life += dt

    const target = byId.get(projectile.targetId)
    if (!target || !target.active || projectile.life > PROJECTILE_MAX_LIFETIME) {
      releaseProjectile(state, projectile)
      continue
    }

    const dx = target.pos.x - projectile.pos.x
    const dy = target.pos.y - projectile.pos.y
    const distance = Math.hypot(dx, dy)
    const stride = projectile.speed * dt

    // Treffer, sobald das Geschoss den Gegner in diesem Schritt erreichen wuerde.
    if (distance <= stride + target.radius) {
      applyDamage(state, target, projectile.damage, { crit: projectile.crit })
      releaseProjectile(state, projectile)
      continue
    }

    projectile.pos = {
      x: projectile.pos.x + (dx / distance) * stride,
      y: projectile.pos.y + (dy / distance) * stride,
    }
  }
}

/**
 * Zielerfassung und Prioritaeten (GDD 05 Abschnitt 4).
 *
 * Zwei Regeln:
 *   - Reichweite ist ein Kreis um das **eigene Modul**, nicht um das Zentrum der
 *     Station. Erst dadurch wird die Position eines Turms zu einer Entscheidung.
 *   - **Angedockte Gegner werden bevorzugt.** Sie verursachen fortlaufend Schaden und
 *     stehen still, sind also das dringendste und einfachste Ziel. Ohne diese Regel
 *     entstehen Todesspiralen, weil die Tuerme auf Nachrueckende schiessen, waehrend die
 *     Station zerlegt wird (GDD 07 Abschnitt 2).
 *
 * Abweichung von der Signatur im Plan: `findTarget` bekommt Position und Reichweite statt
 * eines Turmobjekts. Dadurch ist die Zielwahl fuer sich pruefbar und der Kern kann
 * dieselbe Funktion nutzen wie jeder Turm.
 */

import { dist, type Vec2 } from '../core/vec.ts'
import type { Enemy } from './enemies.ts'

export type TargetMode =
  | 'nearest' // Standard
  | 'strongest' // Sniper: staerkster Gegner zuerst
  | 'boss' // Laser: Boss-Fokus, sonst der staerkste

export function findTarget(
  enemies: readonly Enemy[],
  from: Vec2,
  range: number,
  mode: TargetMode = 'nearest',
): Enemy | null {
  if (range <= 0) return null

  let best: Enemy | null = null
  let bestScore = -Infinity
  let bestDocked = false

  for (const enemy of enemies) {
    if (!enemy.active) continue

    const distance = dist(from, enemy.pos)
    if (distance > range + enemy.radius) continue

    const docked = enemy.dockedTo !== null
    // Angedockte schlagen alles andere - unabhaengig von der Prioritaet des Turms.
    if (best && bestDocked && !docked) continue

    const score = docked !== bestDocked ? Infinity : scoreFor(enemy, distance, mode)
    if (!best || docked !== bestDocked || score > bestScore) {
      best = enemy
      bestScore = docked !== bestDocked ? scoreFor(enemy, distance, mode) : score
      bestDocked = docked
    }
  }

  return best
}

function scoreFor(enemy: Enemy, distance: number, mode: TargetMode): number {
  switch (mode) {
    case 'nearest':
      // Naeher ist besser, deshalb negativ.
      return -distance
    case 'strongest':
    case 'boss':
      return enemy.maxHp
  }
}

/** Wie viele Gegner in Reichweite sind - Grundlage fuer die Raketen-Prioritaet in E14. */
export function countInRange(enemies: readonly Enemy[], from: Vec2, range: number): number {
  let count = 0
  for (const enemy of enemies) {
    if (enemy.active && dist(from, enemy.pos) <= range + enemy.radius) count += 1
  }
  return count
}

