/**
 * Upgrade-Menue (GDD 08 Abschnitt 5).
 *
 * Drei Bereiche: Hauptturm, Turmarten, global. Turm-Upgrades stehen bewusst **je Art**
 * und nicht je Exemplar - bei 15 Tuermen bliebe das Menue sonst nicht ueberschaubar,
 * und die eigentliche Entscheidung ("in welchen Turmtyp investiere ich?") gaebe es nicht.
 *
 * Gekaufte Stufen wirken sofort; die Werte selbst entstehen ausschliesslich in
 * `sim/stats.ts`.
 */

import { formatNumber, formatPercent } from '../core/format.ts'
import { t } from '../data/strings.ts'
import { towerById, TOWERS } from '../data/towers.ts'
import {
  globalUpgrades,
  upgradesForCore,
  upgradesForTower,
  type UpgradeDef,
} from '../data/upgrades.ts'
import { buyUpgrade, nextUpgradeCost } from '../app/actions.ts'
import type { GameState } from '../app/state.ts'
import { upgradeLevel } from '../sim/stats.ts'

export function renderUpgradeMenu(state: GameState, root: HTMLElement, onChange: () => void): void {
  root.replaceChildren()

  const header = document.createElement('header')
  header.innerHTML =
    `<h2>${t('upgrades.title')}</h2>` +
    `<span class="slots">${formatNumber(Math.floor(state.run.gold))}</span>`
  root.appendChild(header)

  section(root, t('upgrades.core'), upgradesForCore(), state, onChange)

  for (const tower of TOWERS) {
    const paths = upgradesForTower(tower.id)
    if (paths.length === 0) continue
    section(root, towerById(tower.id).name, paths, state, onChange)
  }

  section(root, t('upgrades.global'), globalUpgrades(), state, onChange)
}

function section(
  root: HTMLElement,
  title: string,
  paths: readonly UpgradeDef[],
  state: GameState,
  onChange: () => void,
): void {
  const heading = document.createElement('h3')
  heading.textContent = title
  root.appendChild(heading)

  const list = document.createElement('ul')
  list.className = 'upgrades'

  for (const def of paths) {
    const level = upgradeLevel(state.run.upgrades, def.id)
    const cost = nextUpgradeCost(state, def.id)
    const affordable = cost !== null && state.run.gold >= cost

    const item = document.createElement('li')
    item.className = 'upgrade'
    if (cost === null) item.classList.add('maxed')

    const label = document.createElement('span')
    label.className = 'label'
    label.textContent = def.label

    const effect = document.createElement('span')
    effect.className = 'effect'
    // Die aktuelle Gesamtwirkung, nicht der Zuwachs - das ist die Zahl, die zaehlt.
    effect.textContent = level > 0 ? formatPercent(def.amount * level, { sign: true }) : ''

    const button = document.createElement('button')
    button.type = 'button'
    button.disabled = !affordable
    button.textContent =
      cost === null ? t('upgrades.max') : `${t('upgrades.level', { level })} · ${formatNumber(cost)}`
    button.addEventListener('click', () => {
      if (buyUpgrade(state, def.id)) onChange()
    })

    item.append(label, effect, button)
    list.appendChild(item)
  }

  root.appendChild(list)
}

