/**
 * Liegendes Gold (GDD 08 Abschnitt 2). Muenzen verfallen nie, deshalb sind sie dauerhaft
 * sichtbar - ein Stapel traegt seinen Gesamtwert, damit erkennbar bleibt, was dort liegt.
 */
export function drawCoins(
  ctx: CanvasRenderingContext2D,
  coins: readonly Coin[],
  camera: Camera,
  width: number,
  height: number,
  time: number,
): void {
  if (coins.length === 0) return
  const pulse = 0.75 + 0.25 * Math.sin(time * 2.5)

  ctx.save()
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'

  for (const coin of coins) {
    const center = worldToScreen(camera, { x: coin.x, y: coin.y }, width, height)
    if (center.x < -30 || center.y < -30 || center.x > width + 30 || center.y > height + 30) continue

    // Ein Stapel ist groesser, aber nicht beliebig - sonst deckt er die Station zu.
    const radius = (4 + Math.min(6, Math.log10(coin.count + 1) * 5)) * Math.max(0.6, camera.zoom)

    ctx.beginPath()
    ctx.arc(center.x, center.y, radius, 0, Math.PI * 2)
    ctx.fillStyle = PALETTE.gold
    ctx.globalAlpha = pulse
    ctx.shadowColor = PALETTE.gold
    ctx.shadowBlur = 8
    ctx.fill()
    ctx.shadowBlur = 0

    if (coin.count > 1) {
      ctx.globalAlpha = 1
      ctx.font = `600 ${Math.round(9 * Math.max(0.8, camera.zoom))}px ${LABEL_FONT}`
      ctx.fillStyle = PALETTE.ink
      ctx.fillText(formatNumber(Math.floor(coin.value)), center.x, center.y + 0.5)
    }
  }
  ctx.restore()
}

/** Der Sammelradius, solange der Zeiger ueber dem Feld ist. */
export function drawCollectRadius(
  ctx: CanvasRenderingContext2D,
  pointer: Vec2,
  radius: number,
  camera: Camera,
): void {
  ctx.save()
  ctx.beginPath()
  ctx.arc(pointer.x, pointer.y, radius * camera.zoom, 0, Math.PI * 2)
  ctx.strokeStyle = PALETTE.gold
  ctx.globalAlpha = 0.28
  ctx.lineWidth = 1.2
  ctx.setLineDash([5, 5])
  ctx.stroke()
  ctx.restore()
}

/** Kurzes Aufblitzen dort, wo Schaden ankam. */

if (state.runtime.view === 'combat') {
  const combat = state.runtime.combat
  drawCoins(ctx, state.run.coins, camera, width, height, time)
  drawEnemies(ctx, combat.enemies, camera, width, height)
  drawProjectiles(ctx, combat.projectiles, camera, width, height)
  drawHits(ctx, combat.hits, camera, width, height)
  if (input.pointer) {
    drawCollectRadius(ctx, input.pointer, collectRadius(state), camera)
  }
  return
}

