 */

import { formatNumber, formatPercent } from '../core/format.ts'
import { t } from '../data/strings.ts'
import { TOWERS, towerById } from '../data/towers.ts'
import {
  globalUpgrades,
  upgradesForCore,
  upgradesForTower,
  type UpgradeDef,
} from '../data/upgrades.ts'
import { buyUpgrade, nextUpgradeCost } from '../app/actions.ts'
import type { GameState } from '../app/state.ts'
import { upgradeLevel } from '../sim/stats.ts'

export type UpgradeMenu = {
  /** Pro Bild aufrufen - schreibt nur, wenn sich etwas geaendert hat. */
  update(): void
}

type Row = { def: UpgradeDef; effect: HTMLElement; button: HTMLButtonElement }

export function mountUpgradeMenu(
  state: GameState,
  root: HTMLElement,
  onChange: () => void,
): UpgradeMenu {
  root.replaceChildren()
  const rows: Row[] = []

  const header = document.createElement('header')
  const title = document.createElement('h2')
  title.textContent = t('upgrades.title')
  const gold = document.createElement('span')
  gold.className = 'slots'
  header.append(title, gold)
  root.appendChild(header)

  section(root, rows, t('upgrades.core'), upgradesForCore(), state, onChange)
  for (const tower of TOWERS) {
    const paths = upgradesForTower(tower.id)
    if (paths.length > 0) section(root, rows, towerById(tower.id).name, paths, state, onChange)
  }
  section(root, rows, t('upgrades.global'), globalUpgrades(), state, onChange)

  let last = ''

  return {
    update() {
      const signature = `${Math.floor(state.run.gold)}|${JSON.stringify(state.run.upgrades)}`
      if (signature === last) return
      last = signature

      gold.textContent = formatNumber(Math.floor(state.run.gold))

      for (const row of rows) {
        const level = upgradeLevel(state.run.upgrades, row.def.id)
        const cost = nextUpgradeCost(state, row.def.id)

        row.effect.textContent = level > 0 ? formatPercent(row.def.amount * level, { sign: true }) : ''
        row.button.disabled = cost === null || state.run.gold < cost
        row.button.textContent =
          cost === null
            ? t('upgrades.max')
            : `${t('upgrades.level', { level })} · ${formatNumber(cost)}`
      }
    },
  }
}

function section(
  root: HTMLElement,
  rows: Row[],
  title: string,
  paths: readonly UpgradeDef[],
  state: GameState,
  onChange: () => void,
): void {
  const heading = document.createElement('h3')
  heading.textContent = title
  root.appendChild(heading)

  const list = document.createElement('ul')
  list.className = 'upgrades'

  for (const def of paths) {
    const item = document.createElement('li')
    item.className = 'upgrade'

    const label = document.createElement('span')
    label.className = 'label'
    label.textContent = def.label

    const effect = document.createElement('span')
    effect.className = 'effect'

    const button = document.createElement('button')
    button.type = 'button'
    button.addEventListener('click', () => {
      if (buyUpgrade(state, def.id)) onChange()
    })

    item.append(label, effect, button)
    list.appendChild(item)
    rows.push({ def, effect, button })
  }

  root.appendChild(list)
}

