/**
 * Obere Leiste der Kampfansicht (GDD 13 Abschnitt 4).
 *
 * **Eine** Lebensleiste fuer die gesamte Station, keine HP je Modul (GDD 03 Abschnitt 5).
 * Das ist keine Vereinfachung der Anzeige, sondern die Spielregel: Module koennen nicht
 * zerstoert werden, und der Schaden geht immer auf dieselbe Leiste.
 *
 * Die Wellensteuerung `[(<) WAVE 15 (+)(>)]` steuert das Tempo (GDD 07 Abschnitt 10).
 * Vorwaerts geht es nur bis zur hoechsten in diesem Run erreichten Welle - die Regel
 * steckt in `sim/waves.ts`, hier wird sie nur sichtbar gemacht.
 */

import { formatNumber } from '../core/format.ts'
import { t } from '../data/strings.ts'
import { goToNextWave, goToPreviousWave, toggleAutoWaves } from '../app/actions.ts'
import type { GameState } from '../app/state.ts'
import { activeBoss } from '../sim/enemies.ts'
import { goldOnField } from '../sim/economy.ts'
import { canSkipTo } from '../sim/waves.ts'

export type Hud = {
  /** Pro Bild aufrufen - schreibt nur, wenn sich etwas geaendert hat. */
  update(): void
  detach(): void
}

export function mountHud(state: GameState, root: HTMLElement): Hud {
  const bar = document.createElement('div')
  bar.className = 'hud'

  // --- Wellensteuerung ---
  const controls = document.createElement('div')
  controls.className = 'wave-controls'

  const previous = button('(<)', t('hud.prevWave'), () => goToPreviousWave(state))
  const label = document.createElement('span')
  label.className = 'wave-label'
  const auto = button('(+)', t('hud.autoOn'), () => toggleAutoWaves(state))
  const next = button('(>)', t('hud.nextWave'), () => goToNextWave(state))

  controls.append(previous, label, auto, next)

  // --- Stations-HP ---
  const hpOuter = document.createElement('div')
  hpOuter.className = 'hud-hp'
  const hpFill = document.createElement('i')
  const hpText = document.createElement('span')
  hpOuter.append(hpFill, hpText)

  // --- Gold ---
  const gold = document.createElement('span')
  gold.className = 'hud-gold'

  bar.append(controls, hpOuter, gold)
  root.appendChild(bar)

  // --- Boss-Leiste, nur bei aktivem Boss (GDD 07 Abschnitt 7) ---
  const bossBar = document.createElement('div')
  bossBar.className = 'boss-bar'
  bossBar.hidden = true
  const bossName = document.createElement('span')
  const bossOuter = document.createElement('div')
  const bossFill = document.createElement('i')
  const bossText = document.createElement('span')
  bossOuter.className = 'boss-hp'
  bossOuter.append(bossFill, bossText)
  bossBar.append(bossName, bossOuter)
  root.appendChild(bossBar)

  let last = ''

  return {
    update() {
      const combat = state.runtime.combat
      const boss = activeBoss(state)
      const onField = goldOnField(state)

      const signature = [
        state.run.wave,
        Math.round(combat.stationHp),
        Math.round(state.run.gold),
        Math.round(onField),
        combat.phase,
        state.run.autoWaves,
        state.run.waveRecord,
        boss ? Math.round(boss.hp) : 'none',
      ].join('|')
      if (signature === last) return
      last = signature

      label.textContent =
        combat.phase === 'pause'
          ? t('hud.wavePause', { wave: state.run.wave + 1 })
          : t('hud.wave', { wave: state.run.wave })

      previous.disabled = !canSkipTo(state, state.run.wave - 1)
      next.disabled = state.run.wave + 1 > state.run.waveRecord + 1
      auto.classList.toggle('active', state.run.autoWaves)
      auto.title = state.run.autoWaves ? t('hud.autoOn') : t('hud.autoOff')

      const fraction = combat.maxStationHp > 0 ? combat.stationHp / combat.maxStationHp : 0
      hpFill.style.width = `${Math.max(0, Math.min(1, fraction)) * 100}%`
      hpFill.classList.toggle('low', fraction <= 0.3)
      hpText.textContent = `${formatNumber(Math.ceil(combat.stationHp))} / ${formatNumber(combat.maxStationHp)}`

      gold.textContent =
        `${t('hud.gold')} ${formatNumber(Math.floor(state.run.gold))}` +
        (onField > 0 ? ` · ${t('hud.onField', { amount: formatNumber(Math.floor(onField)) })}` : '')

      bossBar.hidden = boss === null
      if (boss) {
        const bossFraction = boss.maxHp > 0 ? boss.hp / boss.maxHp : 0
        bossName.textContent = t('hud.boss')
        bossFill.style.width = `${Math.max(0, Math.min(1, bossFraction)) * 100}%`
        bossText.textContent = `${formatNumber(Math.ceil(boss.hp))} / ${formatNumber(Math.ceil(boss.maxHp))}`
      }
    },
    detach() {
      bar.remove()
      bossBar.remove()
    },
  }
}

function button(text: string, title: string, onClick: () => void): HTMLButtonElement {
  const element = document.createElement('button')
  element.type = 'button'
  element.textContent = text
  element.title = title
  element.addEventListener('click', onClick)
  return element
}

