{
  "name": "wavebreaker-prototypes",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "description": "Isolierte Feature-Prototypen fuer WAVEBREAKER. Kein Teil des Spiels.",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "typescript": "^5.7.2",
    "vite": "^6.0.5"
  }
}

import { readdirSync, existsSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { defineConfig } from 'vite'

const root = dirname(fileURLToPath(import.meta.url))

/**
 * Jeder Unterordner mit einer index.html ist ein eigener Prototyp und wird
 * automatisch als Build-Einstiegspunkt registriert. Ordner mit fuehrendem "_"
 * (z. B. _template) werden ignoriert.
 */
function prototypeEntries(): Record<string, string> {
  const entries: Record<string, string> = { hub: resolve(root, 'index.html') }

  for (const dir of readdirSync(root, { withFileTypes: true })) {
    if (!dir.isDirectory()) continue
    if (dir.name.startsWith('_') || dir.name.startsWith('.') || dir.name === 'node_modules') continue

    const html = resolve(root, dir.name, 'index.html')
    if (existsSync(html)) entries[dir.name] = html
  }

  return entries
}

export default defineConfig({
  root,
  server: { port: 5174, open: true },
  build: {
    outDir: resolve(root, 'dist'),
    emptyOutDir: true,
    rollupOptions: { input: prototypeEntries() },
  },
})

:root {
  --bg: #070b18;
  --panel: #0e1630;
  --line: #1e2a51;
  --text: #c8d4f5;
  --dim: #6b7ba6;
  --neon: #35e0ff;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.5 "Segoe UI", system-ui, sans-serif;
}

#stage {
  display: block;
  width: 100%;
  height: 100%;
}

#hud {
  position: fixed;
  top: 12px;
  left: 12px;
  padding: 10px 14px;
  background: rgba(14, 22, 48, 0.85);
  border: 1px solid var(--line);
  border-radius: 8px;
  pointer-events: none;
  font-variant-numeric: tabular-nums;
}

/**
 * Reine Geometrie des Ansteck-Systems. Kennt weder DOM noch Canvas.
 *
 * Konvention: Alle Polygone sind regelmaessige n-Ecke mit der EINHEITLICHEN Seitenlaenge SIDE
 * und werden mit positiv orientierten Ecken erzeugt (Shoelace-Flaeche > 0). Kante i verlaeuft
 * von v[i] nach v[(i+1) % n]; die Aussennormale einer solchen Kante ist (d.y, -d.x).
 */

export type Vec2 = { x: number; y: number }
export type Edge = { a: Vec2; b: Vec2 }

/** Einheitliche Seitenlaenge aller Module. */
export const SIDE = 56

/** Toleranz fuer Kanten- und Punktvergleiche. Gleitkomma-Drift liegt um Groessenordnungen darunter. */
export const EPS = SIDE * 1e-3

// --- Vektoren --------------------------------------------------------------

export const add = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x + b.x, y: a.y + b.y })
export const sub = (a: Vec2, b: Vec2): Vec2 => ({ x: a.x - b.x, y: a.y - b.y })
export const scale = (a: Vec2, f: number): Vec2 => ({ x: a.x * f, y: a.y * f })
export const mid = (a: Vec2, b: Vec2): Vec2 => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 })
export const len = (a: Vec2): number => Math.hypot(a.x, a.y)
export const dist = (a: Vec2, b: Vec2): number => Math.hypot(a.x - b.x, a.y - b.y)

export function normalize(a: Vec2): Vec2 {
  const l = len(a)
  return l < 1e-12 ? { x: 0, y: 0 } : { x: a.x / l, y: a.y / l }
}

export const samePoint = (a: Vec2, b: Vec2, eps = EPS): boolean => dist(a, b) < eps

// --- Regelmaessige Polygone ------------------------------------------------

/** Abstand Mittelpunkt -> Kantenmitte. */
export const apothem = (n: number): number => SIDE / (2 * Math.tan(Math.PI / n))

/** Abstand Mittelpunkt -> Ecke. */
export const circumradius = (n: number): number => SIDE / (2 * Math.sin(Math.PI / n))

/** Ecken eines n-Ecks, erste Ecke bei `rotation`, danach im Winkel steigend. */
export function polygonAt(n: number, center: Vec2, rotation: number): Vec2[] {
  const r = circumradius(n)
  const out: Vec2[] = []
  for (let k = 0; k < n; k++) {
    const t = rotation + (k * 2 * Math.PI) / n
    out.push({ x: center.x + r * Math.cos(t), y: center.y + r * Math.sin(t) })
  }
  return out
}

export function edgesOf(poly: Vec2[]): Edge[] {
  return poly.map((a, i) => ({ a, b: poly[(i + 1) % poly.length]! }))
}

export function centroid(poly: Vec2[]): Vec2 {
  let x = 0
  let y = 0
  for (const p of poly) {
    x += p.x
    y += p.y
  }
  return { x: x / poly.length, y: y / poly.length }
}

/**
 * Kern des Bausystems: ein n-Eck so setzen, dass eine seiner Kanten exakt auf `edge` liegt —
 * und zwar auf der Aussenseite des Moduls, zu dem `edge` gehoert.
 *
 * Weil ein regelmaessiges n-Eck rotationssymmetrisch ist, gibt es pro Kante genau EINE
 * moegliche Platzierung. Deshalb muss der Spieler nie drehen oder feinpositionieren.
 */
export function attachTo(n: number, edge: Edge): { center: Vec2; rotation: number } {
  const d = normalize(sub(edge.b, edge.a))
  const outward: Vec2 = { x: d.y, y: -d.x }
  const center = add(mid(edge.a, edge.b), scale(outward, apothem(n)))
  // Das neue Modul muss dieselbe Kante rueckwaerts enthalten (b -> a), damit es selbst
  // positiv orientiert ist. Also liegt b auf der ersten Ecke.
  const rotation = Math.atan2(edge.b.y - center.y, edge.b.x - center.x)
  return { center, rotation }
}

// --- Kanten ----------------------------------------------------------------

/** Zwei Kanten gelten als geteilt, wenn ihre Endpunkte uebereinstimmen — Richtung egal. */
export function sameEdge(e1: Edge, e2: Edge, eps = EPS): boolean {
  return (
    (samePoint(e1.a, e2.a, eps) && samePoint(e1.b, e2.b, eps)) ||
    (samePoint(e1.a, e2.b, eps) && samePoint(e1.b, e2.a, eps))
  )
}

export function pointSegmentDistance(p: Vec2, e: Edge): number {
  const ab = sub(e.b, e.a)
  const l2 = ab.x * ab.x + ab.y * ab.y
  if (l2 < 1e-12) return dist(p, e.a)
  let t = ((p.x - e.a.x) * ab.x + (p.y - e.a.y) * ab.y) / l2
  t = Math.max(0, Math.min(1, t))
  return dist(p, add(e.a, scale(ab, t)))
}

// --- Ueberlappung und Treffer ----------------------------------------------

/** Polygon zum Mittelpunkt hin schrumpfen, damit Beruehrung nicht als Ueberlappung zaehlt. */
function erode(poly: Vec2[], factor = 0.997): Vec2[] {
  const c = centroid(poly)
  return poly.map(p => add(c, scale(sub(p, c), factor)))
}

function projectionRange(poly: Vec2[], axis: Vec2): { min: number; max: number } {
  let min = Infinity
  let max = -Infinity
  for (const p of poly) {
    const v = p.x * axis.x + p.y * axis.y
    if (v < min) min = v
    if (v > max) max = v
  }
  return { min, max }
}

/**
 * Separating-Axis-Test fuer konvexe Polygone. Beide werden zuvor minimal geschrumpft:
 * kantenbuendig angesteckte Module beruehren sich, ueberlappen aber nicht.
 */
export function polygonsOverlap(p1: Vec2[], p2: Vec2[]): boolean {
  const c1 = centroid(p1)
  const c2 = centroid(p2)
  // Grobpruefung ueber Umkreise: SIDE ist fuer alle gleich, der groesste Umkreis ist der des 6-Ecks.
  if (dist(c1, c2) > 2 * circumradius(6) + EPS) return false

  const a = erode(p1)
  const b = erode(p2)

  for (const poly of [a, b]) {
    for (let i = 0; i < poly.length; i++) {
      const p = poly[i]!
      const q = poly[(i + 1) % poly.length]!
      const axis = normalize({ x: -(q.y - p.y), y: q.x - p.x })
      const ra = projectionRange(a, axis)
      const rb = projectionRange(b, axis)
      if (ra.max < rb.min || rb.max < ra.min) return false
    }
  }
  return true
}

/** Punkt-in-Polygon fuer konvexe, positiv orientierte Polygone. */
export function pointInPolygon(p: Vec2, poly: Vec2[]): boolean {
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i]!
    const b = poly[(i + 1) % poly.length]!
    const cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x)
    if (cross < 0) return false
  }
  return true
}

/** Vorzeichenbehaftete Flaeche — positiv bei korrekter Orientierung. Nur fuer Selbsttests. */
export function signedArea(poly: Vec2[]): number {
  let sum = 0
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i]!
    const b = poly[(i + 1) % poly.length]!
    sum += a.x * b.y - b.x * a.y
  }
  return sum / 2
}

import type { Vec2 } from './geometry'

/** Tatsaechliche Grundflaeche eines Moduls — bestimmt Geometrie UND Anzahl der Anschlusskanten. */
export type FootprintSides = 3 | 4 | 5 | 6

/** Zeichen im Inneren des Moduls. Reine Optik, dient der Wiedererkennung. */
export type Emblem = 'bars' | 'triangle' | 'circle' | 'ring' | 'star' | 'chevron' | 'shield' | 'core'

export type Category = 'attack' | 'area' | 'special' | 'buff' | 'support'
export type Rarity = 'common' | 'rare' | 'epic' | 'legendary' | 'mythic'

export type StatKey = 'damage' | 'attackSpeed' | 'range' | 'critChance' | 'projectileSpeed'
export type CombatStats = Record<StatKey, number>

export type TowerDef = {
  id: string
  /** Englisch — Spielsprache laut GDD 16 §1. */
  name: string
  sides: FootprintSides
  emblem: Emblem
  category: Category
  stats: CombatStats
  /** nur bei category 'buff': Wirkung auf kantenbenachbarte Nicht-Buff-Module */
  buffs?: { stat: StatKey; amount: number }[]
  /** nur bei category 'support': stationsweite Wirkung ohne Nachbarschaftsbezug */
  stationBonus?: { stationHp?: number }
  accent: string
  description: string
}

/** Platzierung in Weltkoordinaten, abgeleitet aus der Andockkante. */
export type Placement = { center: Vec2; rotation: number }

export type TowerInstance = {
  uid: string
  defId: string
  rarity: Rarity
  /** null = im Inventar */
  placement: Placement | null
  /** abgeleitet aus placement; leer, solange das Modul im Inventar liegt */
  poly: Vec2[]
}

export type Station = {
  core: TowerInstance
  placed: TowerInstance[]
  inventory: TowerInstance[]
  /** Turmplaetze; Start 4 laut GDD 03 §6. Der Hauptturm zaehlt nicht mit. */
  slots: number
}

/**
 * Bauregeln. Reine Funktionen ueber den Zustand — die UI kennt keine Regeln.
 * Kennt weder DOM noch Canvas.
 */
import { attachTo, edgesOf, polygonAt, polygonsOverlap, sameEdge } from './geometry'
import type { Edge, Vec2 } from './geometry'
import { CORE_DEF, defOf, makeInstance, startingInventory } from './catalog'
import type { Station, TowerInstance } from './model'

export type FreeEdge = { ownerUid: string; edgeIndex: number; edge: Edge }

export type PlacementError =
  | 'overlap' // wuerde ein bestehendes Modul schneiden
  | 'no_slots' // Turmplatz-Limit erreicht
  | 'not_owned' // Turm nicht im Inventar
  | 'no_edge' // keine Andockkante getroffen

export const ERROR_TEXT: Record<PlacementError, string> = {
  overlap: 'Kein Platz — wuerde ein Modul schneiden',
  no_slots: 'Alle Turmplaetze belegt',
  not_owned: 'Turm nicht im Inventar',
  no_edge: 'Keine Andockkante in der Naehe',
}

/** Drehung des Hauptturms: Ecke oben, dadurch flache Kanten links und rechts. */
const CORE_ROTATION = Math.PI / 6

export function createStation(slots = 4): Station {
  const core = makeInstance(CORE_DEF.id, 'legendary')
  core.placement = { center: { x: 0, y: 0 }, rotation: CORE_ROTATION }
  core.poly = polygonAt(CORE_DEF.sides, core.placement.center, core.placement.rotation)
  return { core, placed: [], inventory: startingInventory(), slots }
}

/** Hauptturm und alle angebauten Module. */
export function allModules(st: Station): TowerInstance[] {
  return [st.core, ...st.placed]
}

export function findModule(st: Station, uid: string): TowerInstance | undefined {
  return allModules(st).find(m => m.uid === uid)
}

/** Belegte Turmplaetze — der Hauptturm zaehlt nicht mit (GDD 03 §6). */
export const usedSlots = (st: Station): number => st.placed.length

/**
 * Alle Kanten ohne deckungsgleiche Gegenkante. Das sind zugleich die moeglichen
 * Bauplaetze, die laut GDD 13 §12 hervorgehoben werden.
 */
export function freeEdges(st: Station, ignoreUid?: string): FreeEdge[] {
  const mods = allModules(st).filter(m => m.uid !== ignoreUid)
  const all: FreeEdge[] = []
  for (const m of mods) {
    edgesOf(m.poly).forEach((edge, edgeIndex) => all.push({ ownerUid: m.uid, edgeIndex, edge }))
  }
  return all.filter(
    fe => !all.some(other => other.ownerUid !== fe.ownerUid && sameEdge(other.edge, fe.edge)),
  )
}

/** Geometrie, die ein Modul an dieser Kante haette. */
export function previewPolygon(defId: string, at: FreeEdge): { poly: Vec2[]; center: Vec2; rotation: number } {
  const def = defOf(defId)
  const { center, rotation } = attachTo(def.sides, at.edge)
  return { poly: polygonAt(def.sides, center, rotation), center, rotation }
}

export function canPlace(
  st: Station,
  defId: string,
  at: FreeEdge,
  ignoreUid?: string,
): PlacementError | null {
  if (ignoreUid === undefined && usedSlots(st) >= st.slots) return 'no_slots'

  const { poly } = previewPolygon(defId, at)
  for (const m of allModules(st)) {
    if (m.uid === ignoreUid) continue
    if (polygonsOverlap(poly, m.poly)) return 'overlap'
  }
  return null
}

/** Platziert eine Instanz aus dem Inventar. Ruft KEINE Pruefung auf — vorher `canPlace`. */
export function place(st: Station, uid: string, at: FreeEdge): PlacementError | null {
  const idx = st.inventory.findIndex(t => t.uid === uid)
  if (idx < 0) return 'not_owned'
  const inst = st.inventory[idx]!

  const err = canPlace(st, inst.defId, at)
  if (err) return err

  const { poly, center, rotation } = previewPolygon(inst.defId, at)
  inst.placement = { center, rotation }
  inst.poly = poly
  st.inventory.splice(idx, 1)
  st.placed.push(inst)
  return null
}

/** Kantennachbarn eines Moduls — Grundlage des Buff-Systems (ab M5). */
export function neighbors(st: Station, uid: string): TowerInstance[] {
  const self = findModule(st, uid)
  if (!self) return []
  const own = edgesOf(self.poly)
  return allModules(st).filter(
    m => m.uid !== uid && edgesOf(m.poly).some(e => own.some(o => sameEdge(o, e))),
  )
}

/**
 * Trennung von Grundflaeche und Optik:
 *  - Footprint (3/4/5/6 Kanten) = Geometrie und Anzahl der Anschlusskanten, echte Mechanik
 *  - Emblem                     = Zeichen im Inneren, reine Wiedererkennung
 *
 * Damit lassen sich die GDD-Formen "Kreis" und "Spezialform" darstellen, ohne die
 * Ansteck-Geometrie zu brechen (siehe PLAN.md, Abschnitt 4.3).
 */
import type { Emblem, FootprintSides } from './model'
import type { Vec2 } from './geometry'

export const SHAPE_GLYPH: Record<FootprintSides, string> = {
  3: '▲',
  4: '■',
  5: '⬟',
  6: '⬢',
}

export const SHAPE_NAME: Record<FootprintSides, string> = {
  3: 'Dreieck',
  4: 'Viereck',
  5: 'Fuenfeck',
  6: 'Hexagon',
}

export function drawEmblem(
  ctx: CanvasRenderingContext2D,
  emblem: Emblem,
  c: Vec2,
  r: number,
  color: string,
): void {
  ctx.save()
  ctx.strokeStyle = color
  ctx.fillStyle = color
  ctx.lineWidth = Math.max(1, r * 0.14)
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'

  switch (emblem) {
    case 'bars': {
      const n = 3
      const gap = (r * 1.5) / (n - 1)
      for (let i = 0; i < n; i++) {
        const x = c.x - r * 0.75 + i * gap
        ctx.beginPath()
        ctx.moveTo(x, c.y - r * 0.7)
        ctx.lineTo(x, c.y + r * 0.7)
        ctx.stroke()
      }
      break
    }
    case 'triangle': {
      ctx.beginPath()
      for (let i = 0; i < 3; i++) {
        const t = -Math.PI / 2 + (i * 2 * Math.PI) / 3
        const p = { x: c.x + r * Math.cos(t), y: c.y + r * Math.sin(t) }
        i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)
      }
      ctx.closePath()
      ctx.stroke()
      break
    }
    case 'circle': {
      ctx.beginPath()
      ctx.arc(c.x, c.y, r * 0.75, 0, Math.PI * 2)
      ctx.fill()
      break
    }
    case 'ring': {
      ctx.beginPath()
      ctx.arc(c.x, c.y, r * 0.75, 0, Math.PI * 2)
      ctx.stroke()
      ctx.beginPath()
      ctx.arc(c.x, c.y, r * 0.22, 0, Math.PI * 2)
      ctx.fill()
      break
    }
    case 'star': {
      ctx.beginPath()
      for (let i = 0; i < 8; i++) {
        const t = -Math.PI / 2 + (i * Math.PI) / 4
        const rad = i % 2 === 0 ? r : r * 0.4
        const p = { x: c.x + rad * Math.cos(t), y: c.y + rad * Math.sin(t) }
        i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)
      }
      ctx.closePath()
      ctx.stroke()
      break
    }
    case 'chevron': {
      for (let i = 0; i < 2; i++) {
        const dy = -r * 0.35 + i * r * 0.7
        ctx.beginPath()
        ctx.moveTo(c.x - r * 0.7, dy + c.y + r * 0.3)
        ctx.lineTo(c.x, dy + c.y - r * 0.3)
        ctx.lineTo(c.x + r * 0.7, dy + c.y + r * 0.3)
        ctx.stroke()
      }
      break
    }
    case 'shield': {
      ctx.beginPath()
      ctx.moveTo(c.x, c.y - r)
      ctx.lineTo(c.x + r * 0.8, c.y - r * 0.45)
      ctx.lineTo(c.x + r * 0.8, c.y + r * 0.25)
      ctx.lineTo(c.x, c.y + r)
      ctx.lineTo(c.x - r * 0.8, c.y + r * 0.25)
      ctx.lineTo(c.x - r * 0.8, c.y - r * 0.45)
      ctx.closePath()
      ctx.stroke()
      break
    }
    case 'core': {
      ctx.beginPath()
      ctx.arc(c.x, c.y, r * 0.9, 0, Math.PI * 2)
      ctx.stroke()
      ctx.beginPath()
      ctx.arc(c.x, c.y, r * 0.5, 0, Math.PI * 2)
      ctx.stroke()
      ctx.beginPath()
      ctx.arc(c.x, c.y, r * 0.18, 0, Math.PI * 2)
      ctx.fill()
      break
    }
  }
  ctx.restore()
}

/**
 * Auto-Zoom: Die Station bleibt immer komplett im Bild (GDD 13 §4).
 * Der Zoom springt nicht, sondern naehert sich exponentiell an.
 */
import type { Vec2 } from './geometry'

export type Camera = {
  center: Vec2
  zoom: number
  targetCenter: Vec2
  targetZoom: number
  /** true, sobald der Spieler manuell gezoomt hat — dann kein Auto-Fit mehr, bis F gedrueckt wird */
  manual: boolean
}

export const createCamera = (): Camera => ({
  center: { x: 0, y: 0 },
  zoom: 1,
  targetCenter: { x: 0, y: 0 },
  targetZoom: 1,
  manual: false,
})

const MIN_ZOOM = 0.25
const MAX_ZOOM = 2.2

export function fitTo(cam: Camera, polys: Vec2[][], viewW: number, viewH: number, margin = 90): void {
  if (cam.manual || polys.length === 0 || viewW < 1 || viewH < 1) return

  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  for (const poly of polys) {
    for (const p of poly) {
      if (p.x < minX) minX = p.x
      if (p.y < minY) minY = p.y
      if (p.x > maxX) maxX = p.x
      if (p.y > maxY) maxY = p.y
    }
  }

  const w = maxX - minX + margin * 2
  const h = maxY - minY + margin * 2
  cam.targetCenter = { x: (minX + maxX) / 2, y: (minY + maxY) / 2 }
  cam.targetZoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, Math.min(viewW / w, viewH / h)))
}

export function step(cam: Camera, dt: number): void {
  const k = 1 - Math.exp(-8 * dt) // rahmenratenunabhaengige Annaeherung
  cam.center.x += (cam.targetCenter.x - cam.center.x) * k
  cam.center.y += (cam.targetCenter.y - cam.center.y) * k
  cam.zoom += (cam.targetZoom - cam.zoom) * k
}

export function zoomBy(cam: Camera, factor: number): void {
  cam.manual = true
  cam.targetZoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, cam.targetZoom * factor))
}

export function resetAuto(cam: Camera): void {
  cam.manual = false
}

export const worldToScreen = (cam: Camera, p: Vec2, viewW: number, viewH: number): Vec2 => ({
  x: (p.x - cam.center.x) * cam.zoom + viewW / 2,
  y: (p.y - cam.center.y) * cam.zoom + viewH / 2,
})

export const screenToWorld = (cam: Camera, p: Vec2, viewW: number, viewH: number): Vec2 => ({
  x: (p.x - viewW / 2) / cam.zoom + cam.center.x,
  y: (p.y - viewH / 2) / cam.zoom + cam.center.y,
})

/** Zustand des Prototyps. Bewusst flach und ohne Framework. */
import type { Vec2 } from './geometry'
import type { Station } from './model'
import type { FreeEdge, PlacementError } from './station'
import { createStation, freeEdges } from './station'

export type Ghost = { poly: Vec2[]; error: PlacementError | null }

export type AppState = {
  station: Station
  /** Cache der freien Kanten; nach jeder Aenderung ueber refresh() erneuert */
  free: FreeEdge[]
  /** gewaehlte Inventar-Instanz = Bau-Modus aktiv */
  buildUid: string | null
  hoverEdge: FreeEdge | null
  ghost: Ghost | null
  selectedUid: string | null
  showEdgeDebug: boolean
  message: string | null
  messageUntil: number
  time: number
}

export function createApp(): AppState {
  const station = createStation(4)
  return {
    station,
    free: freeEdges(station),
    buildUid: null,
    hoverEdge: null,
    ghost: null,
    selectedUid: null,
    showEdgeDebug: false,
    message: null,
    messageUntil: 0,
    time: 0,
  }
}

/** Nach jeder Zustandsaenderung aufrufen: freie Kanten neu bestimmen. */
export function refresh(app: AppState): void {
  app.free = freeEdges(app.station)
}

export function notify(app: AppState, text: string, seconds = 2.5): void {
  app.message = text
  app.messageUntil = app.time + seconds
}

/**
 * Canvas-Zeichnung. Der praegende Look entsteht aus den hellen Fugen zwischen den Modulen
 * (geteilte Kanten), nicht aus den Fuellflaechen — siehe Zielskizze.
 */
import { circumradius, edgesOf } from './geometry'
import type { Vec2 } from './geometry'
import { defOf, RARITY_COLOR } from './catalog'
import { drawEmblem } from './shapes'
import type { TowerInstance } from './model'
import { allModules } from './station'
import type { AppState } from './app'
import type { Camera } from './camera'
import { worldToScreen } from './camera'

const BG_TOP = '#0d1531'
const BG_BOTTOM = '#05080f'
const FILL = '#161f3d'
const FILL_CORE = '#1d2a53'
const EDGE_SHARED = '#93a3e0'
const EDGE_FREE = '#2b3767'

function path(ctx: CanvasRenderingContext2D, pts: Vec2[]): void {
  ctx.beginPath()
  pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)))
  ctx.closePath()
}

function toScreen(cam: Camera, poly: Vec2[], w: number, h: number): Vec2[] {
  return poly.map(p => worldToScreen(cam, p, w, h))
}

function inset(poly: Vec2[], factor: number): Vec2[] {
  const c = poly.reduce((s, p) => ({ x: s.x + p.x / poly.length, y: s.y + p.y / poly.length }), {
    x: 0,
    y: 0,
  })
  return poly.map(p => ({ x: c.x + (p.x - c.x) * factor, y: c.y + (p.y - c.y) * factor }))
}

function drawBackground(ctx: CanvasRenderingContext2D, w: number, h: number): void {
  const g = ctx.createLinearGradient(0, 0, 0, h)
  g.addColorStop(0, BG_TOP)
  g.addColorStop(1, BG_BOTTOM)
  ctx.fillStyle = g
  ctx.fillRect(0, 0, w, h)

  ctx.strokeStyle = 'rgba(120,150,255,0.04)'
  ctx.lineWidth = 1
  const step = 64
  ctx.beginPath()
  for (let x = 0; x < w; x += step) {
    ctx.moveTo(x + 0.5, 0)
    ctx.lineTo(x + 0.5, h)
  }
  for (let y = 0; y < h; y += step) {
    ctx.moveTo(0, y + 0.5)
    ctx.lineTo(w, y + 0.5)
  }
  ctx.stroke()
}

function drawModule(
  ctx: CanvasRenderingContext2D,
  app: AppState,
  cam: Camera,
  w: number,
  h: number,
  inst: TowerInstance,
  isCore: boolean,
): void {
  const def = defOf(inst.defId)
  const pts = toScreen(cam, inst.poly, w, h)
  const center = worldToScreen(cam, inst.placement!.center, w, h)

  path(ctx, pts)
  ctx.fillStyle = isCore ? FILL_CORE : FILL
  ctx.fill()

  // Raritaetsrahmen leicht nach innen versetzt, damit die Fugen davon unberuehrt bleiben
  path(ctx, inset(pts, 0.86))
  ctx.strokeStyle = RARITY_COLOR[inst.rarity]
  ctx.lineWidth = isCore ? 2.2 : 1.4
  ctx.shadowColor = RARITY_COLOR[inst.rarity]
  ctx.shadowBlur = isCore ? 14 : 7
  ctx.stroke()
  ctx.shadowBlur = 0

  const r = circumradius(def.sides) * cam.zoom * 0.32
  drawEmblem(ctx, def.emblem, center, r, def.accent)

  if (app.selectedUid === inst.uid) {
    path(ctx, inset(pts, 0.95))
    ctx.strokeStyle = '#ffffff'
    ctx.lineWidth = 1.5
    ctx.setLineDash([5, 4])
    ctx.stroke()
    ctx.setLineDash([])
  }
}

/** Kanten aller Module: geteilte hell (Fuge), freie dunkel (Aussenkontur). */
function drawEdges(
  ctx: CanvasRenderingContext2D,
  app: AppState,
  cam: Camera,
  w: number,
  h: number,
): void {
  const freeKeys = new Set(app.free.map(f => `${f.ownerUid}:${f.edgeIndex}`))

  for (const m of allModules(app.station)) {
    edgesOf(m.poly).forEach((e, i) => {
      const isFree = freeKeys.has(`${m.uid}:${i}`)
      const a = worldToScreen(cam, e.a, w, h)
      const b = worldToScreen(cam, e.b, w, h)
      ctx.beginPath()
      ctx.moveTo(a.x, a.y)
      ctx.lineTo(b.x, b.y)
      ctx.strokeStyle = isFree ? EDGE_FREE : EDGE_SHARED
      ctx.lineWidth = isFree ? 1.2 : 2
      if (!isFree) {
        ctx.shadowColor = 'rgba(147,163,224,0.7)'
        ctx.shadowBlur = 6
      }
      ctx.stroke()
      ctx.shadowBlur = 0
    })
  }
}

function drawBuildHints(
  ctx: CanvasRenderingContext2D,
  app: AppState,
  cam: Camera,
  w: number,
  h: number,
): void {
  const pulse = 0.5 + 0.5 * Math.sin(app.time * 4)

  for (const fe of app.free) {
    const a = worldToScreen(cam, fe.edge.a, w, h)
    const b = worldToScreen(cam, fe.edge.b, w, h)
    const active = app.hoverEdge?.ownerUid === fe.ownerUid && app.hoverEdge.edgeIndex === fe.edgeIndex
    ctx.beginPath()
    ctx.moveTo(a.x, a.y)
    ctx.lineTo(b.x, b.y)
    ctx.strokeStyle = active ? '#7cf3ff' : `rgba(124,243,255,${0.18 + 0.22 * pulse})`
    ctx.lineWidth = active ? 3.5 : 2
    ctx.setLineDash(active ? [] : [7, 5])
    ctx.stroke()
    ctx.setLineDash([])
  }

  if (app.ghost) {
    const pts = toScreen(cam, app.ghost.poly, w, h)
    const ok = app.ghost.error === null
    path(ctx, pts)
    ctx.fillStyle = ok ? 'rgba(61,220,132,0.16)' : 'rgba(255,59,107,0.16)'
    ctx.fill()
    ctx.strokeStyle = ok ? '#3ddc84' : '#ff3b6b'
    ctx.lineWidth = 2
    ctx.setLineDash([6, 4])
    ctx.stroke()
    ctx.setLineDash([])
  }
}

function drawEdgeDebug(
  ctx: CanvasRenderingContext2D,
  app: AppState,
  cam: Camera,
  w: number,
  h: number,
): void {
  ctx.font = '10px monospace'
  ctx.fillStyle = '#7cf3ff'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  for (const fe of app.free) {
    const m = { x: (fe.edge.a.x + fe.edge.b.x) / 2, y: (fe.edge.a.y + fe.edge.b.y) / 2 }
    const s = worldToScreen(cam, m, w, h)
    ctx.fillText(String(fe.edgeIndex), s.x, s.y)
  }
}

export function render(
  ctx: CanvasRenderingContext2D,
  app: AppState,
  cam: Camera,
  w: number,
  h: number,
): void {
  drawBackground(ctx, w, h)

  for (const m of allModules(app.station)) {
    drawModule(ctx, app, cam, w, h, m, m.uid === app.station.core.uid)
  }
  drawEdges(ctx, app, cam, w, h)

  if (app.buildUid) drawBuildHints(ctx, app, cam, w, h)
  if (app.showEdgeDebug) drawEdgeDebug(ctx, app, cam, w, h)
}

/**
 * Maus und Tastatur -> Aktionen.
 *
 * Kernentscheidung: Der Spieler zielt nicht auf eine Zelle, sondern auf eine KANTE.
 * Das Ghost-Modul springt von Kante zu Kante — dieses Springen ist das "Einrasten"
 * aus GDD 03 §4 und der wichtigste Punkt am Baugefuehl (offene Frage F1).
 */
import { pointInPolygon, pointSegmentDistance, SIDE } from './geometry'
import type { Vec2 } from './geometry'
import { defOf } from './catalog'
import { allModules, canPlace, place, previewPolygon } from './station'
import type { FreeEdge } from './station'
import { ERROR_TEXT } from './station'
import type { AppState } from './app'
import { notify, refresh } from './app'
import type { Camera } from './camera'
import { resetAuto, screenToWorld, zoomBy } from './camera'

/** Maximale Entfernung des Zeigers zu einer Kante, bis zu der noch angedockt wird. */
const SNAP_RADIUS = SIDE * 2.5

function nearestFreeEdge(p: Vec2, edges: FreeEdge[]): FreeEdge | null {
  let best: FreeEdge | null = null
  let bestDist = SNAP_RADIUS
  for (const fe of edges) {
    const d = pointSegmentDistance(p, fe.edge)
    if (d < bestDist) {
      bestDist = d
      best = fe
    }
  }
  return best
}

function updateGhost(app: AppState, world: Vec2): void {
  if (!app.buildUid) {
    app.hoverEdge = null
    app.ghost = null
    return
  }
  const inst = app.station.inventory.find(t => t.uid === app.buildUid)
  if (!inst) {
    app.buildUid = null
    app.hoverEdge = null
    app.ghost = null
    return
  }

  const edge = nearestFreeEdge(world, app.free)
  app.hoverEdge = edge
  if (!edge) {
    app.ghost = null
    return
  }

  const { poly } = previewPolygon(inst.defId, edge)
  app.ghost = { poly, error: canPlace(app.station, inst.defId, edge) }
}

export function attachInput(
  canvas: HTMLCanvasElement,
  app: AppState,
  cam: Camera,
  view: () => { w: number; h: number },
  onChange: () => void,
): void {
  const worldAt = (ev: MouseEvent): Vec2 => {
    const rect = canvas.getBoundingClientRect()
    const { w, h } = view()
    return screenToWorld(cam, { x: ev.clientX - rect.left, y: ev.clientY - rect.top }, w, h)
  }

  canvas.addEventListener('mousemove', ev => updateGhost(app, worldAt(ev)))

  canvas.addEventListener('mouseleave', () => {
    app.hoverEdge = null
    app.ghost = null
  })

  canvas.addEventListener('click', ev => {
    const world = worldAt(ev)

    if (app.buildUid) {
      updateGhost(app, world)
      if (!app.hoverEdge || !app.ghost) {
        notify(app, ERROR_TEXT.no_edge)
        return
      }
      if (app.ghost.error) {
        notify(app, ERROR_TEXT[app.ghost.error])
        return
      }
      const inst = app.station.inventory.find(t => t.uid === app.buildUid)!
      const err = place(app.station, app.buildUid, app.hoverEdge)
      if (err) {
        notify(app, ERROR_TEXT[err])
        return
      }
      notify(app, `${defOf(inst.defId).name} angedockt`)
      app.buildUid = null
      app.ghost = null
      app.hoverEdge = null
      app.selectedUid = inst.uid
      refresh(app)
      onChange()
      return
    }

    // Auswahl
    const hit = allModules(app.station).find(m => pointInPolygon(world, m.poly))
    app.selectedUid = hit ? hit.uid : null
    onChange()
  })

  canvas.addEventListener('contextmenu', ev => {
    ev.preventDefault()
    if (app.buildUid) {
      app.buildUid = null
      app.ghost = null
      app.hoverEdge = null
      notify(app, 'Bau-Modus verlassen')
      onChange()
    }
  })

  canvas.addEventListener(
    'wheel',
    ev => {
      ev.preventDefault()
      zoomBy(cam, ev.deltaY < 0 ? 1.12 : 1 / 1.12)
    },
    { passive: false },
  )

  window.addEventListener('keydown', ev => {
    switch (ev.key) {
      case 'Escape':
        if (app.buildUid) {
          app.buildUid = null
          app.ghost = null
          app.hoverEdge = null
          onChange()
        }
        break
      case 'e':
      case 'E':
        app.showEdgeDebug = !app.showEdgeDebug
        onChange()
        break
      case 'f':
      case 'F':
        resetAuto(cam)
        notify(app, 'Auto-Zoom aktiv')
        break
    }
  })
}

/** Inventarliste, HUD und Debug-Panel. Kennt keine Bauregeln. */
import { defOf, RARITY_COLOR, RARITY_LABEL } from './catalog'
import { SHAPE_GLYPH, SHAPE_NAME } from './shapes'
import { neighbors, usedSlots } from './station'
import type { AppState } from './app'

export type UiActions = {
  pick(uid: string): void
  setSlots(n: number): void
  reset(): void
  runTests(): void
}

const el = <T extends HTMLElement>(sel: string): T => document.querySelector<T>(sel)!

export function mountUI(app: AppState, actions: UiActions): () => void {
  const invList = el<HTMLDivElement>('#invList')
  const hud = el<HTMLDivElement>('#hud')
  const detail = el<HTMLDivElement>('#detail')
  const toast = el<HTMLDivElement>('#toast')
  const slotsInput = el<HTMLInputElement>('#slots')
  const slotsValue = el<HTMLSpanElement>('#slotsValue')

  slotsInput.value = String(app.station.slots)
  slotsInput.addEventListener('input', () => actions.setSlots(Number(slotsInput.value)))
  el<HTMLButtonElement>('#reset').addEventListener('click', () => actions.reset())
  el<HTMLButtonElement>('#selftest').addEventListener('click', () => actions.runTests())

  function renderInventory(): void {
    invList.innerHTML = ''
    if (app.station.inventory.length === 0) {
      invList.innerHTML = '<p class="empty">Inventar leer</p>'
      return
    }

    for (const inst of app.station.inventory) {
      const def = defOf(inst.defId)
      const card = document.createElement('button')
      card.className = 'invCard' + (app.buildUid === inst.uid ? ' active' : '')
      card.style.setProperty('--rarity', RARITY_COLOR[inst.rarity])
      card.innerHTML = `
        <span class="glyph" style="color:${def.accent}">${SHAPE_GLYPH[def.sides]}</span>
        <span class="body">
          <span class="name">${def.name}</span>
          <span class="meta">${RARITY_LABEL[inst.rarity]} · ${SHAPE_NAME[def.sides]} · ${def.sides} Kanten</span>
        </span>`
      card.title = def.description
      card.addEventListener('click', () => actions.pick(inst.uid))
      invList.appendChild(card)
    }
  }

  function renderDetail(): void {
    const uid = app.selectedUid
    if (!uid) {
      detail.innerHTML = '<p class="empty">Kein Modul ausgewaehlt</p>'
      return
    }
    const inst = [app.station.core, ...app.station.placed].find(m => m.uid === uid)
    if (!inst) {
      detail.innerHTML = '<p class="empty">Kein Modul ausgewaehlt</p>'
      return
    }
    const def = defOf(inst.defId)
    const nb = neighbors(app.station, uid)
    detail.innerHTML = `
      <div class="detailHead" style="--rarity:${RARITY_COLOR[inst.rarity]}">
        <span class="glyph" style="color:${def.accent}">${SHAPE_GLYPH[def.sides]}</span>
        <span>
          <strong>${def.name}</strong><br>
          <span class="meta">${RARITY_LABEL[inst.rarity]} · ${SHAPE_NAME[def.sides]}</span>
        </span>
      </div>
      <p class="desc">${def.description}</p>
      <dl>
        <dt>Nachbarn</dt><dd>${nb.length} / ${def.sides}</dd>
        <dt>Schaden</dt><dd>${def.stats.damage}</dd>
        <dt>Angriffstempo</dt><dd>${def.stats.attackSpeed}/s</dd>
        <dt>Reichweite</dt><dd>${def.stats.range}</dd>
      </dl>
      <p class="hint">Effektivwerte und Buffs folgen in M5.</p>`
  }

  function renderHud(): void {
    const st = app.station
    const mode = app.buildUid
      ? `Bau-Modus: ${defOf(st.inventory.find(t => t.uid === app.buildUid)!.defId).name}`
      : 'Auswahl-Modus'
    hud.innerHTML = `
      <span>Plaetze <b>${usedSlots(st)}/${st.slots}</b></span>
      <span>Module <b>${st.placed.length + 1}</b></span>
      <span>freie Kanten <b>${app.free.length}</b></span>
      <span>Inventar <b>${st.inventory.length}</b></span>
      <span class="mode">${mode}</span>`
  }

  function renderToast(): void {
    const active = app.message !== null && app.time < app.messageUntil
    toast.textContent = active ? app.message! : ''
    toast.classList.toggle('visible', active)
  }

  function update(): void {
    slotsValue.textContent = String(app.station.slots)
    renderInventory()
    renderDetail()
    renderHud()
    renderToast()
  }

  update()
  return update
}

export function showTestResults(results: { name: string; ok: boolean; info?: string }[]): void {
  const out = el<HTMLDivElement>('#testOut')
  const failed = results.filter(r => !r.ok)
  out.innerHTML =
    `<p class="${failed.length ? 'bad' : 'good'}">${results.length - failed.length}/${results.length} bestanden</p>` +
    results
      .map(r => `<div class="${r.ok ? 'good' : 'bad'}">${r.ok ? '✓' : '✗'} ${r.name}${r.info ? ` — ${r.info}` : ''}</div>`)
      .join('')
}

/**
 * Zusicherungen fuer die reinen Funktionen — dort, wo Fehler still bleiben.
 * Kein Testframework: Aufruf ueber ?selftest in der Adresszeile oder den Knopf im Debug-Panel.
 */
import {
  apothem,
  attachTo,
  dist,
  edgesOf,
  EPS,
  polygonAt,
  polygonsOverlap,
  sameEdge,
  signedArea,
  SIDE,
} from './geometry'
import type { Vec2 } from './geometry'
import { CORE_DEF, makeInstance } from './catalog'
import { canPlace, createStation, freeEdges, neighbors, place, previewPolygon } from './station'
import type { Station } from './model'

export type TestResult = { name: string; ok: boolean; info?: string }

const results: TestResult[] = []

function check(name: string, fn: () => string | void): void {
  try {
    const info = fn()
    results.push({ name, ok: true, ...(info ? { info } : {}) })
  } catch (e) {
    results.push({ name, ok: false, info: e instanceof Error ? e.message : String(e) })
  }
}

function assert(cond: boolean, msg: string): void {
  if (!cond) throw new Error(msg)
}

const corePoly = (): Vec2[] => polygonAt(CORE_DEF.sides, { x: 0, y: 0 }, Math.PI / 6)

/** Modul der Groesse n an Kante `edgeIndex` des Hauptturms — reine Geometrie, ohne Station. */
function attachedTo(n: number, poly: Vec2[], edgeIndex: number): Vec2[] {
  const edge = edgesOf(poly)[edgeIndex]!
  const { center, rotation } = attachTo(n, edge)
  return polygonAt(n, center, rotation)
}

function give(st: Station, defId: string): string {
  const inst = makeInstance(defId, 'common')
  st.inventory.push(inst)
  return inst.uid
}

export function runSelfTests(): TestResult[] {
  results.length = 0

  // --- Geometrie -----------------------------------------------------------

  check('apothem(6) = SIDE·√3/2', () => {
    assert(Math.abs(apothem(6) - (SIDE * Math.sqrt(3)) / 2) < 1e-9, `${apothem(6)}`)
  })

  check('polygonAt: alle Seiten haben Laenge SIDE (n=3..6)', () => {
    for (let n = 3; n <= 6; n++) {
      const poly = polygonAt(n, { x: 13, y: -7 }, 0.4)
      for (const e of edgesOf(poly)) {
        assert(Math.abs(dist(e.a, e.b) - SIDE) < 1e-9, `n=${n}: ${dist(e.a, e.b)}`)
      }
    }
  })

  check('polygonAt: positiv orientiert (n=3..6)', () => {
    for (let n = 3; n <= 6; n++) {
      assert(signedArea(polygonAt(n, { x: 0, y: 0 }, 1.1)) > 0, `n=${n}`)
    }
  })

  check('attachTo: angedocktes Modul enthaelt die Andockkante (n=3..6)', () => {
    const core = corePoly()
    const edge = edgesOf(core)[0]!
    for (let n = 3; n <= 6; n++) {
      const poly = attachedTo(n, core, 0)
      assert(edgesOf(poly).some(e => sameEdge(e, edge)), `n=${n}`)
    }
  })

  check('attachTo: Beruehrung zaehlt nicht als Ueberlappung (n=3..6)', () => {
    const core = corePoly()
    for (let n = 3; n <= 6; n++) {
      assert(!polygonsOverlap(attachedTo(n, core, 0), core), `n=${n}`)
    }
  })

  check('Zwei Hexagone an benachbarten Core-Kanten teilen selbst eine Kante', () => {
    const core = corePoly()
    const a = attachedTo(6, core, 0)
    const b = attachedTo(6, core, 1)
    assert(!polygonsOverlap(a, b), 'ueberlappen sich')
    assert(
      edgesOf(a).some(ea => edgesOf(b).some(eb => sameEdge(ea, eb))),
      'keine gemeinsame Kante gefunden',
    )
  })

  check('Zwei Vierecke an benachbarten Core-Kanten teilen nur eine Ecke', () => {
    const core = corePoly()
    const a = attachedTo(4, core, 0)
    const b = attachedTo(4, core, 1)
    assert(!polygonsOverlap(a, b), 'ueberlappen sich')
    assert(
      !edgesOf(a).some(ea => edgesOf(b).some(eb => sameEdge(ea, eb))),
      'duerfen keine Kante teilen',
    )
    assert(
      a.some(pa => b.some(pb => dist(pa, pb) < EPS)),
      'muessen eine Ecke teilen',
    )
  })

  check('Sechs Dreiecke an allen Core-Kanten ueberlappen nicht', () => {
    const core = corePoly()
    const tris = [0, 1, 2, 3, 4, 5].map(i => attachedTo(3, core, i))
    for (let i = 0; i < tris.length; i++) {
      for (let j = i + 1; j < tris.length; j++) {
        assert(!polygonsOverlap(tris[i]!, tris[j]!), `${i} und ${j} ueberlappen`)
      }
    }
  })

  // --- Bauregeln -----------------------------------------------------------

  check('Hauptturm hat anfangs genau 6 freie Kanten', () => {
    assert(freeEdges(createStation()).length === 6, `${freeEdges(createStation()).length}`)
  })

  check('Ein angedocktes n-Eck aendert die freien Kanten um n-2', () => {
    for (const [defId, n] of [
      ['marksman', 3],
      ['autocannon', 4],
      ['rate_amplifier', 5],
      ['bulwark', 6],
    ] as const) {
      const st = createStation(10)
      const before = freeEdges(st).length
      const uid = give(st, defId)
      const err = place(st, uid, freeEdges(st)[0]!)
      assert(err === null, `${defId}: ${err}`)
      const after = freeEdges(st).length
      assert(after === before + n - 2, `${defId}: ${before} -> ${after}, erwartet ${before + n - 2}`)
    }
  })

  check('Platzierung in einen zu engen Keil liefert "overlap"', () => {
    const st = createStation(10)
    // Zwei Vierecke an benachbarten Core-Kanten lassen einen 60°-Keil offen.
    place(st, give(st, 'autocannon'), freeEdges(st)[0]!)
    const edgeNextToCore = freeEdges(st).find(f => f.ownerUid === st.core.uid)!
    place(st, give(st, 'autocannon'), edgeNextToCore)
    // Ein Hexagon (120°) passt dort nicht mehr hinein.
    const blocked = freeEdges(st).filter(f => canPlace(st, 'bulwark', f) === 'overlap')
    assert(blocked.length > 0, 'keine einzige Kante wurde als overlap erkannt')
    return `${blocked.length} Kanten blockiert`
  })

  check('Platzlimit liefert "no_slots"', () => {
    const st = createStation(1)
    assert(place(st, give(st, 'autocannon'), freeEdges(st)[0]!) === null, 'erste Platzierung')
    assert(canPlace(st, 'autocannon', freeEdges(st)[0]!) === 'no_slots', 'zweite muss abgelehnt werden')
  })

  check('Platziertes Modul ist Kantennachbar des Hauptturms', () => {
    const st = createStation(4)
    const uid = give(st, 'autocannon')
    place(st, uid, freeEdges(st)[0]!)
    const nb = neighbors(st, uid)
    assert(nb.length === 1 && nb[0]!.uid === st.core.uid, `Nachbarn: ${nb.length}`)
  })

  check('Platziertes Modul verlaesst das Inventar genau einmal', () => {
    const st = createStation(4)
    const uid = give(st, 'autocannon')
    const before = st.inventory.length
    place(st, uid, freeEdges(st)[0]!)
    assert(st.inventory.length === before - 1, 'Inventarzahl')
    assert(!st.inventory.some(t => t.uid === uid), 'noch im Inventar')
    assert(st.placed.filter(t => t.uid === uid).length === 1, 'nicht genau einmal platziert')
  })

  check('previewPolygon liefert dieselbe Geometrie wie die Platzierung', () => {
    const st = createStation(4)
    const uid = give(st, 'siege_cannon')
    const edge = freeEdges(st)[2]!
    const preview = previewPolygon('siege_cannon', edge).poly
    place(st, uid, edge)
    const placed = st.placed.find(t => t.uid === uid)!
    for (let i = 0; i < preview.length; i++) {
      assert(dist(preview[i]!, placed.poly[i]!) < 1e-9, `Ecke ${i} weicht ab`)
    }
  })

  return [...results]
}

