/**
 * Prototyp 01 — Turmbau, Etappen M0–M3.
 *
 * Enthalten: Geometrie, Katalog, Inventar, Andocken an freie Kanten.
 * Noch nicht enthalten: Entfernen/Verschieben (M4), Buffs (M5), Politur (M6), Persistenz (M7).
 */
import { createApp, notify, refresh } from './app'
import { createCamera, fitTo, step } from './camera'
import { attachInput } from './input'
import { render } from './render'
import { allModules } from './station'
import { mountUI, showTestResults, updateToast } from './ui'
import { runSelfTests } from './selftest'
import { createStation } from './station'

const TICK_HZ = 60
const TICK_MS = 1000 / TICK_HZ
const MAX_CATCHUP_TICKS = 5

const canvas = document.querySelector<HTMLCanvasElement>('#stage')!
const ctx = canvas.getContext('2d')!

let viewW = 0
let viewH = 0

function resize(): void {
  const dpr = Math.min(window.devicePixelRatio || 1, 2)
  viewW = canvas.clientWidth
  viewH = canvas.clientHeight
  canvas.width = Math.round(viewW * dpr)
  canvas.height = Math.round(viewH * dpr)
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
}

const app = createApp()
const cam = createCamera()

const update = mountUI(app, {
  pick(uid) {
    app.buildUid = app.buildUid === uid ? null : uid
    app.ghost = null
    app.hoverEdge = null
    update()
  },
  setSlots(n) {
    app.station.slots = n
    update()
  },
  reset() {
    const slots = app.station.slots
    app.station = createStation(slots)
    app.buildUid = null
    app.selectedUid = null
    app.ghost = null
    app.hoverEdge = null
    refresh(app)
    notify(app, 'Station zurueckgesetzt')
    update()
  },
  runTests() {
    showTestResults(runSelfTests())
  },
})

attachInput(canvas, app, cam, () => ({ w: viewW, h: viewH }), update)

window.addEventListener('resize', resize)
resize()

if (location.search.includes('selftest')) {
  const results = runSelfTests()
  showTestResults(results)
  const failed = results.filter(r => !r.ok)
  console.log(`Selbsttests: ${results.length - failed.length}/${results.length} bestanden`)
  for (const f of failed) console.error(`✗ ${f.name} — ${f.info}`)
}

// --- Schleife: feste Zeitschritte, Rendering entkoppelt (GDD 16 §12) -------

let lastFrame = performance.now()
let accumulator = 0

function tick(dt: number): void {
  app.time += dt
  fitTo(cam, allModules(app.station).map(m => m.poly), viewW, viewH)
  step(cam, dt)
}

function frame(now: number): void {
  accumulator += now - lastFrame
  lastFrame = now

  let ticks = 0
  while (accumulator >= TICK_MS && ticks < MAX_CATCHUP_TICKS) {
    tick(TICK_MS / 1000)
    accumulator -= TICK_MS
    ticks++
  }
  if (ticks === MAX_CATCHUP_TICKS) accumulator = 0

  render(ctx, app, cam, viewW, viewH)
  updateToast(app)
  requestAnimationFrame(frame)
}

requestAnimationFrame(frame)

:root {
  --bg: #070b18;
  --panel: #0c1329;
  --line: #1e2a51;
  --text: #c8d4f5;
  --dim: #6b7ba6;
  --neon: #35e0ff;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font: 13px/1.5 "Segoe UI", system-ui, sans-serif;
}

#layout {
  display: grid;
  grid-template-columns: 250px 1fr 280px;
  grid-template-rows: 1fr 40px;
  height: 100%;
}

aside {
  background: var(--panel);
  border-right: 1px solid var(--line);
  padding: 14px;
  overflow-y: auto;
}

#side { border-right: none; border-left: 1px solid var(--line); }

h2 {
  margin: 0 0 8px;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--dim);
}
#side h2 { margin-top: 22px; }
#side h2:first-child { margin-top: 0; }

.hint { color: var(--dim); font-size: 11.5px; margin: 0 0 12px; }
.empty { color: var(--dim); font-style: italic; margin: 0; }

/* --- Inventar ------------------------------------------------------------ */

.invCard {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  margin-bottom: 6px;
  padding: 8px 10px;
  text-align: left;
  color: inherit;
  font: inherit;
  background: #111a36;
  border: 1px solid var(--line);
  border-left: 3px solid var(--rarity, var(--line));
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
}
.invCard:hover { background: #162043; border-color: var(--rarity); }
.invCard.active {
  background: #1b2a55;
  border-color: var(--neon);
  box-shadow: 0 0 0 1px var(--neon) inset;
}
.invCard .glyph { font-size: 17px; line-height: 1; }
.invCard .body { display: flex; flex-direction: column; min-width: 0; }
.invCard .name { font-weight: 600; }
.invCard .meta { color: var(--dim); font-size: 11px; }

/* --- Baufläche ----------------------------------------------------------- */

#stageWrap { position: relative; }
#stage { display: block; width: 100%; height: 100%; cursor: crosshair; }

#toast {
  position: absolute;
  left: 50%;
  bottom: 22px;
  transform: translateX(-50%) translateY(6px);
  padding: 7px 14px;
  background: rgba(12, 19, 41, 0.94);
  border: 1px solid var(--line);
  border-radius: 999px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s, transform 0.18s;
}
