(async () => {
  const G = await import('/01-tower-building/geometry.ts');
  const S = await import('/01-tower-building/station.ts');

  // Unabhaengige Ueberlappungspruefung: Punktabtastung im Inneren, mit Sicherheitsabstand.
  const insideStrict = (p, poly) => {
    const c = G.centroid(poly);
    const shrunk = poly.map(v => ({ x: c.x + (v.x - c.x) * 0.94, y: c.y + (v.y - c.y) * 0.94 }));
    return G.pointInPolygon(p, shrunk);
  };
  const samplePoints = (poly, n = 12) => {
    const c = G.centroid(poly);
    const pts = [c];
    for (const v of poly) for (let k = 1; k <= n; k++) {
      const t = k / (n + 1);
      pts.push({ x: c.x + (v.x - c.x) * t, y: c.y + (v.y - c.y) * t });
    }
    return pts;
  };
  const reallyOverlaps = (poly, mods) =>
    mods.some(m => samplePoints(poly).some(p => insideStrict(p, m.poly))
              ||   samplePoints(m.poly).some(p => insideStrict(p, poly)));

  // Zufaellige Stationen bauen und jede Entscheidung von canPlace gegenpruefen.
  const defs = ['marksman', 'autocannon', 'rate_amplifier', 'bulwark'];
  let checked = 0, falseBlock = 0, falseAllow = 0, blocked = 0, allowed = 0;
  let seed = 12345;
  const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;

  for (let run = 0; run < 40; run++) {
    const st = S.createStation(99);
    for (let i = 0; i < 14; i++) {
      const free = S.freeEdges(st);
      const options = [];
      for (const fe of free) for (const d of defs) {
        const err = S.canPlace(st, d, fe);
        const poly = S.previewPolygon(d, fe).poly;
        const truth = reallyOverlaps(poly, S.allModules(st));
        checked++;
        if (err === 'overlap') { blocked++; if (!truth) falseBlock++; }
        else { allowed++; if (truth) falseAllow++; if (!err) options.push([d, fe]); }
      }
      if (!options.length) break;
      const [d, fe] = options[Math.floor(rnd() * options.length)];
      const inst = { uid: 'x' + run + '_' + i, defId: d, rarity: 'common', placement: null, poly: [] };
      st.inventory.push(inst);
      S.place(st, inst.uid, fe);
    }
  }
  return { checked, allowed, blocked, falschBlockiert: falseBlock, falschErlaubt: falseAllow };
})()

(async () => {
  const G = await import('/01-tower-building/geometry.ts');
  const S = await import('/01-tower-building/station.ts');

  // Exakte Schnittflaeche zweier konvexer Polygone (Sutherland-Hodgman).
  const clip = (subject, clipper) => {
    let out = subject;
    for (let i = 0; i < clipper.length && out.length; i++) {
      const a = clipper[i], b = clipper[(i + 1) % clipper.length];
      const side = p => (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
      const input = out; out = [];
      for (let j = 0; j < input.length; j++) {
        const cur = input[j], prev = input[(j + input.length - 1) % input.length];
        const sc = side(cur), sp = side(prev);
        if (sc >= 0) {
          if (sp < 0) { const t = sp / (sp - sc); out.push({ x: prev.x + t * (cur.x - prev.x), y: prev.y + t * (cur.y - prev.y) }); }
          out.push(cur);
        } else if (sp >= 0) {
          const t = sp / (sp - sc); out.push({ x: prev.x + t * (cur.x - prev.x), y: prev.y + t * (cur.y - prev.y) });
        }
      }
    }
    return out;
  };
  const area = poly => Math.abs(G.signedArea(poly));
  const overlapArea = (p1, p2) => (p1.length && p2.length) ? area(clip(p1, p2)) : 0;

  const moduleArea = area(G.polygonAt(4, { x: 0, y: 0 }, 0));   // Bezugsgroesse
  const defs = ['marksman', 'autocannon', 'rate_amplifier', 'bulwark'];
  let seed = 12345; const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;

  let blockedMin = Infinity, allowedMax = 0, blocked = 0, allowed = 0, checked = 0;
  const suspicious = [];

  for (let run = 0; run < 40; run++) {
    const st = S.createStation(99);
    for (let i = 0; i < 14; i++) {
      const free = S.freeEdges(st);
      const options = [];
      for (const fe of free) for (const d of defs) {
        const err = S.canPlace(st, d, fe);
        const poly = S.previewPolygon(d, fe).poly;
        const worst = Math.max(0, ...S.allModules(st).map(m => overlapArea(poly, m.poly)));
        const rel = worst / moduleArea;
        checked++;
        if (err === 'overlap') {
          blocked++; blockedMin = Math.min(blockedMin, rel);
          if (rel < 1e-4) suspicious.push({ d, rel: +rel.toExponential(2) });
        } else {
          allowed++; allowedMax = Math.max(allowedMax, rel);
          if (!err) options.push([d, fe]);
        }
      }
      if (!options.length) break;
      const [d, fe] = options[Math.floor(rnd() * options.length)];
      const inst = { uid: 'x' + run + '_' + i, defId: d, rarity: 'common', placement: null, poly: [] };
      st.inventory.push(inst);
      S.place(st, inst.uid, fe);
    }
  }
  return {
    checked, allowed, blocked,
    'kleinste Schnittflaeche bei Blockade (Anteil Modul)': +blockedMin.toExponential(3),
    'groesste Schnittflaeche bei Freigabe (Anteil Modul)': +allowedMax.toExponential(3),
    'verdaechtige Blockaden': suspicious.length
  };
})()

(async () => {
  const A = await import('/01-tower-building/app.ts');
  const C = await import('/01-tower-building/camera.ts');
  const R = await import('/01-tower-building/render.ts');
  const S = await import('/01-tower-building/station.ts');

  // Rendering-Pfad einmal echt ausfuehren (rAF laeuft bei verborgenem Pane nicht).
  const canvas = document.querySelector('#stage');
  const ctx = canvas.getContext('2d');
  const w = canvas.clientWidth, h = canvas.clientHeight;

  const app = A.createApp();
  const cam = C.createCamera();
  for (const [d, i] of [['autocannon',0],['rate_amplifier',2],['marksman',4]]) {
    const inst = { uid: 'r'+i, defId: d, rarity: 'epic', placement: null, poly: [] };
    app.station.inventory.push(inst);
    S.place(app.station, inst.uid, S.freeEdges(app.station)[i]);
  }
  A.refresh(app);
  app.buildUid = app.station.inventory[0].uid;
  app.hoverEdge = app.free[0];
  app.ghost = { poly: S.previewPolygon('bulwark', app.free[0]).poly, error: null };

  C.fitTo(cam, S.allModules(app.station).map(m => m.poly), w, h);
  for (let i = 0; i < 200; i++) C.step(cam, 1/60);
  R.render(ctx, app, cam, w, h);

  // Pixel auswerten: Wie viel weicht vom Hintergrund ab?
  const img = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
  const bins = new Map();
  let bright = 0;
  for (let p = 0; p < img.length; p += 4 * 37) {
    const key = `${img[p] >> 4},${img[p+1] >> 4},${img[p+2] >> 4}`;
    bins.set(key, (bins.get(key) || 0) + 1);
    if (img[p] + img[p+1] + img[p+2] > 300) bright++;
  }
  const total = [...bins.values()].reduce((a, b) => a + b, 0);
  return {
    canvas: `${canvas.width}x${canvas.height}`,
    zoom: +cam.zoom.toFixed(3),
    module: S.allModules(app.station).length,
    verschiedeneFarben: bins.size,
    helleNeonPixelAnteil: +(bright / total).toFixed(4),
    top5: [...bins.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([k, v]) => `${k}:${(v/total*100).toFixed(1)}%`)
  };
})()

