(async () => {
  const S = await import('/01-tower-building/station.ts');
  const defs = ['marksman', 'autocannon', 'rate_amplifier', 'bulwark'];
  let seed = 987654321;
  const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;

  const buckets = {};
  for (const size of [4, 8, 12, 15]) {
    let blocked = 0, total = 0, orphanSum = 0, stations = 0;
    for (let run = 0; run < 120; run++) {
      const st = S.createStation(99);
      for (let i = 0; i < size; i++) {
        const opts = [];
        for (const fe of S.freeEdges(st)) for (const d of defs)
          if (!S.canPlace(st, d, fe)) opts.push([d, fe]);
        if (!opts.length) break;
        const [d, fe] = opts[Math.floor(rnd() * opts.length)];
        const inst = { uid: `${run}_${i}`, defId: d, rarity: 'common', placement: null, poly: [] };
        st.inventory.push(inst);
        S.place(st, inst.uid, fe);
      }
      if (st.placed.length < size) continue;
      stations++;
      for (const m of st.placed) {
        total++;
        const orphans = S.detached(st, m.uid).length;
        if (orphans > 0) { blocked++; orphanSum += orphans; }
      }
    }
    buckets[`${size} Module`] = {
      stationen: stations,
      'Anteil Bissmodule (A blockiert)': +(blocked / total * 100).toFixed(1) + ' %',
      'Ø mitgerissene Module (B)': blocked ? +(orphanSum / blocked).toFixed(2) : 0,
      'max. mitgerissen': 0
    };
  }

  // groesste Insel separat bestimmen
  for (const size of [15]) {
    let worst = 0;
    for (let run = 0; run < 120; run++) {
      const st = S.createStation(99);
      for (let i = 0; i < size; i++) {
        const opts = [];
        for (const fe of S.freeEdges(st)) for (const d of defs)
          if (!S.canPlace(st, d, fe)) opts.push([d, fe]);
        if (!opts.length) break;
        const [d, fe] = opts[Math.floor(rnd() * opts.length)];
        const inst = { uid: `w${run}_${i}`, defId: d, rarity: 'common', placement: null, poly: [] };
        st.inventory.push(inst);
        S.place(st, inst.uid, fe);
      }
      for (const m of st.placed) worst = Math.max(worst, S.detached(st, m.uid).length);
    }
    buckets['15 Module']['max. mitgerissen'] = worst;
  }
  return buckets;
})()

