(async () => {
  const S = await import('/01-tower-building/station.ts');

  // Drei Module DIREKT am Hauptturm (Kanten 0, 2, 4) — keines ist eine Bruecke.
  const st = S.createStation(9);
  const uids = [];
  for (const [d, edgeIndex] of [['autocannon', 0], ['marksman', 2], ['rate_amplifier', 4]]) {
    const inst = { uid: 'm' + edgeIndex, defId: d, rarity: 'epic', placement: null, poly: [] };
    st.inventory.push(inst);
    const fe = S.freeEdges(st).find(f => f.ownerUid === st.core.uid && f.edgeIndex === edgeIndex);
    S.place(st, inst.uid, fe);
    uids.push(inst.uid);
  }

  const report = uids.map(uid => ({
    uid,
    nachbarn: S.neighbors(st, uid).map(m => m.uid),
    abgetrenntOhne: S.detached(st, uid).length,
    entfernenA: S.canRemove(st, uid, 'block'),
    zugErlaubt: S.canMove(st, uid, S.freeEdges(st, uid).find(f => f.ownerUid === st.core.uid))
  }));

  // Gegenprobe: Kette Core—B—A
  const st2 = S.createStation(9);
  const b = { uid: 'B', defId: 'autocannon', rarity: 'common', placement: null, poly: [] };
  st2.inventory.push(b);
  S.place(st2, 'B', S.freeEdges(st2)[0]);
  const own = S.freeEdges(st2).filter(f => f.ownerUid === 'B');
  const far = own.reduce((x, f) => {
    const d = Math.hypot((f.edge.a.x + f.edge.b.x) / 2, (f.edge.a.y + f.edge.b.y) / 2);
    return d > x.d ? { d, f } : x;
  }, { d: -1, f: own[0] }).f;
  const a = { uid: 'A', defId: 'autocannon', rarity: 'common', placement: null, poly: [] };
  st2.inventory.push(a);
  S.place(st2, 'A', far);

  return {
    direktAmKern: report,
    kette: {
      B_nachbarn: S.neighbors(st2, 'B').map(m => m.uid),
      A_nachbarn: S.neighbors(st2, 'A').map(m => m.uid),
      B_entfernenA: S.canRemove(st2, 'B', 'block'),
      A_entfernenA: S.canRemove(st2, 'A', 'block')
    }
  };
})()

