  const defs = ['marksman', 'autocannon', 'rate_amplifier', 'power_amplifier', 'bulwark'];
  let seed = 4242; const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
