  for (let i = 0; i < 300; i++) C.step(cam, 1 / 60);

  const farben = () => {
    const img = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
    const set = new Set(); let n = 0;
    for (let p = 0; p < img.length; p += 4 * 23) { n++; set.add(`${img[p] >> 4},${img[p + 1] >> 4},${img[p + 2] >> 4}`); }
    return { farbtoene: set.size, punkte: n };
