(async () => {
  const S = await import('/01-tower-building/station.ts');
  const B = await import('/01-tower-building/buffs.ts');
  const D = await import('/01-tower-building/devtools.ts');
  const P = await import('/01-tower-building/persist.ts');
  const Cat = await import('/01-tower-building/catalog.ts');

  const clone = st => P.deserialize(JSON.parse(JSON.stringify(P.serialize(st))));
  const FOOT = { marksman: 3, autocannon: 4, rate_amplifier: 5, bulwark: 6 };

  // ---- F3: Wie stark begrenzt die Geometrie das Bauen? ----
  let edgesTotal = 0, dead = 0, fitSum = 0;
  const bySides = { 3: 0, 4: 0, 5: 0, 6: 0 };
  // ---- F5: Nachbarn je Grundflaeche ----
  const nb = { 3: [], 4: [], 5: [], 6: [] };

  for (let run = 0; run < 60; run++) {
    const st = S.createStation(4);
    D.growRandom(st, 15, 1000 + run);
    for (const fe of S.freeEdges(st)) {
      edgesTotal++;
      let fits = 0;
      for (const [defId, sides] of Object.entries(FOOT)) {
        if (S.canPlace(st, defId, fe) === null) { fits++; bySides[sides]++; }
      }
      fitSum += fits;
      if (fits === 0) dead++;
    }
    const adj = S.adjacency(st);
    for (const m of [st.core, ...st.placed]) {
      const sides = Cat.defOf(m.defId).sides;
      nb[sides].push((adj.get(m.uid) ?? []).length);
    }
  }

  const avg = a => a.length ? +(a.reduce((x, y) => x + y, 0) / a.length).toFixed(2) : 0;

  // ---- F7: Amplifier gegen zusaetzlichen Kampfturm ----
  const duell = {};
  for (const rarity of ['common', 'epic', 'legendary']) {
    const buckets = {};
    for (let run = 0; run < 40; run++) {
      const base = S.createStation(4);
      D.growRandom(base, 9, 500 + run);
      const baseDps = B.computeStation(base).theoreticalDps;
      const n = S.freeEdges(base).length;

      for (let i = 0; i < n; i++) {
        const stA = clone(base), stB = clone(base);
        const eA = S.freeEdges(stA)[i], eB = S.freeEdges(stB)[i];
        const amp = { uid: 'amp', defId: 'power_amplifier', rarity, placement: null, poly: [] };
        const gun = { uid: 'gun', defId: 'autocannon', rarity, placement: null, poly: [] };
        stA.inventory.push(amp); stB.inventory.push(gun);
        if (S.place(stA, 'amp', eA) !== null || S.place(stB, 'gun', eB) !== null) continue;

        const gainAmp = B.computeStation(stA).theoreticalDps - baseDps;
        const gainGun = B.computeStation(stB).theoreticalDps - baseDps;
        const k = S.neighbors(stA, 'amp').filter(m => Cat.defOf(m.defId).category !== 'buff').length;
        (buckets[k] ??= { n: 0, wins: 0, amp: 0, gun: 0 });
        buckets[k].n++; buckets[k].amp += gainAmp; buckets[k].gun += gainGun;
        if (gainAmp > gainGun) buckets[k].wins++;
      }
    }
    duell[rarity] = Object.fromEntries(Object.entries(buckets).map(([k, v]) => [
      `${k} Nachbarn`,
      { faelle: v.n, 'Ø Amplifier': +(v.amp / v.n).toFixed(1), 'Ø Kampfturm': +(v.gun / v.n).toFixed(1), 'Amplifier gewinnt': +(v.wins / v.n * 100).toFixed(0) + ' %' }
    ]));
  }

  return {
    F3: {
      freieKanten: edgesTotal,
      'Ø passende Formen je Kante': +(fitSum / edgesTotal).toFixed(2),
      'Kanten ohne jede Option': +(dead / edgesTotal * 100).toFixed(1) + ' %',
      'Kanten die je Form passen': Object.fromEntries(Object.entries(bySides).map(([s, c]) => [s + '-Eck', +(c / edgesTotal * 100).toFixed(0) + ' %'])),
    },
    F5_nachbarn: Object.fromEntries(Object.entries(nb).map(([s, a]) => [
      `${s}-Eck`, { module: a.length, 'Ø Nachbarn': avg(a), 'Auslastung': +(avg(a) / Number(s) * 100).toFixed(0) + ' %' }
    ])),
    F7: duell
  };
})()

