  const S = await import('/01-tower-building/station.ts');
  const B = await import('/01-tower-building/buffs.ts');
  const Cat = await import('/01-tower-building/catalog.ts');

  const TYPES = ['autocannon', 'siege_cannon', 'marksman', 'power_amplifier', 'rate_amplifier'];
  const RARITY = 'epic';

  // Ein Build ist eine Folge von (Turmart, Index der freien Kante). Wird von vorn abgespielt.
  const replay = recipe => {
    const st = S.createStation(99);
    for (const [t, ei] of recipe) {
      const edges = S.freeEdges(st);
      if (ei >= edges.length) return null;
      const inst = { uid: 'm' + st.placed.length, defId: TYPES[t], rarity: RARITY, placement: null, poly: [] };
      st.inventory.push(inst);
      if (S.place(st, inst.uid, edges[ei]) !== null) return null;
    }
    return st;
  };

  const SLOTS = 4, BEAM = 60;
  let beam = [[]];
  for (let depth = 0; depth < SLOTS; depth++) {
    const next = [];
    for (const recipe of beam) {
      const st = replay(recipe);
      if (!st) continue;
      const edges = S.freeEdges(st);
      for (let ei = 0; ei < edges.length; ei++) {
        for (let t = 0; t < TYPES.length; t++) {
          if (S.canPlace(st, TYPES[t], edges[ei]) !== null) continue;
          const child = [...recipe, [t, ei]];
          const cs = replay(child);
          if (!cs) continue;
          next.push({ recipe: child, dps: B.computeStation(cs).theoreticalDps });
        }
      }
    }
    next.sort((a, b) => b.dps - a.dps);
    beam = next.slice(0, BEAM).map(x => x.recipe);
  }

  const scored = beam.map(recipe => {
    const st = replay(recipe);
    const names = recipe.map(([t]) => Cat.defOf(TYPES[t]).name);
    return {
      build: names.join(' + '),
      dps: +B.computeStation(st).theoreticalDps.toFixed(1),
      mitBuffTurm: names.some(n => n.includes('Amplifier'))
    };
  }).sort((a, b) => b.dps - a.dps);

  const bestOhne = scored.find(s => !s.mitBuffTurm);
  const bestMit = scored.find(s => s.mitBuffTurm);

  return {
    bestesGesamt: scored[0],
    bestesOhneBuffTurm: bestOhne,
    bestesMitBuffTurm: bestMit,
    'Abstand': bestMit && bestOhne ? +(100 * (bestMit.dps / bestOhne.dps - 1)).toFixed(1) + ' %' : null,
    top5: scored.slice(0, 5).map(s => `${s.dps} — ${s.build}`)
  };
})()

(async () => {
  const S = await import('/01-tower-building/station.ts');
  const B = await import('/01-tower-building/buffs.ts');

  const put = (st, defId, rarity, fe) => {
    const inst = { uid: 'u' + st.placed.length, defId, rarity, placement: null, poly: [] };
    st.inventory.push(inst);
    return S.place(st, inst.uid, fe) === null ? inst.uid : null;
  };
  const dps = st => +B.computeStation(st).theoreticalDps.toFixed(1);

  const gunTypes = ['marksman', 'autocannon'];
  const out = {};

  for (const gun of gunTypes) {
    for (const ampRarity of ['epic', 'legendary', 'mythic']) {
      // A) vier Kampftuerme direkt am Kern
      const a = S.createStation(99);
      for (let i = 0; i < 4; i++) {
        const fe = S.freeEdges(a).find(f => f.ownerUid === a.core.uid && S.canPlace(a, gun, f) === null);
        if (fe) put(a, gun, 'epic', fe);
      }

      // B) Amplifier zuerst, dann Kampftuerme an SEINE freien Kanten
      const b = S.createStation(99);
      const ampUid = put(b, 'power_amplifier', ampRarity, S.freeEdges(b)[0]);
      let gunsPlaced = 0;
      while (gunsPlaced < 3) {
        const fe = S.freeEdges(b).find(f => f.ownerUid === ampUid && S.canPlace(b, gun, f) === null);
        if (!fe) break;
        put(b, gun, 'epic', fe);
        gunsPlaced++;
      }

      const gebufft = S.neighbors(b, ampUid).length;
      out[`${gun} / Amplifier ${ampRarity}`] = {
        'A: 4 Kampftuerme': dps(a),
        [`B: Amplifier + ${gunsPlaced} Kampftuerme`]: dps(b),
        gebuffteModule: gebufft,
        'B gegen A': +(100 * (dps(b) / dps(a) - 1)).toFixed(1) + ' %'
      };
    }
  }

  // Rechnerische Schwelle: k gebuffte gleiche Tuerme schlagen k+1 ungebuffte, wenn Buff > 1/k
  const schwelle = {};
  for (const k of [1, 2, 3, 4, 5, 6]) schwelle[`${k} Nachbarn`] = `Buff muss > ${(100 / k).toFixed(0)} % sein`;

  return { vergleich: out, schwelle };
})()

